import { Book } from "@/lib/types";

export const psalms: Book = {
  id: "psalms",
  name: "Psalmen",
  shortName: "Ps",
  testament: "old",
  chapters: [
    { number: 1, verses: [
      { number: 1, text: "ERSTES BUCH Glücklich der Mann, der nicht folgt dem Rat der Gottlosen, den Weg der Sünder nicht betritt* und nicht im Kreis der Spötter sitzt*,", heading: "Psalm 11", footnotes: ["℘ Spr 1,15; 4,14", "℘ Ps 26,4.5; Eph 5,7"] },
      { number: 2, text: "sondern seine Lust hat am Gesetz des HERRN* und über sein Gesetz sinnt Tag und Nacht*!", footnotes: ["℘ Ps 112,1; 119,35; Röm 7,22", "℘ Ps 119,15; Jos 1,8"] },
      { number: 3, text: "Er ist wie ein Baum, gepflanzt an Wasserbächen*, der seine Frucht bringt zu seiner Zeit*, und dessen Laub nicht verwelkt; alles was er tut, gelingt ihm*.", footnotes: ["℘ Jes 58,11", "℘ Ps 92,14.15; Jer 17,8", "℘ Ps 128,2; 1Mo 39,3"] },
      { number: 4, text: "Nicht so die Gottlosen; sondern sie sind wie Spreu, die der Wind verweht*.", footnotes: ["℘ Ps 35,5; 37,36; Hi 21,18; Hos 13,3"] },
      { number: 5, text: "Darum bestehen Gottlose nicht im Gericht*, noch Sünder in der Gemeinde der Gerechten.", footnotes: ["℘ 2Petr 2,9"] },
      { number: 6, text: "Denn der HERR kennt den Weg der Gerechten*; aber der Gottlosen Weg vergeht*.", footnotes: ["℘ Ps 37,18; 142,4", "℘ 1Sam 2,9"] },
    ]},
    { number: 2, verses: [
      { number: 1, text: "Warum toben die Nationen* und sinnen Eitles die Völkerschaften*?", heading: "Psalm 2", footnotes: ["℘ Ps 46,7; 83,3", "℘ Apg 4,25.26"] },
      { number: 2, text: "Es treten auf Könige der Erde*, und Fürsten tun sich zusammen gegen den HERRN und seinen Gesalbten*:", footnotes: ["℘ Ps 48,5; Joh 1,41", "℘ Ps 83,6; Offb 11,18"] },
      { number: 3, text: "»Lasst uns zerreißen ihre Bande und von uns werfen ihre Stricke*!«", footnotes: ["℘ Jer 2,20; 5,5"] },
      { number: 4, text: "Der im Himmel thront*, lacht, der Herr spottet über sie*.", footnotes: ["℘ Ps 123,1", "℘ Ps 37,13; 59,9"] },
      { number: 5, text: "Dann spricht er sie an in seinem Zorn, in seiner Zornglut schreckt er sie*:", footnotes: ["℘ Jes 34,2"] },
      { number: 6, text: "»Habe doch ich meinen König geweiht auf Zion, meinem heiligen Berg*!«", footnotes: ["℘ Offb 14,1"] },
      { number: 7, text: "Lasst mich die Anordnung des HERRN bekannt geben! Er hat zu mir gesprochen: »Mein Sohn bist du*, ich habe dich heute gezeugt*.", footnotes: ["℘ Lk 1,32; Joh 1,49", "℘ Apg 13,33; Hebr 1,5"] },
      { number: 8, text: "Fordere von mir, und ich will dir die Nationen zum Erbteil geben*, zu deinem Besitz die Enden der Erde*.", footnotes: ["℘ Ps 82,8; Hebr 1,2", "℘ Dan 7,13.14"] },
      { number: 9, text: "Mit eisernem Stab magst du sie zerschmettern*, wie Töpfergeschirr sie zerschmeißen*.«", footnotes: ["℘ Ps 110,5", "℘ Lk 19,27; Offb 2,27"] },
      { number: 10, text: "Und nun, ihr Könige, handelt verständig; lasst euch zurechtweisen, ihr Richter der Erde!" },
      { number: 11, text: "Dienet dem HERRN mit Furcht, und *jauchzt mit Zittern*!", footnotes: ["Nach Umstellung der hebr. Buchstaben in die Reihenfolge 12a—11b: Küsst seine Füße mit Zittern", "℘ Phil 2,12; Hebr 12,28"] },
      { number: 12, text: "Küsst den Sohn*, dass er nicht zürne und ihr umkommt auf dem Weg; denn leicht entbrennt sein Zorn*. Glücklich alle, die sich bei ihm bergen*!", footnotes: ["Nach Umstellung der hebr. Buchstaben in die Reihenfolge 12a—11b: Küsst seine Füße mit Zittern", "℘ Offb 6,16", "℘ Ps 31,20; 34,9; 84,13; Spr 16,20; Jes 30,18"] },
    ]},
    { number: 3, verses: [
      { number: 1, text: "Ein Psalm. Von David. Als er vor seinem Sohn Absalom floh*.", heading: "Psalm 3", footnotes: ["℘ 2Sam 15,14"] },
      { number: 2, text: "HERR! Wie zahlreich sind meine Bedränger! Viele erheben sich gegen mich*;", footnotes: ["℘ Ps 124,2; 2Sam 16,7"] },
      { number: 3, text: "viele sagen von mir: Es gibt keine Rettung für ihn bei Gott*! //*", footnotes: ["℘ Mt 27,42.43", "Der Doppelstrich steht für das hebr. Sela. Dieses bedeutet vielleicht: Pause, o. Zwischenspiel, o. Verstärkung der begleitenden Musik; vgl. Ps 9,17."] },
      { number: 4, text: "Du aber, HERR, bist ein Schild* um mich her, meine Ehre*, und der mein Haupt emporhebt*.", footnotes: ["℘ Ps 5,13; 18,3; 28,7; 47,10; 84,12; 89,19; 119,114; 1Mo 15,1; Spr 2,7", "℘ Ps 62,8", "℘ Ps 27,6"] },
      { number: 5, text: "Mit meiner Stimme rufe ich zum HERRN, und er antwortet mir* von seinem heiligen Berg. //", footnotes: ["℘ Ps 34,5"] },
      { number: 6, text: "Ich legte mich nieder und schlief; ich erwachte, denn der HERR stützt mich*.", footnotes: ["℘ Ps 4,9; Spr 3,24"] },
      { number: 7, text: "Ich fürchte nicht Zehntausende Kriegsvolks, die ringsum mich belagern*.", footnotes: ["℘ Ps 27,3"] },
      { number: 8, text: "Steh auf, HERR*! Rette mich*, mein Gott*! Denn du hast alle meine Feinde auf die Backe geschlagen; die Zähne der Gottlosen hast du zerschmettert*.", footnotes: ["℘ 4Mo 10,35", "℘ Ps 119,94", "℘ Ps 31,16", "℘ Ps 58,7"] },
      { number: 9, text: "Bei dem HERRN ist die Rettung*. Dein Segen komme auf dein Volk*. //", footnotes: ["℘ Ps 37,39", "℘ Ps 115,12-15"] },
    ]},
    { number: 4, verses: [
      { number: 1, text: "Dem Chorleiter. Mit Saitenspiel. Ein Psalm. Von David.", heading: "Psalm 4" },
      { number: 2, text: "Wenn ich rufe, antworte mir, Gott meiner Gerechtigkeit! In Bedrängnis hast du mir Raum gemacht; sei mir gnädig und höre mein Gebet*!", footnotes: ["℘ Ps 50,15"] },
      { number: 3, text: "Ihr Herrensöhne*, wie lange bleibt meine Ehre zur Schande verkehrt, werdet ihr Eitles lieben und Lüge suchen? //", footnotes: ["℘ Ps 49,3; 62,10"] },
      { number: 4, text: "Erkennt doch, dass der HERR *einen Frommen für sich ausgesondert hat*! Der HERR hört, wenn ich zu ihm rufe*.", footnotes: ["Mit leichter Änderung nach Ps 31,22: mir wunderbar Gnade erwiesen hat", "Mit leichter Änderung nach Ps 31,22: mir wunderbar Gnade erwiesen hat", "℘ Ps 17,6"] },
      { number: 5, text: "Erbebt, aber sündigt nicht*! Denkt nach in eurem Herzen auf eurem Lager, aber seid still*! //", footnotes: ["℘ Eph 4,26", "℘ Ps 77,7"] },
      { number: 6, text: "Opfert Gerechtigkeitsopfer* und vertraut auf den HERRN!", footnotes: ["℘ Ps 51,21; 5Mo 33,19"] },
      { number: 7, text: "Viele sagen: Wer wird uns Gutes schauen lassen? Erhebe, HERR, über uns* das Licht deines Angesichts*!", footnotes: ["Andere übersetzen mit Textkorr.: Gewichen ist, HERR, von uns", "℘ Ps 31,17; 67,2; 80,4; 4Mo 6,25"] },
      { number: 8, text: "Du hast Freude in mein Herz gegeben, mehr als jenen zu der Zeit, da sie viel Korn und Most haben*.", footnotes: ["℘ Ps 16,11"] },
      { number: 9, text: "In Frieden werde ich, sobald ich liege*, schlafen; denn du, HERR, lässt mich, obschon allein, in Sicherheit wohnen*.", footnotes: ["℘ Ps 3,6", "℘ 3Mo 26,6; Hes 34,25.28"] },
    ]},
    { number: 5, verses: [
      { number: 1, text: "Dem Chorleiter. Zu Flöten. Ein Psalm. Von David.", heading: "Psalm 5" },
      { number: 2, text: "Meine Worte nimm zu Ohren, HERR, merke auf mein Seufzen!" },
      { number: 3, text: "Horche auf die Stimme meines Schreiens*, mein König und mein Gott*; denn zu dir bete ich.", footnotes: ["℘ Ps 130,2; Hi 34,28; Kla 3,56", "℘ Ps 44,5; 74,12; 84,4; 145,1"] },
      { number: 4, text: "HERR, in der Frühe wirst du meine Stimme hören. In der Frühe rüste ich dir ein Opfer zu und spähe aus*.", footnotes: ["℘ Ps 63,2; 88,14"] },
      { number: 5, text: "Denn du bist nicht ein Gott, der an Gottlosigkeit Gefallen hat; bei dir darf ein Böser nicht weilen." },
      { number: 6, text: "Verblendete dürfen nicht vor deine Augen hintreten; du hassest alle, die Götzendienst üben*.", footnotes: ["℘ Ps 11,5"] },
      { number: 7, text: "Du lässt die Lügenredner verloren gehen*; den Mann des Blutes und des Truges verabscheut der HERR*.", footnotes: ["℘ Ps 101,7", "℘ Ps 34,17; Spr 6,16.17"] },
      { number: 8, text: "Ich aber darf dank der Fülle deiner Gnade eingehen in dein Haus; ich bete an zu deinem heiligen Tempel hin*, in der Furcht vor dir.", footnotes: ["℘ Ps 138,2"] },
      { number: 9, text: "HERR, leite mich in deiner Gerechtigkeit wegen meiner Feinde*; ebne vor mir deinen Weg*.", footnotes: ["℘ Ps 27,11; 69,19", "℘ Jes 26,7"] },
      { number: 10, text: "Denn nichts Gewisses ist in ihrem Mund, ihr Inneres ist Verderben. Ein offenes Grab ist ihre Kehle*, ihre Zunge glätten sie.", footnotes: ["℘ Röm 3,13"] },
      { number: 11, text: "Lass sie büßen, Gott; mögen sie fallen um ihrer Pläne willen! Stoße sie hinweg wegen der Menge ihrer Vergehen*, denn sie sind widerspenstig gegen dich gewesen.", footnotes: ["o. Treuebrüche"] },
      { number: 12, text: "Doch mögen sich freuen alle, die sich bei dir bergen*, und jubeln allezeit. Du beschirmst sie*, darum jauchzen in dir*, die deinen Namen lieben*.", footnotes: ["℘ Ps 64,11", "℘ Ps 32,7", "℘ Ps 68,4", "℘ Ps 69,37; 119,132"] },
      { number: 13, text: "Denn du segnest den Gerechten, HERR, wie mit einem Schild* umringst du ihn mit Huld.", footnotes: ["℘ Ps 3,4"] },
    ]},
    { number: 6, verses: [
      { number: 1, text: "Dem Chorleiter. Mit Saitenspiel. Auf der Scheminith*. Ein Psalm. Von David.", heading: "Psalm 6", footnotes: ["Wohl ein Instrument mit acht Saiten.\n℘ Ps 12,1; 1Chr 15,20.21"] },
      { number: 2, text: "HERR, strafe mich nicht in deinem Zorn, und züchtige mich nicht in deinem Grimm*!", footnotes: ["℘ Ps 38,2; Jer 10,24"] },
      { number: 3, text: "Sei mir gnädig, HERR*, denn ich bin welk; heile mich, HERR, denn meine Gebeine sind bestürzt*.", footnotes: ["℘ Ps 9,14", "℘ Jer 17,14"] },
      { number: 4, text: "Meine Seele ist tief bestürzt*. Aber du, HERR, bis wann* —?", footnotes: ["℘ Joh 12,27", "℘ Ps 13,2.3; 74,10; 79,5; Offb 6,10"] },
      { number: 5, text: "Kehre um, HERR*, befreie meine Seele*; rette mich um deiner Gnade willen!", footnotes: ["℘ Ps 90,13", "℘ Ps 116,4"] },
      { number: 6, text: "Denn im Tod ruft man dich nicht an; im Scheol*, wer wird dich preisen*?", footnotes: ["d. h. im Totenreich", "℘ Ps 30,10; 88,11-13; 115,17; Jes 38,18"] },
      { number: 7, text: "Müde bin ich durch mein Seufzen*; die ganze Nacht schwemme ich mein Bett, mache mit meinen Tränen mein Lager zerfließen.", footnotes: ["℘ Ps 69,4"] },
      { number: 8, text: "Geschwächt von Gram ist mein Auge*, gealtert wegen all meiner Dränger.", footnotes: ["℘ Ps 31,10; Hi 17,7"] },
      { number: 9, text: "Weicht von mir, alle ihr Übeltäter*; denn der HERR hat die Stimme meines Weinens gehört*.", footnotes: ["℘ Mt 7,23", "℘ Jes 38,5"] },
      { number: 10, text: "Der HERR hat mein Flehen gehört*; mein Gebet nimmt der HERR an.", footnotes: ["℘ Ps 55,20"] },
      { number: 11, text: "Beschämt und tief bestürzt werden alle meine Feinde; sie müssen zurückweichen, werden plötzlich beschämt*.", footnotes: ["℘ Ps 35,4.26; 40,15; Jes 41,11"] },
    ]},
    { number: 7, verses: [
      { number: 1, text: "Ein Schiggajon* von David, das er dem HERRN sang wegen der Worte des Benjaminiten Kusch.", heading: "Psalm 7", footnotes: ["Bezeichnet wahrscheinlich ein bewegtes Klagelied.\n℘ Hab 3,1"] },
      { number: 2, text: "HERR, mein Gott, bei dir berge ich mich*, rette mich von allen meinen Verfolgern und befreie mich*!", footnotes: ["℘ Ps 11,1; 16,1; 31,2", "℘ Ps 59,2"] },
      { number: 3, text: "Dass er nicht wie ein Löwe mein Leben zerreißt, er reißt, und da ist kein Befreier*.", footnotes: ["℘ Ps 22,12"] },
      { number: 4, text: "HERR, mein Gott! Wenn ich solches getan habe, wenn Unrecht an meinen Händen ist*,", footnotes: ["℘ Hi 31,7"] },
      { number: 5, text: "wenn ich Böses vergolten dem, der mit mir Frieden hält, und geplündert den, der mich ohne Ursache bedrängt*,", footnotes: ["℘ 1Sam 24,18"] },
      { number: 6, text: "so verfolge der Feind meine Seele und erreiche sie, er trete mein Leben zu Boden* und strecke meine Ehre* hin in den Staub. //", footnotes: ["℘ Ps 143,3", "d. h. meine Seele (mein Köstlichstes)"] },
      { number: 7, text: "Steh auf, HERR, in deinem Zorn! Erhebe dich gegen das Wüten meiner Bedränger, und wache auf zu mir*! Gericht hast du befohlen.", footnotes: ["℘ Ps 59,5"] },
      { number: 8, text: "Die Schar der Völkerschaften umringe dich, zur Höhe über ihnen kehre zurück*!", footnotes: ["Hinter dem überlieferten Text vermutet man die ursprüngliche Bedeutung: hoch über ihnen nimm auf deinem Richterstuhl Platz."] },
      { number: 9, text: "Der HERR richtet die Völker*. Richte mich, HERR, nach meiner Gerechtigkeit und nach meiner Lauterkeit, die auf mir ist*.", footnotes: ["℘ Ps 9,9; 35,23; 43,1; 96,13; 98,9", "℘ Ps 18,21"] },
      { number: 10, text: "Ein Ende nehme die Bosheit der Gottlosen, aber dem Gerechten gib Bestand, der du Herzen und Nieren* prüfst, gerechter Gott*!", footnotes: ["s. Anm. zu Ps 16,7", "℘ Jer 11,20; 17,10; Lk 16,15; Offb 2,23"] },
      { number: 11, text: "Mein Schild über mir ist Gott, der die von Herzen Aufrichtigen rettet." },
      { number: 12, text: "Gott ist ein gerechter Richter* und ein strafender Gott an jedem Tag.", footnotes: ["℘ Ps 9,5; 129,4; 1Mo 18,25; 2Tim 4,8"] },
      { number: 13, text: "Wahrhaftig, schon wieder wetzt er, der Feind, sein Schwert*, spannt seinen Bogen und rüstet ihn*.", footnotes: ["℘ 5Mo 32,41; Offb 19,15", "℘ Kla 2,4; 3,12"] },
      { number: 14, text: "Aber gegen sich selbst hat er die Mordwerkzeuge bereitet, seine Pfeile brennend gemacht*.", footnotes: ["℘ 5Mo 32,23"] },
      { number: 15, text: "Siehe, er trägt in sich Böses*; er geht schwanger mit Unheil, gebiert Falschheit*.", footnotes: ["w. ist schwanger o. kommt in Wehen mit Bösem", "℘ Hi 4,8; 15,35; Jes 59,4"] },
      { number: 16, text: "Er hat eine Grube gegraben und hat sie ausgehöhlt, doch ist er in die Falle gefallen, die er gemacht hat*.", footnotes: ["℘ Ps 9,16; 35,8; 57,7; 141,10; Spr 26,27"] },
      { number: 17, text: "Sein Unheil kehrt auf sein Haupt zurück, und auf seinen Scheitel herab kommt seine Gewalttat*.", footnotes: ["℘ Ps 140,10; 1Kö 2,32.33; Est 9,25"] },
      { number: 18, text: "Ich will den HERRN preisen nach seiner Gerechtigkeit* und besingen den Namen des HERRN, des Höchsten*.", footnotes: ["℘ Ps 35,28", "℘ Ps 9,3; 69,31"] },
    ]},
    { number: 8, verses: [
      { number: 1, text: "Dem Chorleiter. Nach der Gittit*. Ein Psalm. Von David.", heading: "Psalm 8", footnotes: ["musikalische Anweisung, wahrscheinlich Hinweis auf eine Vortragsart oder Melodie, viell. aber auch auf ein Instrument\n℘ Ps 81,1; 84,1"] },
      { number: 2, text: "HERR, unser Herr, wie herrlich ist dein Name auf der ganzen Erde*, der du deine Hoheit gelegt hast auf den Himmel*!", footnotes: ["℘ Jes 6,3", "℘ Ps 57,6; 148,13"] },
      { number: 3, text: "Aus dem Munde der Kinder und Säuglinge hast du Macht gegründet* wegen deiner Bedränger, um zum Schweigen zu bringen* den Feind und den Rachgierigen.", footnotes: ["o. hast du die Grundmauern einer Festung gelegt\n℘ Mt 21,16", "w. aufhören zu lassen"] },
      { number: 4, text: "Wenn ich anschaue deinen Himmel, deiner Finger Werk*, den Mond und die Sterne, die du bereitet hast*:", footnotes: ["℘ Ps 19,2; 96,5; 1Mo 1,1", "℘ Ps 136,5-9; 1Mo 1,14"] },
      { number: 5, text: "Was ist der Mensch, dass du sein gedenkst, und des Menschen Sohn, dass du dich um ihn kümmerst*?", footnotes: ["℘ Ps 144,3; Hi 7,17"] },
      { number: 6, text: "Denn du hast ihn wenig geringer gemacht als Engel*, mit Herrlichkeit und Pracht krönst du ihn.", footnotes: ["Das hebr. Wort Elohim (sonst = Gott) bedeutet hier wahrscheinlich »Gottwesen, Engel«."] },
      { number: 7, text: "Du machst ihn zum Herrscher über die Werke deiner Hände; alles hast du unter seine Füße gestellt*:", footnotes: ["℘ 1Mo 1,26-28; 1Kor 15,27; Hebr 2,6-8"] },
      { number: 8, text: "Schafe und Rinder allesamt und auch die Tiere des Feldes," },
      { number: 9, text: "Vögel des Himmels und Fische des Meeres, was die Pfade der Meere durchzieht." },
      { number: 10, text: "HERR, unser Herr, wie herrlich ist dein Name auf der ganzen Erde*!", footnotes: ["℘ Jes 63,14"] },
    ]},
    { number: 9, verses: [
      { number: 1, text: "Dem Chorleiter. Almuth Labben*. Ein Psalm. Von David.", heading: "Psalm 91", footnotes: ["d. h. Nach »Stirb für den Sohn«. — Vermutlich ein nicht mehr verständlicher Hinweis für den musikalischen Vortrag."] },
      { number: 2, text: "Ich will dich preisen, HERR, mit meinem ganzen Herzen*, will erzählen alle deine Wundertaten*.", footnotes: ["℘ Ps 86,12; 138,1", "℘ Ps 26,7; 96,3; Apg 2,11"] },
      { number: 3, text: "In dir will ich mich freuen und jauchzen, will deinen Namen besingen, du Höchster*,", footnotes: ["℘ Ps 7,18; 91,9; 92,2"] },
      { number: 4, text: "während meine Feinde zurückweichen, stürzen und umkommen vor deinem Angesicht." },
      { number: 5, text: "Denn du hast ausgeführt mein Recht und meine Rechtssache*; du hast dich auf den Thron gesetzt, ein gerechter Richter*.", footnotes: ["℘ Kla 3,58", "℘ Ps 7,12"] },
      { number: 6, text: "Du hast Nationen gescholten*, den Gottlosen verloren gegeben, ihren Namen ausgelöscht für immer und ewig*;", footnotes: ["o. angeschrien", "℘ Ps 34,17"] },
      { number: 7, text: "der Feind ist erledigt, zertrümmert für immer; du hast Städte zerstört, ihre Namensnennung verschwindet." },
      { number: 8, text: "Der HERR lässt sich nieder auf immer*, er hat seinen Thron aufgestellt zum Gericht.", footnotes: ["℘ Ps 10,16; 29,10; 2Mo 15,18; Jer 10,10"] },
      { number: 9, text: "Und er, er wird richten die Welt in Gerechtigkeit, wird über die Völkerschaften Gericht halten in Geradheit*.", footnotes: ["℘ Ps 7,9; 67,5; 96,10; 98,9; Apg 17,31"] },
      { number: 10, text: "Doch dem Unterdrückten ist der HERR eine hohe Feste, eine hohe Feste in Zeiten der Bedrängnis*.", footnotes: ["℘ Ps 37,39; Jes 25,4; Nah 1,7"] },
      { number: 11, text: "Auf dich vertrauen, die deinen Namen kennen*; denn du hast nicht verlassen, die dich suchen, HERR.", footnotes: ["℘ Ps 91,14"] },
      { number: 12, text: "Singet dem HERRN, der Zion bewohnt*, verkündet unter den Völkern seine Taten*!", footnotes: ["℘ Ps 68,17; 74,2; 76,3; 132,13", "℘ Jes 12,4"] },
      { number: 13, text: "Denn der dem vergossenen Blut nachforscht*, hat ihrer gedacht; er hat das Schreien der Elenden nicht vergessen*.", footnotes: ["℘ 1Mo 4,9.10", "℘ Ps 10,12; 12,6"] },
      { number: 14, text: "Sei mir gnädig, HERR*! Sieh an mein Elend* vonseiten meiner Hasser, indem du mich emporhebst aus den Toren des Todes:", footnotes: ["℘ Ps 6,3", "℘ 2Mo 3,7"] },
      { number: 15, text: "Damit ich all dein Lob erzähle in den Toren der Tochter Zion, dass ich jauchze über deine Rettung*.", footnotes: ["℘ Ps 13,6; 20,6; 35,9; 107,22; 142,8"] },
      { number: 16, text: "Versunken sind die Nationen in die Grube, die sie gemacht*; in dem Netz, das sie versteckt haben, hat sich ihr eigener Fuß gefangen.", footnotes: ["℘ Ps 7,16"] },
      { number: 17, text: "Der HERR hat sich zu erkennen gegeben, er hat Gericht ausgeübt: der Gottlose hat sich verstrickt im Werk seiner Hände. Higgajon*. //", footnotes: ["vermutlich Anordnung eines instrumentalen Zwischenspiels"] },
      { number: 18, text: "Mögen zum Scheol sich wenden die Gottlosen, alle Nationen, die Gott vergessen*.", footnotes: ["℘ Ps 50,22; 139,19"] },
      { number: 19, text: "Denn nicht für immer wird der Arme vergessen, noch geht der Elenden* Hoffnung für ewig verloren.", footnotes: ["o. Demütigen"] },
      { number: 20, text: "Steh auf, HERR*, dass nicht der Mensch Gewalt habe! Mögen gerichtet werden die Nationen vor deinem Angesicht!", footnotes: ["℘ Ps 3,8"] },
      { number: 21, text: "Lege Furcht auf sie, HERR! Mögen die Nationen erkennen, dass sie Menschen sind! //" },
    ]},
    { number: 10, verses: [
      { number: 1, text: "Warum, HERR, stehst du fern, verbirgst dich in Zeiten der Bedrängnis*?", heading: "Psalm 10", footnotes: ["℘ Ps 44,25"] },
      { number: 2, text: "In Hochmut verfolgt der Gottlose den Elenden*. Sie werden erfasst von den Anschlägen, die jene ersonnen haben.", footnotes: ["o. Demütigen\n℘ Ps 109,16"] },
      { number: 3, text: "Denn der Gottlose rühmt sich wegen des Begehrens seiner Seele; und der Habsüchtige lästert*, er verachtet den HERRN*.", footnotes: ["w. segnet; hier euphemistisch, d. h. beschönigend gebraucht", "℘ Röm 1,32"] },
      { number: 4, text: "Der Gottlose denkt hochnäsig: »Er wird nicht nachforschen*.« »Es ist kein Gott*!«, sind alle seine Gedanken.", footnotes: ["℘ Ps 73,11; Zef 1,12", "℘ Ps 14,1"] },
      { number: 5, text: "Erfolgreich sind seine Wege allezeit*. Hoch oben sind deine Gerichte, weit von ihm entfernt; alle seine Widersacher — er bläst sie an.", footnotes: ["℘ Ps 73,3-5"] },
      { number: 6, text: "Er spricht in seinem Herzen: Ich werde nicht wanken, von Generation zu Generation in keinem Unglück sein*.", footnotes: ["℘ Pred 8,11"] },
      { number: 7, text: "Voll Fluch ist sein Mund, voll Hinterlist und Bedrückung; unter seiner Zunge ist Mühsal und Unheil*.", footnotes: ["℘ Ps 50,19; 59,13; Röm 3,14"] },
      { number: 8, text: "Er sitzt im Hinterhalt der Höfe, in Verstecken bringt er den Unschuldigen um; seine Augen spähen dem Armen nach." },
      { number: 9, text: "Er lauert im Versteck wie ein Löwe in seinem Dickicht*; er lauert, um den Elenden* zu fangen; er fängt den Elenden*, indem er ihn in sein Netz zieht*.", footnotes: ["℘ Ps 17,12", "o. Demütigen", "o. Demütigen", "℘ Mi 7,2"] },
      { number: 10, text: "Er zerschlägt, duckt sich nieder; und die Armen fallen durch seine gewaltigen Kräfte." },
      { number: 11, text: "Er spricht in seinem Herzen: Gott hat vergessen, hat verborgen sein Angesicht, ewig sieht er nicht*!", footnotes: ["℘ Ps 59,8; 64,6; 94,7; Hi 22,13"] },
      { number: 12, text: "Steh auf, HERR! Gott*, erhebe deine Hand! Vergiss nicht die Elenden*!", footnotes: ["hebr. el", "o. Demütigen\n℘ Ps 9,13; 74,19"] },
      { number: 13, text: "Warum darf der Gottlose Gott verachten, sprechen in seinem Herzen: »Du wirst nicht nachforschen«?" },
      { number: 14, text: "Du hast es gesehen*, denn du, du schaust auf Mühsal und Gram*, um es in deine Hand zu nehmen. Dir überlässt es der Arme, der Vaterlose; du bist ja Helfer*.", footnotes: ["℘ Ps 35,22", "℘ Ps 31,8", "℘ Ps 68,6; 146,9"] },
      { number: 15, text: "Zerbrich den Arm des Gottlosen* und des Bösen! Ahnde seine Gottlosigkeit, dass du sie nicht mehr findest!", footnotes: ["℘ Ps 37,17"] },
      { number: 16, text: "Der HERR ist König immer und ewig*; verschwunden sind die Nationen aus seinem Land.", footnotes: ["℘ Ps 9,8"] },
      { number: 17, text: "Den Wunsch der Sanftmütigen hast du gehört, HERR; du festigst ihr Herz, lässt aufmerken dein Ohr," },
      { number: 18, text: "um Recht zu schaffen der Waise und dem Unterdrückten*, dass künftig kein Mensch von der Erde mehr zusammenschrickt*.", footnotes: ["℘ 5Mo 10,18", "o. einen anderen erschreckt"] },
    ]},
    { number: 11, verses: [
      { number: 1, text: "Dem Chorleiter. Von David. Bei dem HERRN habe ich mich geborgen*. Wie sagt ihr zu meiner Seele: »Flieh in die Berge wie ein Vogel*«?", heading: "Psalm 11", footnotes: ["℘ Ps 7,2", "so mit alten Handschr. und Üs.; Mas. T.: Flieht in eure Berge, ihr Vögel"] },
      { number: 2, text: "Denn siehe, die Gottlosen spannen den Bogen, haben ihren Pfeil auf der Sehne gerichtet, im Finstern zu schießen auf die von Herzen Aufrichtigen*.", footnotes: ["℘ Ps 37,14; 64,4.5; Lk 20,20; Jak 5,6"] },
      { number: 3, text: "Wenn die Grundpfeiler umgerissen werden, was richtet da der Gerechte aus*?", footnotes: ["℘ Hi 17,9"] },
      { number: 4, text: "Der HERR ist in seinem heiligen Palast*, der HERR — in den Himmeln ist sein Thron*. Seine Augen schauen, seine Augenblitze prüfen die Menschenkinder*.", footnotes: ["℘ Hab 2,20", "℘ Ps 103,19; 113,5; Mt 5,34", "℘ Ps 14,2"] },
      { number: 5, text: "Der HERR prüft den Gerechten*; aber den Gottlosen und den, der Gewalttat liebt, hasst seine Seele*.", footnotes: ["℘ Ps 139,23", "℘ Ps 5,6"] },
      { number: 6, text: "Er lässt Schlingen*, Feuer und Schwefel* regnen auf die Gottlosen. Glutwind ist ihres Bechers Anteil*.", footnotes: ["Eine alte Üs. hat »Kohlen« statt »Schlingen« gelesen: er lässt Feuerkohlen und Schwefel regnen", "℘ 1Mo 19,24", "℘ Ps 18,13; 32,10"] },
      { number: 7, text: "Denn gerecht ist der HERR. Gerechte Taten liebt er*. Aufrichtige schauen sein* Angesicht.", footnotes: ["℘ Ps 33,5; 37,28; 45,8", "w. ihr"] },
    ]},
    { number: 12, verses: [
      { number: 1, text: "Dem Chorleiter. Auf der Scheminith*. Ein Psalm. Von David.", heading: "Psalm 12", footnotes: ["vgl. Ps 6,1"] },
      { number: 2, text: "Rette, HERR! — denn der Fromme ist dahin, denn die Treuen sind verschwunden* unter den Menschenkindern*.", footnotes: ["Dieses Wort kommt nur an dieser Stelle vor; der Sinn ergibt sich aus dem vorausgehenden Halbvers.", "℘ Mi 7,2"] },
      { number: 3, text: "Sie reden Lüge*, ein jeder mit seinem Nächsten; mit glatter Lippe, mit doppeltem Herzen reden sie*.", footnotes: ["o. Nichtiges", "℘ Ps 55,22; 116,11; Jer 9,8; Lk 20,20"] },
      { number: 4, text: "Der HERR möge ausrotten alle glatten Lippen, die Zunge, die große Dinge redet*,", footnotes: ["℘ Ps 140,12; Jak 3,5"] },
      { number: 5, text: "die da sagen: »Dank unserer Zunge sind wir überlegen, unsere Lippen sind mit uns; wer ist unser Herr*?«", footnotes: ["℘ Ps 31,19; 73,8.9"] },
      { number: 6, text: "Wegen der gewalttätigen Behandlung der Elenden, wegen des Seufzens der Armen will ich nun aufstehen*, spricht der HERR; ich will in Sicherheit* stellen den, gegen den man schnaubt.", footnotes: ["℘ Ps 9,13; 76,10; 2Mo 3,7.8", "w. ins Heil"] },
      { number: 7, text: "Die Worte des HERRN sind reine Worte — Silber, am Eingang* zur Erde geläutert, siebenmal gereinigt*.", footnotes: ["d. h. am Schachteingang", "℘ Ps 18,31; 19,9; 119,140"] },
      { number: 8, text: "Du, HERR, wirst sie einhalten, wirst ihn behüten vor dieser Generation ewig*.", footnotes: ["℘ Joh 17,15"] },
      { number: 9, text: "Ringsum wandeln Gottlose, während Gemeinheit emporkommt bei den Menschenkindern." },
    ]},
    { number: 13, verses: [
      { number: 1, text: "Dem Chorleiter. Ein Psalm. Von David.", heading: "Psalm 13" },
      { number: 2, text: "Bis wann*, HERR? Willst du für immer mich vergessen*? Bis wann willst du dein Angesicht vor mir verbergen?", footnotes: ["℘ Ps 6,4", "℘ Ps 77,8; Kla 5,20"] },
      { number: 3, text: "Bis wann soll ich Sorgen* hegen in meiner Seele, Kummer in meinem Herzen bei Tage? Bis wann soll sich mein Feind über mich erheben?", footnotes: ["w. Ratschläge"] },
      { number: 4, text: "Schau her, antworte mir, HERR, mein Gott! Mach hell meine Augen*, dass ich nicht zum Tod entschlafe!", footnotes: ["»Die Augen hell machen« bedeutet: jemanden lebendig machen, beleben; vgl. 1Sam 14,27.29"] },
      { number: 5, text: "Dass mein Feind nicht sage: »Ich habe ihn überwältigt!«, meine Bedränger nicht jauchzen, wenn ich wanke*.", footnotes: ["o. dass ich ins Wanken gebracht werde\n℘ Ps 25,2; 38,17"] },
      { number: 6, text: "Ich aber, ich habe auf deine Gnade vertraut; mein Herz soll jauchzen über deine Rettung*. Ich will dem HERRN singen, denn er hat wohlgetan an mir*.", footnotes: ["℘ Ps 9,15", "℘ Ps 28,7"] },
    ]},
    { number: 14, verses: [
      { number: 1, text: "*Dem Chorleiter. Von David. Der Tor spricht in seinem Herzen: »Es ist kein Gott*!« Sie haben Verderben angerichtet, sie tun abscheuliche Taten; da ist keiner, der Gutes tut*.", heading: "Psalm 14", footnotes: ["℘ V. 1-7: Ps 53", "℘ Ps 10,4", "℘ Pred 7,20"] },
      { number: 2, text: "Der HERR hat vom Himmel herniedergeschaut auf die Menschenkinder*, um zu sehen, ob ein Verständiger da ist, einer, der Gott sucht!", footnotes: ["℘ Ps 11,4; 33,13"] },
      { number: 3, text: "Alle sind abgewichen, sie sind alle verdorben*; da ist keiner, der Gutes tut, auch nicht einer*.", footnotes: ["℘ 1Mo 6,12", "℘ Röm 3,10-12"] },
      { number: 4, text: "Haben denn keine Erkenntnis alle, die Böses tun, die mein Volk fressen, als äßen sie Brot*? Den HERRN rufen sie nicht an*.", footnotes: ["℘ Mi 3,3", "℘ Jes 64,6"] },
      { number: 5, text: "Da überfiel sie Schrecken, denn Gott ist beim Geschlecht* des Gerechten.", footnotes: ["o. bei der Generation"] },
      { number: 6, text: "Die Pläne des Elenden wollt ihr zuschanden machen, aber seine Zuflucht ist der HERR." },
      { number: 7, text: "Käme doch aus Zion die Rettung für Israel! Wenn der HERR die Gefangenschaft seines Volkes wendet, wird Jakob jubeln, Israel sich freuen*.", footnotes: ["℘ Ps 126,1.2; Jes 35,10"] },
    ]},
    { number: 15, verses: [
      { number: 1, text: "Ein Psalm. Von David. HERR, wer darf in deinem Zelt* weilen? Wer darf wohnen auf deinem heiligen Berg?", heading: "Psalm 15", footnotes: ["℘ Ps 24,3"] },
      { number: 2, text: "Der rechtschaffen wandelt und Gerechtigkeit übt* und Wahrheit redet in seinem Herzen*,", footnotes: ["℘ Jes 33,15; Apg 10,35", "℘ Ps 140,14"] },
      { number: 3, text: "nicht verleumdet mit seiner Zunge*, kein Übel tut seinem Gefährten und keine Schmähung bringt auf seinen Nächsten*,", footnotes: ["℘ Tit 3,2", "℘ 3Mo 19,16; Röm 13,10"] },
      { number: 4, text: "in dessen Augen der Verworfene verachtet ist, der aber die ehrt, die den HERRN fürchten; der, hat er zum Schaden geschworen, es nicht ändert;" },
      { number: 5, text: "der sein Geld nicht auf Zins* gibt*, und kein Bestechungsgeschenk nimmt gegen den Unschuldigen*. Wer solches tut, wird nicht wanken in Ewigkeit*.", footnotes: ["o. Wucher", "℘ 2Mo 22,24", "℘ 5Mo 16,19", "℘ Spr 10,30"] },
    ]},
    { number: 16, verses: [
      { number: 1, text: "Ein Miktam*. Von David. Bewahre mich, Gott*, denn ich berge mich bei dir*!", heading: "Psalm 16", footnotes: ["Der Sinn des Wortes ist unbekannt. Miktam auch in Ps 56—60.", "℘ Ps 17,8", "℘ Ps 7,2"] },
      { number: 2, text: "Ich habe zum HERRN gesagt*: »Du bist mein Herr; es gibt kein Glück für mich außer dir.«", footnotes: ["so mit mehreren Handschr. und Üs.; Mas. T.: Du hast gesagt meine Seele"] },
      { number: 3, text: "An den Heiligen, die auf Erden sind, an den Herrlichen ist all mein Wohlgefallen." },
      { number: 4, text: "Zahlreich sind die Schmerzen derer, die einem anderen Gott nachlaufen; ich werde ihre Trankopfer von Blut nicht spenden und ihre Namen nicht auf meine Lippen nehmen." },
      { number: 5, text: "Der HERR ist das Teil meines Erbes* und mein Becher; du bist es, der mein Los festlegt.", footnotes: ["℘ Kla 3,24"] },
      { number: 6, text: "Die Messschnüre sind mir gefallen auf liebliches Land; ja, mein Erbteil* gefällt mir.", footnotes: ["℘ Ps 61,6; 1Petr 1,4"] },
      { number: 7, text: "Ich preise den HERRN, der mich beraten hat, selbst des Nachts unterweisen mich meine Nieren*.", footnotes: ["Die Nieren gelten als Innerstes des Menschen und Sitz des Gewissens. Vgl. Ps 7,10; 26,2; 73,21; 139,13."] },
      { number: 8, text: "Ich habe den HERRN stets vor Augen*; weil er zu meiner Rechten ist, werde ich nicht wanken*.", footnotes: ["w. vor mich gelegt", "℘ Ps 21,8; 62,3.7"] },
      { number: 9, text: "Darum freut sich mein Herz und jauchzt meine Seele*. Auch mein Fleisch wird in Sicherheit ruhen*.", footnotes: ["w. Ehre, o. Würde", "℘ Lk 1,47"] },
      { number: 10, text: "Denn meine Seele wirst du dem Scheol nicht lassen, wirst nicht zugeben, dass dein Frommer die Grube sehe*.", footnotes: ["℘ Apg 2,31"] },
      { number: 11, text: "Du wirst mir kundtun den Weg des Lebens*; Fülle von Freuden ist vor deinem Angesicht*, Lieblichkeiten in deiner Rechten immerdar.", footnotes: ["℘ Mt 7,14", "℘ Ps 68,4; Apg 2,25-28"] },
    ]},
    { number: 17, verses: [
      { number: 1, text: "Ein Gebet. Von David. Höre, HERR, die gerechte Sache, horche auf mein Schreien, nimm zu Ohren mein Gebet* von Lippen ohne Trug*!", heading: "Psalm 17", footnotes: ["℘ Ps 54,4; 55,2; 61,2; 84,9; 86,6; 88,3; 102,2; 143,1", "o. Hinterlist"] },
      { number: 2, text: "Von deinem Angesicht gehe mein Recht aus! Deine Augen mögen Aufrichtigkeit sehen." },
      { number: 3, text: "Du hast mein Herz geprüft*, hast mich des Nachts durchforscht*; du hast mich geläutert* — *nichts findest du. Ich habe überlegt*: nichts wird meinem Mund entschlüpfen.", footnotes: ["℘ 1Chr 29,17", "℘ Ps 139,1", "℘ Ps 26,2; 139,23", "bei Änderung der Vokalisierung: nicht findest du eine Schandtat an mir", "bei Änderung der Vokalisierung: nicht findest du eine Schandtat an mir"] },
      { number: 4, text: "Beim Treiben der Menschen habe ich mich nach dem Wort deiner Lippen gehütet* vor den Wegen des Gewalttätigen.", footnotes: ["℘ Ps 119,9.11"] },
      { number: 5, text: "Meine Schritte hielten sich in deinen Spuren, meine Tritte haben nicht gewankt*.", footnotes: ["℘ Ps 18,37"] },
      { number: 6, text: "Ich rufe dich an, denn du erhörst mich, Gott*. Neige dein Ohr zu mir, höre meine Rede!", footnotes: ["℘ Ps 4,4"] },
      { number: 7, text: "Erweise wunderbar deine Gnade*, du Retter derer, die sich bergen vor den Empörern bei deiner Rechten*.", footnotes: ["eigentlich Mehrzahl, etwa: die Beweise deiner Gnade (= Gemeinschaftstreue)", "o. gegen deine Rechte"] },
      { number: 8, text: "Bewahre mich wie den Augapfel*, birg mich im Schatten deiner Flügel*", footnotes: ["w. wie die Pupille\n℘ Ps 16,1; 5Mo 32,10", "℘ Ps 36,8; 57,2; 61,5; 91,4; Rt 2,12"] },
      { number: 9, text: "vor den Gottlosen, die mich zerstören, meinen Todfeinden, die mich umzingeln." },
      { number: 10, text: "Mit ihrem Fett* verschließen sie sich, mit ihrem Mund reden sie aus Anmaßung*.", footnotes: ["Fett bedeckt die inneren Organe, mit denen die Empfindungen des Erbarmens und Mitgefühls in Verbindung gebracht werden.", "℘ Jud 16"] },
      { number: 11, text: "Unsere Schritte — jetzt haben sie uns umringt*; sie richten ihre Augen darauf, uns zu Boden zu strecken.", footnotes: ["Andere übersetzen mit Textkorr.: Sie spähen mir nach, jetzt haben sie mich umringt"] },
      { number: 12, text: "Er ist gleich einem Löwen, gierig nach Raub, und wie ein Junglöwe, der im Versteck sitzt*.", footnotes: ["℘ Ps 10,9"] },
      { number: 13, text: "Steh auf, HERR*, tritt ihm entgegen, wirf ihn nieder! Rette meine Seele vor dem Gottlosen durch dein Schwert,", footnotes: ["℘ Ps 10,12"] },
      { number: 14, text: "vor den Leuten durch deine Hand, HERR, vor den Leuten, deren Teil im Leben von dieser Welt ist! Was du zugedacht hast* — damit füllst du* ihren Bauch, dass noch ihre Söhne davon satt werden und ihren Kindern den Rest hinterlassen*.", footnotes: ["w. Und dein Aufbewahrtes", "o. fülle", "℘ Lk 16,25"] },
      { number: 15, text: "Ich aber, ich werde dein Angesicht schauen in Gerechtigkeit*, werde gesättigt werden, wenn ich erwache, mit deinem Bild*.", footnotes: ["℘ Mt 5,8; Offb 22,4", "℘ 1Jo 3,2"] },
    ]},
    { number: 18, verses: [
      { number: 1, text: "Dem Chorleiter. Von dem Knecht des HERRN, von David, der die Worte dieses Liedes zum HERRN redete an dem Tag, als der HERR ihn gerettet hatte aus der Hand aller seiner Feinde und aus der Hand Sauls.", heading: "Psalm 181" },
      { number: 2, text: "Und er sprach: Ich liebe dich, HERR*, meine Stärke!", footnotes: ["℘ Ps 116,1"] },
      { number: 3, text: "Der HERR ist mein Fels und meine Burg* und mein Retter, mein Gott ist mein Hort, bei dem ich mich berge, mein Schild* und das Horn meines Heils, meine hohe Feste*.", footnotes: ["℘ Ps 31,4; 71,3; 91,2", "℘ Ps 3,4", "℘ Ps 62,3.7"] },
      { number: 4, text: "»Gepriesen!«, rufe ich* zum HERRN, so werde ich vor meinen Feinden gerettet.", footnotes: ["Andere übersetzen mit Textkorr.: Lobend rufe ich; andere: »Durchbohrt!«, rufe ich"] },
      { number: 5, text: "Es umfingen mich Bande des Todes*, und Bäche des Verderbens erschreckten mich*.", footnotes: ["℘ Ps 116,3", "℘ Ps 69,16; 124,4"] },
      { number: 6, text: "Fesseln des Scheols umgaben mich, ich stand vor den Fallen des Todes*.", footnotes: ["w. Fallen des Todes traten mir entgegen\n℘ Ps 55,5"] },
      { number: 7, text: "In meiner Bedrängnis rief ich zum HERRN, und ich schrie zu meinem Gott. Er hörte aus seinem Tempel meine Stimme, und mein Schrei vor ihm drang an seine Ohren*.", footnotes: ["℘ Ps 34,16.18; 39,13; 40,2"] },
      { number: 8, text: "Da wankte und bebte die Erde, die Grundfesten der Berge erzitterten und wankten*, denn er war von Zorn entbrannt.", footnotes: ["℘ Nah 1,5"] },
      { number: 9, text: "Rauch stieg auf von seiner Nase, und Feuer fraß aus seinem Mund*, glühende Kohlen brannten aus ihm*.", footnotes: ["℘ Ps 50,3; 97,3", "℘ 2Mo 19,18; Hebr 12,29"] },
      { number: 10, text: "Er neigte den Himmel und fuhr hernieder*, und Dunkel war unter seinen Füßen.", footnotes: ["℘ Ps 144,5"] },
      { number: 11, text: "Er fuhr auf einem Cherub und flog daher, so schwebte er auf den Flügeln des Windes*.", footnotes: ["℘ Ps 104,3"] },
      { number: 12, text: "Er machte Finsternis zu seinem Versteck rings um sich her, zu seiner Laube Wasserdunkel, dichtes Gewölk*.", footnotes: ["℘ Jes 50,3"] },
      { number: 13, text: "Aus dem Glanz vor ihm zogen seine Wolken vorüber mit Hagel und Feuerkohlen*.", footnotes: ["℘ Ps 11,6"] },
      { number: 14, text: "Und der HERR donnerte im Himmel, und der Höchste ließ seine Stimme erschallen* mit Hagel und Feuerkohlen.", footnotes: ["℘ Ps 29,3; Hi 37,4.5"] },
      { number: 15, text: "Und er schoss seine Pfeile und zerstreute sie, er schleuderte Blitze und verwirrte sie*.", footnotes: ["℘ Ps 77,18; 144,6; 1Sam 7,10"] },
      { number: 16, text: "Da wurden sichtbar die Betten des Wassers*, und die Fundamente der Welt wurden aufgedeckt vor deinem Schelten, HERR, vor dem Schnauben des Hauchs deiner Nase.", footnotes: ["℘ Nah 1,4"] },
      { number: 17, text: "Er griff aus der Höhe, erfasste mich, zog mich heraus aus großen Wassern*.", footnotes: ["℘ Ps 144,7"] },
      { number: 18, text: "Er rettete mich vor meinem starken Feind und vor meinen Hassern, denn sie waren mächtiger als ich*.", footnotes: ["℘ Ps 138,7"] },
      { number: 19, text: "Sie ereilten mich* am Tage meines Unglücks, aber der HERR wurde mir zur Stütze.", footnotes: ["w. Sie traten mir entgegen"] },
      { number: 20, text: "Und er führte mich heraus ins Weite*, er befreite mich, weil er Gefallen an mir hatte.", footnotes: ["℘ Ps 118,5"] },
      { number: 21, text: "Der HERR handelte an mir nach meiner Gerechtigkeit, nach der Reinheit meiner Hände vergalt er mir*.", footnotes: ["℘ Ps 7,9"] },
      { number: 22, text: "Denn ich habe die Wege des HERRN eingehalten und bin von meinem Gott nicht gottlos abgewichen*.", footnotes: ["w. bin nicht gottlos gewesen, weg von meinem Gott\n℘ Hi 23,11"] },
      { number: 23, text: "Denn alle seine Rechtsbestimmungen waren vor mir, und seine Ordnungen wies ich nicht von mir*.", footnotes: ["℘ Ps 119,30"] },
      { number: 24, text: "Auch war ich untadelig* gegen ihn und hütete mich vor meiner Schuld.", footnotes: ["o. rechtschaffen; o. lauter; o. vollkommen"] },
      { number: 25, text: "So vergalt der HERR mir nach meiner Gerechtigkeit, nach der Reinheit meiner Hände vor seinen Augen." },
      { number: 26, text: "Gegen den Treuen verhältst du dich treu, gegen den untadeligen Mann untadelig*.", footnotes: ["o. rechtschaffen; o. lauter; o. vollkommen"] },
      { number: 27, text: "Gegen den Reinen zeigst du dich rein, gegen den Verkehrten aber verdreht." },
      { number: 28, text: "Ja, du rettest das arme* Volk und erniedrigst hochmütige Augen.", footnotes: ["o. demütige"] },
      { number: 29, text: "Ja, du lässt meine Leuchte strahlen. Der HERR, mein Gott, erhellt meine Finsternis*.", footnotes: ["℘ Ps 27,1"] },
      { number: 30, text: "Denn mit dir erstürme ich einen Wall*, und mit meinem Gott überspringe ich eine Mauer*.", footnotes: ["d. h. eine Feldabgrenzung", "d. h. eine Feldabgrenzung\n℘ Ps 60,14"] },
      { number: 31, text: "Gott — sein Weg ist untadelig*; des HERRN Wort ist lauter*; ein Schild ist er allen, die sich bei ihm bergen.", footnotes: ["o. rechtschaffen; o. lauter; o. vollkommen", "℘ Ps 12,7"] },
      { number: 32, text: "Denn wer ist Gott außer dem HERRN? Und wer ist ein Fels als nur unser Gott*?", footnotes: ["℘ Jes 44,8"] },
      { number: 33, text: "Gott umgürtet mich mit Kraft und untadelig* macht er meinen Weg.", footnotes: ["o. rechtschaffen; o. lauter; o. vollkommen"] },
      { number: 34, text: "Er macht meine Füße den Hirschen gleich, und stellt mich hin auf meine Höhen*.", footnotes: ["℘ Hab 3,19"] },
      { number: 35, text: "Er lehrt meine Hände das Kämpfen und meine Arme spannen den ehernen Bogen*.", footnotes: ["℘ Ps 144,1"] },
      { number: 36, text: "Und du gabst mir den Schild deines Heils, und deine Rechte stützte mich*, und deine Herabneigung* machte mich groß.", footnotes: ["℘ Ps 63,9; Jes 41,10", "w. Demut; in 2Sam 22,36 heißt es mit anderer Vokalisierung: deine Antworten"] },
      { number: 37, text: "Du schaffst Raum meinen Schritten unter mir*, und meine Knöchel haben nicht gewankt*.", footnotes: ["℘ Ps 31,9", "℘ Ps 17,5"] },
      { number: 38, text: "Meinen Feinden jagte ich nach und erreichte sie, und ich kehrte nicht um, bis ich sie aufgerieben hatte." },
      { number: 39, text: "Ich zerschmetterte sie, dass sie nicht mehr aufstehen konnten; sie fielen unter meine Füße." },
      { number: 40, text: "Und du umgürtetest mich mit Kraft zum Kampf, beugtest unter mich, die gegen mich aufstanden." },
      { number: 41, text: "Meine Feinde aber — du hast sie vor mir in die Flucht geschlagen*, und meine Hasser, ich habe sie vernichtet*.", footnotes: ["w. Was aber meine Feinde betrifft — du hast gegeben, dass sie mir den Rücken zuwenden", "o. brachte sie zum Schweigen\n℘ Ps 118,10"] },
      { number: 42, text: "Sie schrien — aber da war kein Retter — zum HERRN, doch er antwortete ihnen nicht*.", footnotes: ["℘ Spr 1,28"] },
      { number: 43, text: "Und ich zermalmte sie wie Staub vor dem Wind; wie Straßenkot schüttete ich sie aus." },
      { number: 44, text: "Du hast mich gerettet aus den Streitigkeiten des Volkes; du hast mich zum Haupt der Nationen gesetzt; ein Volk, das ich nicht kannte, dient mir." },
      { number: 45, text: "Sowie ihr Ohr hörte, gehorchten sie mir; die Söhne der Fremde schmeichelten mir*.", footnotes: ["℘ Ps 66,3; 81,16"] },
      { number: 46, text: "Die Söhne der Fremde sanken hin und zitterten hervor aus ihren Festungen." },
      { number: 47, text: "Der HERR lebt! Gepriesen sei mein Fels und erhoben der Gott meines Heils*!", footnotes: ["℘ Ps 95,1"] },
      { number: 48, text: "Der Gott, der mir Rache gab und mir die Völker unterwarf," },
      { number: 49, text: "der mich rettete vor meinen zornigen Feinden*. Du erhöhtest mich über die, die gegen mich aufstanden; von dem Mann der Gewalttat hast du mich befreit.", footnotes: ["℘ Lk 1,71.74"] },
      { number: 50, text: "Darum will ich dich preisen unter den Völkern*, HERR, und will spielen deinem Namen*,", footnotes: ["℘ Ps 57,10", "℘ Röm 15,9"] },
      { number: 51, text: "der seinem König große Rettungen schenkt* und Gnade erweist seinem Gesalbten, David und seinen Nachkommen ewig*.", footnotes: ["w. der groß macht die Rettungen seines Königs\n℘ Ps 144,10", "℘ Ps 89,30-38"] },
    ]},
    { number: 19, verses: [
      { number: 1, text: "Dem Chorleiter. Ein Psalm. Von David.", heading: "Psalm 19" },
      { number: 2, text: "Der Himmel erzählt die Herrlichkeit Gottes, und das Himmelsgewölbe* verkündet seiner Hände Werk*.", footnotes: ["im Hebr. das gleiche Wort wie 1Mo 1,6—8", "℘ Ps 8,4; Röm 1,20"] },
      { number: 3, text: "Ein Tag sprudelt dem anderen Kunde zu, und eine Nacht meldet der anderen Kenntnis —" },
      { number: 4, text: "ohne Rede und ohne Worte, mit unhörbarer Stimme." },
      { number: 5, text: "Ihre Messschnur geht aus über die ganze Erde und bis an das Ende der Welt ihre Sprache. Dort hat er der Sonne ein Zelt gesetzt." },
      { number: 6, text: "Und sie, wie ein Bräutigam aus seinem Gemach tritt sie hervor; sie freut sich wie ein Held, die Bahn zu durchlaufen." },
      { number: 7, text: "Vom Ende des Himmels geht sie aus und läuft um bis an sein Ende; nichts ist vor ihrer Glut verborgen." },
      { number: 8, text: "Das Gesetz des HERRN ist vollkommen* und erquickt die Seele; das Zeugnis des HERRN ist zuverlässig* und macht den Einfältigen weise*.", footnotes: ["℘ Röm 7,12", "℘ Ps 93,5; 111,7", "℘ Ps 119,130"] },
      { number: 9, text: "Die Vorschriften des HERRN sind richtig und erfreuen das Herz*; das Gebot des HERRN ist lauter* und macht die Augen hell.", footnotes: ["℘ Ps 119,111", "℘ Ps 12,7"] },
      { number: 10, text: "Die Furcht des HERRN ist rein und besteht in Ewigkeit. Die Rechtsbestimmungen des HERRN sind Wahrheit*, sie sind gerecht allesamt;", footnotes: ["o. Treue"] },
      { number: 11, text: "sie, die köstlicher sind als Gold, ja viel gediegenes Gold*, und süßer als Honig und Wabenhonig*.", footnotes: ["℘ Ps 119,72", "℘ Ps 119,103"] },
      { number: 12, text: "Auch wird dein Knecht durch sie gewarnt; in ihrer Befolgung liegt großer Lohn*.", footnotes: ["℘ Jak 1,25"] },
      { number: 13, text: "Verirrungen — wer bemerkt sie? Von den verborgenen Sünden sprich mich frei!" },
      { number: 14, text: "Auch von Übermütigen halte deinen Knecht zurück; sie sollen nicht über mich herrschen! Dann bin ich tadellos und bin rein von schwerem Vergehen." },
      { number: 15, text: "Lass die Reden meines Mundes* und das Sinnen meines Herzens wohlgefällig vor dir sein, HERR, mein Fels und mein Erlöser*!", footnotes: ["℘ Ps 104,34; 119,108; Phil 4,8", "℘ Ps 78,35"] },
    ]},
    { number: 20, verses: [
      { number: 1, text: "Dem Chorleiter. Ein Psalm. Von David.", heading: "Psalm 20" },
      { number: 2, text: "Der HERR erhöre dich am Tag der Bedrängnis, der Name des Gottes Jakobs mache dich unangreifbar*.", footnotes: ["℘ Spr 18,10"] },
      { number: 3, text: "Er sende dir Hilfe aus dem Heiligtum, und von Zion aus unterstütze er dich*.", footnotes: ["℘ Ps 128,5; 134,3"] },
      { number: 4, text: "Er gedenke aller deiner Speisopfer, und dein Brandopfer wolle er annehmen! //" },
      { number: 5, text: "Er gebe dir nach deinem Herzen, und alle deine Pläne erfülle er*!", footnotes: ["℘ Ps 21,3"] },
      { number: 6, text: "Jubeln wollen wir über dein Heil*, im Namen unseres Gottes das Panier erheben. Der HERR erfülle alle deine Bitten!", footnotes: ["℘ Ps 9,15"] },
      { number: 7, text: "Jetzt habe ich erkannt, dass der HERR seinem Gesalbten hilft; aus seinem heiligen Himmel wird er ihn erhören durch Heilstaten seiner Rechten." },
      { number: 8, text: "Diese denken an Wagen und jene an Rosse*, wir aber denken an den Namen des HERRN, unseres Gottes*.", footnotes: ["℘ Ps 33,16.17", "℘ Ps 124,8; 2Chr 14,11"] },
      { number: 9, text: "Jene krümmen sich und fallen, wir aber stehen und bleiben aufrecht*.", footnotes: ["℘ Jes 40,31"] },
      { number: 10, text: "HERR, hilf! Der König erhöre* uns am Tage unseres Rufens!", footnotes: ["Mit LXX nicht »er erhöre«, sondern »und erhöre«. Demnach lautete V. 10: HERR, hilf dem König! Und erhöre uns . . ."] },
    ]},
    { number: 21, verses: [
      { number: 1, text: "Dem Chorleiter. Ein Psalm. Von David.", heading: "Psalm 21" },
      { number: 2, text: "HERR, über deine Kraft* freut sich der König, und wie sehr jauchzt er über deine Hilfe!", footnotes: ["o. in deiner Kraft"] },
      { number: 3, text: "Den Wunsch seines Herzens hast du ihm gewährt*, und das Verlangen seiner Lippen nicht verweigert. //", footnotes: ["℘ Ps 20,5.6"] },
      { number: 4, text: "Denn mit Segnungen an Gutem kamst du ihm entgegen; auf sein Haupt setztest du eine Krone von Gold*.", footnotes: ["℘ Offb 14,14"] },
      { number: 5, text: "Leben erbat er von dir, du hast es ihm gegeben: Länge der Tage immer und ewig*.", footnotes: ["℘ Ps 61,7; 133,3"] },
      { number: 6, text: "Groß ist seine Herrlichkeit durch deine Hilfe; Majestät und Pracht legtest du auf ihn*.", footnotes: ["℘ 2Sam 7,9"] },
      { number: 7, text: "Denn zu Segnungen setzt du ihn für immer*; du erfreust ihn mit Freude vor deinem Angesicht.", footnotes: ["℘ Ps 45,3; 72,17"] },
      { number: 8, text: "Denn auf den HERRN vertraut der König, und durch des Höchsten Gnade wird er nicht wanken*.", footnotes: ["℘ Ps 16,8"] },
      { number: 9, text: "Deine Hand wird alle deine Feinde finden, deine Rechte wird finden deine Hasser*.", footnotes: ["℘ Ps 18,38"] },
      { number: 10, text: "Einem Feuerofen wirst du sie gleichmachen zur Zeit deines Erscheinens; der HERR in seinem Zorn wird sie verschlingen, und Feuer wird sie verzehren*.", footnotes: ["℘ Mal 3,19"] },
      { number: 11, text: "Ihre Frucht wirst du von der Erde vertilgen* und ihre Nachkommen aus den Menschenkindern*.", footnotes: ["w. verloren gehen lassen", "℘ Ps 109,13"] },
      { number: 12, text: "Haben sie auch Böses gegen dich geplant, einen Anschlag ersonnen: nichts werden sie zustande bringen*.", footnotes: ["℘ Jes 8,10"] },
      { number: 13, text: "Denn du wirst machen, dass sie den Rücken kehren, wirst deine Bogensehne gegen ihr Angesicht richten." },
      { number: 14, text: "Erhebe dich, HERR, in deiner Kraft! Wir wollen singen und spielen deiner Macht." },
    ]},
    { number: 22, verses: [
      { number: 1, text: "Dem Chorleiter. Nach »Hirschkuh der Morgenröte«. Ein Psalm. Von David.", heading: "Psalm 22" },
      { number: 2, text: "Mein Gott, mein Gott, warum hast du mich verlassen*? Fern von meiner Rettung sind die Worte meines Gestöhns.", footnotes: ["℘ Mt 27,46; Mk 15,34"] },
      { number: 3, text: "Mein Gott, ich rufe bei Tage, und du antwortest nicht; und bei Nacht, und mir wird keine Ruhe*.", footnotes: ["℘ Ps 88,2"] },
      { number: 4, text: "Doch du bist heilig, der du wohnst unter den Lobgesängen Israels*.", footnotes: ["o. Du thronst als Heiliger, du Lobgesang Israels\n℘ 2Chr 5,13"] },
      { number: 5, text: "Auf dich vertrauten unsere Väter; sie vertrauten, und du rettetest sie." },
      { number: 6, text: "Zu dir schrien sie um Hilfe und wurden gerettet; sie vertrauten auf dich und wurden nicht zuschanden*.", footnotes: ["℘ Ps 25,3"] },
      { number: 7, text: "Ich aber bin ein Wurm und kein Mensch, ein Spott der Leute und verachtet vom Volk*.", footnotes: ["℘ Jes 53,3; Joh 19,3"] },
      { number: 8, text: "Alle, die mich sehen, spotten über mich; sie verziehen die Lippen, schütteln den Kopf*:", footnotes: ["℘ Ps 109,25; Hi 16,4; Mt 27,39"] },
      { number: 9, text: "»Er hat es auf den HERRN gewälzt*, der rette ihn, befreie ihn, denn er hat ja Gefallen an ihm*!«", footnotes: ["alte Üs. und Mas. T.: Wälze ab auf den HERRN", "℘ Mt 27,43"] },
      { number: 10, text: "Ja, du bist es, der mich aus dem Mutterleib gezogen hat, der mir Vertrauen einflößte an meiner Mutter Brüsten." },
      { number: 11, text: "Auf dich bin ich geworfen von Mutterschoß her, von meiner Mutter Leib an bist du mein Gott*.", footnotes: ["℘ Ps 71,6"] },
      { number: 12, text: "Sei nicht fern von mir*, denn Not ist nahe, denn kein Helfer ist da*.", footnotes: ["℘ Ps 35,22; 38,22", "℘ Ps 7,3; 38,23; 40,14; 69,18; 70,2.6"] },
      { number: 13, text: "Viele Stiere haben mich umgeben, starke Stiere von Baschan mich umringt." },
      { number: 14, text: "Sie haben ihr Maul gegen mich aufgesperrt*, wie ein Löwe, reißend und brüllend.", footnotes: ["℘ Ps 35,21; Hi 16,10; Kla 3,46; Joh 19,6"] },
      { number: 15, text: "Wie Wasser bin ich hingeschüttet*, und alle meine Gebeine haben sich zertrennt; wie Wachs ist mein Herz geworden, zerschmolzen in meinem Inneren.", footnotes: ["℘ 2Sam 14,14"] },
      { number: 16, text: "Meine Kraft* ist vertrocknet* wie gebrannter Ton, und meine Zunge klebt an meinem Gaumen*; und in den Staub des Todes legst du mich.", footnotes: ["mit Austausch zweier Buchstaben: Kehle", "℘ Ps 38,11", "℘ Joh 19,28"] },
      { number: 17, text: "Denn Hunde haben mich umgeben, eine Rotte von Übeltätern hat mich umzingelt. Sie haben meine Hände und meine Füße durchgraben*.", footnotes: ["so mit LXX; andere alte Üs.: gebunden; Mas. T.: eine Rotte von Übeltätern hat mich umzingelt, meine Hände und Füße wie die eines Löwen\n℘ Joh 19,18; 20,25.27"] },
      { number: 18, text: "Alle meine Gebeine könnte ich zählen. Sie schauen und sehen auf mich herab." },
      { number: 19, text: "Sie teilen meine Kleider unter sich, und über mein Gewand werfen sie das Los*.", footnotes: ["℘ Mt 27,35"] },
      { number: 20, text: "Du aber, HERR, sei nicht fern! Meine Stärke, eile mir zu Hilfe*!", footnotes: ["℘ Ps 7,3; 38,23; 40,14; 69,18; 70,2.6"] },
      { number: 21, text: "Errette vom Schwert meine Seele*, meine einzige aus der Gewalt des Hundes*!", footnotes: ["℘ Ps 35,17", "w. aus der Hand des Hundes"] },
      { number: 22, text: "Rette mich aus dem Rachen des Löwen* und von den Hörnern der Büffel! Du hast mich erhört*.", footnotes: ["℘ 2Tim 4,17", "o. Du hast mir geantwortet"] },
      { number: 23, text: "Verkündigen will ich deinen Namen meinen Brüdern*; inmitten der Versammlung will ich dich loben*.", footnotes: ["℘ Joh 20,17; Hebr 2,12", "℘ Ps 26,12; 35,18; 109,30; 111,1"] },
      { number: 24, text: "Ihr, die ihr den HERRN fürchtet, lobet ihn; alle Nachkommen Jakobs, verherrlicht ihn, und scheut euch vor ihm, alle Nachkommen Israels!" },
      { number: 25, text: "Denn er hat nicht verachtet noch verabscheut das Elend des Elenden, noch sein Angesicht vor ihm verborgen; und als er zu ihm schrie, hörte er*.", footnotes: ["℘ Hebr 5,7"] },
      { number: 26, text: "Von dir kommt mein Lobgesang in großer Versammlung*; erfüllen will ich meine Gelübde vor denen, die ihn fürchten*.", footnotes: ["℘ Ps 40,10", "℘ Ps 50,14; 116,14; Jon 2,10"] },
      { number: 27, text: "Die Sanftmütigen werden essen und satt werden; es werden den HERRN loben, die ihn suchen; leben wird euer Herz für immer*.", footnotes: ["℘ Ps 69,33"] },
      { number: 28, text: "Es werden daran gedenken und zum HERRN umkehren alle Enden der Erde; vor dir werden niederfallen alle Geschlechter der Nationen*.", footnotes: ["℘ Ps 86,9; Jes 2,2-4; Apg 15,17; Offb 15,4"] },
      { number: 29, text: "Denn dem HERRN gehört das Königtum, er herrscht über die Nationen." },
      { number: 30, text: "*Es aßen und fielen nieder alle Fetten der Erde*; vor ihm werden sich beugen* alle, die in den Staub hinabfuhren, und der, der seine Seele nicht am Leben erhalten konnte*.", footnotes: ["Bei Wegfall eines doppelt geschriebenen Buchstabens und durch Änderung eines anderen heißt es: Nur ihm werden huldigen alle in der Erde Schlafenden", "Bei Wegfall eines doppelt geschriebenen Buchstabens und durch Änderung eines anderen heißt es: Nur ihm werden huldigen alle in der Erde Schlafenden", "℘ Phil 2,10", "w. nicht lebendig macht"] },
      { number: 31, text: "Nachkommen werden ihm dienen*; man wird vom Herrn erzählen einer Generation, die kommen wird.", footnotes: ["℘ Jes 53,10"] },
      { number: 32, text: "Sie werden verkünden seine Gerechtigkeit einem Volk, das noch geboren wird, denn er hat es getan*.", footnotes: ["℘ Ps 102,19"] },
    ]},
    { number: 23, verses: [
      { number: 1, text: "Ein Psalm. Von David. Der HERR ist mein Hirte*, mir wird nichts mangeln*.", heading: "Psalm 23", footnotes: ["℘ Joh 10,11.14", "℘ Ps 34,10.11"] },
      { number: 2, text: "Er lagert mich auf grünen Auen*, er führt mich zu stillen Wassern*.", footnotes: ["℘ Hes 34,14", "℘ Offb 7,17"] },
      { number: 3, text: "Er erquickt meine Seele*. Er leitet mich in Pfaden der Gerechtigkeit* um seines Namens willen*.", footnotes: ["℘ Jer 31,25", "℘ Spr 4,11", "℘ Ps 31,4; 106,8; 109,21"] },
      { number: 4, text: "Auch wenn ich wandere im Tal des Todesschattens*, fürchte ich kein Unheil, denn du bist bei mir*; dein Stecken und dein Stab, sie trösten mich.", footnotes: ["w. der Finsternis", "℘ Jes 43,2"] },
      { number: 5, text: "Du bereitest vor mir einen Tisch angesichts meiner Feinde; du hast mein Haupt mit Öl gesalbt*, mein Becher fließt über.", footnotes: ["℘ Ps 92,11"] },
      { number: 6, text: "Nur Güte und Gnade werden mir folgen alle Tage meines Lebens; und ich kehre zurück ins* Haus des HERRN lebenslang*.", footnotes: ["LXX, die syr. und aram. Üs. lesen: und ich werde wohnen im", "℘ Ps 27,4"] },
    ]},
    { number: 24, verses: [
      { number: 1, text: "Von David. Ein Psalm. Des HERRN ist die Erde und ihre Fülle, die Welt und die darauf wohnen*.", heading: "Psalm 24", footnotes: ["℘ Ps 50,12; 5Mo 10,14; 1Kor 10,26"] },
      { number: 2, text: "Denn er, er hat sie gegründet* über Meeren und über Strömen sie festgestellt*.", footnotes: ["o. ihre Grundmauern gelegt\n℘ Ps 89,12", "℘ Ps 136,6; 1Mo 1,9.10; 2Petr 3,5"] },
      { number: 3, text: "Wer darf hinaufsteigen auf den Berg des HERRN und wer darf stehen an seiner heiligen Stätte*?", footnotes: ["℘ Ps 15,1"] },
      { number: 4, text: "Der unschuldige Hände* und ein reines Herz hat*, der seine Seele nicht auf Falsches* richtet und nicht schwört zum Betrug*.", footnotes: ["℘ Ps 26,6", "℘ Ps 51,12; 73,1; Mt 5,8; Jak 4,8", "o. Nichtiges; o. Lüge", "o. zur Hinterlist"] },
      { number: 5, text: "Er wird Segen empfangen vom HERRN und Gerechtigkeit von dem Gott seines Heils." },
      { number: 6, text: "Das ist das Geschlecht derer, die nach ihm trachten, die dein Angesicht suchen*: Jakob*. //", footnotes: ["℘ Ps 27,8", "die syr. Üs.: Gott Jakobs; LXX: die das Angesicht des Gottes Jakobs suchen"] },
      { number: 7, text: "Erhebt, ihr Tore, eure Häupter, und erhebt euch, ihr ewigen* Pforten, dass der König der Herrlichkeit einziehe!", footnotes: ["w. Pforten der Ewigkeit o. der Vorzeit"] },
      { number: 8, text: "Wer ist dieser König der Herrlichkeit? Der HERR, stark und mächtig! Der HERR, mächtig im Kampf*!", footnotes: ["℘ Offb 19,11-16"] },
      { number: 9, text: "Erhebt, ihr Tore, eure Häupter, und erhebt euch, ihr ewigen Pforten, dass der König der Herrlichkeit einziehe!" },
      { number: 10, text: "Wer ist er, dieser König der Herrlichkeit? Der HERR der Heerscharen*, er ist der König der Herrlichkeit! //", footnotes: ["℘ Jes 6,5"] },
    ]},
    { number: 25, verses: [
      { number: 1, text: "Von David. Zu dir, HERR, erhebe ich meine Seele.", heading: "Psalm 251" },
      { number: 2, text: "Mein Gott, auf dich vertraue ich*; lass mich nicht zuschanden werden*, lass meine Feinde nicht über mich jauchzen*!", footnotes: ["℘ Ps 91,2; Hebr 2,13", "℘ Ps 31,2; 71,1", "℘ Ps 13,5"] },
      { number: 3, text: "Auch werden alle, die auf dich harren, nicht beschämt werden*; es werden beschämt werden, die treulos handeln ohne Ursache*.", footnotes: ["℘ Ps 22,6; Jes 49,23; Röm 10,11", "℘ Ps 31,18"] },
      { number: 4, text: "Deine Wege, HERR, tue mir kund, deine Pfade lehre mich*!", footnotes: ["℘ Ps 27,11; 86,11"] },
      { number: 5, text: "Leite mich in deiner Wahrheit* und lehre mich*, denn du bist der Gott meines Heils; auf dich harre ich den ganzen Tag*.", footnotes: ["o. Treue\n℘ Joh 16,13", "℘ Hi 36,22", "o. täglich"] },
      { number: 6, text: "Denke an deine Erbarmungen*, HERR, und an deine Gnadenerweise; denn sie sind von Ewigkeit her*.", footnotes: ["℘ Lk 1,54", "℘ Ps 103,17"] },
      { number: 7, text: "An die Sünden meiner Jugend* und meine Vergehen denke nicht*; nach deiner Gnade gedenke du meiner, um deiner Güte willen, HERR*!", footnotes: ["℘ Hi 13,26", "℘ Jes 43,25; Jer 31,34", "℘ Ps 106,3"] },
      { number: 8, text: "Gütig und gerade ist der HERR; darum unterweist er die Sünder in dem Weg." },
      { number: 9, text: "Er leitet die Sanftmütigen im Recht und lehrt die Sanftmütigen seinen Weg." },
      { number: 10, text: "Alle Pfade des HERRN sind Gnade und Treue* denen, die seinen Bund und seine Zeugnisse bewahren.", footnotes: ["o. Wahrheit"] },
      { number: 11, text: "Um deines Namens willen, HERR, vergib mir meine Schuld*, denn sie ist groß.", footnotes: ["℘ 2Mo 34,7; 1Jo 2,12"] },
      { number: 12, text: "Wer ist nun der Mann, der den HERRN fürchtet? Ihn wird er unterweisen in dem Weg, den er wählen soll*.", footnotes: ["℘ Ps 32,8"] },
      { number: 13, text: "Seine Seele wird im Guten wohnen, und seine Nachkommen werden das Land besitzen*.", footnotes: ["℘ Ps 37,29.34"] },
      { number: 14, text: "Der HERR zieht ins Vertrauen, die ihn fürchten*, und sein Bund dient dazu, sie zu unterweisen.", footnotes: ["w. Des HERRN vertraute Besprechung für die, die ihn fürchten\n℘ Spr 3,32"] },
      { number: 15, text: "Meine Augen sind stets auf den HERRN gerichtet*; denn er, er wird meine Füße aus dem Netz lösen.", footnotes: ["℘ Ps 123,2; 141,8"] },
      { number: 16, text: "Wende dich zu mir und sei mir gnädig*, denn einsam und elend bin ich*.", footnotes: ["℘ Ps 119,132", "℘ Ps 40,18; 70,6; 86,1; 109,22"] },
      { number: 17, text: "Die Enge* meines Herzens *mache weit, und* führe mich heraus aus meinen Bedrängnissen!", footnotes: ["w. Die Engen (Mehrzahl)", "Mas. T.: machen sie weit. — Die Lesung oben ergibt sich durch eine vom Mas. T. abweichende Wortabtrennung.", "Mas. T.: machen sie weit. — Die Lesung oben ergibt sich durch eine vom Mas. T. abweichende Wortabtrennung."] },
      { number: 18, text: "Sieh mein Elend an und meine Mühsal*, und vergib alle meine Sünden*!", footnotes: ["℘ Ps 132,1", "℘ Ps 32,5"] },
      { number: 19, text: "Sieh meine Feinde an, wie viele sie sind*, mit gewalttätigem Hass hassen sie mich.", footnotes: ["℘ Ps 38,20"] },
      { number: 20, text: "Bewahre meine Seele und rette mich! Lass mich nicht zuschanden werden, denn ich berge mich bei dir*.", footnotes: ["℘ Ps 143,8"] },
      { number: 21, text: "Lauterkeit und Redlichkeit mögen mich behüten, denn ich harre auf dich." },
      { number: 22, text: "Erlöse Israel, Gott, aus allen seinen Nöten*!", footnotes: ["℘ Jes 63,9"] },
    ]},
    { number: 26, verses: [
      { number: 1, text: "Von David. Hilf mir zum Recht, HERR! Denn in meiner Lauterkeit bin ich gewandelt; und auf den HERRN habe ich vertraut, ich werde nicht wanken.", heading: "Psalm 26" },
      { number: 2, text: "Erprobe mich, HERR, und prüfe mich; läutere meine Nieren* und mein Herz*!", footnotes: ["s. Anm. zu Ps 16,7", "℘ Ps 17,3"] },
      { number: 3, text: "Denn deine Gnade war mir vor Augen, und in deiner Wahrheit* wandelte ich.", footnotes: ["o. Treue"] },
      { number: 4, text: "Ich habe nicht bei trügerischen Leuten gesessen, und mit Hinterlistigen ging ich nicht um." },
      { number: 5, text: "Ich habe die Versammlungen der Übeltäter gehasst, und bei Gottlosen saß ich nicht*.", footnotes: ["℘ Ps 1,1; 101,4"] },
      { number: 6, text: "Ich wasche meine Hände in Unschuld*, und umschreite deinen Altar, HERR,", footnotes: ["℘ Ps 24,4; 73,13"] },
      { number: 7, text: "um laut* ein Danklied hören zu lassen und alle deine Wundertaten zu erzählen*.", footnotes: ["w. mit Schall, o. mit Stimme", "℘ Ps 9,2; 1Chr 16,24"] },
      { number: 8, text: "HERR, ich liebe die Wohnung deines Hauses* und den Wohnort deiner Herrlichkeit*.", footnotes: ["℘ Ps 122,1; Lk 2,49", "℘ 2Mo 40,34.35; 2Chr 7,1"] },
      { number: 9, text: "Raffe meine Seele nicht weg mit den Sündern*, noch mein Leben mit Blutmenschen,", footnotes: ["℘ Ps 28,3"] },
      { number: 10, text: "an deren Händen Schandtat und deren Rechte voll Bestechung ist!" },
      { number: 11, text: "Ich aber wandle in meiner Lauterkeit*. Erlöse mich und sei mir gnädig!", footnotes: ["℘ Ps 101,2"] },
      { number: 12, text: "Mein Fuß steht auf ebenem Boden. Den HERRN werde ich in Versammlungen preisen*.", footnotes: ["℘ Ps 22,23; 68,27; 107,32"] },
    ]},
    { number: 27, verses: [
      { number: 1, text: "Von David. Der HERR ist mein Licht* und mein Heil*, vor wem sollte ich mich fürchten*? Der HERR ist meines Lebens Zuflucht*, vor wem sollte ich erschrecken*?", heading: "Psalm 27", footnotes: ["℘ Ps 18,29; Joh 8,12", "℘ Mi 7,8", "℘ Ps 118,6", "w. Schutzburg", "℘ Jes 12,2; Hebr 13,6"] },
      { number: 2, text: "Wenn Übeltäter mir nahen, mein Fleisch zu fressen, meine Bedränger und meine Feinde, so sind sie es, die straucheln und fallen*.", footnotes: ["℘ Joh 18,6"] },
      { number: 3, text: "Wenn sich ein Heer gegen mich lagert, so fürchtet sich mein Herz nicht*; wenn sich auch Krieg gegen mich erhebt, trotzdem bin ich vertrauensvoll.", footnotes: ["℘ Ps 3,7; 112,7"] },
      { number: 4, text: "Eins habe ich vom HERRN erbeten, danach trachte ich: zu wohnen im Haus des HERRN alle Tage meines Lebens*, um anzuschauen die Freundlichkeit des HERRN und nachzudenken in* seinem Tempel.", footnotes: ["℘ Ps 23,6", "Andere übersetzen: Freude zu haben an"] },
      { number: 5, text: "Denn er wird mich bergen in seiner* Hütte am Tag des Unheils, er wird mich verbergen im Versteck seines Zeltes*; auf einen Felsen wird er mich heben*.", footnotes: ["mit anderer Lesart: in einer", "℘ Ps 31,21; 32,7", "℘ Ps 40,3; 61,3"] },
      { number: 6, text: "Und nun wird mein Haupt sich erheben über meine Feinde rings um mich her*. Opfer voller Jubel* will ich opfern in seinem Zelt, ich will singen und spielen dem HERRN*.", footnotes: ["℘ Ps 3,4", "℘ Ps 107,22; 119,108; Hebr 13,15", "℘ Ps 57,8; 59,18"] },
      { number: 7, text: "Höre, HERR, mit meiner Stimme rufe ich: sei mir gnädig und erhöre mich*!", footnotes: ["℘ Ps 30,11; 31,10"] },
      { number: 8, text: "Mein Herz erinnert dich: »Suchet mein Angesicht!« — Dein Angesicht, HERR, suche ich*.", footnotes: ["℘ Ps 24,6; 105,4"] },
      { number: 9, text: "Verbirg dein Angesicht nicht vor mir*, weise deinen Knecht nicht ab im Zorn! Du bist meine Hilfe gewesen. Gib mich nicht auf und verlass mich nicht, Gott meines Heils!", footnotes: ["℘ Ps 69,18; 102,3"] },
      { number: 10, text: "Sogar mein Vater und meine Mutter haben mich verlassen, aber der HERR nimmt mich auf." },
      { number: 11, text: "Lehre mich, HERR, deinen Weg*, und leite mich auf ebenem Pfad* wegen meiner Feinde*!", footnotes: ["℘ Ps 25,4", "℘ Ps 139,24; 143,8.10", "℘ Ps 5,9"] },
      { number: 12, text: "Gib mich nicht preis der Gier meiner Bedränger, denn falsche Zeugen sind gegen mich aufgestanden* und der, der Gewalttat schnaubt.", footnotes: ["℘ Ps 35,11; Mt 26,60"] },
      { number: 13, text: "Ach, wenn ich mir nicht sicher wäre, das Gute des HERRN zu schauen im Land der Lebendigen . . .*!", footnotes: ["℘ Ps 116,9; 142,6"] },
      { number: 14, text: "Harre auf den HERRN! Sei mutig, und dein Herz sei stark*, und harre auf den HERRN*!", footnotes: ["℘ 2Tim 2,1", "℘ Ps 31,25; 37,7"] },
    ]},
    { number: 28, verses: [
      { number: 1, text: "Von David. Zu dir, HERR, rufe ich*; mein Fels, wende dich nicht schweigend von mir ab, dass du nicht gegen mich* verstummst und ich nicht denen gleich werde, die in die Grube hinabfahren*!", heading: "Psalm 28", footnotes: ["℘ Ps 142,2", "w. von mir weg", "℘ Ps 30,4; 88,5; 143,7"] },
      { number: 2, text: "Höre die Stimme meines Flehens, wenn ich zu dir schreie*, wenn ich meine Hände aufhebe zu deinem heiligen Tempelraum*.", footnotes: ["℘ Ps 130,2; 141,1", "℘ 1Kö 6,5"] },
      { number: 3, text: "Reiße mich nicht weg mit den Gottlosen und mit den Übeltätern*, die friedlich reden mit ihren Nächsten, aber Böses in ihrem Herzen haben!", footnotes: ["℘ Ps 26,9; 141,4"] },
      { number: 4, text: "Gib ihnen nach ihrem Tun und nach der Bosheit ihrer Taten; nach dem Werk ihrer Hände gib ihnen, vergilt ihnen ihre Tat*!", footnotes: ["℘ 2Tim 4,14"] },
      { number: 5, text: "Denn sie achten nicht auf die Taten des HERRN, noch auf das Werk seiner Hände*. Er wird sie zerstören und nicht aufbauen.", footnotes: ["℘ Röm 1,19-21"] },
      { number: 6, text: "Gepriesen sei der HERR, denn er hat die Stimme meines Flehens gehört*.", footnotes: ["℘ Ps 116,1.2"] },
      { number: 7, text: "Der HERR ist meine Stärke* und mein Schild*; auf ihn hat mein Herz vertraut, und mir ist geholfen worden; daher jubelt mein Herz, und ich will ihn preisen mit meinem Lied*.", footnotes: ["℘ Ps 37,39; 43,2; 46,2", "℘ Ps 3,4", "℘ Ps 13,6"] },
      { number: 8, text: "Der HERR ist ihre* Stärke, und er ist eine rettende Burg* für seinen Gesalbten*.", footnotes: ["Statt »ihre« haben LXX und einige hebr. Handschr.: seines Volkes", "w. die Feste der Hilfen", "℘ Ps 20,7"] },
      { number: 9, text: "Hilf deinem Volk und segne dein Erbteil*; weide sie und trage sie bis in Ewigkeit*!", footnotes: ["℘ 5Mo 9,26", "℘ Jes 40,11"] },
    ]},
    { number: 29, verses: [
      { number: 1, text: "Ein Psalm. Von David. Gebt dem HERRN, ihr Göttersöhne*, gebt dem HERRN Herrlichkeit und Kraft*!", heading: "Psalm 29", footnotes: ["℘ Ps 89,7", "℘ Ps 68,35; 96,7"] },
      { number: 2, text: "Gebt dem HERRN die Herrlichkeit seines Namens*; betet an den HERRN in heiliger Pracht*!", footnotes: ["℘ Offb 7,12", "Im Ugaritischen hat das Wort die Bedeutung »Gottes-Offenbarung, -Erscheinung«: bei seiner heiligen Offenbarung\n℘ Ps 96,8.9; 110,3"] },
      { number: 3, text: "Die Stimme des HERRN* ist über den Wassern, der Gott der Herrlichkeit* donnert*; der HERR über großen Wassern.", footnotes: ["o. Horch, der HERR; so auch in den Versen 4—9", "℘ Apg 7,2", "℘ Ps 18,14"] },
      { number: 4, text: "Die Stimme des HERRN ist gewaltig*, die Stimme des HERRN ist erhaben*.", footnotes: ["℘ Ps 93,4", "℘ Ps 68,34; Hi 40,9; Jes 30,30; Offb 1,10"] },
      { number: 5, text: "Die Stimme des HERRN zerbricht Zedern, ja, der HERR zerbricht die Zedern des Libanon*.", footnotes: ["℘ Jes 2,13"] },
      { number: 6, text: "Er lässt sie hüpfen wie ein Kalb, den Libanon und Sirjon* wie einen jungen Büffel*.", footnotes: ["Der sidonische Name für den Berg Hermon.", "℘ Ps 114,4"] },
      { number: 7, text: "Die Stimme des HERRN sprüht Feuerflammen*,", footnotes: ["℘ Ps 18,14"] },
      { number: 8, text: "die Stimme des HERRN erschüttert die Wüste, der HERR erschüttert die Wüste Kadesch." },
      { number: 9, text: "Die Stimme des HERRN macht Hirschkühe kreißen* und lässt Zicklein vorzeitig gebären* . . . Und in seinem Tempel ruft alles: Herrlichkeit!", footnotes: ["℘ Hi 39,1", "Andere üs. mit Textänderung: Die Stimme des HERRN lässt Eichen hüpfen und schält Wälder ab"] },
      { number: 10, text: "Der HERR thront auf der Wasserflut, der HERR thront als König ewig*.", footnotes: ["℘ Ps 9,8"] },
      { number: 11, text: "Der HERR möge Kraft geben seinem Volk, der HERR möge sein Volk segnen* mit Frieden*.", footnotes: ["℘ Ps 68,36", "℘ Jes 26,12"] },
    ]},
    { number: 30, verses: [
      { number: 1, text: "Ein Psalm. Ein Lied zur Einweihung des Hauses*. Von David.", heading: "Psalm 30", footnotes: ["nämlich des Tempels"] },
      { number: 2, text: "Ich will dich erheben*, HERR, denn du hast mich emporgezogen und ließest meine Feinde sich nicht über mich freuen*.", footnotes: ["℘ Ps 145,1", "℘ Ps 35,24; 41,12"] },
      { number: 3, text: "HERR, mein Gott, zu dir habe ich geschrien, und du hast mich geheilt*.", footnotes: ["℘ Jes 38,16"] },
      { number: 4, text: "HERR, du hast meine Seele aus dem Scheol heraufgeholt*, hast mich am Leben erhalten und bewahrt vor dem Hinabfahren zur Grube*.", footnotes: ["℘ Ps 86,13", "Mehrere alte Üs. lesen: hast mich gerettet aus den zur Grube Hinabfahrenden\n℘ Ps 28,1; 107,20"] },
      { number: 5, text: "Spielt dem HERRN, ihr seine Frommen*, und preist seinen heiligen Namen*!", footnotes: ["℘ Ps 47,7; 145,10; Eph 5,19", "w. zu seiner heiligen Namensanrufung\n℘ Ps 97,12; 2Mo 3,15"] },
      { number: 6, text: "Denn einen Augenblick stehen wir in seinem Zorn, ein Leben lang in seiner Gunst*; am Abend kehrt Weinen ein*, und am Morgen ist Jubel da*.", footnotes: ["℘ Jes 54,7.8", "»einkehren« w. übernachten, o. über Nacht bleiben", "℘ Ps 126,6"] },
      { number: 7, text: "Ich zwar dachte in meiner Sorglosigkeit: »Niemals werde ich wanken.«" },
      { number: 8, text: "HERR, in deiner Gunst *hattest du mich auf feste Berge gestellt*. Du verbargst dein Angesicht, da wurde ich bestürzt.", footnotes: ["So mit der aram. Üs.; Mas. T.: hast du Kraft zu meinem Berg aufgerichtet", "So mit der aram. Üs.; Mas. T.: hast du Kraft zu meinem Berg aufgerichtet"] },
      { number: 9, text: "Zu dir, HERR, rief ich, und zum Herrn flehte ich*:", footnotes: ["℘ Ps 66,17"] },
      { number: 10, text: "»Was für Gewinn bringt mein Blut, mein Hinabfahren in die Grube? Wird der Staub dich preisen? Wird er deine Treue* verkünden*?", footnotes: ["o. Wahrheit", "℘ Ps 6,6"] },
      { number: 11, text: "Höre, HERR, und sei mir gnädig*! HERR, sei mein Helfer!«", footnotes: ["℘ Ps 27,7"] },
      { number: 12, text: "Meine Wehklage hast du mir in Reigen verwandelt*, mein Sacktuch* hast du gelöst und mit Freude mich umgürtet*,", footnotes: ["℘ Est 9,22", "Sacktuch als Trauerkleidung", "℘ Jes 61,3"] },
      { number: 13, text: "damit meine Seele* dich besinge und nicht schweige*. HERR, mein Gott, in Ewigkeit will ich dich preisen*.", footnotes: ["w. Ehre, o. Würde; vgl. Ps 7,6; »meine« fehlt im Mas. T., steht aber in LXX", "℘ Ps 57,8", "℘ Ps 145,2"] },
    ]},
    { number: 31, verses: [
      { number: 1, text: "Dem Chorleiter. Ein Psalm. Von David.", heading: "Psalm 31" },
      { number: 2, text: "Bei dir, HERR, habe ich mich geborgen*; lass mich niemals zuschanden werden*; rette mich in deiner Gerechtigkeit*!", footnotes: ["℘ Ps 7,2", "℘ Ps 25,2", "℘ Ps 71,2"] },
      { number: 3, text: "Neige zu mir dein Ohr*, eilends rette mich*! Sei mir ein Fels der Zuflucht, ein unzugängliches Haus, mich zu retten*!", footnotes: ["℘ Ps 116,2", "℘ Ps 102,3", "℘ Ps 71,3"] },
      { number: 4, text: "Denn mein Fels und meine Festung* bist du; und um deines Namens willen führe mich und leite mich*!", footnotes: ["℘ Ps 18,3", "℘ Ps 23,3"] },
      { number: 5, text: "Ziehe mich aus dem Netz, das sie mir heimlich gelegt haben; denn du bist mein Schutz." },
      { number: 6, text: "In deine Hand befehle ich meinen Geist*. Du hast mich erlöst, HERR, du Gott der Treue!", footnotes: ["℘ Lk 23,46; Apg 7,59"] },
      { number: 7, text: "Ich hasse* die, die sich an nichtige Götzen* halten, doch ich, ich traue auf den HERRN.", footnotes: ["mit alten Üs.: Du hasst", "w. an Nichtse des Nichts; d. i. eine Bezeichnung für Götzen"] },
      { number: 8, text: "Ich will jauchzen und mich freuen über deine Gnade, dass du mein Elend angesehen, die Bedrängnisse meiner Seele erkannt hast*,", footnotes: ["o. dich um die Bedrängnisse meiner Seele gekümmert hast\n℘ Ps 10,14; 5Mo 26,7"] },
      { number: 9, text: "dass du mich nicht überliefert hast in die Hand des Feindes, sondern meine Füße auf weiten Raum gestellt hast*.", footnotes: ["℘ Ps 18,20.37"] },
      { number: 10, text: "Sei mir gnädig, HERR*, denn ich bin in Bedrängnis; vor Gram verfällt mein Auge*, meine Seele und mein Leib.", footnotes: ["℘ Ps 27,7", "℘ Ps 6,8"] },
      { number: 11, text: "Denn in Kummer schwindet mein Leben dahin und meine Jahre in Seufzen; meine Kraft wankt durch meine Schuld*, und es verfallen meine Gebeine.", footnotes: ["Alte Üs. lesen »Armut« oder »Elend«, »Bedrückung«."] },
      { number: 12, text: "Vor allen meinen Bedrängern bin ich zum Hohn geworden, auch meinen Nachbarn gar sehr*, und zum Schrecken meinen Bekannten; die mich auf der Straße sehen, fliehen vor mir*.", footnotes: ["℘ Ps 89,52", "℘ Ps 38,12; Hi 19,13.14"] },
      { number: 13, text: "In Vergessenheit bin ich geraten, aus dem Herzen fort wie ein Toter, bin wie ein verloren gegangenes* Gefäß.", footnotes: ["o. ruiniertes"] },
      { number: 14, text: "Denn ich höre das Tuscheln vieler, Schrecken ringsum*; indem sie sich miteinander gegen mich zusammentun, sinnen sie darauf, mir das Leben zu nehmen*.", footnotes: ["℘ Jer 20,10", "℘ Mt 26,3.4"] },
      { number: 15, text: "Ich aber, ich habe auf dich vertraut, HERR*; ich sagte: Du bist mein Gott*!", footnotes: ["℘ Ps 25,2; 91,2", "℘ Ps 140,7"] },
      { number: 16, text: "In deiner Hand sind meine Zeiten; rette mich aus der Hand meiner Feinde und vor meinen Verfolgern*!", footnotes: ["℘ Ps 3,8"] },
      { number: 17, text: "Lass dein Angesicht leuchten über deinem Knecht*, hilf mir in deiner Gnade!", footnotes: ["℘ Ps 4,7; 80,4"] },
      { number: 18, text: "HERR, lass mich nicht zuschanden werden, denn ich habe dich angerufen; mögen zuschanden werden die Gottlosen*, verstummen im Scheol!", footnotes: ["℘ Ps 25,3"] },
      { number: 19, text: "Lass schweigen die Lügenlippen*, die in Hochmut und Verachtung Freches reden gegen den Gerechten*!", footnotes: ["℘ Ps 63,12", "℘ Ps 12,5; Lk 20,26"] },
      { number: 20, text: "Wie groß ist deine Güte*, die du bereithältst denen, die dich fürchten*, die du denen erweist, die sich bei dir bergen* vor den Menschen.", footnotes: ["℘ Ps 36,6; 57,11", "℘ Ps 103,8.11", "℘ Ps 2,12; 119,124"] },
      { number: 21, text: "Du verbirgst sie im Schutz deines Angesichts vor den Verschwörungen* der Menschen; du birgst sie in einer Hütte vor dem Gezänk der Zungen*.", footnotes: ["Die Bedeutung des nur hier in der Bibel vorkommenden Wortes ist ungewiss.", "℘ Ps 27,5"] },
      { number: 22, text: "Gepriesen sei der HERR, denn wunderbar hat er seine Gnade an mir erwiesen* in einer befestigten Stadt*.", footnotes: ["℘ Ps 17,7; 66,20", "Andere übersetzen mit Textkorr.: in der Zeit der Bedrängnis"] },
      { number: 23, text: "Ich zwar dachte in meiner Bestürzung: »Ich bin weggenommen* aus deinen Augen.« Doch du hast die Stimme meines Flehens gehört, als ich zu dir schrie.", footnotes: ["Einige Handschr. haben: verstoßen"] },
      { number: 24, text: "Liebet den HERRN, alle seine Frommen! Die Treuen behütet der HERR*, doch er vergilt reichlich dem, der anmaßend handelt.", footnotes: ["℘ 5Mo 6,5"] },
      { number: 25, text: "Seid stark, und euer Herz fasse Mut, alle, die ihr auf den HERRN harrt*!", footnotes: ["℘ Ps 27,14"] },
    ]},
    { number: 32, verses: [
      { number: 1, text: "Von David. Ein Maskil*. Glücklich der, dem Übertretung* vergeben*, dem Sünde zugedeckt ist!", heading: "Psalm 32", footnotes: ["Unterweisung o. kunstvoll gestaltetes Lied", "o. Bruch mit Gott; o. Vergehen", "℘ Ps 103,3"] },
      { number: 2, text: "Glücklich der Mensch, dem der HERR die Schuld nicht zurechnet* und in dessen Geist kein Trug ist*!", footnotes: ["℘ 2Kor 5,19; Röm 4,7.8", "℘ Joh 1,47"] },
      { number: 3, text: "Als ich schwieg, zerfielen meine Gebeine durch mein Gestöhn den ganzen Tag." },
      { number: 4, text: "Denn Tag und Nacht lastete auf mir deine Hand*; verwandelt wurde mein Saft* in Sommergluten. //", footnotes: ["℘ Ps 38,3", "w. Kuchen; gemeint ist ein saftiges, wohlschmeckendes Gebäck"] },
      { number: 5, text: "So tat ich dir kund meine Sünde und deckte meine Schuld nicht zu*. Ich sagte: Ich will dem HERRN meine Übertretungen* bekennen*; und du, du hast vergeben die Schuld meiner Sünde*. //", footnotes: ["℘ Ps 38,19", "o. Vergehen; o. Treuebrüche gegen Gott", "℘ Ps 51,6; Lk 15,18", "℘ Ps 25,16; Spr 28,13; 1Jo 1,9"] },
      { number: 6, text: "Deshalb soll jeder Fromme zu dir beten, zur Zeit, da du zu finden bist*; gewiss, bei großer Wasserflut — ihn werden sie nicht erreichen*.", footnotes: ["℘ Jes 55,6", "℘ Jes 43,2"] },
      { number: 7, text: "Du bist ein Bergungsort für mich*; vor Bedrängnis behütest du mich; du umgibst mich mit Rettungsjubel*. //", footnotes: ["℘ Ps 27,5; 119,114", "℘ Ps 5,12"] },
      { number: 8, text: "Ich will dich unterweisen und dich lehren den Weg, den du gehen sollst*; ich will dir raten*, mein Auge ist über dir.", footnotes: ["℘ Ps 143,8; Jes 48,17", "℘ Ps 25,12"] },
      { number: 9, text: "Seid nicht wie ein Ross, wie ein Maultier, ohne Verstand; mit Zaum und Zügel ist seine Kraft* zu bändigen, sonst nahen sie dir nicht*.", footnotes: ["w. sein Schmuck", "℘ Spr 26,3; Jak 3,3"] },
      { number: 10, text: "Viele Schmerzen hat der Gottlose*; wer aber auf den HERRN vertraut, den umgibt er mit Gnade.", footnotes: ["℘ Ps 11,6"] },
      { number: 11, text: "Freut euch an dem HERRN* und jauchzt, ihr Gerechten, und jubelt, alle ihr von Herzen Aufrichtigen*!", footnotes: ["℘ Phil 3,1", "℘ Ps 33,1; 97,12"] },
    ]},
    { number: 33, verses: [
      { number: 1, text: "Jubelt, ihr Gerechten, über den HERRN; den Aufrichtigen ziemt Lobgesang*.", heading: "Psalm 33", footnotes: ["℘ Ps 32,11"] },
      { number: 2, text: "Preist den HERRN mit der Zither; spielt ihm auf der zehnsaitigen Harfe*!", footnotes: ["℘ Ps 81,3; 92,4; 144,9"] },
      { number: 3, text: "Singt ihm ein neues Lied*; spielt schön auf den Saiten mit Jubelschall!", footnotes: ["℘ Ps 40,4; 96,1; 98,1; 144,9; 149,1; Offb 5,9"] },
      { number: 4, text: "Denn richtig* ist das Wort des HERRN, und all sein Werk geschieht in Treue*.", footnotes: ["Grundbedeutung: gerade", "℘ 5Mo 32,4"] },
      { number: 5, text: "Er liebt Gerechtigkeit und Recht*; die Erde ist voll der Gnade des HERRN*.", footnotes: ["℘ Ps 11,7", "℘ Ps 119,64"] },
      { number: 6, text: "Durch des HERRN Wort ist der Himmel gemacht* und all sein Heer durch den Hauch seines Mundes.", footnotes: ["℘ Ps 148,5; 1Mo 1,6.14; Joh 1,3; Hebr 11,3; 2Petr 3,5"] },
      { number: 7, text: "Er sammelt das Wasser des Meeres wie einen Wall*, legt in Behälter die Fluten*.", footnotes: ["LXX und aram. Üs.: in einem Schlauch", "℘ 1Mo 1,9"] },
      { number: 8, text: "Es fürchte den HERRN die ganze Erde*; mögen sich vor ihm scheuen alle Bewohner der Welt*!", footnotes: ["℘ Ps 67,8", "℘ Offb 15,4"] },
      { number: 9, text: "Denn er sprach, und es geschah*; er gebot, und es stand da*.", footnotes: ["℘ Mk 1,42; Lk 13,13", "℘ 1Mo 1; Hebr 11,3"] },
      { number: 10, text: "Der HERR macht zunichte den Ratschluss der Nationen, er vereitelt die Gedanken der Völker*.", footnotes: ["℘ Hi 5,12; Jes 8,10"] },
      { number: 11, text: "Der Ratschluss des HERRN hat ewig Bestand, die Gedanken seines Herzens von Generation zu Generation*.", footnotes: ["℘ Jes 46,10"] },
      { number: 12, text: "Glücklich die Nation, deren Gott der HERR ist*, das Volk, das er sich erwählt hat zum Erbteil*!", footnotes: ["℘ Ps 144,15", "℘ Ps 135,4; 5Mo 32,9"] },
      { number: 13, text: "Der HERR blickt vom Himmel herab, er sieht alle Menschenkinder*.", footnotes: ["℘ Ps 14,2; 66,7; Spr 15,3"] },
      { number: 14, text: "Von der Stätte seines Thrones schaut er auf alle Bewohner der Erde*;", footnotes: ["℘ Ps 113,6; Sach 4,10"] },
      { number: 15, text: "er, der ihnen allesamt das Herz gebildet hat, achtet auf alle ihre Werke*.", footnotes: ["℘ Jer 16,17; Hebr 4,13; Offb 2,2"] },
      { number: 16, text: "Der König siegt nicht durch die Größe des Heeres; ein Held befreit sich nicht durch die Größe der Kraft." },
      { number: 17, text: "Ein Trug ist das Ross, wenn Rettung nötig ist*, und mit seiner großen Kraft rettet es nicht*.", footnotes: ["w. zur Rettung", "℘ Ps 20,8; 5Mo 20,1; Jes 31,1"] },
      { number: 18, text: "Siehe, das Auge des HERRN ruht auf denen, die ihn fürchten, die auf seine Gnade harren*,", footnotes: ["℘ Ps 34,16; 147,11; 2Chr 16,9"] },
      { number: 19, text: "dass er ihre Seele vom Tod rette und sie am Leben erhalte in Hungersnot*.", footnotes: ["℘ Ps 34,10; 37,19; 111,5"] },
      { number: 20, text: "Unsere Seele wartet auf den HERRN*; unsere Hilfe und unser Schild ist er*.", footnotes: ["℘ Ps 130,5", "℘ Ps 115,9-11"] },
      { number: 21, text: "Denn in ihm wird unser Herz sich freuen, weil wir seinem heiligen Namen vertrauen*.", footnotes: ["℘ Jes 25,9"] },
      { number: 22, text: "Deine Gnade, HERR, sei über uns, gleichwie wir auf dich harren." },
    ]},
    { number: 34, verses: [
      { number: 1, text: "Von David. Als er sich vor Abimelech wahnsinnig stellte und dieser ihn wegtrieb und er fortging*.", heading: "Psalm 341", footnotes: ["℘ 1Sam 21,11-16"] },
      { number: 2, text: "Den HERRN will ich preisen allezeit, beständig soll sein Lob in meinem Munde sein*.", footnotes: ["℘ Eph 5,19"] },
      { number: 3, text: "In dem HERRN soll sich rühmen meine Seele*; hören werden es die Sanftmütigen und sich freuen*.", footnotes: ["℘ Jer 9,24", "℘ Ps 69,33"] },
      { number: 4, text: "Erhebt den HERRN mit mir, lasst uns miteinander erhöhen seinen Namen*!", footnotes: ["℘ Ps 35,27; 40,17"] },
      { number: 5, text: "Ich suchte den HERRN, und er antwortete mir*; und aus allen meinen Ängsten rettete er mich.", footnotes: ["℘ Ps 3,5"] },
      { number: 6, text: "Sie blickten auf ihn und strahlten*, und ihr* Angesicht wird nicht beschämt.", footnotes: ["verschiedene hebr. Handschr., LXX und andere Üs.: Blicket auf ihn und strahlt", "verschiedene Üs.: euer"] },
      { number: 7, text: "Dieser Elende rief, und der HERR hörte, und aus allen seinen Bedrängnissen rettete er ihn*.", footnotes: ["℘ Ps 50,15; 138,3"] },
      { number: 8, text: "Der Engel des HERRN lagert sich um die her, die ihn fürchten, und er befreit sie*.", footnotes: ["℘ Apg 12,11"] },
      { number: 9, text: "Schmecket und sehet, dass der HERR gütig ist*! Glücklich der Mann, der sich bei ihm birgt*!", footnotes: ["℘ 1Petr 2,3", "℘ Ps 2,12"] },
      { number: 10, text: "Fürchtet den HERRN, ihr seine Heiligen! Denn keinen Mangel haben die, die ihn fürchten*.", footnotes: ["℘ Ps 33,19; Phil 4,19"] },
      { number: 11, text: "Junglöwen* darben und hungern, aber die den HERRN suchen, entbehren kein Gut*.", footnotes: ["LXX liest: Reiche. — Die hebr. Wörter ähneln sich.", "℘ Ps 23,1; 107,9; 112,3"] },
      { number: 12, text: "Kommt, ihr Söhne, hört mir zu*: die Furcht des HERRN will ich euch lehren*.", footnotes: ["℘ Spr 7,24", "℘ Spr 9,10"] },
      { number: 13, text: "Wer ist der Mann, der Lust zum Leben hat, der seine Tage liebt, um Gutes zu sehen?" },
      { number: 14, text: "Bewahre deine Zunge vor Bösem* und deine Lippen vor betrügerischer* Rede;", footnotes: ["℘ Ps 39,2", "o. hinterlistiger"] },
      { number: 15, text: "lass ab vom Bösen und tue Gutes*, suche Frieden und jage ihm nach*!", footnotes: ["℘ Ps 37,27; Röm 12,9", "℘ Röm 12,18; Hebr 12,14"] },
      { number: 16, text: "Die Augen des HERRN sind gerichtet auf die Gerechten* und seine Ohren auf ihr Schreien*.", footnotes: ["℘ Ps 33,18; Hi 36,7", "℘ Ps 94,9"] },
      { number: 17, text: "Denen, die Böses tun*, steht das Angesicht des HERRN entgegen, um ihre Erwähnung von der Erde zu tilgen*.", footnotes: ["℘ 1Petr 3,10-12", "℘ Ps 5,7; 9,6; 109,15; Spr 10,7"] },
      { number: 18, text: "Sie* schreien, und der HERR hört*, aus allen ihren Bedrängnissen rettet er sie*.", footnotes: ["Alte Üs. ergänzen: Die Gerechten", "℘ Ps 18,7", "℘ Ps 145,19"] },
      { number: 19, text: "Nahe ist der HERR denen, die zerbrochenen Herzens sind, und die zerschlagenen Geistes sind, rettet er*.", footnotes: ["℘ Ps 147,3; Jes 57,15"] },
      { number: 20, text: "Vielfältig ist das Unglück des Gerechten, aber aus dem allen rettet ihn der HERR*.", footnotes: ["℘ Ps 37,39.40; Hi 5,19; 2Petr 2,9"] },
      { number: 21, text: "Er bewahrt alle seine Gebeine, nicht eines von ihnen wird zerbrochen*.", footnotes: ["℘ Joh 19,36"] },
      { number: 22, text: "Den Gottlosen wird die Bosheit töten; und die den Gerechten hassen, werden es büßen*.", footnotes: ["℘ Ps 37,12-15"] },
      { number: 23, text: "Der HERR erlöst die Seele seiner Knechte*; und alle, die sich bei ihm bergen, müssen nicht büßen.", footnotes: ["℘ Ps 71,23"] },
    ]},
    { number: 35, verses: [
      { number: 1, text: "Von David. Streite, HERR, mit denen, die gegen mich streiten, kämpfe mit denen, die mich bekämpfen!", heading: "Psalm 35" },
      { number: 2, text: "Ergreife Kleinschild und Langschild, und stehe auf zu meiner Hilfe*!", footnotes: ["℘ Ps 91,4"] },
      { number: 3, text: "Zücke den Speer und versperre den Weg* gegenüber meinen Verfolgern; sprich zu meiner Seele: »Ich bin deine Hilfe!«", footnotes: ["Andere lesen nach Änderung der Vokalisierung: Zücke Speer und Beil"] },
      { number: 4, text: "Es sollen sich schämen und zuschanden werden, die nach meinem Leben trachten; es sollen zurückweichen und beschämt werden, die mir Unheil ersinnen*!", footnotes: ["℘ Ps 6,11; 83,18"] },
      { number: 5, text: "Lass sie sein wie Spreu vor dem Wind*, und der Engel des HERRN stoße sie!", footnotes: ["℘ Ps 1,4"] },
      { number: 6, text: "Ihr Weg sei finster und schlüpfrig*, und der Engel des HERRN verfolge sie!", footnotes: ["℘ Ps 73,18; Jer 23,12"] },
      { number: 7, text: "Denn ohne Ursache haben sie mir ihr Netz* heimlich gelegt*, ohne Ursache meiner Seele eine Grube gegraben*.", footnotes: ["w. die Grube ihres Netzes", "℘ Ps 57,7", "℘ Ps 119,85"] },
      { number: 8, text: "Verderben komme über ihn, ohne dass er es erkennt; und sein Netz, das er heimlich gelegt hat, fange ihn; ins Verderben falle er hinein*!", footnotes: ["℘ Ps 7,16"] },
      { number: 9, text: "Und meine Seele wird jauchzen über den HERRN*, wird sich freuen über seine Hilfe*.", footnotes: ["℘ Ps 104,34; Lk 1,47", "℘ Ps 9,15; 1Sam 2,1"] },
      { number: 10, text: "Alle meine Gebeine werden sagen*: »HERR, wer ist wie du*! Der du den Elenden rettest vor dem Stärkeren und den Elenden und Armen vor seinem Räuber*.«", footnotes: ["℘ Ps 51,10", "℘ Ps 71,19", "℘ Ps 103,6; 140,13; 146,7"] },
      { number: 11, text: "Es treten gewalttätige Zeugen auf*; was ich nicht weiß, fragen sie mich.", footnotes: ["℘ Ps 27,12"] },
      { number: 12, text: "Sie vergelten mir Böses für Gutes*; *vereinsamt ist meine Seele*.", footnotes: ["℘ Ps 38,21; 109,5; Jer 18,20", "w. Kinderlosigkeit für meine Seele. — Manche vermuten, dass im Mas. T. ein Buchstabe doppelt geschrieben wurde, und lesen: lauern auf meine Seele", "w. Kinderlosigkeit für meine Seele. — Manche vermuten, dass im Mas. T. ein Buchstabe doppelt geschrieben wurde, und lesen: lauern auf meine Seele\n℘ Ps 142,5"] },
      { number: 13, text: "Ich aber, als sie krank waren, kleidete mich in Sacktuch*; ich kasteite mit Fasten meine Seele. Ach, dass mein Gebet in meinen Schoß zurückkehrte*!", footnotes: ["℘ Ps 69,12; Röm 12,15", "℘ Hi 30,25"] },
      { number: 14, text: "Als wäre es mir ein Freund, ein Bruder gewesen, so bin ich einhergegangen; wie leidtragend um die Mutter habe ich mich trauernd niedergebeugt." },
      { number: 15, text: "Sie aber haben sich über mein Straucheln gefreut und sich versammelt, Schläger* haben sich versammelt gegen mich, und ich kannte sie nicht; sie zerreißen und hören nicht auf.", footnotes: ["LXX: Peitschenschläge. — Mit Ergänzung eines Buchstabens: Fremde"] },
      { number: 16, text: "Unter Gottesverächtern verspotten sie meinen Rückzugsort, sie knirschen* gegen mich mit ihren Zähnen*.", footnotes: ["so mit LXX; Mas. T.: zu knirschen", "℘ Ps 37,12; Apg 7,54"] },
      { number: 17, text: "Herr, wie lange willst du zusehen*? Stell mein Leben wieder her aus ihren Verwüstungen, aus der Gewalt der Junglöwen mein einziges Gut*.", footnotes: ["℘ Hab 1,13", "℘ Ps 22,21"] },
      { number: 18, text: "Ich werde dich preisen in der großen Versammlung, unter zahlreichem Volk dich loben*.", footnotes: ["℘ Ps 22,23"] },
      { number: 19, text: "Lass nicht über mich jauchzen*, die mir ohne Grund feind sind, noch mit den Augen zwinkern, die ohne Ursache mich hassen*.", footnotes: ["℘ Ps 38,17", "℘ Ps 38,20; 69,5; 109,3; Joh 15,25"] },
      { number: 20, text: "Denn nicht zum Frieden reden sie; und gegen die Stillen im Land ersinnen sie Worte des Betrugs;" },
      { number: 21, text: "reißen ihr Maul gegen mich auf*, sagen: »Haha! Haha! Unser Auge hat es gesehen*!«", footnotes: ["℘ Ps 22,14", "℘ Ps 40,16"] },
      { number: 22, text: "Du hast es gesehen, HERR*; schweige nicht! Herr, sei nicht fern von mir*!", footnotes: ["℘ Ps 10,14", "℘ Ps 22,12.20; 71,12"] },
      { number: 23, text: "Rege dich und erwache* für mein Recht, mein Gott und Herr, zu meinem Rechtsstreit*!", footnotes: ["℘ Ps 44,24", "℘ Ps 7,7; 74,22; 119,154"] },
      { number: 24, text: "Schaffe mir Recht nach deiner Gerechtigkeit, HERR, mein Gott, dass sie nicht über mich jubeln*!", footnotes: ["℘ Ps 30,2"] },
      { number: 25, text: "Sie sollen nicht in ihrem Herzen sagen: »Haha, so wollten wir es!*« Sie sollen nicht sagen: »Wir haben ihn verschlungen*!«", footnotes: ["o. Haha, unser Begehr ist er.", "℘ Kla 2,16"] },
      { number: 26, text: "Sie sollen sich schämen und beschämt werden allesamt, die sich freuen über mein Unglück*. Sie sollen mit Schimpf und Schande bekleidet werden, die gegen mich großtun*!", footnotes: ["℘ Ps 40,15", "℘ V. 4; Ps 132,18"] },
      { number: 27, text: "Es sollen jubeln und sich freuen, die meine Gerechtigkeit wünschen, und sie sollen stets sagen: »Erhoben sei der HERR*, der den Frieden seines Knechtes will!«", footnotes: ["℘ Ps 34,4; 40,17"] },
      { number: 28, text: "Und meine Zunge soll hersagen* deine Gerechtigkeit*, dein Lob den ganzen Tag.", footnotes: ["w. halblaut lesen, o. murmelnd bedenken", "℘ Ps 7,18"] },
    ]},
    { number: 36, verses: [
      { number: 1, text: "Dem Chorleiter. Vom Knecht des HERRN. Von David.", heading: "Psalm 36" },
      { number: 2, text: "Die Übertretung* spricht* zum Gottlosen im Innern seines* Herzens: Es ist keine Furcht Gottes vor seinen Augen*.", footnotes: ["o. Der Bruch mit Gott; o. Das Vergehen", "w. Ausspruch der Übertretung. — Andere üs. mit Textkorr.: Angenehm ist die Übertretung dem Gottlosen", "so mit verschiedenen hebr. Handschr. sowie der LXX und der syr. Üs.; Mas. T.: meines", "℘ Röm 3,18"] },
      { number: 3, text: "Denn es schmeichelt ihm in seinen Augen, seine Sünde zu vollbringen, Hass zu üben." },
      { number: 4, text: "Lüge und Betrug* sind die Worte seines Mundes; er hat es aufgegeben, verständig zu handeln, Gutes zu tun*.", footnotes: ["o. Hinterlist", "℘ Jer 4,22"] },
      { number: 5, text: "Bosheit ersinnt er auf seinem Lager*; er betritt einen Weg, der nicht gut ist*; Böses verschmäht er nicht.", footnotes: ["℘ Mi 2,1", "℘ Jes 65,2"] },
      { number: 6, text: "HERR, an den Himmel reicht deine Gnade*, deine Treue bis zu den Wolken.", footnotes: ["℘ Ps 31,20"] },
      { number: 7, text: "Deine Gerechtigkeit ist den Bergen Gottes gleich*, deine Rechtssprüche dem gewaltigen Urmeer; Menschen und Vieh hilfst du, HERR.", footnotes: ["℘ Ps 71,19"] },
      { number: 8, text: "Wie köstlich ist deine Gnade*, Gott! und Menschenkinder bergen sich in deiner Flügel Schatten*;", footnotes: ["℘ Ps 31,20", "℘ Ps 17,8"] },
      { number: 9, text: "sie laben sich am Fett deines Hauses*, und mit dem Strom deiner Wonnen tränkst du sie.", footnotes: ["℘ Ps 65,5"] },
      { number: 10, text: "Denn bei dir ist der Quell des Lebens*; in deinem Licht sehen wir das Licht*.", footnotes: ["℘ Jon 4,14; Offb 21,6; 22,1", "℘ Jes 2,5; Joh 1,4"] },
      { number: 11, text: "Erhalte deine Gnade denen, die dich kennen, und deine Gerechtigkeit den von Herzen Aufrichtigen!" },
      { number: 12, text: "Nicht erreiche mich der Fuß der Hochmütigen, und die Hand der Gottlosen vertreibe mich nicht!" },
      { number: 13, text: "Da sind gefallen die Übeltäter; sie wurden umgestoßen und können nicht mehr aufstehen." },
    ]},
    { number: 37, verses: [
      { number: 1, text: "Von David. Entrüste dich nicht über die Übeltäter, beneide nicht die, welche Böses tun*!", heading: "Psalm 371", footnotes: ["℘ Spr 23,17; 24,19"] },
      { number: 2, text: "Denn wie das Gras werden sie schnell verdorren und wie das grüne Kraut verwelken*.", footnotes: ["℘ Ps 92,8; 129,6"] },
      { number: 3, text: "Vertraue auf den HERRN und tue Gutes*; wohne im Land und hüte Treue;", footnotes: ["℘ 1Petr 4,19"] },
      { number: 4, text: "und habe deine Lust am HERRN, so wird er dir geben, was dein Herz begehrt*.", footnotes: ["℘ Lk 11,9; 1Jo 3,22"] },
      { number: 5, text: "Befiehl dem HERRN* deinen Weg und vertraue auf ihn, so wird er handeln", footnotes: ["w. Wälze auf den HERRN"] },
      { number: 6, text: "und wird deine Gerechtigkeit aufgehen lassen wie das Licht* und dein Recht wie den Mittag*.", footnotes: ["℘ Jes 58,8", "℘ Hi 11,17"] },
      { number: 7, text: "Sei still dem HERRN und harre auf ihn*! Entrüste dich nicht über den, dessen Weg gelingt, über den Mann, der böse Pläne ausführt!", footnotes: ["℘ Ps 27,14; Kla 3,25"] },
      { number: 8, text: "Lass ab vom Zorn und lass den Grimm! Entrüste dich nicht! Es führt nur zum Bösen*.", footnotes: ["℘ Röm 12,19"] },
      { number: 9, text: "Denn die Übeltäter werden ausgerottet*; aber die auf den HERRN hoffen, die werden das Land besitzen*.", footnotes: ["℘ Mal 4,1", "℘ Ps 25,13; 5Mo 5,33; Jes 57,13; Mt 5,5"] },
      { number: 10, text: "Noch kurze Zeit, und der Gottlose ist nicht mehr; und siehst du dich um nach seiner Stätte, so ist er nicht da*.", footnotes: ["℘ Hi 20,5.9"] },
      { number: 11, text: "Aber die Sanftmütigen werden das Land besitzen* und werden ihre Lust haben an Fülle von Heil.", footnotes: ["℘ Ps 25,13; 5Mo 5,33; Jes 57,13; Mt 5,5"] },
      { number: 12, text: "Der Gottlose sinnt gegen den Gerechten, und mit seinen Zähnen knirscht er gegen ihn*.", footnotes: ["℘ Ps 35,16"] },
      { number: 13, text: "Der Herr lacht über ihn*, denn er sieht, dass sein Tag kommt*.", footnotes: ["℘ Ps 2,4", "℘ Jes 2,12"] },
      { number: 14, text: "Die Gottlosen haben das Schwert gezogen und ihren Bogen gespannt, um zu fällen den Elenden und Armen, hinzuschlachten die, die aufrichtig wandeln*.", footnotes: ["℘ Ps 11,2"] },
      { number: 15, text: "Ihr Schwert wird in ihr eigenes Herz dringen*, und ihre Bogen werden zerbrochen*.", footnotes: ["℘ Ps 34,22", "℘ Ps 46,10; 76,4"] },
      { number: 16, text: "Das Wenige des Gerechten ist besser als der Überfluss vieler Gottloser*.", footnotes: ["℘ Spr 16,8"] },
      { number: 17, text: "Denn die Arme der Gottlosen werden zerbrochen*, aber der HERR stützt die Gerechten*.", footnotes: ["℘ Ps 10,15", "℘ Jes 41,10"] },
      { number: 18, text: "Der HERR kennt die Tage der Rechtschaffenen*, und ihr Erbteil wird ewig bestehen*;", footnotes: ["℘ Ps 1,6", "℘ Spr 2,21; Jes 60,21"] },
      { number: 19, text: "sie werden nicht zuschanden zur Zeit des Unglücks, und in den Tagen des Hungers werden sie gesättigt*.", footnotes: ["℘ Ps 33,19; Spr 10,3"] },
      { number: 20, text: "Denn die Gottlosen werden umkommen, und die Feinde des HERRN — wie die Pracht der Auen schwinden sie, sie schwinden dahin wie* Rauch*.", footnotes: ["so mit vielen hebr. Handschr. und mit alten Üs.; Mas. T.: im", "℘ Ps 68,3"] },
      { number: 21, text: "Der Gottlose borgt und zahlt nicht zurück; der Gerechte aber ist gütig und gibt*.", footnotes: ["℘ Mt 5,42"] },
      { number: 22, text: "Denn die von ihm Gesegneten werden das Land besitzen*, und die von ihm Verfluchten werden ausgerottet.", footnotes: ["℘ Ps 25,13; 5Mo 5,33; Jes 57,13; Mt 5,5"] },
      { number: 23, text: "Vom HERRN her werden eines Mannes Schritte gefestigt, und seinen Weg hat er gern*;", footnotes: ["℘ Ps 40,3; 1Petr 5,10"] },
      { number: 24, text: "fällt er, so wird er doch nicht hingestreckt*, denn der HERR stützt seine Hand*.", footnotes: ["℘ Spr 24,16", "℘ Ps 94,18; 145,14"] },
      { number: 25, text: "Ich war jung und bin auch alt geworden, doch nie sah ich einen Gerechten verlassen*, noch seine Nachkommen um Brot betteln;", footnotes: ["℘ Hebr 13,5"] },
      { number: 26, text: "alle Tage ist er gütig und leiht*, und seine Nachkommen werden zum Segen.", footnotes: ["℘ Ps 112,5"] },
      { number: 27, text: "Lass ab vom Bösen und tue Gutes, so wirst du für immer im Lande wohnen*!", footnotes: ["℘ Ps 34,15; 1Jo 2,17"] },
      { number: 28, text: "Denn der HERR liebt Recht* und wird seine Frommen nicht verlassen; *ewig werden sie bewahrt*, und die Nachkommenschaft der Gottlosen wird ausgerottet.", footnotes: ["℘ Ps 11,7", "LXX: Die Gesetzlosen werden für immer vertilgt. Für diese Lesart spricht dreierlei: 1. Die Mas. T.-Lesart lässt sich aus ihr erklären. 2. Der in diesem alphabetischen Psalm fällige Strophenanfang ist in ihr (im Gegensatz zum Mas. T.) erhalten. 3. Sie entspricht der Schlusszeile von V. 28.", "LXX: Die Gesetzlosen werden für immer vertilgt. Für diese Lesart spricht dreierlei: 1. Die Mas. T.-Lesart lässt sich aus ihr erklären. 2. Der in diesem alphabetischen Psalm fällige Strophenanfang ist in ihr (im Gegensatz zum Mas. T.) erhalten. 3. Sie entspricht der Schlusszeile von V. 28.\n℘ 1Petr 1,5"] },
      { number: 29, text: "Die Gerechten werden das Land besitzen* und für immer darin wohnen*.", footnotes: ["℘ Spr 2,21; Jes 60,21", "℘ Spr 2,21; Jes 60,21"] },
      { number: 30, text: "Der Mund des Gerechten spricht Weisheit aus, und seine Zunge redet Recht*;", footnotes: ["℘ Spr 10,20"] },
      { number: 31, text: "die Weisung seines Gottes ist in seinem Herzen*, seine Schritte werden nicht wanken.", footnotes: ["℘ Ps 40,9; 5Mo 6,6; Jes 51,7"] },
      { number: 32, text: "Der Gottlose lauert auf den Gerechten und sucht, ihn zu töten*;", footnotes: ["℘ Ps 56,7; Lk 6,7"] },
      { number: 33, text: "doch der HERR lässt ihn nicht in seiner Hand und lässt ihn nicht verurteilen, wenn man ihn richtet." },
      { number: 34, text: "Harre auf den HERRN* und halte seinen Weg ein, und er wird dich erhöhen, das Land zu besitzen*. Wenn die Gottlosen ausgerottet werden, wirst du zusehen*.", footnotes: ["℘ Spr 20,22", "℘ Ps 25,13; 5Mo 5,33; Jes 57,13; Mt 5,5", "℘ Ps 54,9; 91,8; 92,12; 112,8"] },
      { number: 35, text: "Ich habe einen Gottlosen gesehen, gewalttätig und *sich erhebend wie eine üppige Zeder*;", footnotes: ["LXX stützt diese Üs., bei der drei Änderungen im hebr. Buchstabentext nötig sind; Mas. T.: sich entblößt zeigend wie ein üppiger Einheimischer", "LXX stützt diese Üs., bei der drei Änderungen im hebr. Buchstabentext nötig sind; Mas. T.: sich entblößt zeigend wie ein üppiger Einheimischer"] },
      { number: 36, text: "und man ging vorbei, siehe, da war er nicht mehr; und ich suchte ihn, doch er war nicht zu finden*.", footnotes: ["℘ Hi 20,5.9"] },
      { number: 37, text: "*Achte auf den Rechtschaffenen und sieh auf den Redlichen*; denn die Zukunft für einen solchen ist Frieden;", footnotes: ["Mit LXX und anderen Üs.: Bewahre Lauterkeit und sieh auf Redlichkeit", "Mit LXX und anderen Üs.: Bewahre Lauterkeit und sieh auf Redlichkeit"] },
      { number: 38, text: "die von Gott Abgefallenen* aber werden allesamt vertilgt, die Zukunft der Gottlosen wird abgeschnitten.", footnotes: ["o. die mit Gott gebrochen haben"] },
      { number: 39, text: "Doch die Hilfe der Gerechten kommt vom HERRN*, der ihre Fluchtburg ist* zur Zeit der Not*;", footnotes: ["℘ Ps 3,9; 62,2", "℘ Ps 28,7", "℘ Ps 9,10"] },
      { number: 40, text: "und der HERR wird ihnen beistehen und sie retten; er wird sie retten von den Gottlosen und ihnen helfen*, denn sie haben sich bei ihm geborgen.", footnotes: ["℘ Ps 34,20"] },
    ]},
    { number: 38, verses: [
      { number: 1, text: "Ein Psalm. Von David. Zum Gedächtnis*.", heading: "Psalm 38", footnotes: ["o. nach jüdischer Tradition: Zum Weihrauchopfer; vgl. Ps 70,1"] },
      { number: 2, text: "HERR, strafe mich nicht in deinem Zorn, und züchtige mich nicht in deinem Grimm*!", footnotes: ["℘ Ps 6,2"] },
      { number: 3, text: "Denn deine Pfeile sind in mich eingedrungen,* und deine Hand hat sich auf mich herabgesenkt*.*", footnotes: ["℘ Hi 6,4", "aramäische Üs.: liegt o. lastet auf mir", "℘ Ps 32,4"] },
      { number: 4, text: "Keine heile Stelle ist an meinem Fleisch wegen deiner Verwünschung, nichts Heiles an meinen Gebeinen wegen meiner Verfehlung." },
      { number: 5, text: "Denn meine Sünden wachsen mir über den Kopf*, wie eine schwere Last sind sie zu schwer für mich*.", footnotes: ["℘ Ps 40,13; 65,4", "℘ Esr 9,6; Mt 11,28"] },
      { number: 6, text: "Es stinken, es eitern meine Wunden wegen meiner Torheit*.", footnotes: ["℘ Ps 107,17"] },
      { number: 7, text: "Ich bin gekrümmt, sehr gebeugt; den ganzen Tag gehe ich trauernd einher." },
      { number: 8, text: "Denn voll Brand sind meine Lenden, und keine heile Stelle ist an meinem Fleisch." },
      { number: 9, text: "Ich bin ermattet und ganz zerschlagen, ich schreie aus dem Stöhnen meines Herzens." },
      { number: 10, text: "Herr, vor dir ist all mein Begehren, und mein Seufzen ist nicht vor dir verborgen*.", footnotes: ["℘ Lk 8,47"] },
      { number: 11, text: "Mein Herz pocht, verlassen hat mich meine Kraft*; und das Licht meiner Augen, auch das habe ich nicht mehr*.", footnotes: ["℘ Ps 22,16", "w. und das Licht meiner Augen — auch es (w. Mehrzahl: sie) — ist nicht bei mir"] },
      { number: 12, text: "Meine Lieben und meine Gefährten stehen fernab von meiner Plage, und meine Verwandten stehen von ferne*.", footnotes: ["℘ Ps 31,12; 69,9; 88,9.19; Hi 19,13.14; Mt 27,55"] },
      { number: 13, text: "Die nach meinem Leben trachten, legen Schlingen*; und die mein Unglück suchen, reden von Verderben und sinnen auf Betrug* den ganzen Tag.", footnotes: ["℘ Ps 119,110", "o. Hinterlist"] },
      { number: 14, text: "Ich aber bin wie ein Tauber, höre nicht, und wie ein Stummer, der seinen Mund nicht aufmacht*.", footnotes: ["℘ Jes 53,7; Mt 26,63"] },
      { number: 15, text: "Ja, ich bin wie ein Mann, der nicht hört, und in dessen Mund keine Entgegnungen* sind*.", footnotes: ["o. Widerreden; o. Vorwürfe", "℘ Jes 53,7; Mt 26,63"] },
      { number: 16, text: "Denn auf dich, HERR, harre ich; du, du wirst antworten, Herr, mein Gott." },
      { number: 17, text: "Denn ich sprach: »Dass sie sich nicht über mich freuen*, beim Wanken meines Fußes großtun gegen mich*.«", footnotes: ["℘ Ps 35,19", "℘ Ps 13,5"] },
      { number: 18, text: "Denn ich bin nahe am Straucheln, und mein Schmerz steht mir ständig vor Augen." },
      { number: 19, text: "Denn ich bekenne meine Schuld*; ich bin bekümmert wegen meiner Verfehlung.", footnotes: ["℘ Ps 32,5"] },
      { number: 20, text: "*Meine lebendigen Feinde* sind stark*, und zahlreich sind, die ohne Grund mich hassen*;", footnotes: ["mit Änderung eines Buchstabens: Die mich grundlos anfeinden", "mit Änderung eines Buchstabens: Die mich grundlos anfeinden", "℘ Ps 142,7", "℘ Ps 35,19"] },
      { number: 21, text: "ja, sie vergelten Gutes mit Bösem*, sie feinden mich an, weil ich dem Guten nachjage.", footnotes: ["℘ Ps 35,12"] },
      { number: 22, text: "Verlass mich nicht, HERR; mein Gott, sei nicht fern von mir*!", footnotes: ["℘ Ps 22,12"] },
      { number: 23, text: "Eile zu meiner Hilfe, Herr, meine Rettung*!", footnotes: ["℘ Ps 22,20; 40,18"] },
    ]},
    { number: 39, verses: [
      { number: 1, text: "Dem Chorleiter. Für Jedutun*.* Ein Psalm. Von David.", heading: "Psalm 39", footnotes: ["vgl. 1Chr 16,41.42; 25,1.3", "℘ Ps 62,1; 77,1"] },
      { number: 2, text: "Ich sprach: Ich will auf meine Wege achthaben*, dass ich nicht sündige mit meiner Zunge*; ich will meinen Mund im Zaum halten*, solange der Gottlose vor mir ist.", footnotes: ["℘ Ps 119,33", "℘ Ps 34,14", "℘ Ps 141,3"] },
      { number: 3, text: "Ich verstummte in Schweigen, schwieg — fern vom Guten. Da wurde mein Schmerz erregt." },
      { number: 4, text: "Mein Herz wurde heiß in meinem Innern, bei meinem Stöhnen entbrannte ein Feuer; ich sprach mit meiner Zunge*:", footnotes: ["℘ Ps 90,12"] },
      { number: 5, text: "Tue mir kund, HERR, mein Ende und welches das Maß meiner Tage ist, damit ich erkenne, wie vergänglich ich bin*!", footnotes: ["℘ Ps 90,9"] },
      { number: 6, text: "Siehe, handbreit hast du meine Tage gemacht, und meine Lebenszeit ist wie nichts vor dir; nur ein Hauch* ist jeder Mensch, *wie fest er stehe*. //", footnotes: ["o. nur Nichtigkeit", "w. stehend, o. hingestellt", "w. stehend, o. hingestellt\n℘ Ps 89,48; 144,4; Jak 4,14"] },
      { number: 7, text: "Nur als ein Schattenbild wandelt der Mann einher*; nur um Nichtigkeit lärmen sie; er häuft auf und weiß nicht, wer es einsammeln wird*.", footnotes: ["℘ Hi 14,2", "℘ Ps 49,11; Pred 2,21; Lk 12,20"] },
      { number: 8, text: "Und nun, auf was harre ich, Herr? Meine Hoffnung, sie gilt dir*!", footnotes: ["℘ Ps 130,6"] },
      { number: 9, text: "Rette mich von allen meinen Vergehen, mach mich nicht dem Narren zum Hohn!" },
      { number: 10, text: "Ich bin verstummt, mache meinen Mund nicht auf; denn du, du hast gehandelt." },
      { number: 11, text: "Nimm von mir deine Plage! Vom Streit deiner Hand gegen mich* vergehe ich.", footnotes: ["LXX: Von der Wucht (o. Kraft) deiner Hand"] },
      { number: 12, text: "Strafst du einen Mann mit Züchtigungen wegen seiner Schuld, so lässt du seine Schönheit wie die Motte zergehen*; nur ein Hauch* sind alle Menschen*. //", footnotes: ["℘ Hi 13,28", "o. nur Nichtigkeit", "℘ Ps 90,9"] },
      { number: 13, text: "Höre mein Gebet, HERR, und vernimm mein Schreien*; schweige nicht zu meinen Tränen! Denn ein Fremdling bin ich bei dir, ein Beisasse* wie alle meine Väter*.", footnotes: ["℘ Ps 18,7", "d. i. ein Ansässiger ohne Bürgerrecht", "℘ Ps 119,19; 3Mo 25,23; 1Chr 29,15; Hebr 11,13"] },
      { number: 14, text: "Blicke von mir weg, dass ich noch einmal fröhlich werde, bevor ich dahingehe und nicht mehr bin*!", footnotes: ["℘ Hi 10,20"] },
    ]},
    { number: 40, verses: [
      { number: 1, text: "Dem Chorleiter. Von David. Ein Psalm.", heading: "Psalm 40" },
      { number: 2, text: "Beharrlich habe ich auf den HERRN geharrt, und er hat sich zu mir geneigt und mein Schreien gehört*.", footnotes: ["℘ Ps 18,7"] },
      { number: 3, text: "Er hat mich heraufgeholt aus der Grube des Verderbens*, aus Schlick und Schlamm*; und er hat meine Füße auf Felsen gestellt*, meine Schritte fest gemacht*.", footnotes: ["o. der Öde\n℘ Ps 55,24", "℘ Ps 69,3", "℘ Ps 27,5", "℘ Ps 37,23; 119,133"] },
      { number: 4, text: "Und in meinen Mund hat er ein neues Lied gelegt*, einen Lobgesang auf unseren Gott*. Viele werden es sehen und sich fürchten und auf den HERRN vertrauen.", footnotes: ["℘ Ps 33,3", "℘ Ps 71,6"] },
      { number: 5, text: "Glücklich der Mann, der den HERRN zu seiner Zuversicht macht* und sich nicht wendet zu den Drängern* und den in Lüge Festgefahrenen!", footnotes: ["℘ Ps 73,28", "o. den Ungestümen"] },
      { number: 6, text: "Vielfach hast du, HERR, mein Gott, deine Wundertaten und deine Pläne an uns vollbracht; nichts ist mit dir zu vergleichen. Wollte ich davon berichten und reden — sie sind zu zahlreich, um sie aufzuzählen*.", footnotes: ["℘ Ps 71,15; 139,17.18; Hi 5,9"] },
      { number: 7, text: "An Schlacht- und Speisopfern hattest du kein Gefallen,* Ohren hast du mir gegraben*; Brand- und Sündopfer hast du nicht gefordert*.", footnotes: ["℘ Ps 51,18", "℘ Jes 50,4.5", "℘ Ps 50,9.13"] },
      { number: 8, text: "Da sprach ich: Siehe, ich komme; in der Rolle des Buches steht über mich *geschrieben*.", footnotes: ["Zieht man im Mas. T. das erste Wort von V. 9 noch zu V. 8, was aus Gründen des Versmaßes möglich wäre, so heißt es: geschrieben, was zu tun ist. 9 Dein Wohlgefallen, mein Gott", "℘ Lk 24,44; Joh 5,46"] },
      { number: 9, text: "Dein Wohlgefallen zu tun, mein Gott*, liebe ich*; und dein Gesetz* ist tief in meinem Innern*.", footnotes: ["Zieht man im Mas. T. das erste Wort von V. 9 noch zu V. 8, was aus Gründen des Versmaßes möglich wäre, so heißt es: geschrieben, was zu tun ist. 9 Dein Wohlgefallen, mein Gott", "℘ Joh 4,34; Phil 2,8; Hebr 10,5-7", "o. deine Weisung", "℘ Ps 37,31; Jer 31,33"] },
      { number: 10, text: "Ich habe Gerechtigkeit verkündet in großer Versammlung*; siehe, meine Lippen hemmte ich nicht — HERR, du weißt es!", footnotes: ["℘ Ps 22,26"] },
      { number: 11, text: "Deine Gerechtigkeit habe ich nicht verborgen im Innern meines Herzens; deine Zuverlässigkeit und deine Hilfe habe ich ausgesprochen, deine Gnade und deine Treue* nicht verhehlt vor der großen Versammlung.", footnotes: ["o. Wahrheit\n℘ Ps 89,2"] },
      { number: 12, text: "Du, HERR, wirst dein Erbarmen nicht von mir zurückhalten; deine Gnade und deine Treue* werden beständig mich behüten*!", footnotes: ["o. Wahrheit", "℘ Ps 61,8"] },
      { number: 13, text: "Denn Übel bis zur Unzahl haben mich umgeben, meine Sünden haben mich erreicht*, dass ich nicht aufzublicken vermag; zahlreicher sind sie als die Haare meines Hauptes, und mein Herz hat mich verlassen.", footnotes: ["℘ Ps 38,5"] },
      { number: 14, text: "*Lass dir gefallen, HERR, mich zu retten! HERR, eile zu meiner Hilfe*!", footnotes: ["℘ V. 14-18: Ps 70,2-6", "℘ Ps 22,20; 38,23"] },
      { number: 15, text: "Es sollen sich schämen und beschämt werden allesamt, die nach meinem Leben trachten, es wegzuraffen; es sollen zurückweichen und zuschanden werden, die Gefallen haben an meinem Unglück*!", footnotes: ["℘ Ps 6,11; 35,26; 129,5"] },
      { number: 16, text: "Es sollen sich entsetzen über ihre Schande, die zu mir sagen: Haha! Haha*!", footnotes: ["℘ Ps 35,21.25; Hes 26,2"] },
      { number: 17, text: "Es mögen fröhlich sein und sich freuen an dir alle, die dich suchen; es mögen stets sagen: »Groß ist der HERR!«, die dein Heil lieben*.", footnotes: ["℘ Ps 35,27; Jes 25,9"] },
      { number: 18, text: "Ich aber bin elend und arm*, der Herr denkt an mich*. Meine Hilfe und mein Retter bist du; mein Gott, zögere nicht*!", footnotes: ["℘ Ps 25,16; 142,7", "℘ 1Petr 5,7", "℘ Ps 22,20; 38,23"] },
    ]},
    { number: 41, verses: [
      { number: 1, text: "Dem Chorleiter. Ein Psalm. Von David.", heading: "Psalm 41" },
      { number: 2, text: "Glücklich, wer achthat auf den Geringen*; am Tage des Übels wird der HERR ihn retten*.", footnotes: ["℘ Spr 14,21; 19,17", "℘ Mt 5,7"] },
      { number: 3, text: "Der HERR wird ihn bewahren und ihn am Leben erhalten; er wird glücklich gepriesen im Lande. Gib ihn nicht der Gier seiner Feinde preis!*", footnotes: ["mit alten Üs.: Er wird ihn nicht preisgeben der Gier seiner Feinde."] },
      { number: 4, text: "Der HERR wird ihn stützen auf dem Siechbett, sein ganzes Lager wandelst du um in seiner Krankheit." },
      { number: 5, text: "Ich sprach: HERR, sei mir gnädig*! Heile meine Seele, denn ich habe gegen dich gesündigt*.", footnotes: ["℘ Ps 51,3; 56,2; 57,2; 67,2; 86,3", "℘ Ps 51,6"] },
      { number: 6, text: "Meine Feinde reden Böses gegen mich:* »Wann wird er sterben und sein Name verloren gehen?«", footnotes: ["so mit alten Üs.; Mas. T.: Meine Feinde sprechen mir Böses (zu)."] },
      { number: 7, text: "Und wenn einer kommt, um mich zu sehen, redet Falsches* sein Herz, er* sammelt sich Schlechtes; er geht hinaus, draußen sagt er es.", footnotes: ["o. Nichtiges; o. Lüge", "o. es (das Herz)"] },
      { number: 8, text: "Vereint gegen mich flüstern all meine Hasser; gegen mich ersinnen sie mir Böses:" },
      { number: 9, text: "»Verderben* ist über ihn ausgegossen;* und der da liegt, wird nicht wieder aufstehen.«", footnotes: ["w. Eine heillose Sache", "℘ Ps 101,3"] },
      { number: 10, text: "Selbst mein Freund*, auf den ich vertraute, der mein Brot aß, hat die Ferse gegen mich erhoben*.", footnotes: ["w. Mann meiner Unbefangenheit (unversehrten Beziehung, Freundschaft, meines Friedens) = mein Vertrauter", "℘ Ps 55,13-15; Joh 13,18"] },
      { number: 11, text: "Du aber, HERR, sei mir gnädig und richte mich auf, dass ich es ihnen vergelte!" },
      { number: 12, text: "Daran erkenne ich, dass du Gefallen an mir hast, dass mein Feind nicht über mich jauchzt*.", footnotes: ["℘ Ps 30,2"] },
      { number: 13, text: "Ich aber in meiner Lauterkeit, mich hast du aufrecht gehalten* und mich vor dein Angesicht gestellt auf ewig.", footnotes: ["℘ Ps 147,6"] },
      { number: 14, text: "Gepriesen sei der HERR, der Gott Israels, von Ewigkeit bis in Ewigkeit! Amen, ja Amen*.", footnotes: ["℘ Ps 72,18.19; 89,53; 106,48"] },
    ]},
    { number: 42, verses: [
      { number: 1, text: "ZWEITES BUCH Dem Chorleiter. Ein Maskil*. Von den Söhnen Korachs*.", heading: "Psalm 42", footnotes: ["s. Anm. zu Ps 32,1", "℘ 2Mo 6,24; 4Mo 26,11"] },
      { number: 2, text: "Wie eine Hirschkuh lechzt nach Wasserbächen*, so lechzt meine Seele nach dir, Gott!", footnotes: ["w. über den Wasserbächen"] },
      { number: 3, text: "Meine Seele dürstet nach Gott*, nach dem lebendigen Gott*: Wann werde ich kommen und erscheinen vor Gottes Angesicht*?*", footnotes: ["℘ Ps 63,2; 143,6", "℘ Ps 84,3; 1Tim 4,10", "so Mas. T.; vielleicht ist aber mit hebr. Handschr. und alten Üs. zu lesen: Wann werde ich kommen und Gottes Angesicht schauen", "℘ 2Mo 23,17"] },
      { number: 4, text: "Meine Tränen sind mein Brot geworden* Tag und Nacht, da man den ganzen Tag zu mir sagt: Wo ist dein Gott*?", footnotes: ["℘ Ps 80,6; 102,10", "℘ Ps 79,10; 115,2; Joe 2,17"] },
      { number: 5, text: "Daran will ich denken und vor mir ausschütten meine Seele, wie ich einherzog, *in der Schar sie führte* zum Hause Gottes, mit Klang des Jubels und Dankes — ein feierlicher Aufzug.", footnotes: ["Der Mas. T. ist hier recht zweifelhaft. Die vorgeschlagene Üs. versucht, ihn zu halten. Manche schlagen vor, mit geringfügiger Abänderung der Konsonanten und Vokale zu lesen: vorbei am Versteck der Mächtigen (d. h. ungefährdet)", "Der Mas. T. ist hier recht zweifelhaft. Die vorgeschlagene Üs. versucht, ihn zu halten. Manche schlagen vor, mit geringfügiger Abänderung der Konsonanten und Vokale zu lesen: vorbei am Versteck der Mächtigen (d. h. ungefährdet)"] },
      { number: 6, text: "Was bist du so aufgelöst*, meine Seele, und stöhnst* in mir? Harre auf Gott! — denn ich werde ihn noch preisen für *das Heil* seines Angesichts*.", footnotes: ["o. gebeugt", "o. bist unruhig", "Bei anderer Vers- und Wortabtrennung lautet der Text wie in V. 12 und Ps 43,5.", "w. Rettungen, o. Heilstaten", "℘ Ps 43,5"] },
      { number: 7, text: "Mein Gott*, aufgelöst* in mir ist meine Seele; darum denke ich an dich aus dem Land des Jordan und des Hermon, vom Berg Misar.", footnotes: ["Bei anderer Vers- und Wortabtrennung lautet der Text wie in V. 12 und Ps 43,5.", "o. gebeugt"] },
      { number: 8, text: "Urflut ruft der Urflut zu beim Brausen deiner Wassergüsse; alle deine Wogen und deine Wellen sind über mich hingegangen*.", footnotes: ["℘ Ps 88,8; 124,4; Jon 2,4"] },
      { number: 9, text: "Des Tages wird der HERR seine Gnade aufbieten, und des Nachts wird sein Lied bei mir sein,* ein Gebet zu dem Gott meines Lebens.", footnotes: ["℘ Ps 92,3"] },
      { number: 10, text: "Sagen will ich zu Gott, meinem Fels: »Warum hast du mich vergessen*? Warum muss ich trauernd einhergehen, bedrückt durch den Feind?*«", footnotes: ["℘ Kla 5,20", "℘ Ps 43,2; 55,4"] },
      { number: 11, text: "Wie* Mord in meinen Gebeinen höhnen mich meine Bedränger*, indem sie den ganzen Tag zu mir sagen: Wo ist dein Gott*?", footnotes: ["so mit leichter Änderung des Konsonantentextes; w. Bei, o. Mit", "℘ Ps 102,9", "℘ Ps 79,10; 115,2; Joe 2,17"] },
      { number: 12, text: "Was bist du so aufgelöst*, meine Seele, und was stöhnst* du in mir? Harre auf Gott! — denn ich werde ihn noch preisen, das Heil* meines Angesichts und meinen Gott*.", footnotes: ["o. gebeugt", "o. bist unruhig", "w. Rettungen, o. Heilstaten", "℘ Ps 43,5"] },
    ]},
    { number: 43, verses: [
      { number: 1, text: "Schaffe mir Recht, Gott,* und führe meinen Rechtsstreit* mit* der gnadenlosen Nation! Vom Mann des Betrugs* und des Unrechts rette mich*!", heading: "Psalm 431", footnotes: ["℘ Ps 54,3", "℘ Ps 7,7", "eigentlich: von . . . weg", "o. der Hinterlist", "℘ Ps 71,4; 140,5"] },
      { number: 2, text: "Denn du bist der Gott meiner Zuflucht*. Warum hast du mich verworfen*? Warum muss ich trauernd einhergehen, bedrückt durch den Feind*?", footnotes: ["w. Zufluchtsort, o. Bergfeste\n℘ Ps 28,7", "℘ Ps 88,15", "℘ Ps 42,10"] },
      { number: 3, text: "Sende dein Licht und deine Wahrheit*; sie sollen mich leiten, mich bringen zu deinem heiligen Berg und zu deinen Wohnungen.", footnotes: ["o. Treue\n℘ Ps 57,4"] },
      { number: 4, text: "So werde ich kommen zum Altar Gottes, zum Gott meiner Jubelfreude, und werde dich preisen auf der Zither*, Gott, mein Gott*!", footnotes: ["℘ Ps 57,8.9; 71,22", "℘ Ps 63,2; Sach 13,9"] },
      { number: 5, text: "Was bist du so aufgelöst*, meine Seele, und was stöhnst* du in mir? Harre auf Gott, denn ich werde ihn noch preisen, das Heil* meines Angesichts und meinen Gott*.", footnotes: ["o. gebeugt", "o. bist unruhig", "w. Rettungen, o. Heilstaten", "℘ Ps 42,6.12"] },
    ]},
    { number: 44, verses: [
      { number: 1, text: "Dem Chorleiter. Von den Söhnen Korachs*. Ein Maskil*.", heading: "Psalm 44", footnotes: ["℘ Ps 42,1", "s. Anm. zu Ps 32,1"] },
      { number: 2, text: "Gott, mit unseren Ohren haben wir gehört, unsere Väter haben uns erzählt die Großtat, die du gewirkt hast in ihren Tagen, in den Tagen der Vorzeit." },
      { number: 3, text: "Du, du hast mit deiner Hand Nationen ausgetrieben, aber sie hast du eingepflanzt, Völkerschaften hast du Schaden zugefügt*, aber sie hast du ausgebreitet*.", footnotes: ["andere Lesart: zerschlagen", "℘ Ps 78,55; 80,9-12"] },
      { number: 4, text: "Denn nicht durch ihr Schwert haben sie das Land in Besitz genommen, und nicht ihr Arm hat ihnen geholfen; sondern deine Rechte* und dein Arm* und das Licht deines Angesichts, weil du Wohlgefallen an ihnen hattest.", footnotes: ["℘ 2Mo 15,6", "℘ Ps 111,6; 5Mo 7,8.19; Apg 7,45"] },
      { number: 5, text: "Du selbst bist mein König*, Gott; gebiete die Rettungen Jakobs!", footnotes: ["℘ Ps 5,3; Jes 33,22"] },
      { number: 6, text: "Durch dich werden wir niederstoßen unsere Bedränger; durch deinen Namen werden wir zertreten, die gegen uns aufstehen*.", footnotes: ["℘ Ps 60,14"] },
      { number: 7, text: "Denn nicht auf meinen Bogen vertraue ich, und mein Schwert wird mich nicht retten*.", footnotes: ["℘ Hos 1,7"] },
      { number: 8, text: "Denn du rettest uns von unseren Bedrängern, und unsere Hasser machst du zuschanden*.", footnotes: ["℘ Ps 106,10; Lk 1,71"] },
      { number: 9, text: "In Gott rühmen wir uns den ganzen Tag, und deinen Namen werden wir ewig preisen*. //", footnotes: ["℘ Jer 9,24"] },
      { number: 10, text: "Doch du hast uns* verworfen* und in Schande gebracht und zogst nicht aus mit unseren Heeren*.", footnotes: ["Einige Handschr. und eine Üs. haben »uns«.", "℘ Ps 89,39", "℘ Ps 60,12; 4Mo 14,42"] },
      { number: 11, text: "Du ließest uns zurückweichen vor dem Bedränger, und die uns hassen, haben für sich geraubt*.", footnotes: ["℘ Ri 2,14"] },
      { number: 12, text: "Du gabst uns hin wie Schlachtvieh, und unter die Nationen hast du uns zerstreut*.", footnotes: ["℘ 5Mo 4,27"] },
      { number: 13, text: "Du verkauftest dein Volk um ein Geringes und hast keinen Gewinn gemacht durch ihren Kaufpreis." },
      { number: 14, text: "Du machtest uns unseren Nachbarn zum Hohn, zu Spott und Schimpf denen, die uns umgeben*.", footnotes: ["℘ Ps 79,4; 123,3"] },
      { number: 15, text: "Du machtest uns zum Sprichwort unter den Nationen, zum Kopfschütteln unter den Völkerschaften*.", footnotes: ["℘ 1Kö 9,7; Kla 2,15"] },
      { number: 16, text: "Den ganzen Tag ist meine Schande vor mir, und Scham hat mir mein Gesicht bedeckt" },
      { number: 17, text: "wegen der Stimme des Schmähers und Lästerers, angesichts des Feindes und des Rachgierigen." },
      { number: 18, text: "Dieses alles ist über uns gekommen, doch wir hatten dich nicht vergessen, noch verraten deinen Bund." },
      { number: 19, text: "Unser Herz ist nicht zurückgewichen, noch sind unsere Schritte abgebogen von deinem Pfad*,", footnotes: ["℘ Hi 23,11"] },
      { number: 20, text: "dass du uns so zermalmt hast am Ort der Schakale* und uns bedeckt mit Finsternis.", footnotes: ["℘ Ps 63,11"] },
      { number: 21, text: "Hätten wir den Namen unseres Gottes vergessen und unsere Hände zu einem fremden Gott ausgestreckt," },
      { number: 22, text: "würde Gott das nicht erforschen? Denn er erkennt die Geheimnisse des Herzens*.", footnotes: ["℘ Ps 94,11; 139,2; Jer 17,10; Apg 15,8"] },
      { number: 23, text: "Ja, deinetwegen werden wir umgebracht den ganzen Tag, als Schlachtvieh werden wir angesehen*.", footnotes: ["℘ Röm 8,36"] },
      { number: 24, text: "Erwache! Warum schläfst du, Herr? Wache auf!* Verwirf uns nicht auf ewig!", footnotes: ["℘ Ps 35,23"] },
      { number: 25, text: "Warum verbirgst du dein Angesicht*, vergisst unser Elend und unsere Bedrückung*?", footnotes: ["℘ Ps 88,15; Hi 13,24", "℘ Ps 10,1; Mk 4,38"] },
      { number: 26, text: "Denn unsere Seele ist in den Staub gebeugt, unser Bauch klebt an der Erde*.", footnotes: ["℘ Ps 119,25"] },
      { number: 27, text: "Stehe auf, uns zur Hilfe, und erlöse uns um deiner Güte willen*!", footnotes: ["℘ Ps 80,3; 115,1"] },
    ]},
    { number: 45, verses: [
      { number: 1, text: "Dem Chorleiter. Nach Schoschannim*. Von den Söhnen Korachs*. Ein Maskil*. Ein Liebeslied.", heading: "Psalm 45", footnotes: ["wahrscheinlich Angabe einer Melodie: Lilien\n℘ Ps 69,1; 80,1", "℘ Ps 42,1", "s. Anm. zu Ps 32,1"] },
      { number: 2, text: "Bewegt ist mein Herz von gutem Wort. Sagen will ich meine Gedichte dem König! Meine Zunge sei wie der Griffel eines geschickten Schreibers!" },
      { number: 3, text: "Du bist schöner als andere Menschen, Anmut ist ausgegossen über deine Lippen*; darum hat Gott dich gesegnet für ewig*.", footnotes: ["℘ Hi 1,16", "℘ Ps 21,7"] },
      { number: 4, text: "Gürte dein Schwert um die Hüfte, du Held; deine Majestät und deine Pracht!" },
      { number: 5, text: "Und deine Pracht* — sei stark, zieh aus für die Sache der Wahrheit* und der Sanftmut* und* der Gerechtigkeit*; da lehre dich furchtbare Taten deine Rechte.", footnotes: ["Vielleicht ist das Wort versehentlich doppelt geschrieben worden, vgl. V. 4.", "o. Treue\n℘ Eph 4,21", "℘ Mt 11,29", "»und« wird so von alten Üs. gelesen", "℘ Jer 23,6; Offb 19,11"] },
      { number: 6, text: "Deine geschärften Pfeile — Völker fallen unter dir — ins Herz der Feinde des Königs!" },
      { number: 7, text: "Dein Thron, Gott, ist immer und ewig*, ein Zepter der Geradheit ist das Zepter deiner Herrschaft.*", footnotes: ["℘ Lk 1,33", "℘ Jes 11,4.5"] },
      { number: 8, text: "Gerechtigkeit hast du geliebt* und Gottlosigkeit gehasst: darum hat Gott, dein Gott, dich gesalbt mit Freudenöl vor deinen Gefährten*.", footnotes: ["℘ Ps 11,7", "℘ Hebr 1,8.9"] },
      { number: 9, text: "Myrrhe und Aloe, Kassia sind alle deine Kleider; aus Palästen von Elfenbein erfreut dich Saitenspiel." },
      { number: 10, text: "Königstöchter stehen da, mit deinen Kostbarkeiten geschmückt*; die Königin steht zu deiner Rechten in Gold von Ofir.", footnotes: ["o. stehen da unter deinen kostbaren Frauen. — Die Üs. ist fraglich. Manche schlagen auch vor, ein Wort im Mas. T. abzuändern und zu lesen: Königstöchter stehen da, dir gegenüber. Damit wäre ein strenger Parallelismus zu V. 10b gewahrt."] },
      { number: 11, text: "Höre, Tochter, und sieh, und neige dein Ohr; und vergiss dein Volk und deines Vaters Haus!" },
      { number: 12, text: "Und wird der König deine Schönheit begehren*, denn er ist dein Herr: So neige dich vor ihm!", footnotes: ["℘ Hi 2,14"] },
      { number: 13, text: "Und die Tochter Tyrus kommt mit Geschenk, deine Gunst suchen die Reichen im Volk." },
      { number: 14, text: "Ganz herrlich ist die Königstochter drinnen*, von Goldgewebe ihr Gewand;", footnotes: ["d. h. in den königlichen Gemächern"] },
      { number: 15, text: "in buntgewebten Kleidern wird sie zum König geführt; Jungfrauen ihr Gefolge, ihre Gefährtinnen*, sie werden zu dir hineingebracht.", footnotes: ["℘ Mt 25,1"] },
      { number: 16, text: "Sie werden geführt unter Freude und Jubel*, sie ziehen ein in den Palast des Königs.", footnotes: ["℘ Jud 24"] },
      { number: 17, text: "An die Stelle deiner Väter werden deine Söhne treten; als Oberste wirst du sie einsetzen auf der ganzen Erde." },
      { number: 18, text: "Ich will deinen Namen bekannt machen durch alle Generationen; darum werden die Völker dich preisen immer und ewig*.", footnotes: ["℘ Ps 66,8; 67,4; 72,15; 117,1; Röm 15,11; Offb 15,4"] },
    ]},
    { number: 46, verses: [
      { number: 1, text: "Dem Chorleiter. Von den Söhnen Korachs*. Nach Alamoth*. Ein Lied.", heading: "Psalm 46", footnotes: ["℘ Ps 42,1", "Unverständlicher Hinweis auf eine Melodie.\n℘ 1Chr 15,20"] },
      { number: 2, text: "Gott ist uns Zuflucht* und Stärke*, als Beistand in Nöten reichlich gefunden*.", footnotes: ["℘ Ps 62,8.9; 91,2; 142,6", "℘ Ps 28,7", "℘ Ps 37,39; 59,17"] },
      { number: 3, text: "Darum fürchten wir uns nicht, wenn auch die Erde erbebt und die Berge mitten ins Meer wanken*.", footnotes: ["℘ Jes 54,10"] },
      { number: 4, text: "Mögen seine Wasser tosen und schäumen*, die Berge erbeben durch sein Aufbäumen! //", footnotes: ["℘ Ps 93,3.4; Jes 8,7"] },
      { number: 5, text: "Des Stromes Läufe* erfreuen die Stadt Gottes, die heiligste der Wohnungen des Höchsten*.", footnotes: ["℘ Offb 22,1", "LXX: geheiligt hat seine Wohnung der Höchste"] },
      { number: 6, text: "Gott ist in ihrer Mitte*, sie wird nicht wanken*; Gott wird ihr helfen früh am Morgen.", footnotes: ["℘ Hes 48,35; Offb 22,3", "℘ Ps 125,1"] },
      { number: 7, text: "Nationen tobten*, Königreiche wankten. Er ließ seine Stimme erschallen: die Erde zerschmolz.", footnotes: ["℘ Ps 2,1"] },
      { number: 8, text: "Der HERR der Heerscharen ist mit uns*, eine Festung* ist uns der Gott Jakobs*. //", footnotes: ["℘ 5Mo 20,1; Jes 7,14; 8,10", "℘ Ps 59,10", "℘ Ps 146,5"] },
      { number: 9, text: "Kommt, schaut die Großtaten des HERRN*, der Entsetzen verbreitet auf Erden*!", footnotes: ["℘ Ps 66,5", "℘ Jes 10,23"] },
      { number: 10, text: "Der Kriege beschwichtigt bis ans Ende der Erde,* Bogen zerbricht* und Speere zerschlägt, Wagen mit Feuer verbrennt*.", footnotes: ["℘ Mi 4,3", "℘ Ps 37,15", "℘ Jos 11,9"] },
      { number: 11, text: "Lasst ab und erkennt, dass ich Gott bin; ich werde erhöht sein unter den Nationen, erhöht auf der Erde*.", footnotes: ["℘ 2Chr 20,6"] },
      { number: 12, text: "Der HERR der Heerscharen ist mit uns, eine Festung ist uns der Gott Jakobs*. //", footnotes: ["℘ Ps 146,5"] },
    ]},
    { number: 47, verses: [
      { number: 1, text: "Dem Chorleiter. Von den Söhnen Korachs*. Ein Psalm.", heading: "Psalm 47", footnotes: ["℘ Ps 42,1"] },
      { number: 2, text: "Ihr Völker alle, klatscht in die Hände! Jauchzt Gott mit Jubelschall!" },
      { number: 3, text: "Denn der HERR, der Höchste, ist gefürchtet*, ein großer König* über die ganze Erde*.", footnotes: ["℘ Ps 66,5", "℘ Ps 95,3", "℘ Ps 99,2; Sach 14,9; Mal 1,14"] },
      { number: 4, text: "Er unterwarf uns die Völker und die Völkerschaften unter unsere Füße." },
      { number: 5, text: "Er erwählte für uns unser Erbe,* den Stolz Jakobs*, den er geliebt hat*. //", footnotes: ["℘ Hes 20,6", "℘ Am 8,7", "℘ Mal 2,3"] },
      { number: 6, text: "Gott ist emporgestiegen unter Jauchzen, der HERR beim Schall des Horns*.", footnotes: ["℘ 1Chr 15,28"] },
      { number: 7, text: "Singt Gott, singet, singt unserem König, singet*!*", footnotes: ["Das hebr. Wort für »singen« kann ebenso mit »spielen« übersetzt werden. Gemeint ist wahrsch. Gesang mit Instrumentalbegleitung.", "℘ Ps 30,5"] },
      { number: 8, text: "Denn Gott ist König der ganzen Erde*; singt einen Psalm*!", footnotes: ["℘ Ps 99,2; Sach 14,9; Mal 1,14", "w. Maskil; vgl. Anm. zu Ps 32,1"] },
      { number: 9, text: "Gott ist König geworden über die Nationen*; Gott hat sich auf seinen heiligen Thron gesetzt.", footnotes: ["℘ Offb 15,3"] },
      { number: 10, text: "Die Edlen der Völker haben sich versammelt mit dem Volk des Gottes Abrahams*; denn die Könige* der Erde sind Gottes; er ist sehr erhaben.", footnotes: ["℘ Jes 2,3", "w. Schilde; vgl. Ps 84,10; 89,19 (Könige als Schutzschilde ihrer Völker)"] },
    ]},
    { number: 48, verses: [
      { number: 1, text: "Ein Lied. Ein Psalm. Von den Söhnen Korachs.*", heading: "Psalm 48", footnotes: ["℘ Ps 42,1"] },
      { number: 2, text: "Groß ist der HERR und sehr zu loben in der Stadt unseres Gottes*. Sein heiliger Berg*", footnotes: ["℘ Ps 87,3; Hebr 12,22", "℘ Ps 99,9; Jes 2,2.3"] },
      { number: 3, text: "ragt schön empor, eine Freude der ganzen Erde; der Berg Zion*, im äußersten Norden, die Stadt des großen Königs*.", footnotes: ["℘ Ps 50,2", "℘ Ps 135,21; Mt 5,35"] },
      { number: 4, text: "Gott ist in ihren Palästen bekannt als Zuflucht." },
      { number: 5, text: "Denn siehe, die Könige hatten sich verabredet*, waren herangezogen miteinander.", footnotes: ["℘ Ps 2,2"] },
      { number: 6, text: "Sie sahen, da staunten sie; sie wurden bestürzt, von Angst fortgetrieben." },
      { number: 7, text: "Zittern ergriff sie dort, Wehen wie die Gebärende*.", footnotes: ["℘ 2Mo 15,14; Jes 13,8"] },
      { number: 8, text: "Durch den Ostwind zertrümmerst du die Tarsisschiffe*.", footnotes: ["℘ 1Kö 22,49"] },
      { number: 9, text: "Wie wir gehört haben, so haben wir es gesehen in der Stadt des HERRN der Heerscharen*, in der Stadt unseres Gottes; Gott wird sie fest gründen bis in Ewigkeit*. //", footnotes: ["℘ 1Kö 10,6.7", "℘ Ps 87,5"] },
      { number: 10, text: "Wir haben nachgedacht, Gott, über deine Gnade im Innern deines Tempels." },
      { number: 11, text: "Wie dein Name, Gott, so ist dein Ruhm bis an die Enden der Erde*; mit Gerechtigkeit ist gefüllt deine Rechte.", footnotes: ["℘ Mal 1,11"] },
      { number: 12, text: "Es freue sich der Berg Zion, es sollen jauchzen die Töchter Judas wegen deiner Gerichte*!", footnotes: ["℘ Ps 97,8"] },
      { number: 13, text: "Zieht rund um Zion und umkreist ihn, zählt seine Türme;" },
      { number: 14, text: "richtet euer Herz auf seine Wälle, mustert* seine Paläste, damit ihr erzählt der künftigen Generation*:", footnotes: ["Die Bedeutung des Wortes ist ungeklärt; die Üs. ist abgeleitet aus der Entsprechung zum vorausgehenden Satz.", "℘ Ps 71,18"] },
      { number: 15, text: "Ja, dieser ist Gott, unser Gott* immer und ewig*! Er wird uns leiten*.", footnotes: ["℘ Ps 95,7; 105,7", "℘ Ps 90,2", "Mas. T. fügt hier hinzu: al-muth, w. auf das Sterben, d. h. vielleicht: bis an den Tod. Manche lesen mit leichter Änderung des Mas. T.: bis in alle Ewigkeit (so auch viele hebr. Handschr. und LXX). Es könnte aber auch, ähnlich wie Ps 9,1, ein Hinweis für den musikalischen Vortrag sein und zur Überschrift von Ps 49 gehören.\n℘ Jes 58,11"] },
    ]},
    { number: 49, verses: [
      { number: 1, text: "Dem Chorleiter. Von den Söhnen Korachs*. Ein Psalm.", heading: "Psalm 49", footnotes: ["℘ Ps 42,1"] },
      { number: 2, text: "Hört dies, ihr Völker alle; nehmt es zu Ohren, alle Bewohner der Welt*;", footnotes: ["℘ Mi 1,2"] },
      { number: 3, text: "Söhne der Einfachen wie der Vornehmen*, Reiche und Arme miteinander!", footnotes: ["w. sowohl Menschensöhne als auch Männersöhne\n℘ Ps 4,3"] },
      { number: 4, text: "Mein Mund soll Weisheit reden, und das Sinnen meines Herzens ist Einsicht." },
      { number: 5, text: "Mein Ohr will ich zu einem Spruch neigen, mein Rätsel auflösen zur Zither*.", footnotes: ["℘ Ps 78,2"] },
      { number: 6, text: "Warum sollte ich mich fürchten in Tagen des Übels*, wenn die Sünde derer, die mich hintergehen*, mich umringt*?", footnotes: ["℘ Ps 112,7.8", "so mit Änderung der Vokalisierung; Mas. T.: die Sünde meiner Fersen mich umringt", "℘ Ps 56,5-7"] },
      { number: 7, text: "Sie vertrauen auf ihr Vermögen* und rühmen sich der Größe ihres Reichtums*.", footnotes: ["℘ Mk 10,24", "℘ Jer 9,22"] },
      { number: 8, text: "Niemals kann ein Mann seinen Bruder* loskaufen, nicht kann er Gott sein Lösegeld geben", footnotes: ["Statt »Bruder« lesen 8 hebr. Handschr.: nur, jedoch. Dann heißt der Satz: Nur, es kann sich niemand loskaufen"] },
      { number: 9, text: "— denn zu kostbar ist das Kaufgeld für ihre Seele, und er muss davon ablassen auf ewig* —,", footnotes: ["℘ Mt 16,26"] },
      { number: 10, text: "dass er fortlebe immer, die Grube nicht sehe*.", footnotes: ["℘ Ps 89,49"] },
      { number: 11, text: "Denn man sieht: die Weisen sterben, der Tor und der Unvernünftige kommen miteinander um, und sie lassen anderen ihr Vermögen*.", footnotes: ["℘ Ps 39,7"] },
      { number: 12, text: "*Ihr Gedanke ist, dass ihre Häuser in Ewigkeit stehen, ihre Wohnung von Generation zu Generation*; sie hatten Ländereien nach ihren Namen benannt.", footnotes: ["Diese Üs. ist ein Versuch, den schwierigen Mas. T. wiederzugeben. Bei Umstellung zweier Konsonanten: Gräber sind ihre Häuser in Ewigkeit, ihre Wohnung von Generation zu Generation. So LXX und andere alte Üs.", "Diese Üs. ist ein Versuch, den schwierigen Mas. T. wiederzugeben. Bei Umstellung zweier Konsonanten: Gräber sind ihre Häuser in Ewigkeit, ihre Wohnung von Generation zu Generation. So LXX und andere alte Üs."] },
      { number: 13, text: "Doch der Mensch, der im Ansehen ist, bleibt nicht*; er gleicht dem Vieh, das umkommt*.", footnotes: ["mit Änderung eines Buchstabens: er hat keine Einsicht; wie in V. 21", "℘ Pred 3,19"] },
      { number: 14, text: "Dies ist ihr Weg, der Weg derer, die unerschütterlich sind, und ihr Ende, das Ende derer, die Gefallen finden an ihren Worten: //" },
      { number: 15, text: "Wie Schafe weidet sie der Tod, sie sinken zum Scheol hinab; und am Morgen herrschen die Aufrichtigen über sie; ihre Gestalt zerfällt, der Scheol ist ihre Wohnung*.", footnotes: ["Der Mas. T. dieses Verses ist bis zur Unverständlichkeit entstellt. Unsere Üs. legt vorsichtige Änderungen zugrunde."] },
      { number: 16, text: "Gott aber wird meine Seele erlösen von der Gewalt des Scheols*; denn er wird mich aufnehmen*. //", footnotes: ["℘ Hos 13,14", "o. er wird mich dem Scheol entreißen"] },
      { number: 17, text: "Fürchte dich nicht, wenn ein Mann sich bereichert, wenn sich vergrößert die Pracht seines Hauses." },
      { number: 18, text: "Denn bei seinem Tod nimmt er das alles nicht mit*; seine Pracht folgt ihm nicht hinab.*", footnotes: ["℘ Lk 12,20", "℘ 1Tim 6,7"] },
      { number: 19, text: "Wenn er auch in seinem Leben seine Seele segnet* — und man preist dich, wenn du es dir gut gehen lässt —,", footnotes: ["℘ Lk 12,19"] },
      { number: 20, text: "so kommt sie doch zur Generation seiner Väter, die nie mehr das Licht sehen*.", footnotes: ["℘ Hi 10,21"] },
      { number: 21, text: "Der Mensch, der im Ansehen ist, hat keine Einsicht, er gleicht dem Vieh, das vertilgt wird*. //", footnotes: ["℘ Pred 3,19"] },
    ]},
    { number: 50, verses: [
      { number: 1, text: "Ein Psalm. Von Asaf.* Gott*, Gott, der HERR, hat geredet und die Erde gerufen, vom Aufgang der Sonne bis zu ihrem Niedergang.", heading: "Psalm 50", footnotes: ["℘ Ps 73-83; 1Chr 6,24", "hebr. el"] },
      { number: 2, text: "Aus Zion, der Schönheit Vollendung*, ist Gott hervorgestrahlt*.", footnotes: ["℘ Ps 48,3; Kla 2,15", "℘ Ps 80,2; 94,1; 5Mo 33,2"] },
      { number: 3, text: "Unser Gott kommt*, und er wird nicht schweigen; Feuer frisst vor ihm her*, und rings um ihn stürmt es gewaltig.", footnotes: ["℘ Ps 96,13; Jes 35,4; Offb 1,7", "℘ Ps 18,9; Dan 7,10"] },
      { number: 4, text: "Er ruft dem Himmel droben und der Erde zu, um sein Volk zu richten:" },
      { number: 5, text: "»Versammelt mir meine Frommen, die meinen Bund geschlossen haben beim Opfer*!«", footnotes: ["℘ 2Mo 24,3-8"] },
      { number: 6, text: "Und der Himmel verkündet seine Gerechtigkeit*, dass Gott Richter ist, er selbst*. //", footnotes: ["℘ Ps 97,6", "℘ 1Mo 18,25"] },
      { number: 7, text: "»Höre, mein Volk, und ich will reden, Israel, und ich will dich verwarnen*!* Ich bin Gott, dein Gott*.", footnotes: ["o. als Zeuge gegen dich auftreten", "℘ Ps 81,9", "℘ 2Mo 20,2"] },
      { number: 8, text: "Nicht wegen deiner Schlachtopfer tadle ich dich, auch deine Brandopfer sind beständig vor mir*.", footnotes: ["℘ Jer 7,21-23"] },
      { number: 9, text: "Ich nehme keinen Stier aus deinem Haus, noch Böcke aus deinen Hürden*.", footnotes: ["℘ Ps 40,7; Apg 17,25"] },
      { number: 10, text: "Denn mein ist alles Getier des Waldes, das Vieh auf tausend Bergen*.", footnotes: ["o. auf den Rinderbergen. — Die hebr. Wörter für »tausend« und »Rinder« sind gleich.\n℘ Ps 24,1.2"] },
      { number: 11, text: "Ich kenne alle Vögel der Berge, und was sich tummelt im Feld, ist mir bekannt." },
      { number: 12, text: "Wenn mich hungerte, ich würde es dir nicht sagen; denn mein ist die Welt und ihre Fülle*.", footnotes: ["℘ 1Kor 10,26"] },
      { number: 13, text: "Sollte ich das Fleisch von Stieren* essen und das Blut von Böcken trinken?", footnotes: ["eigentlich: von Starken"] },
      { number: 14, text: "Opfere Gott Dank* und erfülle dem Höchsten deine Gelübde*;", footnotes: ["℘ Hebr 13,15", "℘ Ps 22,26; 61,9; 69,32; 76,12; 5Mo 23,22; Nah 2,1"] },
      { number: 15, text: "und rufe mich an am Tag der Not;* ich will dich retten*, und du wirst mich verherrlichen*!«", footnotes: ["℘ Ps 77,3; 86,5.7; Mt 8,25; Jak 5,13", "℘ Ps 4,2", "℘ Ps 34,5-7; 120,1; Lk 18,43"] },
      { number: 16, text: "Zu dem Gottlosen aber spricht Gott: »Was hast du meine Ordnungen herzusagen und nimmst meinen Bund in deinen Mund?" },
      { number: 17, text: "Du hast ja die Zucht* gehasst und meine Worte hinter dich geworfen*.", footnotes: ["o. Unterweisung; o. Zurechtweisung", "℘ Spr 1,29; 15,10"] },
      { number: 18, text: "Sahst du einen Dieb, so befreundetest* du dich mit ihm, und mit Ehebrechern hattest du Gemeinschaft*.", footnotes: ["LXX: du liefst mit ihm", "℘ Röm 1,32"] },
      { number: 19, text: "Deinen Mund schicktest du los zum Bösen, und deine Zunge spannte Betrug* davor*.", footnotes: ["o. Hinterlist", "℘ Ps 10,7; 52,4"] },
      { number: 20, text: "Du saßest da, redetest gegen deinen Bruder, gegen den Sohn deiner Mutter stießest du Schmähung aus*.", footnotes: ["℘ 3Mo 19,16"] },
      { number: 21, text: "Das hast du getan, und ich schwieg*; du dachtest, ich sei ganz wie du. Ich werde dich zurechtweisen und es dir vor Augen stellen*.", footnotes: ["℘ Jes 57,11", "℘ Pred 12,14"] },
      { number: 22, text: "Merket doch dies, die ihr Gott vergesst*, damit ich nicht zerreiße, und keiner kann retten*!", footnotes: ["℘ Ps 9,18", "℘ 5Mo 32,39"] },
      { number: 23, text: "Wer Dank opfert*, verherrlicht mich* *und bahnt einen Weg*; ihn werde ich das Heil Gottes sehen lassen*.«", footnotes: ["℘ Ps 34,5-7; 120,1; Lk 18,43", "℘ Ps 34,5-7; 120,1; Lk 18,43", "o. und wer einen Weg bahnt. — Ein paar Handschr. und Üs. lesen »dort«, also: dort ist ein Weg", "o. und wer einen Weg bahnt. — Ein paar Handschr. und Üs. lesen »dort«, also: dort ist ein Weg", "℘ Ps 91,16"] },
    ]},
    { number: 51, verses: [
      { number: 1, text: "Dem Chorleiter. Ein Psalm. Von David.", heading: "Psalm 51" },
      { number: 2, text: "Als der Prophet Nathan zu ihm kam, nachdem er zu Batseba eingegangen war*.", footnotes: ["℘ 2Sam 12,1-14"] },
      { number: 3, text: "Sei mir gnädig, Gott*, nach deiner Gnade; tilge* meine Vergehen* nach der Größe deiner Barmherzigkeit!", footnotes: ["℘ Ps 41,5; Lk 18,13", "o. wische ab; o. lösche aus", "o. Treuebrüche"] },
      { number: 4, text: "Wasche mich völlig von meiner Schuld, und reinige mich von meiner Sünde*!", footnotes: ["℘ Jes 43,25"] },
      { number: 5, text: "Denn ich erkenne meine Vergehen*, und meine Sünde ist stets vor mir.", footnotes: ["o. Treuebrüche"] },
      { number: 6, text: "Gegen dich, gegen dich allein habe ich gesündigt* und getan, was böse ist in deinen Augen; damit du im Recht bist mit deinem Reden, rein erfunden in deinem Richten*.", footnotes: ["℘ Ps 32,5; 41,5", "℘ Röm 3,4"] },
      { number: 7, text: "Siehe, in Schuld bin ich geboren*, und in Sünde hat mich meine Mutter empfangen*.", footnotes: ["℘ Ps 58,4", "℘ Hi 14,4; 1Jo 1,8"] },
      { number: 8, text: "Siehe, du hast Lust an der Wahrheit* im Innern*, und im Verborgenen wirst du mir Weisheit kundtun.", footnotes: ["o. Treue", "Die Bedeutung ist ungeklärt und wird aus der zweiten Verszeile (im Verborgenen, insgeheim) erschlossen.\n℘ 1Chr 29,17"] },
      { number: 9, text: "Entsündige mich mit Ysop, und ich werde rein sein; wasche mich, und ich werde weißer sein als Schnee*.", footnotes: ["℘ Jes 1,18; Apg 15,9"] },
      { number: 10, text: "Lass mich Fröhlichkeit und Freude hören, so werden die Gebeine jauchzen*, die du zerschlagen hast.", footnotes: ["℘ Ps 35,10"] },
      { number: 11, text: "Verbirg dein Angesicht vor meinen Sünden, und tilge* alle meine Schuld!", footnotes: ["o. wische ab; o. lösche aus"] },
      { number: 12, text: "Erschaffe* mir, Gott, ein reines Herz*, und erneuere in mir* einen festen Geist!", footnotes: ["Es handelt sich um das Wort, das sonst von Gottes Schöpferhandeln gebraucht wird (1Mo 1,1).", "℘ Apg 15,9", "w. in meinem Innern"] },
      { number: 13, text: "Verwirf mich nicht von deinem Angesicht, und den Geist deiner Heiligkeit nimm nicht von mir!" },
      { number: 14, text: "Lass mir wiederkehren die Freude deines Heils, und stütze mich mit einem willigen Geist!" },
      { number: 15, text: "Lehren will ich die von dir Abgefallenen* deine Wege*, dass die Sünder zu dir umkehren*.", footnotes: ["o. die, die mit dir gebrochen haben", "℘ Lk 22,32", "℘ Hes 33,11"] },
      { number: 16, text: "Rette mich von Blutschuld*, Gott, du Gott meines Heils, so wird meine Zunge deine Gerechtigkeit jubelnd preisen*.", footnotes: ["℘ 2Sam 12,9", "℘ Ps 71,15"] },
      { number: 17, text: "Herr, tue meine Lippen auf, dass mein Mund dein Lob verkünde*.", footnotes: ["℘ Lk 1,64"] },
      { number: 18, text: "Denn du hast keine Lust am Schlachtopfer*, sonst gäbe ich es; Brandopfer gefällt dir nicht*.", footnotes: ["℘ Ps 40,7", "℘ Hebr 10,6"] },
      { number: 19, text: "Die Opfer Gottes sind ein zerbrochener Geist; ein zerbrochenes und zerschlagenes Herz wirst du, Gott, nicht verachten*.", footnotes: ["℘ Ps 34,19; Jes 57,15; 66,2"] },
      { number: 20, text: "Tue Zion Gutes in deiner Gunst, baue die Mauern Jerusalems*!", footnotes: ["℘ Ps 122,6"] },
      { number: 21, text: "Dann wirst du Lust haben an rechten Opfern*, Brandopfern und Ganzopfern; dann wird man Stiere darbringen auf deinem Altar*.", footnotes: ["w. Opfern der Gerechtigkeit\n℘ Ps 4,6", "℘ Jes 56,7"] },
    ]},
    { number: 52, verses: [
      { number: 1, text: "Dem Chorleiter. Ein Maskil*. Von David.", heading: "Psalm 52", footnotes: ["s. Anm. zu Ps 32,1"] },
      { number: 2, text: "Als Doëg, der Edomiter, kam und dem Saul berichtete und ihm sagte: David ist in das Haus Ahimelechs gekommen*.", footnotes: ["℘ 1Sam 22,9.10"] },
      { number: 3, text: "Was rühmst du dich der Bosheit, du Gewaltiger? Die Gnade Gottes währt den ganzen Tag." },
      { number: 4, text: "Verderben plant deine Zunge, wie ein geschliffenes Schermesser, du Lügner*.", footnotes: ["o. Betrug (Lüge) Übender\n℘ Ps 50,19; 140,4"] },
      { number: 5, text: "Du hast das Böse mehr geliebt als das Gute, die Lüge mehr als gerechtes Reden. //" },
      { number: 6, text: "Du hast alle Worte des Verderbens geliebt, du betrügerische* Zunge*!", footnotes: ["o. hinterlistige", "℘ Ps 120,2"] },
      { number: 7, text: "Gott wird dich auch zerstören für immer; er wird dich niederschlagen und herausreißen aus dem Zelt und entwurzeln aus dem Land der Lebendigen*. //", footnotes: ["℘ Spr 2,22"] },
      { number: 8, text: "Und sehen werden es die Gerechten* und sich fürchten*, und sie werden über ihn lachen:", footnotes: ["℘ Ps 58,11", "℘ Apg 5,11"] },
      { number: 9, text: "»Siehe, der Mann machte nicht Gott zu seinem Schutz, sondern vertraute auf die Größe seines Reichtums, durch sein Schadentun war er stark!«" },
      { number: 10, text: "Ich aber bin wie ein grüner Olivenbaum im Hause Gottes*; ich vertraue auf die Gnade Gottes immer und ewig.", footnotes: ["℘ Ps 92,14"] },
      { number: 11, text: "Ich werde dich ewig preisen, weil du es getan hast; und auf deinen Namen — denn er ist gut* — werde ich harren vor deinen Frommen.", footnotes: ["℘ Ps 54,8"] },
    ]},
    { number: 53, verses: [
      { number: 1, text: "Dem Chorleiter. Al-Machalath*. Ein Maskil*. Von David.", heading: "Psalm 531", footnotes: ["Ein nicht mehr verständlicher Hinweis auf Melodie, Darbietung o. Begleitung des Psalmes.\n℘ Ps 88,1", "s. Anm. zu Ps 32,1"] },
      { number: 2, text: "Der Tor spricht in seinem Herzen: »Es ist kein Gott!« Sie haben Verderben angerichtet und abscheuliches Unrecht geübt; da ist keiner, der Gutes tut." },
      { number: 3, text: "Gott hat vom Himmel herabgeschaut auf die Menschenkinder, um zu sehen, ob ein Verständiger da ist, einer, der Gott sucht." },
      { number: 4, text: "Alle sind abgewichen, sie sind alle verdorben; da ist keiner, der Gutes tut, auch nicht einer*.", footnotes: ["℘ Röm 3,10-12"] },
      { number: 5, text: "Haben denn keine Erkenntnis, die Böses tun, die mein Volk fressen, als äßen sie Brot? Gott rufen sie nicht an." },
      { number: 6, text: "Da überfiel sie Schrecken, ohne dass ein Schrecken da war*; denn Gott hat zerstreut die Gebeine dessen, der dich bedrängt*. Du hast sie zuschanden werden lassen, denn Gott hat sie verworfen.", footnotes: ["℘ 3Mo 26,36; Spr 28,1", "Üs. unsicher, eigentlich: belagert; vielleicht ist jedoch nach LXX mit leichter Änderung der Konsonanten zu übersetzen: Gott hat zerstreut die Gebeine des Gottlosen"] },
      { number: 7, text: "Kämen doch aus Zion die Rettungen für Israel*! Wenn Gott die Gefangenschaft seines Volkes wendet, wird Jakob jubeln, Israel sich freuen.", footnotes: ["℘ Röm 11,26"] },
    ]},
    { number: 54, verses: [
      { number: 1, text: "Dem Chorleiter. Mit Saitenspiel. Ein Maskil*. Von David.", heading: "Psalm 54", footnotes: ["s. Anm. zu Ps 32,1"] },
      { number: 2, text: "Als die Sifiter kamen und zu Saul sprachen: Hält sich David nicht bei uns verborgen?*", footnotes: ["℘ 1Sam 23,19; 26,1"] },
      { number: 3, text: "Gott, durch deinen Namen* rette mich und schaffe mir Recht durch deine Macht*!", footnotes: ["℘ Ps 20,2", "℘ Ps 43,1"] },
      { number: 4, text: "Gott, höre mein Gebet, nimm zu Ohren die Reden meines Mundes*!", footnotes: ["℘ Ps 17,1"] },
      { number: 5, text: "Denn Fremde sind gegen mich aufgestanden, und Gewalttätige trachten nach meinem Leben; sie haben Gott nicht vor sich gestellt*. //", footnotes: ["℘ Ps 86,14"] },
      { number: 6, text: "Siehe, Gott ist mir ein Helfer*; der Herr ist der, der meine Seele stützt*.", footnotes: ["℘ Ps 118,7; Jes 50,7.9", "w. der Herr ist unter denen, die meine Seele stützen"] },
      { number: 7, text: "Er wird das Böse zurücklenken auf meine Feinde; nach deiner Treue vernichte sie*!", footnotes: ["o. bringe sie zum Schweigen\n℘ Ps 143,12"] },
      { number: 8, text: "Opfern will ich dir aus freiem Antrieb; deinen Namen will ich preisen, HERR, denn er ist gut*.", footnotes: ["℘ Ps 52,11; 135,3"] },
      { number: 9, text: "Denn aus aller Not hat er mich gerettet, so dass mein Auge auf meine Feinde herabsieht*.", footnotes: ["℘ Ps 59,11; 91,8"] },
    ]},
    { number: 55, verses: [
      { number: 1, text: "Dem Chorleiter. Mit Saitenspiel. Ein Maskil*. Von David.", heading: "Psalm 55", footnotes: ["s. Anm. zu Ps 32,1"] },
      { number: 2, text: "Nimm zu Ohren, Gott, mein Gebet, und verbirg dich nicht vor meinem Flehen*!", footnotes: ["℘ Ps 17,1; Kla 3,56"] },
      { number: 3, text: "Horche auf mich und antworte mir! Ich irre umher in meiner Klage und muss stöhnen" },
      { number: 4, text: "vor der Stimme des Feindes, vor der Bedrückung des Gottlosen*; denn sie wälzen Unheil auf mich, und im Zorn feinden sie mich an*.", footnotes: ["℘ Ps 42,10", "℘ 2Sam 16,7.8"] },
      { number: 5, text: "Mein Herz bebte in meinem Innern, und Todesschrecken haben mich befallen*.", footnotes: ["℘ Ps 18,6"] },
      { number: 6, text: "Furcht und Zittern kamen mich an, und Schauder bedeckte mich*.", footnotes: ["℘ Jes 21,4"] },
      { number: 7, text: "Und ich sprach: Hätte ich doch Flügel wie die Taube, ich wollte hinfliegen und ruhen." },
      { number: 8, text: "Siehe, weithin entflöhe ich, würde nächtigen in der Wüste. //" },
      { number: 9, text: "Ich wollte eilen, dass ich Zuflucht hätte vor dem heftigen Wind, vor dem Sturm." },
      { number: 10, text: "Verwirre, Herr, spalte ihre Zunge*! — denn Gewalttat und Streit habe ich in der Stadt gesehen*.", footnotes: ["℘ 2Sam 15,31", "℘ Ps 58,3"] },
      { number: 11, text: "Tag und Nacht machen sie die Runde um sie auf ihren Mauern; und Unheil und Mühsal sind in ihrer Mitte*.", footnotes: ["℘ Jes 59,6"] },
      { number: 12, text: "Verderben ist in ihrer Mitte, und Bedrückung und Betrug* weichen nicht von ihrem Marktplatz.", footnotes: ["o. Hinterlist"] },
      { number: 13, text: "Denn nicht ein Feind höhnt mich, sonst würde ich es ertragen; nicht mein Hasser hat großgetan gegen mich, sonst würde ich mich vor ihm verbergen;" },
      { number: 14, text: "sondern du, ein Mensch meinesgleichen, mein Freund und mein Vertrauter*,", footnotes: ["℘ Ps 41,10; Hi 19,19"] },
      { number: 15, text: "die wir die Süße der Gemeinschaft miteinander erlebten, ins Haus Gottes gingen in festlicher Unruhe*!", footnotes: ["Das seltene Wort weist auf den tumultartigen Festbetrieb (vgl. Ps 2,1a »toben«) o. auf die feierliche Erregung."] },
      { number: 16, text: "Der Tod überrasche sie, lebendig mögen sie hinabfahren in den Scheol*; denn Bosheiten sind in ihrer Wohnung*, in ihrem Innern.", footnotes: ["℘ 4Mo 16,33", "Das zugrunde liegende hebr. Wort ist bisher unerklärt. Der Übersetzungsversuch lehnt sich an das folgende, sicher als Parallele aufzufassende Wort »in ihrem Innern« an."] },
      { number: 17, text: "Ich aber, ich rufe zu Gott, und der HERR hilft mir*.", footnotes: ["℘ Ps 72,12"] },
      { number: 18, text: "Abends und morgens und mittags klage und stöhne ich*; und er hat meine Stimme gehört*.", footnotes: ["℘ Ps 17,1; Kla 3,56", "℘ Lk 18,7"] },
      { number: 19, text: "Er hat meine Seele zum Frieden erlöst, dass sie mir nicht nahen können*; denn mit vielen sind sie gegen mich gewesen.", footnotes: ["Mas. T. ist nur mit leichter Änderung der Vokale zu übersetzen."] },
      { number: 20, text: "Hören wird Gott* und sie unterdrücken — er thront ja von alters her*; // weil es keine Zuverlässigkeit* bei ihnen gibt* und sie Gott nicht fürchten*.", footnotes: ["℘ Ps 6,10", "℘ Ps 93,2", "w. gegenseitige Verpflichtungen; also auch kein Beachten solcher Verbindlichkeiten", "℘ Jer 5,3", "℘ 2Kö 17,34"] },
      { number: 21, text: "Er* hat ausgestreckt seine Hände gegen seine Friedensbeschlüsse*, entweiht hat er seinen Bund.", footnotes: ["d. h. der Gottlose", "wahrscheinlich mit Änderung der Vokalisierung: Freunde; der Mas. T. dürfte hier entstellt sein"] },
      { number: 22, text: "Glatter als weiche Butter ist sein Mund*,* und Feindschaft ist sein Herz; geschmeidiger als Öl sind seine Worte, aber sie sind gezogene Schwerter*.", footnotes: ["Die Bed. des Mas. T. ist hier ungewiss. Unsere Üs. folgt anderen alten Üs. und hebr. Handschr.; sie legt geringfügige Änderungen des Mas. T. zugrunde.", "℘ Mt 26,49", "℘ Ps 12,3"] },
      { number: 23, text: "Wirf auf den HERRN deine Last*, und er wird dich erhalten*; er wird nimmermehr zulassen, dass der Gerechte wankt*.", footnotes: ["Mas. T. bietet hier ein bisher unerklärtes Wort; LXX: Sorge", "℘ 1Petr 5,7", "℘ Ps 66,9; 112,6; 121,3"] },
      { number: 24, text: "Und du, Gott, wirst sie hinabstürzen in den Brunnen der Grube*; die Männer des Blutes und des Betruges* werden ihre Tage nicht zur Hälfte bringen*. Ich aber will auf dich vertrauen.*", footnotes: ["Grube heißt hier so viel wie Grab, Brunnen der Grube, also: Schacht des Grabes, des Verderbens.\n℘ Ps 40,3", "o. der Hinterlist", "℘ Ps 109,8; Spr 10,27", "℘ Ps 62,2"] },
    ]},
    { number: 56, verses: [
      { number: 1, text: "Dem Chorleiter. Nach »Die Taube der fernen Inseln*«. Von David. Ein Miktam*. Als die Philister ihn zu Gat ergriffen*.", heading: "Psalm 56", footnotes: ["So mit Textkorr. Andere übersetzen ebenfalls mit Textkorr.: Die Taube der fernen Terebinthen. Mas. T. ist hier kaum verständlich.", "Bedeutung unbekannt; vgl. Ps 16,1; 57,1; 58,1; 59,1; 60,1", "℘ 1Sam 21,11"] },
      { number: 2, text: "Sei mir gnädig, Gott*! — denn es stellen mir Menschen nach; den ganzen Tag bedrängt mich ein Streitender.", footnotes: ["℘ Ps 41,5"] },
      { number: 3, text: "Meine Feinde stellen mir den ganzen Tag nach*, ja, viele bekämpfen mich von oben herab*.", footnotes: ["w. schnappen nach mir", "Damit soll gleichzeitig die Übermacht und der Hochmut der Feinde ausgedrückt werden."] },
      { number: 4, text: "An dem Tag, da ich mich fürchte — ich, ich vertraue auf dich*.", footnotes: ["℘ 2Chr 20,3"] },
      { number: 5, text: "Auf Gott — sein Wort rühme ich — auf Gott vertraue ich, ich werde mich nicht fürchten; was sollte Fleisch mir tun*?", footnotes: ["℘ Ps 118,6"] },
      { number: 6, text: "Den ganzen Tag tadeln* sie meine Worte, alle ihre Gedanken sind gegen mich zum Bösen*.", footnotes: ["o. kränken", "℘ Hi 16,10"] },
      { number: 7, text: "Sie greifen an, verstecken sich, sie beobachten meine Fersen, weil sie meiner Seele auflauern*.", footnotes: ["℘ Ps 37,32; 49,6; 59,4"] },
      { number: 8, text: "Sollte es bei ihrer Bosheit Rettung für sie geben? Im Zorn stürze die Völker nieder, Gott*!", footnotes: ["℘ Jer 18,23"] },
      { number: 9, text: "Meine Heimatlosigkeit hast du abgemessen. Gieße meine Tränen in deinen Schlauch! Stehen sie nicht in deinem Verzeichnis*?", footnotes: ["℘ Mal 3,16"] },
      { number: 10, text: "Dann werden meine Feinde ablassen — an dem Tag, da ich rufe*; dieses habe ich erkannt, dass Gott für mich ist*.", footnotes: ["℘ 2Chr 18,31", "℘ Ps 118,6; 124,1.2; Röm 8,31"] },
      { number: 11, text: "Auf Gott — sein Wort rühme ich — auf den HERRN — sein Wort rühme ich —" },
      { number: 12, text: "auf Gott vertraue ich, ich werde mich nicht fürchten; was kann ein Mensch mir tun*?", footnotes: ["℘ Ps 118,6"] },
      { number: 13, text: "Auf mir liegen, Gott, deine Gelübde*, ich werde dir Dankopfer einlösen.", footnotes: ["d. h. die ich dir gelobt habe"] },
      { number: 14, text: "Denn du hast meine Seele vom Tod gerettet, ja, meine Füße vom Sturz, dass ich wandle vor dem Angesicht Gottes im Licht der Lebendigen*.", footnotes: ["℘ Ps 116,8.9; Hi 33,30"] },
    ]},
    { number: 57, verses: [
      { number: 1, text: "Dem Chorleiter.Nach der Melodie: »Verdirb nicht!«* Von David. Ein Miktam*. Als er vor Saul in die Höhle floh.*", heading: "Psalm 57", footnotes: ["Wahrscheinlich Anweisung für den musikalischen Vortrag.\n℘ Ps 58,1; 5Mo 9,26", "s. Anm. zu Ps 56,1", "℘ Ps 142,1; 1Sam 22,1; 24,4"] },
      { number: 2, text: "Sei mir gnädig, Gott*, sei mir gnädig! Denn bei dir birgt sich meine Seele. Im Schatten deiner Flügel* berge ich mich, bis vorübergezogen das Verderben*.", footnotes: ["℘ Ps 41,5", "℘ Ps 17,8; 143,9", "℘ Jes 26,20"] },
      { number: 3, text: "Ich rufe zu Gott, dem Höchsten, zu dem Gott, der es für mich vollendet*.", footnotes: ["℘ Ps 138,8"] },
      { number: 4, text: "Er sende vom Himmel und rette mich; gehöhnt hat der, der mir nachstellt*. // Gott sende seine Gnade und seine Wahrheit*, er rette meine Seele*.", footnotes: ["w. nach mir schnappt; vgl. V. 5; o. er (Gott) hat den verhöhnt, der mir nachstellt", "o. Treue\n℘ Ps 43,3", "Das Wort für »meine Seele« steht im Mas. T. zusammenhanglos am Anfang von V. 5. Die Umstellung und Ergänzung folgt der LXX."] },
      { number: 5, text: "Mitten unter Löwen liege ich, die Menschen verschlingen. Ihre Zähne sind Speer und Pfeile, und ihre Zunge ist ein scharfes Schwert*.", footnotes: ["℘ Ps 59,8; 64,4; Spr 30,14"] },
      { number: 6, text: "Erhebe dich über den Himmel, Gott, über der ganzen Erde sei deine Herrlichkeit*!", footnotes: ["℘ Ps 8,2; 108,6; 1Chr 29,11"] },
      { number: 7, text: "Ein Netz haben sie meinen Schritten gestellt*, er* hat meine Seele gebeugt. Sie haben vor mir eine Grube gegraben, sie sind mitten hineingefallen*. //", footnotes: ["℘ Ps 35,7; 141,9", "Nämlich der Feind. Möglich ist nach Textkorr. die Üs.: Er (Gott) hat den verhöhnt, der mir nachstellt", "℘ Ps 7,16"] },
      { number: 8, text: "*Gefestigt ist mein Herz, Gott, gefestigt ist mein Herz! Ich will singen und spielen*.", footnotes: ["℘ V. 8-12: Ps 108,2-6", "℘ Ps 27,6; Jak 5,13"] },
      { number: 9, text: "Wache auf, meine Seele*! Wachet auf, Harfe und Zither*! Ich will aufwecken die Morgenröte.", footnotes: ["vgl. Ps 7,6; 30,13\n℘ Eph 5,14", "℘ Ps 43,4"] },
      { number: 10, text: "Ich will dich preisen unter den Völkern, Herr, will dich besingen unter den Völkerschaften*.", footnotes: ["℘ Ps 18,50"] },
      { number: 11, text: "Denn groß bis zum Himmel ist deine Gnade, und bis zu den Wolken deine Wahrheit*.*", footnotes: ["o. Treue", "℘ Ps 31,20; 59,17"] },
      { number: 12, text: "Erhebe dich über den Himmel, Gott, über der ganzen Erde sei deine Herrlichkeit*!", footnotes: ["℘ Ps 113,4"] },
    ]},
    { number: 58, verses: [
      { number: 1, text: "Dem Chorleiter.Nach der Melodie:»Verdirb nicht!«* Von David. Ein Miktam*.", heading: "Psalm 58", footnotes: ["Wahrscheinlich Anweisung für den musikalischen Vortrag.", "s. Anm. zu Ps 56,1"] },
      { number: 2, text: "Redet ihr wirklich Gerechtigkeit, Götter*? Richtet ihr in Geradheit die Menschenkinder*?", footnotes: ["Das Wort im Mas. T. ist unübersetzbar. Die Üs. legt eine geringe Änderung der Vokalisierung zugrunde. Manche deuten das sich dann ergebende hebr. Wort für »Götter« als »Machthaber«, »Mächtige«.", "℘ Ps 82,1; Pred 3,16"] },
      { number: 3, text: "Sogar im Herzen übt ihr Ungerechtigkeiten*; der Gewalttat eurer Hände brecht ihr Bahn im Land*.", footnotes: ["℘ Mi 2,1; Mt 15,19", "℘ Ps 55,10"] },
      { number: 4, text: "Abgewichen* sind die Gottlosen von Mutterschoße an, es irren von Mutterleibe an die Lügenredner*.", footnotes: ["Das Wort im Mas. T. ist unübersetzbar, vermutlich ist ein Konsonant ausgefallen. Setzt man ihn ein, ergibt sich die vorgeschlagene Üs.", "℘ Ps 51,7; 1Mo 8,21"] },
      { number: 5, text: "Gift haben sie gleich Schlangengift, wie eine taube Viper, die ihr Ohr verschließt*,", footnotes: ["℘ Ps 140,4; Jak 3,8"] },
      { number: 6, text: "dass sie nicht hört auf die Stimme der Beschwörer, des Zauberers, der die Zaubersprüche beherrscht*.", footnotes: ["℘ Jer 8,17"] },
      { number: 7, text: "Zerschmettere, Gott, ihre Zähne in ihrem Maul, brich aus das Gebiss der Junglöwen, HERR*!", footnotes: ["℘ Ps 3,8"] },
      { number: 8, text: "Sie sollen zergehen wie Wasser, das verrinnt*! Legt er seine Pfeile an, so seien sie wie abgeknickt.", footnotes: ["w. die ihnen zerrinnen"] },
      { number: 9, text: "Wie die Schnecke zerschmelzend dahingeht, so einer Frau Fehlgeburt, welche nie die Sonne erblickt*!", footnotes: ["℘ Hi 3,16"] },
      { number: 10, text: "Bevor eure Töpfe den Dornstrauch* merken — ob grün oder Glut, er wird ihn fortwirbeln*!", footnotes: ["Dornsträucher waren als Brennmaterial gebräuchlich.", "℘ Spr 10,25"] },
      { number: 11, text: "Freuen wird sich der Gerechte, wenn er die Rache anschaut*; er watet* im Blut des Gottlosen*.", footnotes: ["℘ Ps 52,8; 107,42", "w. seine Schritte badet er", "℘ Ps 68,24"] },
      { number: 12, text: "Und der Mensch soll sagen: Es gibt doch Lohn* für den Gerechten*; es gibt doch einen Gott, der auf Erden richtet*.", footnotes: ["eigentlich: Frucht", "℘ Jes 3,10; Mal 3,18", "℘ Ps 94,15; Spr 11,31"] },
    ]},
    { number: 59, verses: [
      { number: 1, text: "Dem Chorleiter.Nach der Melodie:»Verdirb nicht*!« Von David. Ein Miktam*. Als Saul sandte und sie das Haus bewachten, um ihn zu töten*.", heading: "Psalm 59", footnotes: ["℘ Ps 57,1", "s. Anm. zu Ps 56,1", "℘ 1Sam 19,11"] },
      { number: 2, text: "Befreie mich von meinen Feinden, mein Gott! Bring mich in Sicherheit* vor denen, die sich gegen mich erheben*!", footnotes: ["w. Mach mich unzugänglich o. hoch", "℘ Ps 7,2"] },
      { number: 3, text: "Befreie mich von denen, die Böses tun, und rette mich von den Blutmenschen*!", footnotes: ["℘ Ps 140,2"] },
      { number: 4, text: "Denn siehe, sie lauern auf meine Seele*; Starke greifen mich an, ohne mein Vergehen* und ohne meine Sünde, HERR*!", footnotes: ["℘ Ps 56,7", "o. ohne meinen Treuebruch", "℘ 1Sam 19,4"] },
      { number: 5, text: "Ohne eine Schuld meinerseits laufen sie an und gehen in Stellung; wache auf, mir entgegen, und sieh*!", footnotes: ["℘ Ps 7,7"] },
      { number: 6, text: "Und du, HERR, Gott der Heerscharen, Gott Israels, erwache, heimzusuchen alle Nationen! Sei keinem gnädig von den treulosen Götzendienern! //" },
      { number: 7, text: "Am Abend kehren sie wieder, heulen wie Hunde und umkreisen die Stadt." },
      { number: 8, text: "Siehe, sie lassen ihren Mund Böses reden, Schwerter sind auf ihren Lippen* — denn sie denken: »Wer hört*?«", footnotes: ["℘ Ps 57,5", "℘ Ps 10,11"] },
      { number: 9, text: "Du aber, HERR, wirst über sie lachen, spotten über alle Nationen*.", footnotes: ["℘ Ps 2,4"] },
      { number: 10, text: "Meine* Stärke, auf dich will ich achten; denn Gott ist meine Festung*.", footnotes: ["so mit einigen Handschr. und alten Üs.; Mas. T.: Seine", "℘ Ps 46,8.12"] },
      { number: 11, text: "Mein gnädiger Gott wird mir zuvorkommen; Gott wird mich herabsehen lassen auf meine Feinde*.", footnotes: ["℘ Ps 54,9; 118,7"] },
      { number: 12, text: "Töte sie nicht, damit mein Volk es nicht vergesse*; lass sie umherirren durch deine Macht*, und stürze sie nieder, Herr, unser Schild!", footnotes: ["℘ Hes 12,16", "℘ Hi 12,24"] },
      { number: 13, text: "Sünde ihres Mundes ist das Wort ihrer Lippen*; so lass sie gefangen werden in ihrem Hochmut und wegen des Fluches und wegen der Lüge, die sie aussprechen*!", footnotes: ["℘ Ps 10,7", "℘ Ps 64,9; 109,17; Spr 12,13"] },
      { number: 14, text: "Vertilge im Zorn, vertilge, dass sie nicht mehr sind. Dann wird man erkennen, dass Gott in Jakob herrscht bis an die Enden der Erde*! //", footnotes: ["℘ Ps 83,19"] },
      { number: 15, text: "Und am Abend kehren sie wieder, heulen wie Hunde und umkreisen die Stadt." },
      { number: 16, text: "Sie schweifen umher nach Speise; wenn sie nicht satt werden, knurren* sie.", footnotes: ["Mas. T.: nächtigen. Unsere Üs. folgt hier der LXX, die einen geringfügig abweichenden Mas. T. vor sich hatte."] },
      { number: 17, text: "Ich aber will singen von deiner Stärke und am Morgen jubelnd preisen deine Gnade*; denn du bist mir eine Festung gewesen und eine Zuflucht am Tag meiner Not*.", footnotes: ["℘ Ps 57,10.11", "℘ Ps 46,2"] },
      { number: 18, text: "Meine Stärke*, dir will ich spielen*; denn Gott ist meine Festung*, der Gott meiner Gnade.", footnotes: ["℘ Ps 81,2", "℘ Ps 27,6", "℘ Ps 46,8.12"] },
    ]},
    { number: 60, verses: [
      { number: 1, text: "Dem Chorleiter. Nach Schuschan*. Ein Zeugnis. Ein Miktam*. Von David. Zum Lehren.", heading: "Psalm 60", footnotes: ["Wahrscheinlich eine Melodieangabe: Lilie, vgl. Ps 45,1; 69,1; 80,1.", "s. Anm. zu Ps 56,1"] },
      { number: 2, text: "Als er stritt mit den Syrern von Mesopotamien und mit den Syrern von Zoba, und Joab zurückkehrte und die Edomiter im Salztal schlug, zwölftausend Mann*.", footnotes: ["℘ 2Sam 8,1-14; 1Chr 18,3-13"] },
      { number: 3, text: "Gott, du hast uns verworfen, hast uns zerstreut; du bist zornig gewesen* — stelle uns wieder her*!", footnotes: ["℘ Ps 89,39", "℘ Ps 80,4; 85,5"] },
      { number: 4, text: "Du hast das Land erschüttert, hast es zerrissen; heile seine Risse, denn es wankt!" },
      { number: 5, text: "Du hast dein Volk Hartes sehen lassen*, mit Taumelwein hast du uns getränkt*.", footnotes: ["℘ Ps 71,20", "℘ Ps 75,9; Jes 51,17"] },
      { number: 6, text: "Denen, die dich fürchten, hast du ein Signal gegeben, dass sie fliehen können* vor den Bogen. //", footnotes: ["Das hebr. Wort bedeutet wahrscheinlich: im Zickzack davonlaufen."] },
      { number: 7, text: "*Damit deine Geliebten befreit werden, hilf durch deine Rechte und erhöre mich*!", footnotes: ["℘ V. 7-14: Ps 108,7-14", "so mit der Leseform des Mas. T., vielen Handschr. und alten Üs.; mit der Schreibform: uns"] },
      { number: 8, text: "Gott hat geredet in seinem Heiligtum*: »Jubeln will ich, will Sichem verteilen und das Tal Sukkot ausmessen.", footnotes: ["o. seiner Heiligkeit"] },
      { number: 9, text: "Mein ist Gilead und mein Manasse, und Ephraim ist die Bergfestung meines Hauptes, Juda mein Herrscherstab*.", footnotes: ["℘ 1Mo 49,10"] },
      { number: 10, text: "Moab ist mein Waschbecken, auf Edom will ich meine Sandale werfen; Philistäa, jauchze mir zu!«" },
      { number: 11, text: "Wer wird mich führen in die feste Stadt, wer *wird mich leiten* bis nach Edom?", footnotes: ["so mit alten Üs.; Mas. T.: hat mich geleitet", "so mit alten Üs.; Mas. T.: hat mich geleitet"] },
      { number: 12, text: "Hast du, Gott, uns nicht verworfen? Du ziehst nicht aus, Gott, mit unseren Heeren*.", footnotes: ["℘ Ps 44,10"] },
      { number: 13, text: "Schaffe uns Hilfe vor dem Bedränger! Menschenhilfe ist ja wertlos*.", footnotes: ["o. ein Nichts\n℘ Ps 33,16.17"] },
      { number: 14, text: "Mit Gott werden wir mächtige Taten tun*; und er, er wird unsere Bedränger zertreten*.", footnotes: ["℘ Ps 18,30", "℘ Ps 44,6; Röm 16,20"] },
    ]},
    { number: 61, verses: [
      { number: 1, text: "Dem Chorleiter. Auf Saitenspiel. Von David.", heading: "Psalm 61" },
      { number: 2, text: "Höre, Gott, mein Schreien, horche auf mein Gebet*!", footnotes: ["℘ Ps 17,1"] },
      { number: 3, text: "Vom Ende der Erde rufe ich zu dir, weil mein Herz verzagt; du wollest mich auf den Felsen leiten*, der mir zu hoch ist.", footnotes: ["℘ Ps 27,5"] },
      { number: 4, text: "Denn du bist mir eine Zuflucht geworden, ein starker Turm vor dem Feind*.", footnotes: ["℘ Spr 18,10"] },
      { number: 5, text: "Ich möchte weilen in deinem Zelt in Ewigkeit, mich bergen im Schutz deiner Flügel*. //", footnotes: ["℘ Ps 17,8; 91,2"] },
      { number: 6, text: "Denn du, Gott, hast auf meine Gelübde gehört, hast mir gegeben das Erbteil* derer, die deinen Namen fürchten.", footnotes: ["mit Änderung eines Buchstabens: gewährst das Verlangen derer\n℘ Ps 16,5.6"] },
      { number: 7, text: "Du wirst Tage zu den Tagen des Königs hinzufügen; seine Jahre mögen sein wie Generation auf Generation*.", footnotes: ["℘ Ps 21,5"] },
      { number: 8, text: "Er möge ewig thronen vor dem Angesicht Gottes*. Bestelle Gnade und Treue*, dass sie ihn behüten*!", footnotes: ["℘ Ps 89,5.30", "o. Wahrheit", "℘ Ps 40,12"] },
      { number: 9, text: "So werde ich deinen Namen besingen immerdar; um damit meine Gelübde zu erfüllen Tag für Tag*.", footnotes: ["℘ Ps 50,14"] },
    ]},
    { number: 62, verses: [
      { number: 1, text: "Dem Chorleiter. Nach Jedutun*. Ein Psalm. Von David.", heading: "Psalm 62", footnotes: ["vgl. 1Chr 16,41.42; 25,1.3"] },
      { number: 2, text: "Nur auf Gott vertraut still meine Seele*, von ihm kommt meine Hilfe*.", footnotes: ["℘ Ps 55,24; Kla 3,26", "℘ Ps 37,39"] },
      { number: 3, text: "Nur er ist mein Fels und meine Hilfe, meine Festung*; ich werde kaum* wanken*.", footnotes: ["℘ Ps 18,3", "w. nicht viel", "℘ Ps 16,8; 125,1"] },
      { number: 4, text: "Wie lange wollt ihr einen Mann bestürmen, morden* ihr alle — wie eine überhängende Wand, eine eingestoßene Mauer*?", footnotes: ["Manche schlagen vor, mit Änderung des Mas. T. zu übersetzen: ihn berennen", "℘ Jes 30,13"] },
      { number: 5, text: "Sie planen nur, ihn von seiner Höhe zu stoßen; sie finden Gefallen an der Lüge*; mit ihrem* Mund segnen sie*, doch in ihrem Innern fluchen sie. //", footnotes: ["℘ 2Thes 2,12", "so mit alten Üs.; Mas. T.: seinem", "℘ Jer 9,8"] },
      { number: 6, text: "Nur auf Gott vertraue still meine Seele, denn von ihm kommt meine Hoffnung*.", footnotes: ["℘ Mi 7,7"] },
      { number: 7, text: "Nur er ist mein Fels und meine Hilfe, meine Festung; ich werde nicht wanken*.", footnotes: ["℘ Ps 16,8; 125,1"] },
      { number: 8, text: "Auf Gott ruht mein Heil und meine Ehre*; der Fels meines Schutzes, meine Zuflucht ist in Gott*.", footnotes: ["℘ Ps 3,4", "℘ Ps 91,2; 94,22"] },
      { number: 9, text: "Vertraut auf ihn allezeit, ihr von Gottes Volk*! Schüttet euer Herz vor ihm aus*! Gott ist unsere Zuflucht*. //", footnotes: ["℘ Jes 26,4", "℘ Ps 142,3; 1Sam 1,15", "℘ Ps 46,2; 71,7"] },
      { number: 10, text: "Nur Hauch* sind die Menschensöhne, Lüge die Herrensöhne*.* Auf der Waagschale steigen sie empor, sie sind allesamt leichter als ein Hauch*.", footnotes: ["o. Nichtigkeit", "℘ Ps 4,3", "vgl. Ps 49,3", "℘ Jes 40,15"] },
      { number: 11, text: "Vertraut nicht auf Erpressung, und betrügt euch nicht* durch Raub; wenn der Reichtum* wächst, richtet euer Herz nicht darauf*!", footnotes: ["w. seid nicht eitel, nichtig leer; d. h. setzt keine Hoffnung auf Raub, die ist vergeblich", "℘ 1Tim 6,17", "℘ Mt 19,22; Lk 12,19"] },
      { number: 12, text: "Eines hat Gott geredet, zwei Dinge sind es, die ich gehört*, dass die Macht bei Gott ist*", footnotes: ["℘ Hi 33,14", "℘ 1Chr 29,12"] },
      { number: 13, text: "und dein, Herr, die Gnade*; denn du, du vergiltst jedem nach seinem Werk*.", footnotes: ["℘ 2Mo 34,6", "℘ Offb 2,23"] },
    ]},
    { number: 63, verses: [
      { number: 1, text: "Ein Psalm. Von David. Als er in der Wüste Juda war*.", heading: "Psalm 63", footnotes: ["℘ 1Sam 26,3"] },
      { number: 2, text: "Gott, mein Gott* bist du; nach dir suche ich*. Es dürstet nach dir meine Seele, nach dir schmachtet mein Fleisch in einem dürren und erschöpften Land ohne Wasser*.", footnotes: ["℘ Ps 43,4", "℘ Ps 5,4", "℘ Jer 31,14"] },
      { number: 3, text: "So schaue ich im Heiligtum* nach dir, um deine Macht und deine Herrlichkeit zu sehen*.", footnotes: ["℘ Ps 42,2.3", "℘ Ps 68,25"] },
      { number: 4, text: "Denn deine Gnade ist besser als Leben; meine Lippen werden dich rühmen." },
      { number: 5, text: "So werde ich dich preisen während meines Lebens*, meine Hände in deinem Namen aufheben.", footnotes: ["℘ Ps 96,6"] },
      { number: 6, text: "Wie von Mark und Fett wird meine Seele gesättigt werden*, und mit jubelnden Lippen wird mein Mund loben,", footnotes: ["℘ Ps 104,33"] },
      { number: 7, text: "wenn ich deiner gedenke auf meinem Lager, über dich nachdenke in den Nachtwachen." },
      { number: 8, text: "Denn du bist mir zur Hilfe geworden, und im Schatten deiner Flügel kann ich jubeln." },
      { number: 9, text: "Meine Seele hängt an dir*, deine Rechte hält mich aufrecht*.", footnotes: ["w. hängt hinter dir her\n℘ 1Kor 6,17", "℘ Ps 18,36"] },
      { number: 10, text: "Jene aber, die mir zum Verderben* nach meinem Leben trachten, werden in die Tiefen der Erde hinsinken.", footnotes: ["Nach einer hebr. Handschr. und LXX heißt es: die zum Trug (vergeblich, aus nichtigen Gründen) nach meinem Leben trachten. Diese Üs. setzt aber geringfügige Änderungen des Mas. T. voraus."] },
      { number: 11, text: "Man wird sie* der Gewalt des Schwertes preisgeben*, das Teil der Schakale werden sie sein*.", footnotes: ["w. ihn; aber vgl. V. 11b", "℘ Jer 18,21", "℘ Ps 44,20"] },
      { number: 12, text: "Und der König wird sich freuen in Gott; jeder darf sich rühmen, der bei ihm schwört*; denn der Mund der Lügenredner wird verstopft werden*.", footnotes: ["℘ 5Mo 6,13", "℘ Ps 31,19"] },
    ]},
    { number: 64, verses: [
      { number: 1, text: "Dem Chorleiter. Ein Psalm. Von David.", heading: "Psalm 64" },
      { number: 2, text: "Höre, Gott, meine Stimme in meiner Klage; behüte mein Leben vor dem Schrecken des Feindes!" },
      { number: 3, text: "Verbirg mich vor der Verschwörung der Übeltäter, vor dem Aufruhr derer, die Böses tun!" },
      { number: 4, text: "Die ihre Zunge gleich einem Schwert geschärft*, bitteres Wort als ihren Pfeil angelegt haben,", footnotes: ["℘ Ps 55,22; 57,5"] },
      { number: 5, text: "um im Versteck auf den Unschuldigen zu schießen, plötzlich schießen sie auf ihn und scheuen sich nicht." },
      { number: 6, text: "Sie stärken sich in böser Sache; sie reden davon, Fallstricke zu verbergen; sie sagen: »Wer wird sie sehen*?«", footnotes: ["℘ Ps 10,11"] },
      { number: 7, text: "Sie denken Schlechtigkeiten aus: »Wir sind fertig. Der Plan ist ausgedacht. Und das Innere eines jeden und sein Herz ist unergründlich*.«", footnotes: ["℘ Pred 9,3; Jer 17,9"] },
      { number: 8, text: "Aber Gott schießt auf sie einen Pfeil*, plötzlich sind ihre Wunden da.", footnotes: ["℘ Ps 144,6"] },
      { number: 9, text: "Und sie brachten ihn zum Straucheln, doch ihre Zunge* kommt über sie*; alle, die auf sie sehen, schütteln sich.", footnotes: ["d. h. das Planen ihrer Zunge, ihre geplanten Schlechtigkeiten", "℘ Ps 59,13; 140,10"] },
      { number: 10, text: "Da fürchteten sich alle Menschen und verkündeten das Tun Gottes und verstanden sein Werk." },
      { number: 11, text: "Der Gerechte wird sich am HERRN freuen und sich bei ihm bergen*; und alle von Herzen Aufrichtigen werden sich rühmen.", footnotes: ["℘ Ps 5,12"] },
    ]},
    { number: 65, verses: [
      { number: 1, text: "Dem Chorleiter. Ein Psalm. Von David. Ein Lied.", heading: "Psalm 65" },
      { number: 2, text: "Dir gilt Stille*, Lobgesang, Gott, in Zion, und dir soll man das Gelübde erfüllen*.", footnotes: ["LXX bietet mit einer Vokaländerung die Lesart: Dir entspricht (o. geziemt) Lobgesang", "℘ Ps 66,13; 116,18"] },
      { number: 3, text: "Hörer des Gebets*, zu dir wird alles Fleisch kommen.", footnotes: ["℘ 1Kö 9,3; 2Kö 20,5; 1Jo 5,14"] },
      { number: 4, text: "Sündige Taten* haben mich überwältigt*; unsere Vergehen*, du wirst sie vergeben*.", footnotes: ["w. Sachen der Sünden, o. Dinge der Sünden", "℘ Ps 38,5", "o. Treuebrüche", "℘ Mi 7,18"] },
      { number: 5, text: "Glücklich, den du erwählst und nahen lässt, dass er wohne in deinen Vorhöfen*! Wir werden gesättigt werden mit dem Gut deines Hauses*, dem Heiligen deines Tempels.", footnotes: ["℘ Ps 84,5", "℘ Ps 36,9"] },
      { number: 6, text: "Du wirst uns furchtbare Dinge in Gerechtigkeit antworten*, Gott unseres Heils*, du Zuversicht aller Enden der Erde* und des fernen Meeres,", footnotes: ["℘ Jes 63,1", "℘ Jes 12,2", "℘ Jes 45,22"] },
      { number: 7, text: "der die Berge festigt durch seine Kraft*, umgürtet ist mit Macht*,", footnotes: ["℘ Jer 10,12", "℘ Ps 93,1"] },
      { number: 8, text: "der das Brausen der Meere besänftigt, das Brausen ihrer Wellen* und das Getümmel der Völker*.", footnotes: ["℘ Ps 89,10; 107,29; Mt 8,26", "℘ Jes 17,13"] },
      { number: 9, text: "Und so fürchten sich die Bewohner der Enden der Erde vor deinen Zeichen*; die Aufgänge des Morgens und des Abends* lässt du jauchzen*.", footnotes: ["℘ Dan 4,2.3", "℘ Mal 1,11", "d. h. den Osten und den Westen"] },
      { number: 10, text: "Du hast das Land heimgesucht und es überschüttet, du bereicherst es sehr: Gottes Bach ist voll Wasser. Du bereitest ihnen Getreide, wenn du das Land so bereitest:" },
      { number: 11, text: "Du tränkst seine Furchen, ebnest seine Schollen, du erweichst es mit Regengüssen*, segnest sein Gewächs*.", footnotes: ["℘ Ps 68,10", "℘ Ps 104,13; 5Mo 11,12; Apg 14,17; Hebr 6,7"] },
      { number: 12, text: "Du hast das Jahr deiner Güte gekrönt, und deine Spuren triefen von Fett." },
      { number: 13, text: "Es triefen die Weideplätze der Steppe*, und mit Jubel umgürten sich die Hügel*.", footnotes: ["℘ Joe 2,22", "℘ Ps 98,8; Jes 44,23; 55,12"] },
      { number: 14, text: "Die Weiden bekleiden sich mit Herden*, und die Täler bedecken sich mit Korn; sie jauchzen, ja, sie singen*!", footnotes: ["℘ Ps 144,13", "℘ Jes 35,1.2"] },
    ]},
    { number: 66, verses: [
      { number: 1, text: "Dem Chorleiter. Ein Lied. Ein Psalm. Jauchzt Gott, alle Welt*!", heading: "Psalm 66", footnotes: ["℘ Ps 98,4; 100,1"] },
      { number: 2, text: "Besingt die Herrlichkeit seines Namens*, macht herrlich sein Lob*!", footnotes: ["℘ Neh 9,5", "℘ Ps 68,33; Jes 6,3"] },
      { number: 3, text: "Sprecht zu Gott: Wie furchtbar sind deine Werke*! Wegen der Größe deiner Macht* werden dir deine Feinde Ergebung heucheln*.", footnotes: ["℘ Ps 68,36", "℘ Jes 40,26", "℘ Ps 18,45"] },
      { number: 4, text: "Die ganze Erde wird dich anbeten und dir Psalmen singen*; sie wird deinen Namen besingen. //", footnotes: ["℘ Ps 96,1"] },
      { number: 5, text: "Kommt und seht die Großtaten Gottes*! Furchtbar ist sein Tun gegenüber den Menschenkindern*.", footnotes: ["℘ Ps 46,9", "℘ Ps 47,3"] },
      { number: 6, text: "Er wandelte das Meer in trockenes Land*: durch den Strom* gehen sie hinüber zu Fuß. Dort haben wir uns an ihm gefreut.", footnotes: ["℘ 2Mo 14,22", "℘ Jos 3,17"] },
      { number: 7, text: "Durch seine Macht herrscht er auf ewig*; seine Augen beobachten die Nationen*, dass die Widerspenstigen sich nicht erheben*. //", footnotes: ["℘ Dan 4,34", "eigentlich: spähen unter den Nationen\n℘ Ps 33,13-15", "℘ Ps 75,5.6"] },
      { number: 8, text: "Preist, ihr Völker, unseren Gott, und lasst hören den Klang seines Lobes*;", footnotes: ["℘ Ps 45,18; 117,1"] },
      { number: 9, text: "der unsere Seele zum Leben bringt und nicht zugelassen hat, dass unsere Füße wankten*!", footnotes: ["℘ Ps 55,23"] },
      { number: 10, text: "Denn du hast uns geprüft, Gott, du hast uns geläutert, wie man Silber läutert*.", footnotes: ["℘ Sach 13,9; Mal 3,3"] },
      { number: 11, text: "Du hast uns ins Netz gehen lassen, hast eine drückende Last* auf unsere Hüften gelegt.", footnotes: ["Die Bedeutung des meistens mit »drückende Last« wiedergegebenen Wortes ist bisher ungeklärt."] },
      { number: 12, text: "Du hast Menschen über unseren Kopf reiten lassen; wir sind ins Feuer und ins Wasser gekommen*, aber du hast uns herausgeführt zum Überfluss*.", footnotes: ["℘ Jes 43,2", "Alte Üs. stützen die Lesart vieler Handschr. »zur Weite« (Erleichterung)."] },
      { number: 13, text: "Ich will eingehen in dein Haus mit Brandopfern*, will dir erfüllen meine Gelübde*,", footnotes: ["℘ 5Mo 12,11", "℘ Ps 65,2"] },
      { number: 14, text: "zu denen sich meine Lippen aufgetan haben und die mein Mund ausgesprochen hat in meiner Not*.", footnotes: ["℘ Ri 11,35"] },
      { number: 15, text: "Brandopfer von Mastvieh will ich dir opfern zusammen mit Opferrauch von Widdern; Rinder mit Böcken will ich zubereiten*. //", footnotes: ["℘ Esr 8,35"] },
      { number: 16, text: "Kommt, hört zu, alle, die ihr Gott fürchtet*, dass ich erzähle, was er an meiner Seele getan hat*.", footnotes: ["℘ Mal 3,16", "℘ Mk 5,20"] },
      { number: 17, text: "Zu ihm rief ich mit meinem Munde, und Erhebung seines Namens war unter meiner Zunge*.", footnotes: ["℘ Ps 30,9"] },
      { number: 18, text: "Wenn ich es in meinem Herzen auf Götzendienst abgesehen hätte, so würde der Herr nicht hören*.", footnotes: ["℘ Joh 9,31"] },
      { number: 19, text: "Doch Gott hat gehört, er hat geachtet auf die Stimme meines Gebets*.", footnotes: ["℘ Kla 3,56"] },
      { number: 20, text: "Gepriesen sei Gott, der nicht verworfen hat mein Gebet noch seine Gnade von mir zurückzieht*!", footnotes: ["℘ Ps 31,22"] },
    ]},
    { number: 67, verses: [
      { number: 1, text: "Dem Chorleiter. Mit Saitenspiel. Ein Psalm. Ein Lied.", heading: "Psalm 67" },
      { number: 2, text: "Gott sei uns gnädig* und segne uns*, er lasse sein Angesicht leuchten über* uns, //", footnotes: ["℘ Ps 41,5", "℘ Ps 4,7", "w. mit, o. bei"] },
      { number: 3, text: "dass man auf der Erde erkenne deinen Weg, unter allen Nationen deine Hilfe*!", footnotes: ["℘ Jes 49,6"] },
      { number: 4, text: "Es sollen dich preisen die Völker, Gott; es sollen dich preisen die Völker alle*.", footnotes: ["℘ Ps 45,18"] },
      { number: 5, text: "Es sollen sich freuen und jubeln die Völkerschaften; denn du wirst die Völker richten in Geradheit*, und die Völkerschaften auf der Erde — du wirst sie leiten*. //", footnotes: ["℘ Ps 9,9", "℘ Röm 15,12"] },
      { number: 6, text: "Es sollen dich preisen die Völker, Gott; es sollen dich preisen die Völker alle*.", footnotes: ["℘ Ps 45,18"] },
      { number: 7, text: "Die Erde gibt ihren Ertrag*; Gott, unser Gott, wird uns segnen.", footnotes: ["℘ 3Mo 26,4; Jes 30,23; Sach 8,12"] },
      { number: 8, text: "Gott wird uns segnen*, und alle Enden der Erde werden ihn fürchten*.", footnotes: ["℘ Ps 115,12-15; 5Mo 7,13.14", "℘ Ps 33,8; 102,16"] },
    ]},
    { number: 68, verses: [
      { number: 1, text: "Dem Chorleiter. Von David. Ein Psalm. Ein Lied.", heading: "Psalm 68" },
      { number: 2, text: "Gott wird sich erheben, es werden sich zerstreuen seine Feinde, und die ihn hassen, werden fliehen vor seinem Angesicht*.", footnotes: ["℘ 4Mo 10,35"] },
      { number: 3, text: "Wie Rauch auseinandergetrieben wird, so treibst du sie auseinander; wie Wachs vor dem Feuer zerschmilzt, so werden die Gottlosen umkommen vor dem Angesicht Gottes*.", footnotes: ["℘ Ps 37,20; 75,4"] },
      { number: 4, text: "Aber freuen werden sich die Gerechten, sie werden jauchzen vor dem Angesicht Gottes und jubeln in Freude*.", footnotes: ["℘ Ps 5,12; 16,11; 97,11"] },
      { number: 5, text: "Singt Gott, spielt seinem Namen*! Macht Bahn* dem, der einherfährt durch die Wüsten. Jah* ist sein Name*, und jubelt vor ihm*!", footnotes: ["℘ Jes 12,4", "w. Schüttet auf; d. h. einen Weg", "LXX übersetzt »Herr«, weil in »Jah« der Eigenname Gottes »Jahwe« anklingt; Mas. T. ist kaum übersetzbar, w. Bei Jah", "℘ 2Mo 3,15", "℘ Ps 118,19; 150,6"] },
      { number: 6, text: "Ein Vater der Waisen und ein Richter der Witwen* ist Gott in seiner heiligen Wohnung.", footnotes: ["℘ Ps 10,14.18"] },
      { number: 7, text: "Gott ist es, der Einsame zu Hause wohnen lässt, Gefangene hinausführt ins Glück*; Widerspenstige jedoch bleiben in der Dürre*.", footnotes: ["℘ Ps 146,7; Jes 61,1", "℘ Ps 107,34"] },
      { number: 8, text: "Gott, als du auszogst vor deinem Volk, als du einherschrittest durch die Wüste*, //", footnotes: ["℘ 2Mo 13,18.21"] },
      { number: 9, text: "bebte die Erde, auch troff der Himmel vor Gott, dem vom Sinai, vor Gott, dem Gott Israels*.", footnotes: ["℘ Ri 5,4.5; Hebr 12,26"] },
      { number: 10, text: "Reichlich Regen gießt du aus, Gott*; dein Erbland — wenn es ermattet war, hast du selbst es wiederhergestellt*.", footnotes: ["℘ Ps 65,10.11", "℘ Jes 40,29"] },
      { number: 11, text: "Deine Schar ist darin sesshaft geworden; du sorgst in deiner Güte für den Elenden, Gott!" },
      { number: 12, text: "Der Herr erlässt einen Ausspruch: »Siegesbotinnen, eine große Schar!«" },
      { number: 13, text: "Die Könige der Heere fliehen, sie fliehen*! Und auf der Stätte des Hauses verteilt man Beute*:", footnotes: ["℘ Jos 10,16", "Andere übersetzen in Anlehnung an LXX: Und die Schöne des Hauses (die Hausfrau) verteilt Beute\n℘ 4Mo 31,27"] },
      { number: 14, text: "— Wollt ihr zwischen den Hürden liegen?* — Die Flügel einer Taube, mit Silber überzogen und ihre Schwungfedern mit grüngelbem Gold.", footnotes: ["Dieser Satz scheint eine Anspielung auf Ri 5,16 zu sein."] },
      { number: 15, text: "Wenn der Allmächtige Könige im Land* zerstreut, schneit es auf dem Zalmon*.", footnotes: ["w. in ihm; vgl. V. 10f", "℘ Ri 9,48"] },
      { number: 16, text: "Ein Berg Gottes ist der Berg Baschans, ein gipfelreicher Berg ist der Berg Baschans." },
      { number: 17, text: "Warum lauert ihr neidisch, ihr gipfelreichen Berge, auf den Berg, den Gott zu seinem Wohnsitz begehrt hat?* Ja, der HERR wird dort wohnen für immer*.", footnotes: ["℘ Ps 9,12", "℘ Jes 2,2"] },
      { number: 18, text: "Der Wagen Gottes sind zehntausendmal Tausende — Erhabenheit!; der Herr *ist unter ihnen, Sinai im Heiligtum*.", footnotes: ["Andere vermuten hier im Anschluss an 5Mo 33,2 als ursprünglichen Text (ein Buchstabe ergänzt; Vokalisierung und Wortabtrennung geändert): ist gekommen vom Sinai ins Heiligtum", "Andere vermuten hier im Anschluss an 5Mo 33,2 als ursprünglichen Text (ein Buchstabe ergänzt; Vokalisierung und Wortabtrennung geändert): ist gekommen vom Sinai ins Heiligtum"] },
      { number: 19, text: "Du bist hinaufgestiegen zur Höhe, du hast Gefangene weggeführt*, hast Gaben empfangen bei den Menschen; und sogar Widerspenstige sind bereit, sich Jah, Gott, zu unterwerfen.", footnotes: ["℘ Eph 4,8"] },
      { number: 20, text: "Gepriesen sei der Herr Tag für Tag! Er trägt für uns Last, Gott ist unsere Rettung*. //", footnotes: ["℘ 2Mo 15,2"] },
      { number: 21, text: "Gott ist uns ein Gott der Rettungen*, und in der Macht des HERRN*, des Herrn, stehen die Auswege vom Tod.", footnotes: ["℘ Ps 91,3; Jes 12,2", "w. und bei dem HERRN"] },
      { number: 22, text: "Gewiss, Gott wird zerschmettern das Haupt seiner Feinde, den Haarscheitel dessen, der da wandelt in seinen Verschuldungen*.", footnotes: ["℘ Ps 110,6"] },
      { number: 23, text: "Der Herr sprach: »Ich werde zurückbringen aus Baschan, zurückbringen aus den Tiefen des Meeres*,", footnotes: ["℘ Am 9,3"] },
      { number: 24, text: "damit du deinen Fuß in Blut badest*, die Zunge deiner Hunde von den Feinden ihr Teil habe.«", footnotes: ["So in Übereinstimmung mit alten Üs. (vgl. Ps 58,11) mit leichter Änderung eines Konsonanten. Mas. T.: damit du deinen Fuß in Blut zerschmetterst"] },
      { number: 25, text: "Gesehen haben sie deine Umzüge*, Gott, die Umzüge meines Gottes, meines Königs, ins* Heiligtum*.", footnotes: ["im Sinne von Prozessionen", "o. im", "℘ Ps 63,3; 77,14"] },
      { number: 26, text: "Voran gingen Sänger, danach Saitenspieler, inmitten Tamburin schlagender Mädchen*.", footnotes: ["℘ Ps 87,7; 2Mo 15,20"] },
      { number: 27, text: "»Preist Gott in Versammlungen*, den HERRN*, die ihr aus dem Quell Israels seid*!«", footnotes: ["℘ Ps 26,12", "Viele Handschr. lesen nicht »Jahwe«, sondern »Adonai«: Herr", "℘ Jes 48,1"] },
      { number: 28, text: "Da sind Benjamin, der Jüngste, ihr Herrscher*, die Obersten Judas, ihre lärmende Menge; die Obersten Sebulons, die Obersten Naftalis*.", footnotes: ["℘ 1Sam 9,21", "℘ Ri 4,10"] },
      { number: 29, text: "*Entbiete, Gott*, deine Macht, Gottes Macht, die du für uns gewirkt hast*", footnotes: ["so mit alten Üs.; Mas. T.: Entboten hat dein Gott", "so mit alten Üs.; Mas. T.: Entboten hat dein Gott", "℘ Phil 1,6"] },
      { number: 30, text: "von deinem Tempel über Jerusalem*! Könige werden dir Geschenke bringen*.", footnotes: ["Andere beenden den Satz hinter »gewirkt hast«. V. 30 lautet dann: Von deinem Tempel oberhalb Jerusalems werden Könige dir Geschenke bringen.", "℘ Ps 72,10; Sach 8,22"] },
      { number: 31, text: "Schilt* das Tier des Schilfs, die Schar der Starken mit den Kälbern der Völker; tritt denen entgegen*, die nach Silber rennen*. Zerstreue* die Völker, die Lust haben am Krieg!", footnotes: ["o. Schrei an", "w. entgegentretend denen", "Ein paar Handschr. bieten diese Vokalisierung des sonst unübersetzbaren Mas. T.", "so mit alten Üs.; Mas. T.: Er hat zerstreut"] },
      { number: 32, text: "Es werden kommen Bronzesachen* aus Ägypten*; Äthiopien soll seine Hände ausstrecken* zu Gott.", footnotes: ["Die Bedeutung des hebr. Wortes ist unsicher; LXX: Gesandte, Vornehme", "℘ Jes 19,21", "w. seine Hände laufen lassen"] },
      { number: 33, text: "Ihr Königreiche der Erde, singt Gott*, spielt dem Herrn, //", footnotes: ["℘ Ps 66,1.2"] },
      { number: 34, text: "ihm, der einherfährt auf dem Himmel, dem Himmel der Vorzeit*! Siehe, er lässt seine Stimme erschallen, eine mächtige Stimme*.", footnotes: ["℘ 5Mo 33,26", "℘ Ps 29,4"] },
      { number: 35, text: "Gebt Gott Macht*! Seine Hoheit ist über Israel und seine Macht in den Wolken*.", footnotes: ["℘ Ps 29,1", "℘ 5Mo 33,26; Mt 24,30"] },
      { number: 36, text: "Furchtbar bist du, Gott*, aus deinen Heiligtümern* her. Der Gott Israels, er ist es, der Stärke und Kraft gibt dem Volk*. Gepriesen sei Gott*!", footnotes: ["℘ Ps 66,3", "Viele Handschr. und Üs. lesen: deinem Heiligtum", "℘ Ps 29,11", "℘ 2Kor 1,3"] },
    ]},
    { number: 69, verses: [
      { number: 1, text: "Dem Chorleiter. Nach Schoschannim*. Von David.", heading: "Psalm 69", footnotes: ["o. Nach Lilien\n℘ Ps 45,1"] },
      { number: 2, text: "Rette mich, Gott, denn Wasser ist bis an die Seele* gekommen.", footnotes: ["o. an den Hals"] },
      { number: 3, text: "Ich bin versunken in tiefen Schlamm*, und kein fester Grund ist da; in Wassertiefen bin ich gekommen*, und die Flut schwemmt mich fort.", footnotes: ["℘ Ps 40,3", "℘ Ps 88,7"] },
      { number: 4, text: "Ich bin müde von meinem Rufen, entzündet ist meine Kehle*; meine Augen vergehen vom Harren* auf meinen Gott.", footnotes: ["℘ Ps 6,7; Hebr 5,7", "w. harrend"] },
      { number: 5, text: "Mehr als die Haare meines Hauptes sind die, die mich ohne Ursache hassen; mächtig sind, die mich vernichten* wollen, meine Feinde sind sie ohne Grund*; was ich nicht geraubt habe, das soll ich dann erstatten.", footnotes: ["o. zum Schweigen bringen", "℘ Ps 35,19"] },
      { number: 6, text: "Du, Gott, hast meine Torheit erkannt, und meine Verschuldungen sind dir nicht verborgen." },
      { number: 7, text: "Lass nicht durch mich beschämt werden, die auf dich hoffen, Herr, HERR der Heerscharen! Lass nicht an mir zuschanden werden, die dich suchen, Gott Israels!" },
      { number: 8, text: "Denn deinetwegen trage ich Hohn*, hat Schande bedeckt mein Gesicht*.", footnotes: ["℘ Ps 89,51.52; Jer 15,15", "℘ Jes 50,6; Mt 26,67; Mk 15,32"] },
      { number: 9, text: "Entfremdet bin ich meinen Brüdern und ein Fremder geworden den Söhnen meiner Mutter*.", footnotes: ["℘ Ps 38,12; Joh 7,5"] },
      { number: 10, text: "Denn der Eifer um dein Haus hat mich verzehrt*, und die Schmähungen derer, die dich schmähen, sind auf mich gefallen*.", footnotes: ["℘ Ps 119,139; Joh 2,17", "℘ Röm 15,3"] },
      { number: 11, text: "Als ich weinte und meine Seele fastete, da* wurde es mir zu Schmähungen*.", footnotes: ["w. Als ich weinte — meine Seele im Fasten — da", "℘ Ps 109,24.25"] },
      { number: 12, text: "Als ich mich in Sacktuch kleidete*, da wurde ich ihnen zum Sprichwort*.", footnotes: ["℘ Ps 35,13", "℘ Jer 20,7"] },
      { number: 13, text: "Die im Tore sitzen, reden über mich, und auch die Spottlieder* der Zecher*.", footnotes: ["o. mit leichter Abänderung des Mas. T. in Anlehnung an alte Üs.: und über mich dichten die Zecher ihre Spottlieder", "w. der Trinker von Rauschtrank\n℘ Kla 3,63"] },
      { number: 14, text: "Ich aber richte mein Gebet an dich, HERR*, zur Zeit des Wohlgefallens.* Gott, nach der Größe deiner Gnade,* erhöre mich durch die Treue deiner Hilfe!", footnotes: ["℘ Jon 2,8", "℘ 2Kor 6,2", "℘ Ps 86,5"] },
      { number: 15, text: "Ziehe mich heraus aus dem Schlamm, dass ich nicht versinke! Lass mich gerettet werden von denen, die mich hassen, und aus den Wassertiefen!" },
      { number: 16, text: "Lass die Flut des Wassers mich nicht fortschwemmen und die Tiefe mich nicht verschlingen; und lass die Grube ihren Mund nicht über mir verschließen!" },
      { number: 17, text: "Erhöre mich, HERR, denn gut ist deine Gnade; wende dich zu mir nach der Größe deiner Erbarmungen*!", footnotes: ["℘ Kla 3,22"] },
      { number: 18, text: "Und verbirg dein Angesicht nicht vor deinem Knecht*, denn ich bin bedrängt; erhöre mich eilends*!", footnotes: ["℘ Ps 27,9", "℘ Ps 22,20; 143,7"] },
      { number: 19, text: "Nahe dich meiner Seele, erlöse sie*; erlöse mich wegen meiner Feinde*!", footnotes: ["w. nimm sie für dich in Anspruch (vgl. den im Buch Rut, Kap. 3f, dargestellten Vorgang)", "℘ Ps 5,9"] },
      { number: 20, text: "Du, du hast meine Schmähung erkannt und meine Schmach und meine Schande*; vor dir sind alle meine Bedränger.", footnotes: ["℘ Mt 27,29.30; Hebr 12,2"] },
      { number: 21, text: "Der Hohn hat mein Herz gebrochen*, und es ist unheilbar*; und ich habe auf Mitleid gewartet — aber da war keins; und auf Tröster, aber ich habe keine gefunden*.", footnotes: ["℘ Mt 27,41", "Mit leichter Vokaländerung, um Mas. T. übersetzbar zu machen.", "℘ Kla 1,2.9; Mt 26,40; Joh 16,32"] },
      { number: 22, text: "Und sie gaben mir zur Speise* Gift*, und in meinem Durst tränkten sie mich mit Essig*.", footnotes: ["Das hebr. Wort meint so viel wie Diät, nämlich Brot, das man speziell Kranken verabreicht.", "LXX: Galle", "℘ Mt 27,47.48"] },
      { number: 23, text: "Es werde ihr Tisch vor ihnen zur Falle, und den Sorglosen zum Fallstrick!" },
      { number: 24, text: "Lass dunkel werden ihre Augen, dass sie nicht sehen; und lass beständig ihre Hüften wanken*!", footnotes: ["℘ Röm 11,9.10"] },
      { number: 25, text: "Schütte über sie aus deine Verwünschung, und deines Zornes Glut soll sie erreichen!" },
      { number: 26, text: "Verödet sei ihr Lagerplatz, in ihren Zelten sei kein Bewohner*!", footnotes: ["℘ Mt 23,38; Apg 1,20"] },
      { number: 27, text: "Denn den* du geschlagen hast, haben sie verfolgt*, und vom Schmerz deiner Verwundeten erzählen sie.", footnotes: ["so mit alten Üs.; Mas. T.: Du bist es, der", "℘ Jes 53,4"] },
      { number: 28, text: "Füge Schuld zu ihrer Schuld, und lass sie nicht hineinkommen in deine Gerechtigkeit!" },
      { number: 29, text: "Sie sollen ausgelöscht werden aus dem Buch des Lebens* und nicht eingeschrieben werden mit den Gerechten!", footnotes: ["℘ Offb 3,5"] },
      { number: 30, text: "Ich aber bin elend, und mir ist wehe; deine Rettung, Gott, bringe mich in Sicherheit!" },
      { number: 31, text: "Loben will ich den Namen Gottes im Lied und ihn erheben mit Dank*.", footnotes: ["℘ Ps 7,18"] },
      { number: 32, text: "Denn es wird dem HERRN wohlgefälliger sein als ein Stier, ein Opferstier mit Hörnern und* gespaltenen Hufen*.", footnotes: ["»und« lesen viele Handschr. und alte Üs.", "℘ Ps 50,13.14"] },
      { number: 33, text: "Die Sanftmütigen haben es gesehen, sie werden sich freuen*; die ihr Gott sucht, euer Herz soll leben*!", footnotes: ["℘ Ps 34,3", "℘ Ps 22,27"] },
      { number: 34, text: "Denn der HERR hört auf die Armen, und seine Gefangenen verachtet er nicht*.", footnotes: ["℘ Ps 102,18"] },
      { number: 35, text: "Ihn sollen loben Himmel und Erde, die Meere, und alles, was in ihnen wimmelt*!", footnotes: ["℘ Ps 145,10; 148,4.7; Jes 44,23"] },
      { number: 36, text: "Denn Gott wird Zion retten und die Städte Judas bauen*; und sie werden dort wohnen und es besitzen.", footnotes: ["℘ Jes 44,26"] },
      { number: 37, text: "Die Nachkommen seiner Knechte werden es erben; und die seinen Namen lieben*, werden darin wohnen*.", footnotes: ["℘ Ps 5,12", "℘ Ps 102,29; Jes 65,9"] },
    ]},
    { number: 70, verses: [
      { number: 1, text: "Dem Chorleiter. Von David. Zum Gedächtnis*.", heading: "Psalm 701", footnotes: ["w. Um in Erinnerung zu bringen. — Nach der aram. Üs. ist das Wort haskir eine Ableitung von askarah, was nach 3Mo 2,2; 9,16 und anderen Stellen der Teil des Speisopfers ist, der unter Beigabe von Weihrauch verbrannt wird. Eine mögliche Üs. wäre: Zum Weihrauchopfer; vgl. Ps 38,1"] },
      { number: 2, text: "Eile, Gott, mich zu retten, HERR, zu meiner Hilfe*!", footnotes: ["℘ Ps 22,20"] },
      { number: 3, text: "Es sollen sich schämen und zuschanden werden, die nach meinem Leben trachten! Es sollen zurückweichen und beschimpft sein, die Gefallen haben an meinem Unglück*!", footnotes: ["℘ Ps 71,13"] },
      { number: 4, text: "Sie sollen umkehren* wegen ihrer Schande, die da* sagen: Haha! Haha!", footnotes: ["syr. Üs. liest: Sie sollen sich entsetzen; vgl. auch Ps 40,16", "LXX, syr. und aram. Üs. lesen: die zu mir sagen"] },
      { number: 5, text: "Jauchzen und deiner sich freuen sollen alle, die dich suchen! Stets sollen sagen: »Groß ist Gott!«, die dein Heil lieben." },
      { number: 6, text: "Ich aber bin elend und arm*; Gott, eile zu mir*! Mein Helfer und mein Retter bist du! HERR, zögere nicht!", footnotes: ["℘ Ps 25,16", "℘ Ps 71,12; 141,1"] },
    ]},
    { number: 71, verses: [
      { number: 1, text: "Bei dir, HERR, habe ich mich geborgen. Lass mich niemals beschämt werden*!", heading: "Psalm 71", footnotes: ["℘ Ps 25,2"] },
      { number: 2, text: "In deiner Gerechtigkeit rette mich und befreie mich*! Neige dein Ohr zu mir und hilf mir.", footnotes: ["℘ Ps 31,2"] },
      { number: 3, text: "Sei mir ein Fels zur Wohnung*, *zu dem ich immer kommen kann! Du hast geboten, mich zu retten*. Denn mein Fels und meine Burg bist du*.", footnotes: ["Andere Üs. mit Textkorr.: ein Fels der Zuflucht\n℘ Ps 31,3", "o. einzugehen für immer hast du geboten, um mir zu helfen", "o. einzugehen für immer hast du geboten, um mir zu helfen", "℘ Ps 18,3"] },
      { number: 4, text: "Mein Gott, befreie mich aus der Hand des Gottlosen, aus der Faust des Ungerechten und des Gewalttätigen*.", footnotes: ["℘ Ps 43,1"] },
      { number: 5, text: "Denn meine Hoffnung bist du*, Herr; HERR, meine Zuversicht von meiner Jugend an.", footnotes: ["Mas. T. teilt den V. an dieser Stelle: bist du; Herr, HERR, meine Zuversicht"] },
      { number: 6, text: "Auf dich habe ich mich gestützt von Mutterschoße an, vom Mutterleib hast du mich entbunden*; dir gilt stets mein Lobgesang*.", footnotes: ["Mas. T. w. von meiner Mutter Leibe bist du mein Abschneider. — Naheliegend wäre die Üs.: seitdem du mich vom Mutterleib entbunden hast\n℘ Ps 22,11", "℘ Ps 40,4"] },
      { number: 7, text: "Vielen bin ich wie ein Wunder*; du aber bist meine starke Zuflucht*.", footnotes: ["℘ Jes 8,18; Sach 3,8", "℘ Ps 62,8.9"] },
      { number: 8, text: "Mein Mund ist voll von deinem Lob, von deinem Ruhm den ganzen Tag." },
      { number: 9, text: "Verwirf mich nicht zur Zeit des Alters; beim Schwinden meiner Kraft verlass mich nicht!" },
      { number: 10, text: "Denn meine Feinde haben über mich geredet, und die nach meinem Leben trachten, miteinander beratschlagt." },
      { number: 11, text: "Sie sagen: Gott hat ihn verlassen! Verfolgt und ergreift ihn, denn kein Retter ist da!" },
      { number: 12, text: "Gott, sei nicht fern von mir*; mein Gott, eile mir zur Hilfe*!", footnotes: ["℘ Ps 35,22", "℘ Ps 70,2.6"] },
      { number: 13, text: "Zuschanden werden, vergehen sollen, die meine Seele beschuldigen; in Hohn und Schande sollen sich hüllen, die mein Unglück suchen*!", footnotes: ["℘ Ps 70,3"] },
      { number: 14, text: "Ich aber will beständig harren* und all dein Lob vermehren.", footnotes: ["℘ Kla 3,24.25"] },
      { number: 15, text: "Mein Mund soll erzählen deine Gerechtigkeit*, dein Retten den ganzen Tag. Denn ich kenne ihre Zahl* nicht.*", footnotes: ["℘ Ps 51,16; 145,7", "Das hebr. Wort kommt nur an dieser Stelle vor. Die Bedeutung »Zahl« ist aus dem Wortstamm abgeleitet.", "℘ Ps 40,6"] },
      { number: 16, text: "Ich will kommen mit den Machttaten des Herrn, HERRN. Ich will preisen deine Gerechtigkeit, dich allein*.", footnotes: ["℘ Jes 45,24"] },
      { number: 17, text: "Gott! Du hast mich unterwiesen von meiner Jugend an*, und bis hierher verkündige ich deine Wundertaten.*", footnotes: ["℘ 2Tim 3,15", "℘ Ps 73,28"] },
      { number: 18, text: "Und auch bis zum Alter und bis zum Greisentum verlass mich nicht, Gott, bis ich verkündige deinen Arm der künftigen Generation*, allen, die da kommen werden, deine Macht*", footnotes: ["℘ Ps 48,14", "℘ Ps 78,4"] },
      { number: 19, text: "und deine Gerechtigkeit, Gott, bis zur Höhe*, der du große Dinge getan hast, Gott, wer ist wie du*?", footnotes: ["℘ Ps 36,7", "℘ Ps 35,10"] },
      { number: 20, text: "Der du uns viele und unheilvolle Nöte hast sehen lassen*, du wirst uns wieder beleben und uns aus den Tiefen der Erde wieder heraufführen*.", footnotes: ["℘ Ps 60,5", "℘ Ps 95,4; 1Sam 2,6"] },
      { number: 21, text: "Du wirst meine Größe mehren und dich wenden und mich trösten*.", footnotes: ["℘ Ps 86,17"] },
      { number: 22, text: "Dann will auch ich dich preisen mit der Harfe, preisen deine Treue*, mein Gott! Ich will dir spielen mit der Zither*, du Heiliger Israels!", footnotes: ["o. Wahrheit", "℘ Ps 43,4; 98,4.5"] },
      { number: 23, text: "Jubeln sollen meine Lippen, wenn ich dir spiele, und meine Seele, die du erlöst hast*.", footnotes: ["℘ Ps 34,23"] },
      { number: 24, text: "Auch meine Zunge soll von deiner Gerechtigkeit reden den ganzen Tag*; denn beschämt, denn mit Scham sind bedeckt worden, die mein Unglück suchen*. //", footnotes: ["℘ Jak 3,9", "℘ Ps 70,3"] },
    ]},
    { number: 72, verses: [
      { number: 1, text: "Von Salomo*. Gott, gib dem König deine Rechtssprüche und deine Gerechtigkeit dem Königssohn*,", heading: "Psalm 72", footnotes: ["℘ Ps 127,1; 1Chr 22,9", "℘ 1Chr 29,19"] },
      { number: 2, text: "dass er dein Volk richte in Gerechtigkeit und deine Elenden nach Recht*.", footnotes: ["℘ 2Sam 23,3; Jes 32,1"] },
      { number: 3, text: "Es mögen dem Volk Heil tragen die Berge und die Hügel Gerechtigkeit*.*", footnotes: ["Mas. T.: in Gerechtigkeit. — Die Üs. ohne »in« stützt sich auf griech. Handschr.", "℘ Ps 85,11; Jes 32,17"] },
      { number: 4, text: "Er schaffe Recht den Elenden des Volkes; bringe Hilfe den Kindern des Armen, und den Unterdrücker zertrete er*.", footnotes: ["℘ Jes 42,3"] },
      { number: 5, text: "Und *er möge lange leben*, solange die Sonne scheint, solange der Mond leuchtet, von Generation zu Generation.", footnotes: ["Mas. T.: sie werden dich fürchten. — Unsere Üs. folgt LXX.", "Mas. T.: sie werden dich fürchten. — Unsere Üs. folgt LXX."] },
      { number: 6, text: "Er komme herab wie ein Regen auf die gemähte Flur*, wie Regenschauer als Befeuchtung auf das Land.", footnotes: ["℘ 5Mo 32,2; Hos 6,3"] },
      { number: 7, text: "In seinen Tagen wird der Gerechte* blühen, und Fülle von Heil wird sein, bis der Mond nicht mehr ist.", footnotes: ["mit Handschr. und alten Üs.: Gerechtigkeit. — Diese Lesart wird durch den folgenden Halbvers wahrscheinlich."] },
      { number: 8, text: "Und er* möge herrschen von Meer zu Meer und vom Strom bis an die Enden der Erde*.*", footnotes: ["d. h. der König", "o. des Landes", "℘ 2Mo 23,31; Sach 9,10"] },
      { number: 9, text: "Vor ihm sollen sich beugen die Bewohner der Wüste, und seine Feinde sollen den Staub lecken*.", footnotes: ["℘ Jes 49,23; Mi 7,17"] },
      { number: 10, text: "Die Könige von Tarsis und den Inseln sollen Geschenke bringen, es sollen Tribute entrichten* die Könige von Scheba und Saba*.", footnotes: ["℘ Ps 68,30", "℘ 1Kö 10,1.2; Jes 60,6.9"] },
      { number: 11, text: "Und alle Könige sollen vor ihm niederfallen*, alle Nationen ihm dienen.", footnotes: ["℘ Jes 49,23; Mi 7,17"] },
      { number: 12, text: "Denn retten wird er den Armen, der um Hilfe ruft*, und den Elenden und den, der keinen Helfer hat*.", footnotes: ["℘ Ps 55,17", "℘ Hi 36,15"] },
      { number: 13, text: "Er wird sich erbarmen des* Geringen* und des Armen, und das Leben* der Armen wird er retten.", footnotes: ["w. Er wird fließen (d. h. weinen) über den", "o. des Hilflosen; o. des Schwachen", "o. die Seelen"] },
      { number: 14, text: "Aus Bedrückung und Gewalttat wird er ihr Leben erlösen, denn ihr Blut ist kostbar in seinen Augen*.", footnotes: ["℘ Ps 116,15"] },
      { number: 15, text: "Und er soll leben, und von dem Golde Schebas wird man* ihm geben*; und man soll beständig für ihn beten, den ganzen Tag ihn segnen*.", footnotes: ["w. er", "℘ 1Kö 10,10", "℘ Ps 45,18"] },
      { number: 16, text: "Überfluss an Getreide soll im Land sein; auf dem Gipfel der Berge soll es wogen*; wie der Libanon sei seine Frucht; sie sollen hervorblühen aus der Stadt wie das Kraut der Erde.", footnotes: ["Die Bedeutung des hebr. Wortes an dieser Stelle ist umstritten. Andere übersetzen: wird es reichlich stehen"] },
      { number: 17, text: "Sein Name soll ewig sein; vor der Sonne soll aufsprossen sein Name; *und in ihm wird man sich segnen; alle Nationen sollen ihn glücklich preisen*.", footnotes: ["o. und in ihm werden sich Segen wünschen alle Nationen; sie werden ihn glücklich preisen", "o. und in ihm werden sich Segen wünschen alle Nationen; sie werden ihn glücklich preisen"] },
      { number: 18, text: "Gepriesen sei Gott, der HERR, der Gott Israels*. Er tut Wunder, er allein*!", footnotes: ["℘ Ps 106,48; Lk 1,68", "℘ Ps 77,15; 98,1; 136,4; Hi 5,9"] },
      { number: 19, text: "Und gepriesen sei sein herrlicher Name in Ewigkeit! Seine Herrlichkeit erfülle die ganze Erde*! Amen, ja Amen*.", footnotes: ["℘ 4Mo 14,21; Jes 6,3; Hab 2,14", "℘ Ps 41,14"] },
      { number: 20, text: "Es sind zu Ende die Gebete Davids, des Sohnes Isais." },
    ]},
    { number: 73, verses: [
      { number: 1, text: "DRITTES BUCH Ein Psalm. Von Asaf*. Fürwahr, Gott ist Israel gut, denen, die reinen Herzens sind*.", heading: "Psalm 73", footnotes: ["℘ Ps 50,1", "℘ Ps 24,4"] },
      { number: 2, text: "Ich aber — fast wären meine Füße ausgeglitten, beinahe hätten gewankt meine Schritte." },
      { number: 3, text: "Denn ich beneidete die Übermütigen, als ich das Wohlergehen der Gottlosen sah*.", footnotes: ["℘ Ps 10,5; Hi 21,7; Jer 12,1"] },
      { number: 4, text: "Denn keine Qualen haben sie bei ihrem Tod*, und wohlgenährt ist ihr Leib*.", footnotes: ["Teilt man das hebr. Wort in zwei auf, ergibt sich folgende Üs.: Denn keine Qualen haben sie, gesund und wohlgenährt ist ihr Leib", "℘ Hi 21,13"] },
      { number: 5, text: "In der Mühsal der Menschheit sind sie nicht, und sie werden nicht wie die anderen Menschen geplagt." },
      { number: 6, text: "Deshalb umgibt sie Hochmut wie ein Halsgeschmeide, Gewalttat umhüllt sie wie ein Gewand*.", footnotes: ["℘ Ps 109,18"] },
      { number: 7, text: "Es tritt aus dem Fett heraus ihr Auge; *sie fahren daher in den Einbildungen des Herzens*.", footnotes: ["w. es fahren daher die Einbildungen des Herzens, o. darüber ziehen die Einbildungen des Herzens", "w. es fahren daher die Einbildungen des Herzens, o. darüber ziehen die Einbildungen des Herzens"] },
      { number: 8, text: "Sie höhnen und *reden in Bosheit Bedrückendes, von oben herab reden sie*.", footnotes: ["LXX teilt den V. so auf: reden in Bosheit; Bedrückendes reden sie von oben herab", "LXX teilt den V. so auf: reden in Bosheit; Bedrückendes reden sie von oben herab\n℘ Ps 12,5"] },
      { number: 9, text: "Sie setzen in den Himmel ihren Mund, und ihre Zunge ergeht sich auf der Erde." },
      { number: 10, text: "Deshalb wendet sich* hierher sein Volk, denn Wasser in Fülle wird bei ihnen geschlürft*.", footnotes: ["Schreibform des Mas. T.: wendet er. — Die hebr. Wörter ähneln sich.", "o. wird ihnen ausgepresst"] },
      { number: 11, text: "Ja, sie sprechen: Wie sollte Gott es wissen? Gibt es ein Wissen beim Höchsten*?", footnotes: ["℘ Ps 10,4; Hi 22,13"] },
      { number: 12, text: "Siehe, dies sind Gottlose und, immer sorglos*, erwerben sie sich Vermögen.", footnotes: ["o. sicher; o. ruhig"] },
      { number: 13, text: "Fürwahr, umsonst habe ich mein Herz rein gehalten* und in Unschuld gewaschen meine Hände*;", footnotes: ["℘ Mal 3,14", "℘ Ps 26,6"] },
      { number: 14, text: "doch ich wurde geplagt den ganzen Tag, meine Züchtigung ist jeden Morgen da*.", footnotes: ["℘ Hi 7,18"] },
      { number: 15, text: "Wenn ich gesagt hätte: Ich will ebenso reden, siehe, so hätte ich treulos gehandelt an dem Geschlecht deiner Söhne." },
      { number: 16, text: "Da dachte ich nach, um dies zu begreifen*. Eine Mühe war es in meinen Augen*,", footnotes: ["o. zu erkennen\n℘ Pred 1,17", "℘ Pred 8,17"] },
      { number: 17, text: "bis ich hineinging in das Heiligtum* Gottes. Bedenken will ich dort ihr Ende*.", footnotes: ["w. Heiligtümer; gemeint ist das eine Heiligtum mit seinen verschiedenen Bauten", "o. und dort ihr Ende bedachte"] },
      { number: 18, text: "Fürwahr, auf schlüpfrige Wege stellst du sie*, du lässt sie in Täuschungen* fallen*.", footnotes: ["℘ Ps 35,6", "andere: Trümmer", "℘ Ps 55,24; 92,8"] },
      { number: 19, text: "Wie sind sie so plötzlich zum Entsetzen geworden! Sie haben ein Ende gefunden, sind umgekommen in Schrecken." },
      { number: 20, text: "Wie einen Traum nach dem Erwachen, so verachtest du, Herr, beim Aufstehen ihr Bild." },
      { number: 21, text: "Als mein Herz erbittert war und es mich in meinen Nieren* stach,", footnotes: ["s. Anm. zu Ps 16,7"] },
      { number: 22, text: "da war ich dumm und verstand* nicht; wie ein Tier* war ich bei dir*.", footnotes: ["o. erkannte", "w. Vieh", "℘ Ps 92,7"] },
      { number: 23, text: "Doch ich bin stets bei dir. Du hast meine rechte Hand gefasst." },
      { number: 24, text: "Nach deinem Rat leitest du mich*, und nachher nimmst du mich in Herrlichkeit auf*.", footnotes: ["℘ Jes 48,17", "w. und nach einer Herrlichkeit nimmst du mich auf"] },
      { number: 25, text: "Wen habe ich im Himmel? Und außer dir habe ich an nichts Gefallen auf der Erde." },
      { number: 26, text: "Mag auch mein Leib und mein Herz vergehen — meines Herzens Fels und mein Teil ist Gott auf ewig*.", footnotes: ["℘ Kla 3,24"] },
      { number: 27, text: "Denn siehe, es werden umkommen die, die sich von dir fernhalten. Du bringst zum Schweigen* jeden, der dir die Treue bricht*.", footnotes: ["o. Du vernichtest", "w. von dir weg hurt"] },
      { number: 28, text: "Ich aber: Gott zu nahen ist mir gut. Ich habe meine Zuversicht auf den Herrn, HERRN, gesetzt*, zu erzählen alle deine Taten*.", footnotes: ["℘ Ps 40,5", "℘ Ps 71,15.17"] },
    ]},
    { number: 74, verses: [
      { number: 1, text: "Ein Maskil*. Von Asaf*. Gott, warum hast du verworfen für immer*, warum raucht dein Zorn gegen die Herde* deiner Weide*?", heading: "Psalm 74", footnotes: ["s. Anm. zu Ps 32,1", "℘ Ps 50,1", "℘ Ps 77,8; 85,6", "w. das Kleinvieh", "℘ Ps 79,13; 95,7; 100,3"] },
      { number: 2, text: "Gedenke deiner Gemeinde, die du erworben hast vor alters*, erlöst zum Stamm deines Eigentums*, des Berges Zion, auf dem du gewohnt hast*!", footnotes: ["℘ Apg 20,28", "o. Erbes\n℘ Ps 94,14; 5Mo 9,26", "℘ Ps 9,12"] },
      { number: 3, text: "Erhebe deine Schritte zu den ewigen Trümmern! Alles hat der Feind im Heiligtum verwüstet*.", footnotes: ["℘ Dan 9,17"] },
      { number: 4, text: "Es brüllen deine Widersacher inmitten deiner Versammlungsstätte*. Sie haben ihre Zeichen als Zeichen des Sieges gesetzt.", footnotes: ["℘ Kla 2,7"] },
      { number: 5, text: "*Es sieht aus, wie wenn man* Äxte emporhebt im Dickicht des Waldes.", footnotes: ["w. Er (d. h. jeder von ihnen) zeigt sich wie einer, der", "w. Er (d. h. jeder von ihnen) zeigt sich wie einer, der"] },
      { number: 6, text: "Und jetzt — deine* Schnitzereien allesamt, mit Beilen und Brechstangen zerschlagen sie sie.", footnotes: ["w. ihre (weiblich Einzahl)"] },
      { number: 7, text: "Sie haben dein Heiligtum* in Brand gesteckt*, bis auf den Grund entweiht die Wohnung deines Namens.", footnotes: ["w. Heiligtümer; vgl. Anm. zu Ps 73,17", "℘ Jer 52,13"] },
      { number: 8, text: "Sie sprachen in ihrem Herzen: *Lasst sie uns allesamt niederzwingen!* Sie haben alle Versammlungsstätten Gottes im Lande verbrannt.", footnotes: ["so mit Änderung eines Vokalzeichens; Mas. T.: ihre Nachkommen allesamt.", "so mit Änderung eines Vokalzeichens; Mas. T.: ihre Nachkommen allesamt.\n℘ Ps 83,5"] },
      { number: 9, text: "Zeichen für uns sehen wir nicht. Kein Prophet ist mehr da, und keiner bei uns ist da, der weiß, bis wann." },
      { number: 10, text: "Bis wann*, Gott, soll höhnen der Bedränger, soll der Feind deinen Namen verachten immerfort*?", footnotes: ["℘ Ps 6,4", "℘ Jes 37,23"] },
      { number: 11, text: "Warum ziehst du deine Hand und deine Rechte zurück*? Zieh sie hervor aus deinem Gewandbausch, mach ein Ende*!", footnotes: ["℘ Kla 2,3", "o. vernichte sie"] },
      { number: 12, text: "Doch Gott ist mein König* von alters her*, der Heilstaten vollbringt auf der Erde.", footnotes: ["℘ Ps 5,3", "℘ Jer 10,10; Hab 1,12"] },
      { number: 13, text: "Du hast aufgestört das Meer durch deine Macht*, hast zerschmettert die Häupter der Wasserungeheuer auf dem Wasser*.", footnotes: ["℘ 2Mo 14,21", "℘ Jes 51,9"] },
      { number: 14, text: "Du hast zerschlagen die Köpfe des Leviatans, gabst ihn zur Speise den Haifischen des Meeres*.", footnotes: ["Diese Üs. ergibt sich nach einer anderen Aufteilung des hebr. Konsonantentextes. Mas. T.: dem Volk, den Schakalen"] },
      { number: 15, text: "Du ließest Quelle und Bach hervorquellen*, immerfließende Ströme trocknetest du aus*.", footnotes: ["w. Du hast aufgebrochen (geöffnet) Quelle und Bach\n℘ 2Mo 17,6", "℘ Ps 114,3"] },
      { number: 16, text: "Dein ist der Tag, dein auch die Nacht*. Den Mond* und die Sonne hast du bereitet*.", footnotes: ["℘ Jer 33,25", "w. Die Leuchte", "℘ Ps 104,19; 136,8.9; 1Mo 1,16"] },
      { number: 17, text: "Du hast festgelegt alle Grenzen der Erde*. Sommer und Winter, du hast sie geschaffen.", footnotes: ["℘ Apg 17,26"] },
      { number: 18, text: "Denk daran: Der Feind hat gehöhnt, HERR*, und ein törichtes* Volk hat deinen Namen verachtet*.", footnotes: ["o. hat den HERRN geschmäht", "o. gemeines; o. gottloses", "℘ Jes 37,23"] },
      { number: 19, text: "Gib nicht den Raubtieren hin die Seele deiner Turteltaube! Das Leben deiner Elenden vergiss nicht für immer*!", footnotes: ["℘ Ps 10,12"] },
      { number: 20, text: "Schaue hin auf den Bund! Denn die Schlupfwinkel des Landes sind voll von Stätten der Gewalttat." },
      { number: 21, text: "Lass den Unterdrückten nicht beschämt davongehen! Den Elenden und Armen lass deinen Namen loben!" },
      { number: 22, text: "Stehe auf, Gott, führe deinen Rechtsstreit*! Gedenke deiner Verhöhnung durch den Toren den ganzen Tag!", footnotes: ["℘ Ps 35,23"] },
      { number: 23, text: "Vergiss nicht die Stimme deiner Widersacher, das ständig aufsteigende Getöse derer, die sich gegen dich erheben*.", footnotes: ["℘ Ps 2,1.2"] },
    ]},
    { number: 75, verses: [
      { number: 1, text: "Dem Chorleiter.Nach der Melodie:»Verdirb nicht*!« Ein Psalm. Von Asaf*. Ein Lied.", heading: "Psalm 75", footnotes: ["℘ Ps 57,1", "℘ Ps 50,1"] },
      { number: 2, text: "Wir preisen dich, Gott, wir preisen dich. Und nahe ist dein Name denen, die deine Wunder erzählen*.", footnotes: ["o. Und nahe ist dein Name; deine Wunder erzählen es\n℘ Jes 25,1"] },
      { number: 3, text: "»Wenn mein Zeitpunkt gekommen ist*, werde ich gerecht richten*.", footnotes: ["w. Wenn ich die bestimmte Zeit ergreife; andere übersetzen: Wenn ich mir auch eine Frist nehme, so werde ich doch gerecht richten.", "℘ 1Mo 18,25"] },
      { number: 4, text: "Wanken mag die Erde und alle ihre Bewohner*, ich habe ihre Säulen festgestellt*.« //", footnotes: ["℘ Ps 68,3; 97,5", "℘ 1Sam 2,8"] },
      { number: 5, text: "Ich sprach zu den Tobenden: Tobt nicht! Und zu den Gottlosen: Erhebt nicht das Horn!" },
      { number: 6, text: "Erhebt nicht zur Höhe euer Horn*! Redet nicht Freches mit stolz gerecktem Hals!", footnotes: ["d. h. handelt nicht herausfordernd; lehnt euch nicht auf\n℘ Ps 66,7"] },
      { number: 7, text: "Denn nicht von Osten, noch von Westen, und nicht von Süden* her kommt Erhöhung.", footnotes: ["w. von der Wüste her; die Wüste liegt südlich von Palästina"] },
      { number: 8, text: "Denn Gott ist Richter. Diesen erniedrigt er, und jenen erhöht er*.", footnotes: ["℘ 1Sam 2,7"] },
      { number: 9, text: "Denn ein Becher ist in der Hand des HERRN, schäumender Wein voll Würze. Und er schenkt daraus ein*: Ja, seine Hefen müssen schlürfen, müssen trinken alle Gottlosen der Erde.", footnotes: ["℘ Jer 25,15; Offb 14,10"] },
      { number: 10, text: "Ich aber, ich will verkünden ewig, ich will spielen dem Gott Jakobs." },
      { number: 11, text: "Alle Hörner der Gottlosen will ich* abhauen*. Es sollen erhöht sein die Hörner des Gerechten*.", footnotes: ["so Mas. T.; andere übersetzen mit Änderung eines Buchstabens: wird er abhauen", "℘ Jer 48,25", "℘ Ps 89,18; 92,11"] },
    ]},
    { number: 76, verses: [
      { number: 1, text: "Dem Chorleiter. Mit Saitenspiel. Ein Psalm. Von Asaf*. Ein Lied.", heading: "Psalm 76", footnotes: ["℘ Ps 50,1"] },
      { number: 2, text: "Bekannt ist Gott in Juda*, in Israel ist groß sein Name*.", footnotes: ["℘ Joh 4,22", "℘ Ps 48,2-4"] },
      { number: 3, text: "In Salem entstand seine Hütte, und seine Wohnung auf dem Zion*.", footnotes: ["℘ Ps 9,12"] },
      { number: 4, text: "Dort zerstörte er des Bogens Brände*, Schild und Schwert und Krieg*. //", footnotes: ["Gemeint sind die Brandpfeile.", "℘ Ps 37,15"] },
      { number: 5, text: "Glanzvoller bist du, herrlicher als die Berge des Raubes*.", footnotes: ["LXX liest: die ewigen Berge"] },
      { number: 6, text: "Beraubt stehen da die Heldenmütigen*, sie schlafen ihren Schlaf; und keiner der starken Männer findet seine Hände*.", footnotes: ["w. die starken Herzens sind", "℘ 2Chr 32,21"] },
      { number: 7, text: "Von deinem Schelten, Gott Jakobs, sinken in tiefen Schlaf Wagen wie Ross*.", footnotes: ["℘ 2Mo 15,1"] },
      { number: 8, text: "Du, du bist furchtbar*, und wer kann vor dir bestehen, sobald du zürnst*!", footnotes: ["℘ Neh 1,5", "℘ Nah 1,6; Offb 6,17"] },
      { number: 9, text: "Du ließest Gericht hören vom Himmel her. Die Erde fürchtete sich und wurde stille*,", footnotes: ["℘ Hab 2,20"] },
      { number: 10, text: "als Gott aufstand zum Gericht*, um zu retten alle Demütigen auf Erden*. //", footnotes: ["℘ Ps 12,6; 82,8", "℘ Jes 11,4"] },
      { number: 11, text: "Denn selbst der Grimm des Menschen wird dich preisen; auch noch mit dem Rest des Grimmes wirst du dich gürten." },
      { number: 12, text: "Sprecht Gelübde und erfüllt sie dem HERRN, eurem Gott*, alle, die ihr rings um ihn her seid. Bringt Geschenke dem Furchtbaren!", footnotes: ["℘ Ps 50,14"] },
      { number: 13, text: "Er demütigt den Geist der Fürsten*, er ist furchtbar den Königen der Erde*.", footnotes: ["℘ Jes 40,23", "℘ Jes 24,21"] },
    ]},
    { number: 77, verses: [
      { number: 1, text: "Dem Chorleiter. Nach Jedutun*. Von Asaf*. Ein Psalm.", heading: "Psalm 77", footnotes: ["vgl. 1Chr 16,41.42; 25,1.3", "℘ Ps 50,1"] },
      { number: 2, text: "Meine Stimme ruft zu Gott, und ich will schreien! Meine Stimme ruft zu Gott, dass er mir Gehör schenke*.", footnotes: ["℘ Ps 55,17"] },
      { number: 3, text: "Am Tag meiner Bedrängnis suchte ich den Herrn*. Meine Hand war des Nachts ausgestreckt und ließ nicht ab*. Meine Seele weigerte sich, getröstet zu werden.", footnotes: ["℘ Ps 50,15; Jes 26,16", "w. erschlaffte nicht"] },
      { number: 4, text: "Denke ich an Gott, so stöhne ich. Sinne ich nach, so verzagt* mein Geist. //", footnotes: ["o. fühlt sich kraftlos"] },
      { number: 5, text: "Du hieltest offen die Lider meiner Augen*; ich war voll Unruhe und redete nicht.", footnotes: ["℘ Ps 102,8"] },
      { number: 6, text: "Ich durchdachte die Tage vor alters. Der Jahre der Urzeit gedachte ich*.", footnotes: ["Ergibt sich durch andere Versteilung mit LXX. Mas. T. zieht »ich gedachte« zum folgenden Vers.\n℘ Ps 143,4.5; 5Mo 32,7"] },
      { number: 7, text: "Ich sann nach* des Nachts; in meinem Herzen überlegte ich, und es forschte mein Geist*.", footnotes: ["mit LXX; Mas. T.: Mein Saitenspiel", "℘ Ps 4,5"] },
      { number: 8, text: "Wird der Herr auf ewig verwerfen* und künftig keine Gunst mehr erweisen*?", footnotes: ["℘ Ps 74,1; Röm 11,1", "℘ Ps 13,2"] },
      { number: 9, text: "Ist seine Gnade für immer zu Ende? Hat das Wort* aufgehört von Generation zu Generation*?", footnotes: ["d. h. die Zusage (Verheißung)", "℘ 4Mo 23,19"] },
      { number: 10, text: "Hat Gott vergessen, gnädig zu sein? Hat er im Zorn verschlossen seine Erbarmungen? //" },
      { number: 11, text: "Da sprach ich: Das ist mein Schmerz*, dass sich die Rechte des Höchsten geändert hat.", footnotes: ["w. mein Durchbohrtsein"] },
      { number: 12, text: "Ich will gedenken der Taten Jahs; ja, deiner Wunder von alters her will ich gedenken*.", footnotes: ["℘ Ps 105,5; 119,52; 5Mo 7,18.19"] },
      { number: 13, text: "Ich will nachdenken über all dein Tun, und über deine Taten will ich sinnen*.", footnotes: ["℘ Ps 105,2; 119,27"] },
      { number: 14, text: "Gott! Dein Weg ist im Heiligtum*. Wer ist ein so großer Gott wie unser* Gott*?", footnotes: ["o. in Heiligkeit\n℘ Ps 68,25", "So ergänzt mit LXX und syr. Üs.", "℘ 2Mo 15,11"] },
      { number: 15, text: "Du bist der Gott, der Wunder tut*, du hast deine Stärke kundgetan unter den Völkern.", footnotes: ["℘ Ps 72,18"] },
      { number: 16, text: "Du hast dein Volk erlöst mit deinem Arm*, die Söhne Jakobs und Josefs*. //", footnotes: ["℘ 2Mo 6,6", "℘ 1Mo 48,5"] },
      { number: 17, text: "Dich sahen die Wasser, Gott, dich sahen die Wasser: sie bebten*; ja, es erzitterten die Tiefen.", footnotes: ["℘ Ps 114,3; Hab 3,10"] },
      { number: 18, text: "Die Wolken ergossen Wasser, das Gewölk ließ eine Stimme erschallen, und deine Pfeile fuhren hin und her*.", footnotes: ["℘ Ps 18,14.15"] },
      { number: 19, text: "Die Stimme deines Donners war im Wirbelwind*. Blitze erleuchteten die Welt. Es zitterte und bebte die Erde*.", footnotes: ["w. in dem Rad", "℘ Ps 97,4; 104,32; 2Mo 19,18"] },
      { number: 20, text: "Durch das Meer führt dein Weg und deine Pfade durch große Wasser*. Doch deine Fußspuren erkannte niemand.", footnotes: ["℘ Jes 43,16"] },
      { number: 21, text: "Wie eine Herde hast du dein Volk geleitet* durch die Hand Moses und Aarons*.", footnotes: ["℘ Ps 78,52; 80,2", "℘ 2Mo 6,13; 4Mo 33,1; 1Sam 12,6; Jes 63,11.12.14; Hos 12,14; Mi 6,4"] },
    ]},
    { number: 78, verses: [
      { number: 1, text: "Ein Maskil*. Von Asaf*. Höre, mein Volk, auf meine Weisung! Neigt euer Ohr zu den Worten meines Mundes*!", heading: "Psalm 78", footnotes: ["s. Anm. zu Ps 32,1", "℘ Ps 50,1", "℘ Spr 22,17"] },
      { number: 2, text: "Ich will meinen Mund öffnen zu einem Spruch, will hervorbringen* Rätsel aus der Vorzeit*.", footnotes: ["w. hervorsprudeln lassen", "℘ Ps 49,5; Mt 13,35"] },
      { number: 3, text: "Was wir gehört* und erfahren und unsere Väter uns erzählt haben,", footnotes: ["℘ 1Jo 1,1.3"] },
      { number: 4, text: "wollen wir nicht verhehlen ihren Söhnen* und der künftigen Generation erzählen die Ruhmestaten des HERRN und seine Macht* und seine Wunder, die er getan hat*.", footnotes: ["℘ 5Mo 4,9; Jes 38,19", "℘ Ps 71,18", "℘ Ps 145,4; 2Mo 13,14; Jos 4,6.7"] },
      { number: 5, text: "Denn er hat ein Zeugnis aufgerichtet in Jakob und ein Gesetz aufgestellt in Israel und gebot unseren Vätern, sie ihren Söhnen kundzutun*,", footnotes: ["℘ 5Mo 6,7"] },
      { number: 6, text: "damit die künftige Generation sie kenne, die Söhne, die geboren werden sollten, und auch sie aufständen und sie ihren Söhnen erzählten*.", footnotes: ["℘ 2Mo 10,2"] },
      { number: 7, text: "Damit sie auf Gott ihr Vertrauen setzten und die Taten Gottes nicht vergäßen und seine Gebote befolgten*.", footnotes: ["℘ Ps 105,45; 5Mo 6,21-25"] },
      { number: 8, text: "Damit sie nicht würden wie ihre Väter, eine widersetzliche und widerspenstige Generation*, eine Generation, deren Herz nicht fest war* und deren Geist nicht treu war gegen Gott,", footnotes: ["℘ 5Mo 31,27; Hes 20,8; Lk 9,41", "w. die ihr Herz nicht festigte"] },
      { number: 9, text: "wie die Söhne Ephraim, gerüstete Bogenschützen, sich wendeten am Tag des Kampfes." },
      { number: 10, text: "Sie hielten nicht den Bund Gottes* und weigerten sich, nach seinem Gesetz zu wandeln*.", footnotes: ["℘ 2Kö 17,15; Hebr 8,9", "℘ Hes 20,21"] },
      { number: 11, text: "Sie vergaßen seine Taten und seine Wunder, die er sie hatte schauen lassen*.", footnotes: ["℘ Ps 106,13"] },
      { number: 12, text: "Er tat Wunder vor ihren Vätern im Lande Ägypten, dem Gebiet Zoans*.", footnotes: ["eine Stadt in Unterägypten\n℘ V. 43; Ps 135,9; 5Mo 4,34; Jos 9,9"] },
      { number: 13, text: "Er spaltete das Meer* und ließ sie hindurchgehen, er ließ das Wasser stehen wie einen Damm*.", footnotes: ["℘ Ps 136,13; Jes 63,12", "℘ 2Mo 15,8; Jos 3,16"] },
      { number: 14, text: "Er leitete sie des Tages mit der Wolke und die ganze Nacht mit dem Licht eines Feuers*.", footnotes: ["℘ 2Mo 13,21"] },
      { number: 15, text: "Er spaltete Felsen in der Wüste und tränkte sie reichlich, wie mit Urfluten*.", footnotes: ["℘ 2Mo 17,6; 4Mo 20,11; 1Kor 10,4"] },
      { number: 16, text: "Er ließ Bäche hervorkommen aus dem Felsen und Wasser herablaufen wie Flüsse*.", footnotes: ["℘ Ps 105,41; 107,35; 114,7"] },
      { number: 17, text: "Doch sie fuhren weiter fort, gegen ihn zu sündigen, sich gegen den Höchsten widerspenstig zu zeigen in der Wüste*.", footnotes: ["℘ 5Mo 31,27; Hes 20,8; Lk 9,41"] },
      { number: 18, text: "Sie versuchten Gott in ihrem Herzen*, indem sie Speise forderten für ihr Gelüste*.", footnotes: ["℘ Ps 106,14; 2Mo 17,7", "℘ 4Mo 11,4-6"] },
      { number: 19, text: "Und sie redeten gegen Gott; sie sprachen: Sollte Gott imstande sein, uns in der Wüste einen Tisch zu bereiten*?", footnotes: ["℘ 2Mo 16,3.12"] },
      { number: 20, text: "Siehe, den Felsen hat er zwar geschlagen, und Wasser floss heraus, und Bäche strömten. Wird er aber auch Brot geben können, oder wird er seinem Volk Fleisch verschaffen*?", footnotes: ["℘ 4Mo 11,4"] },
      { number: 21, text: "Darum, als der HERR es hörte, wurde er zornig*, und Feuer entzündete sich gegen Jakob, und auch Zorn stieg auf gegen Israel*,", footnotes: ["℘ Hebr 3,10", "℘ 4Mo 11,1.10"] },
      { number: 22, text: "weil sie Gott nicht glaubten und nicht vertrauten auf seine Hilfe*.", footnotes: ["℘ Hebr 3,17-19"] },
      { number: 23, text: "Und doch hat er den Wolken oben geboten und die Türen des Himmels geöffnet*.", footnotes: ["℘ Mal 3,10"] },
      { number: 24, text: "Und hat Manna auf sie regnen lassen*, dass sie es äßen, und ihnen Himmelsgetreide gegeben.", footnotes: ["℘ 2Mo 16,14; Joh 6,31"] },
      { number: 25, text: "Ein jeder aß Brot der Starken*. Speise sandte er ihnen bis zur Sättigung*.", footnotes: ["d. h. Brot der Engel", "℘ Ps 105,40"] },
      { number: 26, text: "Er ließ den Ostwind losbrechen am Himmel und trieb durch seine Stärke den Südwind herbei*.", footnotes: ["℘ Ps 135,7; 147,18"] },
      { number: 27, text: "Er ließ Fleisch auf sie regnen wie Staub und Vögel* wie Sand der Meere*,", footnotes: ["w. geflügeltes Gevögel", "℘ 4Mo 11,31"] },
      { number: 28, text: "und ließ sie mitten in sein Lager fallen, rings um seine Wohnungen*.", footnotes: ["℘ 2Mo 16,13"] },
      { number: 29, text: "Da aßen sie und wurden sehr satt, und was sie verlangten*, brachte er ihnen*.", footnotes: ["w. ihr Verlangen", "℘ Ps 106,15; 4Mo 11,19.20"] },
      { number: 30, text: "Sie hatten sich noch nicht abgewendet von ihrem Verlangen, ihre Speise war noch in ihrem Mund," },
      { number: 31, text: "da stieg der Zorn Gottes gegen sie auf. Er brachte viele unter ihren stattlichen Leuten um. Die jungen Männer Israels streckte er nieder*.", footnotes: ["w. zwang er in die Knie\n℘ 4Mo 11,33.34"] },
      { number: 32, text: "Trotz alledem sündigten sie weiter und glaubten nicht an seine Wunder." },
      { number: 33, text: "Da ließ er in Nichtigkeit hinschwinden ihre Tage und ihre Jahre in Schrecken*.", footnotes: ["℘ Ps 90,7-9; 4Mo 14,33-38"] },
      { number: 34, text: "Wenn er sie umbrachte, dann fragten sie nach ihm, kehrten um und suchten nach Gott*.", footnotes: ["℘ Jes 26,16"] },
      { number: 35, text: "Und sie dachten daran, dass Gott ihr Fels sei und Gott, der Höchste, ihr Erlöser*.", footnotes: ["℘ Ps 19,15"] },
      { number: 36, text: "Doch sie betrogen ihn mit ihrem Mund, und mit ihrer Zunge belogen sie ihn*.", footnotes: ["℘ Mi 6,12"] },
      { number: 37, text: "Denn ihr Herz war nicht fest ihm gegenüber, und sie blieben nicht treu an seinem Bund*.", footnotes: ["℘ Jer 31,32"] },
      { number: 38, text: "Er aber war barmherzig, er vergab die Schuld und vertilgte nicht; und oftmals wandte er seinen Zorn ab und ließ nicht erwachen seinen ganzen Grimm*.", footnotes: ["℘ Jes 48,9"] },
      { number: 39, text: "Er dachte daran, dass sie Fleisch sind*, ein Hauch, der dahinfährt und nicht wiederkehrt*.", footnotes: ["℘ 1Mo 6,3", "℘ Ps 103,14"] },
      { number: 40, text: "Wie oft waren sie widerspenstig gegen ihn in der Wüste*, betrübten ihn in der Einöde!", footnotes: ["℘ V. 8"] },
      { number: 41, text: "Immer wieder versuchten sie Gott und kränkten den Heiligen Israels*.", footnotes: ["℘ Jes 1,4"] },
      { number: 42, text: "Sie dachten nicht an seine Hand, an den Tag, da er sie von dem Bedränger erlöste*,", footnotes: ["℘ Ps 106,21.22"] },
      { number: 43, text: "*als er seine Zeichen tat in Ägypten und seine Wunder im Gebiet Zoans*:", footnotes: ["℘ V. 43-51: Ps 105,27-36", "℘ V. 12"] },
      { number: 44, text: "Er verwandelte ihre Ströme in Blut* und ihre Bäche, so dass sie nicht mehr trinken konnten.", footnotes: ["℘ 2Mo 7,20.21"] },
      { number: 45, text: "Er sandte Hundsfliegen unter sie, die sie fraßen, und Frösche, die ihnen Verderben brachten*.", footnotes: ["℘ 2Mo 8,17.24"] },
      { number: 46, text: "Ihren Ertrag gab er der Heuschreckenlarve, und was sie erarbeitet hatten, der Heuschrecke*.", footnotes: ["℘ 2Mo 10,14.15"] },
      { number: 47, text: "Ihren Weinstock zerschlug er mit Hagel, ihre Maulbeerbäume mit Schloßen*.", footnotes: ["große Hagelkörner"] },
      { number: 48, text: "Und er gab ihr Vieh dem Hagel preis und ihre Herden den Blitzen*.", footnotes: ["℘ 2Mo 9,25"] },
      { number: 49, text: "Er ließ gegen sie los seines Zornes Glut, Grimm, Verwünschung und Bedrängnis, eine Schar* von Unheilsboten.", footnotes: ["w. eine Sendung"] },
      { number: 50, text: "Er bahnte seinem Zorn einen Weg, er entzog ihre Seele nicht dem Tod und gab ihr Leben der Pest preis." },
      { number: 51, text: "Er schlug alle Erstgeburt in Ägypten, die Erstlinge der Kraft in den Zelten Hams*.", footnotes: ["℘ Ps 135,8; 136,10; 2Mo 12,29"] },
      { number: 52, text: "Und er ließ sein Volk aufbrechen wie die Schafe und leitete sie wie eine Herde in der Wüste*.", footnotes: ["℘ Ps 77,21; Jes 63,11"] },
      { number: 53, text: "Er führte sie sicher, so dass sie sich nicht fürchteten*; und ihre Feinde bedeckte das Meer*.", footnotes: ["℘ 2Mo 14,13", "℘ Ps 106,11; 136,15; 2Mo 18,24"] },
      { number: 54, text: "Er brachte sie in sein heiliges Land*, zu diesem Berg, den seine Rechte erworben hat*.", footnotes: ["w. zur Grenze seines Heiligtums", "℘ 2Mo 15,17"] },
      { number: 55, text: "Er vertrieb Nationen vor ihnen und verteilte sie mit der Messschnur des Erbes* und ließ in ihren Zelten wohnen die Stämme Israels*.", footnotes: ["d. h. als zugemessenes Erbe", "℘ Ps 44,3; Jos 21,43"] },
      { number: 56, text: "Aber sie versuchten Gott, den Höchsten, und waren widerspenstig* gegen ihn; und seine Mahnungen beachteten sie nicht.", footnotes: ["℘ V. 8"] },
      { number: 57, text: "Sie wurden abtrünnig und handelten treulos wie ihre Väter. Sie versagten wie ein schlaffer Bogen*.", footnotes: ["o. drehten sich wie ein trügerischer Bogen\n℘ Hos 7,16"] },
      { number: 58, text: "Und sie erbitterten ihn durch ihre Höhen* und reizten ihn zur Eifersucht* mit ihren Götzenbildern*.", footnotes: ["℘ 5Mo 12,2; 2Kö 17,9", "℘ 5Mo 32,16; 1Kor 10,22", "℘ Ri 3,19; 2Kö 21,7"] },
      { number: 59, text: "Gott hörte es und ergrimmte, und er verwarf Israel völlig*.", footnotes: ["℘ Hebr 8,9"] },
      { number: 60, text: "Er gab die Wohnung zu Silo* auf, das Zelt, in dem er unter den Menschen wohnte*.", footnotes: ["℘ Jos 18,1", "w. wohnen ließ\n℘ 1Sam 4,11; Jer 7,12"] },
      { number: 61, text: "Und er gab seine Kraft* in Gefangenschaft und seine Herrlichkeit* in die Hand des Bedrängers*.", footnotes: ["Gemeint ist die Bundeslade.", "Gemeint ist die Bundeslade.", "℘ 1Sam 4,21.22"] },
      { number: 62, text: "Er gab sein Volk dem Schwert preis*, und gegen sein Erbe ergrimmte er*.", footnotes: ["℘ 1Sam 4,10", "℘ Jer 12,7-13"] },
      { number: 63, text: "Seine jungen Männer fraß das Feuer, und seine Jungfrauen wurden nicht besungen*.", footnotes: ["d. h. in Hochzeitsliedern\n℘ Jer 7,34"] },
      { number: 64, text: "Seine Priester fielen durch das Schwert*, und seine Witwen weinten nicht*.", footnotes: ["℘ 1Sam 4,11", "d. h. sie konnten keine Totenklage halten\n℘ Hi 27,15"] },
      { number: 65, text: "Da erwachte der Herr wie ein Schlafender, wie ein Held*, der nüchtern wird vom Wein.", footnotes: ["℘ Jes 42,13; Zef 3,17"] },
      { number: 66, text: "Und er schlug seine Bedränger zurück,* ewige Schande bereitete er ihnen.", footnotes: ["℘ 1Sam 7,10"] },
      { number: 67, text: "Und er verwarf das Zelt Josefs, und den Stamm Ephraim erwählte er nicht," },
      { number: 68, text: "sondern er erwählte den Stamm Juda*, den Berg Zion, den er geliebt hat*.", footnotes: ["℘ 1Mo 49,10", "℘ Ps 87,2; 132,13; 2Chr 6,6"] },
      { number: 69, text: "Er baute sein Heiligtum wie Himmelshöhen, wie die Erde, die er auf ewig gegründet hat*.", footnotes: ["℘ Ps 87,1"] },
      { number: 70, text: "Er erwählte David*, seinen Knecht, und nahm ihn weg von den Hürden der Schafe*.", footnotes: ["℘ 1Sam 16,12", "℘ 2Sam 7,8"] },
      { number: 71, text: "Von den Muttertieren* weg holte er ihn, dass er Jakob, sein Volk, weidete* und Israel, sein Erbteil*.", footnotes: ["w. Säugenden", "℘ Hes 34,23", "℘ Mt 2,6"] },
      { number: 72, text: "Und er weidete sie nach der Lauterkeit seines Herzens*, und mit der Geschicklichkeit seiner Hände leitete er sie.", footnotes: ["℘ 1Kö 9,4"] },
    ]},
    { number: 79, verses: [
      { number: 1, text: "Ein Psalm. Von Asaf*. Gott! Nationen sind in dein Erbteil gekommen, haben deinen heiligen Tempel verunreinigt, haben Jerusalem zu Trümmerhaufen gemacht*.", heading: "Psalm 79", footnotes: ["℘ Ps 50,1", "℘ 2Kö 25,9; Kla 1,10; Mi 3,12; Lk 21,24"] },
      { number: 2, text: "Die Leichen deiner Knechte haben sie den Vögeln des Himmels zum Fraß gegeben, das Fleisch deiner Frommen den wilden Tieren des Feldes*.", footnotes: ["℘ Jer 7,33"] },
      { number: 3, text: "Sie haben ihr Blut wie Wasser vergossen rings um Jerusalem, und niemand war da, der begraben hätte*.", footnotes: ["℘ Jer 14,16; Zef 1,17; Offb 11,9"] },
      { number: 4, text: "Wir sind ein Hohn geworden unseren Nachbarn, ein Spott und Schimpf denen, die uns umgeben*.", footnotes: ["℘ Ps 44,14"] },
      { number: 5, text: "Bis wann, HERR, willst du immerfort zürnen, soll wie Feuer brennen dein Eifer*?", footnotes: ["℘ Ps 80,5; 89,47"] },
      { number: 6, text: "Schütte deinen Zorn aus über die Nationen, die dich nicht erkennen*, auf die Königreiche, die deinen Namen nicht anrufen*!", footnotes: ["℘ 2Thes 1,8", "℘ Jer 10,25"] },
      { number: 7, text: "Denn sie haben* Jakob aufgezehrt, sein Weidegebiet haben sie verwüstet*.", footnotes: ["so mit einigen Handschr., LXX, der syr. und aram. Üs., vor allem wegen V. 7b; Mas. T. w. er hat . . . aufgezehrt", "℘ Jes 64,9.10"] },
      { number: 8, text: "Rechne uns nicht an die Schuld der Vorfahren*; lass uns dein Erbarmen eilends entgegenkommen! Denn wir sind sehr gering* geworden.", footnotes: ["w. Gedenke uns nicht der Sünden der Vorfahren", "o. schwach"] },
      { number: 9, text: "Hilf uns, Gott unseres Heils, um der Ehre* deines Namens willen. Rette uns und vergib unsere Sünden um deines Namens willen*!", footnotes: ["o. Herrlichkeit", "℘ Hes 20,44"] },
      { number: 10, text: "Warum sollen die Nationen sagen: Wo ist ihr Gott*? Lass unter den Nationen vor unseren Augen kundwerden, *dass du das vergossene Blut deiner Knechte rächst*!", footnotes: ["℘ Ps 42,4", "w. die Rache für das . . .", "w. die Rache für das . . .\n℘ 5Mo 32,43"] },
      { number: 11, text: "Lass vor dich kommen das Seufzen des Gefangenen; nach der Größe deines Armes lass übrig bleiben die Kinder des Todes*!", footnotes: ["℘ Ps 102,21"] },
      { number: 12, text: "Und gib unseren Nachbarn siebenfach in ihren Schoß zurück ihren Hohn, mit dem sie dich gehöhnt haben*, Herr!", footnotes: ["℘ Ps 89,52"] },
      { number: 13, text: "Wir aber sind dein Volk und die Herde deiner Weide*. Wir wollen dich ewig preisen, von Generation zu Generation dein Lob erzählen*!", footnotes: ["℘ Ps 74,1", "℘ Jes 43,21"] },
    ]},
    { number: 80, verses: [
      { number: 1, text: "Dem Chorleiter. Nach Schoschannim*. Ein Zeugnis. Von Asaf *. Ein Psalm.", heading: "Psalm 80", footnotes: ["℘ Ps 45,1; 60,1", "℘ Ps 50,1"] },
      { number: 2, text: "Du Hirte Israels, der du Josef leitest wie eine Herde*, höre doch! Der du thronst *auf den Cherubim*, strahle hervor*!", footnotes: ["℘ Ps 77,21", "o. auf den Cherubim! Erstrahle 3 vor Ephraim, Benjamin und Manasse! Erwecke", "℘ Ps 99,1; 1Sam 4,4; 2Kö 19,15", "℘ Ps 50,2"] },
      { number: 3, text: "Vor Ephraim, Benjamin und Manasse erwecke* deine Macht und komm zu unserer Rettung*!", footnotes: ["o. auf den Cherubim! Erstrahle 3 vor Ephraim, Benjamin und Manasse! Erwecke", "℘ Ps 44,27"] },
      { number: 4, text: "Gott! Stelle uns wieder her*! Lass dein Angesicht leuchten*, so werden wir gerettet*.", footnotes: ["℘ Ps 60,3", "℘ Ps 4,7; Dan 9,17", "℘ Ps 31,17"] },
      { number: 5, text: "HERR, Gott der Heerscharen! Bis wann zürnst du* trotz des Gebets* deines Volkes*?", footnotes: ["w. rauchst du; vgl. den Ausdruck in Ps 74,1", "w. beim Gebet", "℘ Ps 74,1; 79,5"] },
      { number: 6, text: "Du hast sie mit Tränenbrot gespeist, sie in reichem Maß* getränkt mit Tränen*.", footnotes: ["w. im Dreimaß, maßweise", "℘ Ps 42,4"] },
      { number: 7, text: "Du setztest uns zum Streit* unseren Nachbarn, und unsere Feinde spotten über uns*.", footnotes: ["d. h. zum Gegenstand des Streites, der Anfeindung", "so mit LXX und syr. Üs.; Mas. T.: untereinander"] },
      { number: 8, text: "Gott der Heerscharen! Stelle uns wieder her*! Lass dein Angesicht leuchten, so werden wir gerettet*.", footnotes: ["℘ Ps 31,17", "℘ Ps 31,17"] },
      { number: 9, text: "Einen Weinstock* hobst du aus aus Ägypten. Du vertriebst Nationen und pflanztest ihn ein*.", footnotes: ["℘ Joh 15,1", "℘ Ps 44,3; Jer 2,21"] },
      { number: 10, text: "Du machtest Raum vor ihm*, und er schlug Wurzeln und erfüllte das Land.", footnotes: ["℘ Jos 24,12"] },
      { number: 11, text: "Die Berge wurden bedeckt von seinem Schatten, von seinen Ästen die Zedern Gottes." },
      { number: 12, text: "Er streckte seine Zweige aus bis ans Meer, bis zum Strom hin seine Triebe*.", footnotes: ["℘ 1Kö 5,1"] },
      { number: 13, text: "Warum hast du seine Mauern niedergerissen, so dass ihn alle berupfen, die des Weges kommen*?", footnotes: ["℘ Ps 89,42"] },
      { number: 14, text: "Es frisst ihn ab das Wildschwein aus dem Wald, das Wild des Feldes weidet ihn ab." },
      { number: 15, text: "Gott der Heerscharen! Kehre doch zurück*! Schau vom Himmel und sieh*! Und suche diesen Weinstock heim!", footnotes: ["Man könnte mit LXX entsprechend den Versen 4, 8 und 20 lesen: Gott der Heerscharen! Stelle uns wieder her!\n℘ Ps 90,13", "℘ Jes 63,15"] },
      { number: 16, text: "Und beschirme*, was deine Rechte gepflanzt hat, den Sohn, den du dir hast stark werden lassen.", footnotes: ["Das hier mit »beschirmen« übersetzte hebr. Wort kommt nur an dieser Stelle vor. Andere übersetzen: Und den Setzling, den"] },
      { number: 17, text: "Er ist mit Feuer verbrannt, er ist abgehauen*. Vor dem Schelten deines Angesichtes kommen sie um.", footnotes: ["℘ Hes 21,3"] },
      { number: 18, text: "Deine Hand sei über dem Mann deiner Rechten, über dem Menschensohn, den du dir hast stark werden lassen." },
      { number: 19, text: "So werden wir nicht von dir abweichen*. Belebe uns, und wir werden deinen Namen anrufen.", footnotes: ["℘ 5Mo 5,32; Jos 1,7; Jer 32,40"] },
      { number: 20, text: "HERR, Gott der Heerscharen! Stelle uns wieder her! Lass dein Angesicht leuchten, so werden wir gerettet*.", footnotes: ["℘ Ps 31,17"] },
    ]},
    { number: 81, verses: [
      { number: 1, text: "Dem Chorleiter. Nach der Gittit*. Von Asaf*.", heading: "Psalm 81", footnotes: ["℘ Ps 8,1", "℘ Ps 50,1"] },
      { number: 2, text: "Jubelt Gott zu, unserer Stärke*! Jauchzt dem Gott Jakobs!", footnotes: ["℘ Ps 59,17.18"] },
      { number: 3, text: "Hebt an den Gesang, und lasst das Tamburin ertönen, die liebliche Zither samt der Harfe*!", footnotes: ["℘ Ps 33,2; 149,3"] },
      { number: 4, text: "Stoßt am Neumond in das Horn, am Vollmond zum Tag unseres Festes*!", footnotes: ["℘ 4Mo 10,10"] },
      { number: 5, text: "Denn eine Ordnung für Israel ist dies, eine Verordnung des Gottes Jakobs." },
      { number: 6, text: "Er setzte es ein als ein Zeugnis in Josef*, als er auszog gegen das Land Ägypten. Eine Sprache höre ich, die ich bisher nicht kannte*:", footnotes: ["℘ Ps 112,4", "℘ Ps 114,1"] },
      { number: 7, text: "Ich habe von der Last befreit seine Schulter, seine Hände lösten sich vom Tragkorb*.", footnotes: ["℘ 2Mo 6,6; 20,2; 5Mo 5,6; Jer 16,14"] },
      { number: 8, text: "In der Bedrängnis riefst du, und ich befreite dich. Ich antwortete dir im Donnergewölk*. Ich prüfte dich am Wasser von Meriba*. //", footnotes: ["℘ 2Mo 19,16.19", "℘ 2Mo 17,7; 4Mo 20,13"] },
      { number: 9, text: "Höre, mein Volk, ich will dich warnen*. Israel, wenn du mir doch gehorchtest*!", footnotes: ["℘ Ps 50,7", "℘ 2Mo 15,26"] },
      { number: 10, text: "Es soll kein fremder Gott bei dir sein, und du sollst nicht anbeten einen Gott des Auslands*.", footnotes: ["℘ 2Mo 20,3; 5Mo 5,7; Jos 24,23"] },
      { number: 11, text: "Ich bin der HERR, dein Gott, der dich aus dem Land Ägypten herausgeführt hat*. Tue deinen Mund weit auf, und ich will ihn füllen.", footnotes: ["℘ 2Mo 6,6; 20,2; 5Mo 5,6; Jer 16,14"] },
      { number: 12, text: "Aber mein Volk hat nicht auf meine Stimme gehört*, und Israel ist mir nicht willig gewesen.", footnotes: ["℘ Hos 9,17"] },
      { number: 13, text: "Da gab ich sie dahin in die Verstocktheit ihres Herzens*. Sie wandelten nach ihren Ratschlägen*.", footnotes: ["℘ Joh 12,40; Apg 7,42; Röm 1,24", "℘ Spr 1,31"] },
      { number: 14, text: "Dass mein Volk auf mich hörte*, Israel in meinen Wegen wandelte*!", footnotes: ["℘ Jes 48,18", "℘ 5Mo 10,12"] },
      { number: 15, text: "Bald würde ich ihre Feinde beugen, meine Hand wenden gegen ihre Bedränger*.", footnotes: ["℘ 3Mo 26,3.7"] },
      { number: 16, text: "Die den HERRN hassen, würden ihm Ergebung heucheln*, ihre* Zeit würde ewig sein*.", footnotes: ["℘ Ps 18,45", "d. h. Israels Zeit. Man kann auch übersetzen: ihre (d. h. der Bedränger) Gerichtszeit.", "℘ 5Mo 5,29"] },
      { number: 17, text: "Mit dem besten* Weizen würde ich* es speisen*, und mit Honig aus dem Felsen würde ich es sättigen*.", footnotes: ["w. Mit dem Fett (d. h. dem Besten) des Weizens", "Mas. T.: er. — Wegen 17b ist jedoch »ich« zu lesen.", "℘ Ps 147,14", "℘ 5Mo 32,13"] },
    ]},
    { number: 82, verses: [
      { number: 1, text: "Ein Psalm. Von Asaf*. Gott steht in der Gottesversammlung, inmitten der Götter richtet er*.", heading: "Psalm 82", footnotes: ["℘ Ps 50,1", "℘ Ps 58,2"] },
      { number: 2, text: "Bis wann wollt ihr ungerecht richten und die Gottlosen begünstigen*? //", footnotes: ["w. die Gesichter der Gottlosen ansehen\n℘ 3Mo 19,15; 5Mo 1,17; Spr 18,5"] },
      { number: 3, text: "Schafft Recht dem Geringen und der Waise, dem Elenden und dem Bedürftigen lasst Gerechtigkeit widerfahren*!", footnotes: ["℘ Jes 1,17"] },
      { number: 4, text: "Rettet den Geringen und den Armen, entreißt ihn der Hand der Gottlosen*!", footnotes: ["℘ Jer 22,3"] },
      { number: 5, text: "Sie erkennen nichts und verstehen nichts*, im Dunkeln laufen sie umher*. Es wanken alle Grundfesten der Erde*.", footnotes: ["℘ Hi 8,9", "℘ Spr 4,19", "℘ Ps 99,1"] },
      { number: 6, text: "Ich sagte zwar: Ihr seid Götter*, Söhne des Höchsten seid ihr alle*!", footnotes: ["℘ Joh 10,34", "℘ Apg 17,28"] },
      { number: 7, text: "Doch wie ein Mensch werdet ihr sterben, wie einer der Obersten werdet ihr fallen." },
      { number: 8, text: "Stehe auf, Gott, richte die Erde*! Denn du sollst zum Erbteil haben alle Nationen*.", footnotes: ["℘ Ps 76,10; 94,2", "℘ Ps 2,8"] },
    ]},
    { number: 83, verses: [
      { number: 1, text: "Ein Lied. Ein Psalm. Von Asaf*.", heading: "Psalm 83", footnotes: ["℘ Ps 50,1"] },
      { number: 2, text: "Gott, schweige nicht*! Verstumme nicht und sei nicht stille, Gott!", footnotes: ["w. sei nicht ruhig o. untätig\n℘ Ps 109,1"] },
      { number: 3, text: "Denn siehe, deine Feinde toben*, und die dich hassen, erheben das Haupt.", footnotes: ["℘ Ps 2,1"] },
      { number: 4, text: "Gegen dein Volk planen sie listige Anschläge, und sie beraten sich gegen die, die bei dir geborgen sind." },
      { number: 5, text: "Sie sprechen: Kommt und lasst uns sie als Nation* vertilgen, dass nicht mehr gedacht werde des Namens Israel*!", footnotes: ["w. von der Nation weg", "℘ Ps 74,8; 124,3; Est 3,6"] },
      { number: 6, text: "Denn sie haben sich beraten mit einmütigem Herzen, sie haben einen Bund gegen dich geschlossen*:", footnotes: ["℘ Ps 2,2"] },
      { number: 7, text: "Die Zelte Edoms und die Ismaeliter, Moab und die Hageriter," },
      { number: 8, text: "Gebal und Ammon und Amalek, Philistäa samt den Bewohnern von Tyrus." },
      { number: 9, text: "Auch Assur hat sich ihnen angeschlossen. Sie sind zu einem Arm geworden den Söhnen Lots*. //", footnotes: ["℘ 1Mo 19,37.38"] },
      { number: 10, text: "Tu ihnen wie Midian*, wie Sisera, wie Jabin am Bach Kischon*!", footnotes: ["℘ Ri 7,25", "℘ Ri 4,15.23; 5,21"] },
      { number: 11, text: "Sie wurden vertilgt zu En-Dor, sie wurden dem Erdboden zum Dünger*!", footnotes: ["℘ Jer 8,2"] },
      { number: 12, text: "Mache sie, ihre Edlen, wie Oreb und wie Seeb*, und wie Sebach und wie Zalmunna* alle ihre Fürsten!", footnotes: ["℘ Ri 7,25", "℘ Ri 8,21"] },
      { number: 13, text: "Die gesagt haben: Lasst uns in Besitz nehmen die Weideplätze Gottes*!", footnotes: ["℘ Hes 36,2"] },
      { number: 14, text: "Mein Gott, mache sie gleich der Raddistel*, wie Spreu vor dem Wind*!", footnotes: ["Gemeint sind vertrocknete und vom Wind umhergewirbelte Teile dieser Pflanzen, deren Stacheln besonders für Pferde gefährlich werden können.", "℘ Hi 21,18; Jes 17,13"] },
      { number: 15, text: "Wie Feuer den Wald verbrennt und wie eine Flamme die Berge entzündet*,", footnotes: ["℘ Hes 21,3"] },
      { number: 16, text: "so verfolge sie mit deinem Wetter, und mit deinem Sturmwind schrecke sie*!", footnotes: ["℘ Hi 27,20"] },
      { number: 17, text: "Bedecke* ihr Gesicht mit Schande, damit sie deinen Namen, HERR, suchen!", footnotes: ["w. Fülle"] },
      { number: 18, text: "Lass sie beschämt und erschreckt sein für immer, mit Scham bedeckt sein und umkommen*,", footnotes: ["℘ Ps 35,4.26"] },
      { number: 19, text: "damit sie erkennen, dass du allein — HERR ist ja dein Name*! — der Höchste bist über die ganze Erde*!", footnotes: ["℘ 2Mo 6,2.3; Jes 42,8", "℘ Ps 59,14; 97,9; 138,6; Jes 37,16; Dan 4,21.22"] },
    ]},
    { number: 84, verses: [
      { number: 1, text: "Dem Chorleiter. Nach der Gittit*. Von den Söhnen Korachs*. Ein Psalm.", heading: "Psalm 84", footnotes: ["℘ Ps 8,1", "℘ Ps 42,1"] },
      { number: 2, text: "Wie lieblich sind deine Wohnungen*, HERR der Heerscharen!", footnotes: ["℘ 4Mo 24,5"] },
      { number: 3, text: "Es sehnt sich, ja, es schmachtet meine Seele nach den Vorhöfen des HERRN, mein Herz und mein Leib*, sie jauchzen dem lebendigen Gott* entgegen.", footnotes: ["o. Fleisch", "℘ Ps 42,3"] },
      { number: 4, text: "Auch der Vogel hat ein Haus gefunden und die Schwalbe ein Nest für sich, wo sie ihre Jungen hingelegt hat — deine Altäre*, HERR der Heerscharen, mein König und mein Gott*!", footnotes: ["bei geringfügiger Verbesserung des Mas. T.: bei deinen Altären", "℘ Ps 5,3; Joh 20,28"] },
      { number: 5, text: "Glücklich sind, die in deinem Haus wohnen*. Stets werden sie dich loben*. //", footnotes: ["℘ Ps 65,5", "℘ Ps 134,1"] },
      { number: 6, text: "Glücklich ist der Mensch, dessen Stärke in dir ist, in dessen Herz gebahnte Wege sind*!", footnotes: ["Mit zwei hebr. Handschr., LXX, Targum und der syr. Üs. kann man übersetzen: Glücklich ist das Volk, das in dir, HERR, Kraft hat; Zuversicht ist in seinem Herzen"] },
      { number: 7, text: "Sie gehen durch das Tränental* und machen es zu einem Quellort*. Ja, mit Segnungen bedeckt es der Frühregen*.", footnotes: ["o. Tal des Bakastrauchs; vielleicht ein bestimmtes Tal in der Nähe von Jerusalem", "℘ Jes 58,11", "℘ Hes 34,26"] },
      { number: 8, text: "Sie gehen von Kraft zu Kraft*. Sie erscheinen* vor Gott in Zion*.", footnotes: ["℘ Jes 40,31; 2Kor 4,16", "w. Er erscheint", "℘ 5Mo 16,16"] },
      { number: 9, text: "HERR, Gott der Heerscharen, höre mein Gebet*! Vernimm es, Gott Jakobs! //", footnotes: ["℘ Ps 17,1"] },
      { number: 10, text: "Blicke doch, Gott, auf unseren Schild*! Schaue an das Gesicht deines Gesalbten*!", footnotes: ["Gemeint ist der König; vgl. Ps 47,10; 89,19. Andere übersetzen: Gott, unser Schild", "℘ 2Chr 6,42"] },
      { number: 11, text: "Denn ein Tag in deinen Vorhöfen ist besser als sonst tausend. Ich will lieber an der Schwelle stehen im Haus meines Gottes als wohnen in den Zelten des Unrechts." },
      { number: 12, text: "Denn Gott, der HERR, ist Sonne* und Schild*. Gnade* und Herrlichkeit* wird der HERR geben, kein Gutes vorenthalten denen, die in Lauterkeit wandeln*.", footnotes: ["℘ Jes 60,19.20; Offb 21,23", "℘ Ps 3,4", "℘ Joh 1,16", "℘ Röm 8,30", "℘ Ps 125,4"] },
      { number: 13, text: "HERR der Heerscharen! Glücklich ist der Mensch, der auf dich vertraut*!", footnotes: ["℘ Ps 2,12"] },
    ]},
    { number: 85, verses: [
      { number: 1, text: "Dem Chorleiter. Von den Söhnen Korachs*. Ein Psalm.", heading: "Psalm 85", footnotes: ["℘ Ps 42,1"] },
      { number: 2, text: "HERR, du hast Gefallen gefunden an deinem Land, hast die Gefangenschaft Jakobs gewendet*.", footnotes: ["℘ Ps 126,1"] },
      { number: 3, text: "Du hast vergeben die Ungerechtigkeit deines Volkes, alle ihre Sünde hast du zugedeckt*. //", footnotes: ["℘ 5Mo 32,43; Jes 40,1.2; Jer 50,20; Mi 7,19"] },
      { number: 4, text: "Du hast zurückgezogen all deinen Grimm, hast dich abgewandt von der Glut deines Zorns*.", footnotes: ["℘ Jes 12,1; Hos 11,9"] },
      { number: 5, text: "Stelle uns wieder her*, Gott unseres Heils*, und mache deinem Unwillen gegen uns ein Ende*!", footnotes: ["℘ Ps 60,3", "℘ Mi 7,7", "℘ 5Mo 29,27"] },
      { number: 6, text: "Willst du uns ewig zürnen*? Willst du deinen Zorn währen lassen von Generation zu Generation?", footnotes: ["℘ Ps 77,8"] },
      { number: 7, text: "Willst du uns nicht wieder beleben, dass dein Volk sich in dir freue*?", footnotes: ["℘ Jer 33,10.11"] },
      { number: 8, text: "Lass uns, HERR, deine Gnade sehen, und gewähre uns dein Heil!" },
      { number: 9, text: "Hören will ich, was Gott, was der HERR reden wird; gewiss wird er Frieden ansagen* seinem Volk und seinen Frommen*, doch sollen sie nicht zur Torheit zurückkehren.", footnotes: ["w. reden", "℘ Jer 29,11"] },
      { number: 10, text: "Fürwahr, nahe ist sein Heil denen, die ihn fürchten, damit Herrlichkeit wohne in unserem Land*.", footnotes: ["℘ Jes 46,13"] },
      { number: 11, text: "Gnade und Wahrheit* sind sich begegnet*, Gerechtigkeit und Frieden* haben sich geküsst.", footnotes: ["o. Treue", "℘ Joh 1,15.17", "℘ Ps 72,3"] },
      { number: 12, text: "Wahrheit* wird sprossen aus der Erde, Gerechtigkeit herniederschauen vom Himmel*.", footnotes: ["o. Treue", "℘ Jes 45,8"] },
      { number: 13, text: "Auch wird der HERR das Gute geben, und unser Land wird seinen Ertrag bringen*.", footnotes: ["℘ Hes 36,30"] },
      { number: 14, text: "Gerechtigkeit wird vor ihm hergehen, und er wird ihre Tritte zum Weg machen*.", footnotes: ["d. h. verbindlich machen; o. sie wird seine Tritte zum Weg machen"] },
    ]},
    { number: 86, verses: [
      { number: 1, text: "Ein Gebet. Von David. Neige, HERR, dein Ohr, erhöre mich! Denn ich bin elend und arm*.", heading: "Psalm 86", footnotes: ["℘ Ps 25,16"] },
      { number: 2, text: "Bewahre meine Seele*, denn ich bin fromm! Rette deinen Knecht, der auf dich vertraut! Du bist doch mein Gott!", footnotes: ["o. Leben"] },
      { number: 3, text: "Sei mir gnädig*, Herr! Denn zu dir rufe ich den ganzen Tag*.", footnotes: ["℘ Ps 41,5", "℘ Ps 88,2"] },
      { number: 4, text: "Erfreue die Seele deines Knechtes! Denn zu dir, Herr, erhebe ich meine Seele*.", footnotes: ["℘ Ps 143,8"] },
      { number: 5, text: "Denn du, Herr, bist gut* und zum Vergeben bereit*, groß an Gnade gegen alle, die dich anrufen*.", footnotes: ["℘ Ps 130,7; 145,9; Mk 10,18", "℘ Ps 103,3", "℘ Ps 69,14; Mt 7,11"] },
      { number: 6, text: "HERR, höre mein Gebet! Horche auf die Stimme meines Flehens*!", footnotes: ["℘ Ps 17,1"] },
      { number: 7, text: "Am Tag meiner Bedrängnis rufe ich dich an, denn du erhörst mich*.", footnotes: ["℘ Ps 50,15"] },
      { number: 8, text: "Keiner ist wie du, Herr, unter den Göttern*, und nichts gleicht deinen Werken.", footnotes: ["℘ Ps 95,3; 135,5; 5Mo 3,24; Jes 40,25; Jer 10,6"] },
      { number: 9, text: "Alle Nationen, die du gemacht hast, werden kommen und vor dir anbeten*, Herr, und deinen Namen verherrlichen.", footnotes: ["℘ Ps 22,28; Mal 1,11; Röm 15,9; Offb 15,4"] },
      { number: 10, text: "Denn groß bist du und tust Wunder*, du bist Gott, du allein*.", footnotes: ["℘ Ps 72,18; 2Mo 15,11", "℘ 5Mo 6,4; Jes 45,5"] },
      { number: 11, text: "Lehre mich, HERR, deinen Weg*: Ich will wandeln in deiner Wahrheit*! Fasse mein Herz zusammen* zur Furcht deines Namens.", footnotes: ["℘ Ps 25,4", "o. Treue\n℘ 2Jo 4", "w. Einige mein Herz"] },
      { number: 12, text: "Ich will dich preisen, Herr, mein Gott, mit meinem ganzen Herzen und deinen Namen ewig verherrlichen*.", footnotes: ["℘ Ps 9,2"] },
      { number: 13, text: "Denn deine Gnade ist groß gegen mich, und du hast meine Seele gerettet aus dem tiefsten Scheol*.", footnotes: ["℘ Ps 30,4; Jes 38,17"] },
      { number: 14, text: "Gott! Übermütige sind gegen mich aufgestanden; die Rotte der Gewalttätigen trachtet nach meinem Leben; und sie haben dich nicht vor sich gestellt*.", footnotes: ["℘ Ps 54,5"] },
      { number: 15, text: "Du aber, Herr, bist ein barmherziger und gnädiger Gott*, langsam zum Zorn und groß an Gnade und Wahrheit*.", footnotes: ["℘ Ps 111,4", "o. Treue\n℘ Ps 103,8; 145,8; 2Mo 34,6; 4Mo 14,18; Neh 9,17; Joe 2,13; Jon 4,2"] },
      { number: 16, text: "Wende dich zu mir und sei mir gnädig*! Gewähre deinem Knecht deine Kraft, rette den Sohn deiner Magd*!", footnotes: ["℘ Ps 41,5", "℘ Ps 116,16"] },
      { number: 17, text: "Wirke an mir ein Zeichen zum Guten, dass die, die mich hassen, es sehen und beschämt werden*, weil du, HERR, mir geholfen und mich getröstet hast.", footnotes: ["℘ Ps 71,21; Jes 12,1"] },
    ]},
    { number: 87, verses: [
      { number: 1, text: "Von den Söhnen Korachs*. Ein Psalm. Ein Lied. Seine Gründung ist auf den heiligen Bergen*.", heading: "Psalm 87", footnotes: ["℘ Ps 42,1", "℘ Ps 78,69; Jes 2,2"] },
      { number: 2, text: "Der HERR liebt die Tore des Zion mehr als alle Wohnungen Jakobs*.", footnotes: ["℘ Ps 78,68; Offb 20,9"] },
      { number: 3, text: "Herrliches ist über dich geredet, du Stadt Gottes*. //", footnotes: ["℘ Ps 48,2; Hes 48,35; Hebr 12,22"] },
      { number: 4, text: "Ich will Rahab* und Babel erwähnen bei denen, die mich kennen; siehe, Philistäa und Tyrus samt Kusch*. Dieser ist dort geboren.", footnotes: ["Ägypten", "Äthiopien"] },
      { number: 5, text: "Von Zion aber wird gesagt werden: Mann für Mann ist darin geboren. Und der Höchste, er wird es befestigen*.", footnotes: ["℘ Ps 48,9"] },
      { number: 6, text: "Der HERR wird schreiben beim Verzeichnen* der Völker*: Dieser ist dort geboren*. //", footnotes: ["w. beim Schreiben", "℘ Hes 13,9", "℘ Gal 4,26"] },
      { number: 7, text: "Und singend und den Reigen tanzend* werden sie sagen: Alle meine Quellen sind in dir*!", footnotes: ["℘ Ps 68,26; 149,3", "℘ Jes 12,3; Hes 47,1"] },
    ]},
    { number: 88, verses: [
      { number: 1, text: "Ein Lied. Ein Psalm. Von den Söhnen Korachs*. Dem Chorleiter. Nach Machalath* zu singen. Ein Maskil*. Von Heman, dem Esrachiter*.", heading: "Psalm 88", footnotes: ["℘ Ps 42,1", "℘ Ps 53,1", "s. Anm. zu Ps 32,1", "℘ 1Kö 5,11"] },
      { number: 2, text: "HERR, Gott meines Heils! Des Tages habe ich geschrien* und des Nachts vor dir*.", footnotes: ["℘ Ps 86,3", "℘ Ps 22,3; 119,147; Lk 18,7"] },
      { number: 3, text: "Es komme vor dich mein Gebet! Neige dein Ohr zu meinem Schreien*!", footnotes: ["℘ Ps 17,1"] },
      { number: 4, text: "Denn satt ist meine Seele vom Leiden*, und mein Leben ist nahe dem Scheol*.", footnotes: ["℘ Kla 3,15-19", "℘ Mt 26,38"] },
      { number: 5, text: "Ich bin gerechnet zu denen, die in die Grube hinabfahren*. Ich bin wie ein Mann, der keine Kraft hat,", footnotes: ["℘ Ps 28,1"] },
      { number: 6, text: "unter die Toten hingestreckt, wie Erschlagene, die im Grab liegen, derer du nicht mehr gedenkst. Denn sie sind von deiner Hand* abgeschnitten.", footnotes: ["w. von deiner rettenden, helfenden Hand weg"] },
      { number: 7, text: "Du hast mich in die tiefste Grube gelegt, in Finsternisse, in Tiefen*.", footnotes: ["℘ Ps 69,3; Jon 2,4-6"] },
      { number: 8, text: "Auf mir liegt schwer dein Zorn, und mit allen deinen Wellen hast du mich niedergedrückt*. //", footnotes: ["℘ Ps 42,8"] },
      { number: 9, text: "Meine Bekannten* hast du von mir entfernt*, hast mich ihnen zum Abscheu gemacht. Ich bin eingeschlossen und kann nicht herauskommen*.", footnotes: ["o. Vertrauten; so auch V. 19b", "℘ Ps 38,12; Mt 26,56", "℘ Kla 3,7"] },
      { number: 10, text: "Mein Auge verschmachtet vor Elend. Zu dir rufe ich, HERR, den ganzen Tag*. Ich strecke meine Hände aus zu dir*.", footnotes: ["℘ Ps 86,3", "℘ Ps 143,6"] },
      { number: 11, text: "Wirst du an den Toten Wunder tun? Oder werden die Gestorbenen aufstehen, dich preisen*? //", footnotes: ["℘ Ps 6,6; Jes 26,19"] },
      { number: 12, text: "Wird von deiner Gnade erzählt werden im Grab, im Abgrund von deiner Treue?" },
      { number: 13, text: "Werden in der Finsternis* bekannt werden deine Wunder, und deine Gerechtigkeit im Land des Vergessens*?", footnotes: ["℘ Hi 10,21.22", "℘ Pred 9,5"] },
      { number: 14, text: "Ich aber, HERR, schreie zu dir, und am Morgen möge dir mein Gebet begegnen*.", footnotes: ["℘ Ps 5,4"] },
      { number: 15, text: "Warum, HERR, verwirfst du meine Seele*, verbirgst du dein Angesicht vor mir*?", footnotes: ["℘ Ps 43,2", "℘ Ps 44,25"] },
      { number: 16, text: "Elend bin ich und todkrank von Jugend auf. Ich trage deine Schrecken*, bin verwirrt*.", footnotes: ["℘ Ps 119,120", "o. erstarrt, ratlos\n℘ Hi 30,15"] },
      { number: 17, text: "Deine Zorngluten sind über mich hingegangen, deine Schrecknisse haben mich vernichtet*.", footnotes: ["o. haben mich zum Schweigen gebracht"] },
      { number: 18, text: "Sie umgeben mich wie Wasser den ganzen Tag, sie umringen mich allesamt*.", footnotes: ["℘ Ps 118,10-12"] },
      { number: 19, text: "Du hast mir entfremdet Freund und Nachbarn*. Meine Bekannten sind Finsternis.", footnotes: ["℘ Ps 38,12; Mt 26,56"] },
    ]},
    { number: 89, verses: [
      { number: 1, text: "Ein Maskil*. Von Etan, dem Esrachiter.*", heading: "Psalm 89", footnotes: ["s. Anm. zu Ps 32,1", "℘ 1Kö 5,11"] },
      { number: 2, text: "Die Gnadenerweise des HERRN will ich ewig besingen, von Generation zu Generation mit meinem Mund deine Treue verkündigen*.", footnotes: ["℘ Ps 40,11"] },
      { number: 3, text: "Denn ich sagte: Auf ewig wird die Gnade gebaut werden. Im Himmel wirst du festgründen deine Treue." },
      { number: 4, text: "Einen Bund habe ich mit meinem Auserwählten geschlossen*, habe David, meinem Knecht, geschworen*:", footnotes: ["℘ 1Chr 28,4; Jes 42,1", "℘ V. 36.50; Ps 132,11; Apg 2,30"] },
      { number: 5, text: "»Bis in Ewigkeit will ich deiner Nachkommenschaft Bestand geben und für alle Generationen bauen deinen Thron*.« //", footnotes: ["℘ V. 30.37; Ps 61,8; 1Chr 17,11-14; Jes 9,6"] },
      { number: 6, text: "Der Himmel wird deine Wunder preisen, HERR, ja, deine Treue in der Versammlung der Heiligen." },
      { number: 7, text: "Denn wer in den Wolken ist mit dem HERRN zu vergleichen*? Wer ist dem HERRN gleich unter den Göttersöhnen*?", footnotes: ["℘ Ps 86,8; Offb 13,4", "℘ Ps 29,1"] },
      { number: 8, text: "Gott ist gefürchtet im Kreis der Heiligen, groß ist er und furchtbar über alle, die rings um ihn her sind*.", footnotes: ["℘ 5Mo 7,21"] },
      { number: 9, text: "HERR, Gott der Heerscharen! Wer ist stark wie du, Jah*? Deine Treue* ist rings um dich her.", footnotes: ["℘ Ps 113,5; Jer 32,18", "℘ Jes 11,5"] },
      { number: 10, text: "Du beherrschst des Meeres Toben*, erheben sich seine Wogen — du stillst sie*.", footnotes: ["w. Übermut", "℘ Ps 65,8"] },
      { number: 11, text: "Du hast Rahab* zertreten wie einen Erschlagenen. Mit deinem starken Arm hast du deine Feinde zerstreut*.", footnotes: ["d. h. Ägypten", "℘ Jes 51,9; Lk 1,51"] },
      { number: 12, text: "Dein ist der Himmel, und dein ist die Erde. Die Welt und ihre Fülle, du hast sie gegründet*.", footnotes: ["℘ Ps 24,1; 115,16"] },
      { number: 13, text: "Norden und Süden, du hast sie erschaffen*. Tabor und Hermon jubeln in deinem Namen*.", footnotes: ["℘ Hi 26,7", "℘ Ps 98,8; Jes 44,23"] },
      { number: 14, text: "Du hast einen gewaltigen Arm*, stark ist deine Hand*, erhoben deine Rechte*.", footnotes: ["℘ 2Mo 15,16", "℘ 2Mo 13,3", "℘ 2Mo 15,6"] },
      { number: 15, text: "Gerechtigkeit und Recht sind deines Thrones Grundfeste*. Gnade und Treue* gehen vor deinem Angesicht her.", footnotes: ["℘ Ps 97,2", "o. Wahrheit"] },
      { number: 16, text: "Glücklich ist das Volk, das den Jubelruf* kennt! HERR, im Licht deines Angesichts wandeln sie*.", footnotes: ["℘ 3Mo 25,8-13", "℘ Jes 2,5; Offb 21,24"] },
      { number: 17, text: "In deinem Namen freuen sie sich täglich*, und durch deine Gerechtigkeit* werden sie erhöht.", footnotes: ["℘ Phil 4,4", "℘ Jes 45,24.25"] },
      { number: 18, text: "Denn die Zierde ihrer Stärke bist du; und durch deine Gunst wird unser Horn erhöht*.", footnotes: ["℘ Ps 75,11; 148,14"] },
      { number: 19, text: "Denn dem HERRN gehört unser Schild* und dem Heiligen Israels unser König.", footnotes: ["℘ Ps 3,4"] },
      { number: 20, text: "Damals redetest du in einer Vision zu deinen Frommen und sagtest: Hilfe* habe ich auf einen Helden gelegt, ich habe einen Auserwählten erhöht aus dem Volk*.", footnotes: ["bei Änderung eines Buchstabens: Krone; vgl. dasselbe Wort in V. 40.", "℘ 5Mo 17,15"] },
      { number: 21, text: "Ich habe David gefunden*, meinen Knecht. Mit meinem heiligen Öl habe ich ihn gesalbt*.", footnotes: ["℘ Apg 13,22", "℘ 1Sam 16,13"] },
      { number: 22, text: "Meine Hand soll beständig mit ihm sein, und mein Arm soll ihn stärken." },
      { number: 23, text: "Kein Feind soll ihn bedrängen und kein Sohn der Ungerechtigkeit ihn bedrücken." },
      { number: 24, text: "Ich will seine Bedränger vor ihm zerschmettern. Die ihn hassen, will ich niederstoßen." },
      { number: 25, text: "Meine Treue und meine Gnade sollen mit ihm sein, und durch meinen Namen soll sein Horn erhöht werden*.", footnotes: ["℘ Ps 132,17; 1Sam 2,10"] },
      { number: 26, text: "Ich will seine Hand auf das Meer legen, und seine Rechte auf die Ströme*.", footnotes: ["℘ Sach 9,10"] },
      { number: 27, text: "Er wird mich anrufen: Mein Vater* bist du, mein Gott und der Fels meines Heils*!", footnotes: ["℘ 2Sam 7,14; Hebr 1,5", "℘ Ps 71,3"] },
      { number: 28, text: "So will auch ich ihn zum Erstgeborenen* machen, zum Höchsten unter den Königen der Erde*.", footnotes: ["℘ Kol 1,15.18; Hebr 1,6", "℘ Offb 1,5; 19,16"] },
      { number: 29, text: "Ewig will ich ihm meine Gnade bewahren, und mein Bund soll ihm festbleiben*.", footnotes: ["℘ 2Sam 23,5; Jes 55,3"] },
      { number: 30, text: "Und ich will seine Nachkommen einsetzen für immer* und seinen Thron wie die Tage des Himmels*.", footnotes: ["℘ V. 5; Jer 33,17", "℘ 5Mo 11,21"] },
      { number: 31, text: "Wenn seine Söhne mein Gesetz verlassen* und nicht wandeln in meinen Rechtsbestimmungen,", footnotes: ["℘ Jos 24,20"] },
      { number: 32, text: "wenn sie meine Ordnungen entweihen und meine Gebote nicht halten*,", footnotes: ["℘ 1Kö 9,6; Neh 1,7"] },
      { number: 33, text: "so werde ich ihr Vergehen mit der Rute und ihre Ungerechtigkeit mit Schlägen heimsuchen*.", footnotes: ["℘ 2Sam 7,14"] },
      { number: 34, text: "Aber meine Gnade werde ich nicht von ihm weichen lassen* und nicht verleugnen meine Treue*.", footnotes: ["℘ Ps 18,51", "℘ 2Sam 7,15; 2Tim 2,13"] },
      { number: 35, text: "Ich werde meinen Bund nicht entweihen und nicht ändern, was hervorgegangen ist aus meinen Lippen*.", footnotes: ["℘ 4Mo 23,19"] },
      { number: 36, text: "Einmal habe ich geschworen* bei meiner Heiligkeit* — *wie könnte ich David täuschen!* —.", footnotes: ["℘ V. 4", "℘ Am 4,2", "w. Wenn ich dem David lüge, dann . . .!; hebr. Schwurformel, deren zweite Hälfte nicht ausgesprochen wurde", "w. Wenn ich dem David lüge, dann . . .!; hebr. Schwurformel, deren zweite Hälfte nicht ausgesprochen wurde"] },
      { number: 37, text: "»Seine Nachkommenschaft soll ewig sein und sein Thron wie die Sonne vor mir*.", footnotes: ["℘ V. 5"] },
      { number: 38, text: "Wie der Mond wird er ewig fest stehen. Der Zeuge in den Wolken ist treu.« //" },
      { number: 39, text: "Du aber hast verworfen* und verstoßen, bist sehr zornig gewesen* gegen deinen Gesalbten.", footnotes: ["℘ Ps 44,10", "℘ Ps 60,3"] },
      { number: 40, text: "Preisgegeben hast du den Bund mit deinem Knecht, hast zu Boden geworfen und entweiht seine Krone*.", footnotes: ["℘ Hes 21,31"] },
      { number: 41, text: "Du hast niedergerissen all seine Mauern, hast seine Burgen in Trümmer gelegt*.", footnotes: ["℘ Jes 5,5"] },
      { number: 42, text: "Es haben ihn alle ausgeplündert, die des Weges vorübergehen*. Er ist zum Hohn geworden seinen Nachbarn.", footnotes: ["℘ Ps 80,13"] },
      { number: 43, text: "Du hast erhöht die Rechte seiner Bedränger, hast erfreut alle seine Feinde*.", footnotes: ["℘ Kla 2,17"] },
      { number: 44, text: "Auch hast du zurückweichen lassen die Schärfe seines Schwertes und hast ihn nicht bestehen lassen im Kampf." },
      { number: 45, text: "Du hast aufhören lassen seinen Glanz und zur Erde gestürzt seinen Thron*.", footnotes: ["℘ Kla 2,1.2"] },
      { number: 46, text: "Du hast verkürzt die Tage seiner Jugend*, mit Schmach hast du ihn bedeckt*. //", footnotes: ["℘ Ps 102,24", "℘ Jer 51,51"] },
      { number: 47, text: "Bis wann, HERR, willst du dich immerfort verbergen, soll wie Feuer brennen dein Zorn*?", footnotes: ["℘ Ps 79,5"] },
      { number: 48, text: "*Gedenke meiner, wie kurz meine Lebensdauer ist,* zu welcher Nichtigkeit du alle Menschenkinder erschaffen hast*!", footnotes: ["Mas. T.: Gedenke! — Ich. — Was ist Lebensdauer?", "Mas. T.: Gedenke! — Ich. — Was ist Lebensdauer?", "℘ Ps 39,6; 119,84"] },
      { number: 49, text: "Welcher Mann lebt und wird den Tod nicht sehen*, wird sein Leben befreien von der Gewalt des Scheols*? //", footnotes: ["℘ Röm 5,12", "℘ Ps 49,8.10"] },
      { number: 50, text: "Wo sind deine früheren Gnaden, Herr, die du David zugeschworen hast in deiner Treue*?", footnotes: ["℘ V. 4"] },
      { number: 51, text: "Gedenke, Herr, der Schmach deiner Knechte. In meiner Brust* trage ich all die vielen Völker* mit ihrem Hohn,", footnotes: ["w. Gewandbausch (Falte des Obergewands in der Brustgegend, die man als Tasche benutzte)", "℘ Dan 9,16"] },
      { number: 52, text: "womit deine Feinde gehöhnt haben*, HERR, womit sie gehöhnt haben die Fußspuren deines Gesalbten*!", footnotes: ["℘ Ps 31,12; 79,12", "℘ Ps 69,8"] },
      { number: 53, text: "Gepriesen sei der HERR ewig! Amen, ja Amen*!", footnotes: ["℘ Ps 41,14; Offb 7,12"] },
    ]},
    { number: 90, verses: [
      { number: 1, text: "VIERTES BUCH Ein Gebet von Mose, dem Mann Gottes*. Herr, du bist unsere Wohnung* gewesen* von Generation zu Generation.", heading: "Psalm 90", footnotes: ["℘ 5Mo 33,1", "o. Zufluchtsort", "℘ 5Mo 33,27"] },
      { number: 2, text: "Ehe die Berge geboren waren* und du die Erde und die Welt erschaffen* hattest, von Ewigkeit zu Ewigkeit bist du, Gott*.", footnotes: ["℘ Spr 8,25", "w. geboren", "℘ Ps 48,15; 93,2; 102,13; Hab 1,12; 1Tim 6,16"] },
      { number: 3, text: "Du lässt den Menschen zum Staub* zurückkehren und sprichst: Kehrt zurück, ihr Menschenkinder*!", footnotes: ["w. zur Zermalmung", "℘ Ps 104,29; 146,4; 1Mo 3,19; Hi 34,14.15; Pred 12,7"] },
      { number: 4, text: "Denn tausend Jahre sind in deinen Augen wie der gestrige Tag, wenn er vergangen ist, und wie eine Wache in der Nacht*.", footnotes: ["℘ 2Petr 3,8"] },
      { number: 5, text: "Du schwemmst sie hinweg, sie sind wie ein Schlaf, sie sind am Morgen wie Gras*, das aufsprosst*.", footnotes: ["℘ Ps 103,15", "In der ersten Vershälfte ist der Mas. T. sehr schwierig. Geringe Eingriffe lassen auch folgende Üs. zu: Du säst sie aus Jahr um Jahr; sie sind am Morgen wie Gras, das aufsprosst."] },
      { number: 6, text: "Am Morgen blüht es und sprosst auf. Am Abend welkt es und verdorrt*.", footnotes: ["℘ Ps 102,12; Hi 14,2; Jes 40,6-8"] },
      { number: 7, text: "Denn wir vergehen durch deinen Zorn, und durch deinen Grimm werden wir verstört*.", footnotes: ["w. bestürzt, erschreckt\n℘ Ps 78,33; Hab 3,12"] },
      { number: 8, text: "Du hast unsere Ungerechtigkeiten vor dich gestellt, unser verborgenes Tun vor das Licht deines Angesichts*.", footnotes: ["℘ Ps 109,15; Jer 16,17; 1Kor 4,5; Hebr 4,13"] },
      { number: 9, text: "Denn alle unsere Tage schwinden durch deinen Grimm. Wir bringen unsere Jahre zu wie einen Seufzer*.", footnotes: ["℘ Ps 35,5.6; Jak 4,14"] },
      { number: 10, text: "Die Tage unserer Jahre sind siebzig Jahre, und, wenn in Kraft, achtzig Jahre, und ihr Stolz ist Mühe und Nichtigkeit, denn schnell eilt es vorüber, und wir fliegen dahin*.", footnotes: ["℘ Hi 5,7"] },
      { number: 11, text: "Wer erkennt die Stärke deines Zorns und deines Grimms, wie es der Furcht vor dir entspricht?" },
      { number: 12, text: "So lehre uns denn zählen unsere Tage, damit wir ein weises Herz erlangen*!", footnotes: ["℘ Ps 39,5.6"] },
      { number: 13, text: "Kehre wieder, HERR*! — Bis wann*? Erbarme dich deiner Knechte!", footnotes: ["℘ Ps 80,15; 4Mo 10,36", "℘ Ps 6,4.5; 5Mo 32,36"] },
      { number: 14, text: "Sättige uns am Morgen mit deiner Gnade*, so werden wir jubeln und uns freuen in allen unseren Tagen.", footnotes: ["℘ Ps 143,8"] },
      { number: 15, text: "Erfreue uns so viele Tage, wie du uns gebeugt hast, so viele Jahre, wie wir Übles gesehen haben!" },
      { number: 16, text: "Lass an deinen Knechten sichtbar werden dein Tun und deine Majestät über ihren Söhnen." },
      { number: 17, text: "Die Freundlichkeit des Herrn, unseres Gottes, sei über uns und festige über uns das Werk unserer Hände! Ja, das Werk unserer Hände, festige du es*!", footnotes: ["℘ Jes 26,12"] },
    ]},
    { number: 91, verses: [
      { number: 1, text: "Wer im Schutz* des Höchsten wohnt, bleibt im Schatten des Allmächtigen*.", heading: "Psalm 91", footnotes: ["w. Versteck", "℘ Jes 25,4"] },
      { number: 2, text: "Ich sage* zum HERRN: Meine Zuflucht* und meine Burg*, mein Gott, ich vertraue auf ihn!", footnotes: ["LXX: Der sage", "℘ Ps 61,5; 142,6", "℘ Ps 18,3; 25,2; 31,15"] },
      { number: 3, text: "Denn er rettet dich von der Schlinge des Vogelstellers, von der verderblichen Pest*.", footnotes: ["℘ Ps 68,21; 124,7"] },
      { number: 4, text: "Mit seinen Schwingen deckt er dich, und du findest Zuflucht unter seinen Flügeln*. Schild und Schutzwehr ist seine Treue*.", footnotes: ["℘ Ps 17,8", "o. Wahrheit\n℘ Ps 35,2"] },
      { number: 5, text: "Du fürchtest dich nicht vor dem Schrecken der Nacht*, vor dem Pfeil, der am Tag fliegt,", footnotes: ["℘ Spr 3,24.25"] },
      { number: 6, text: "vor der Pest, die im Finstern umgeht, vor der Seuche, die am Mittag verwüstet." },
      { number: 7, text: "Tausend fallen an deiner Seite, zehntausend an deiner Rechten — dich erreicht es nicht*.", footnotes: ["℘ Jer 39,18"] },
      { number: 8, text: "Nur schaust du es mit deinen Augen, und du siehst die Vergeltung an den Gottlosen*.", footnotes: ["℘ Ps 37,34"] },
      { number: 9, text: "Denn du hast gesagt: »Der HERR ist meine Zuflucht!«; du hast den Höchsten zu deiner Wohnung gesetzt;" },
      { number: 10, text: "so begegnet dir kein Unglück, und keine Plage naht deinem Zelt*.", footnotes: ["℘ 5Mo 7,15"] },
      { number: 11, text: "Denn er bietet seine Engel für dich auf, dich zu bewahren auf allen deinen Wegen*.", footnotes: ["℘ Hebr 1,14"] },
      { number: 12, text: "Auf den Händen tragen sie dich, damit du deinen Fuß nicht an einen Stein stößt*.", footnotes: ["℘ Spr 3,23; Mt 4,6"] },
      { number: 13, text: "Auf Löwen und Vipern trittst du, Junglöwen und Schlangen trittst du nieder*.", footnotes: ["℘ Lk 10,19"] },
      { number: 14, text: "»Weil er an mir hängt, will ich ihn retten. Ich will ihn schützen, weil er meinen Namen kennt*.", footnotes: ["℘ Ps 9,11"] },
      { number: 15, text: "Er ruft mich an*, und ich antworte ihm*. Ich bin bei ihm in der Not.* Ich befreie ihn und bringe ihn zu Ehren.", footnotes: ["℘ Ps 50,15", "℘ Jer 33,3", "℘ Jes 43,2"] },
      { number: 16, text: "Ich sättige ihn mit langem Leben* und lasse ihn mein Heil schauen*.«", footnotes: ["w. Länge der Tage\n℘ Spr 10,27", "℘ Ps 50,23"] },
    ]},
    { number: 92, verses: [
      { number: 1, text: "Ein Psalm. Ein Lied. Für den Tag des Sabbats.", heading: "Psalm 92" },
      { number: 2, text: "Es ist gut, den HERRN zu preisen und deinen Namen*, du Höchster, zu besingen*;", footnotes: ["℘ Ps 101,1; 147,1; Hebr 13,15", "℘ Ps 9,3"] },
      { number: 3, text: "am Morgen zu verkünden deine Gnade und deine Treue in den Nächten*", footnotes: ["℘ Ps 42,9"] },
      { number: 4, text: "zur zehnsaitigen Laute und zur Harfe, zum klingenden Spiel auf der Zither*.", footnotes: ["℘ Ps 33,2"] },
      { number: 5, text: "Denn du hast mich erfreut, HERR, durch dein Tun. Über die Werke deiner Hände juble ich." },
      { number: 6, text: "Wie groß sind deine Werke, HERR*! Sehr tief sind deine Gedanken*.", footnotes: ["℘ Ps 104,24; 139,14; Offb 15,3", "℘ Jes 55,9; Röm 11,33"] },
      { number: 7, text: "Ein unvernünftiger Mensch erkennt es nicht, und ein Tor versteht dies nicht*.", footnotes: ["℘ Ps 73,22"] },
      { number: 8, text: "Wenn die Gottlosen sprossen wie Gras* und alle Übeltäter blühen, dann nur, damit sie vertilgt werden für immer*.", footnotes: ["w. Kraut", "℘ Ps 37,2; 73,17-19"] },
      { number: 9, text: "Du aber bist ewig erhaben, HERR*!", footnotes: ["℘ Ps 97,9; 102,13"] },
      { number: 10, text: "Denn siehe, deine Feinde, HERR, denn siehe, deine Feinde werden umkommen*. Es werden zerstreut werden* alle Übeltäter.*", footnotes: ["℘ Ri 5,31", "℘ Ps 18,15", "℘ Ps 101,8; 125,5"] },
      { number: 11, text: "Aber du wirst mein Horn erhöhen* wie das eines Büffels. Mit frischem Öl *hast du mich überschüttet*.", footnotes: ["℘ Ps 75,11; 112,9", "so mit syr. und aram. Handschr.; Mas. T.: übergieße ich", "so mit syr. und aram. Handschr.; Mas. T.: übergieße ich\n℘ Ps 23,5"] },
      { number: 12, text: "Und mein Auge wird seine Lust sehen an meinen Feinden. Meine Ohren werden ihre Lust hören an den Übeltätern, die gegen mich aufstehen*.", footnotes: ["℘ Ps 37,34"] },
      { number: 13, text: "Der Gerechte wird sprossen wie die Palme, wie eine Zeder auf dem Libanon wird er emporwachsen*.", footnotes: ["℘ Hos 14,5.6"] },
      { number: 14, text: "Die gepflanzt sind im Haus des HERRN*, werden grünen in den Vorhöfen unseres Gottes.", footnotes: ["℘ Ps 52,10"] },
      { number: 15, text: "Noch im Greisenalter gedeihen sie, sind sie saftvoll und grün*,", footnotes: ["℘ Ps 1,3"] },
      { number: 16, text: "um zu verkünden, dass der HERR gerecht ist. Er ist mein Fels, und kein Unrecht ist an ihm*.", footnotes: ["℘ 5Mo 32,4; Hi 34,10; Zef 3,5"] },
    ]},
    { number: 93, verses: [
      { number: 1, text: "Der HERR ist König*! Er hat sich bekleidet mit Hoheit! Der HERR hat sich bekleidet*, mit Stärke hat er sich umgürtet*! Ja, fest steht die Welt, sie wird nicht wanken*.", heading: "Psalm 93", footnotes: ["℘ Ps 97,1; 99,1", "℘ Ps 104,1", "℘ Ps 65,7", "℘ Ps 96,10"] },
      { number: 2, text: "Dein Thron steht fest von alters her*, von Ewigkeit her bist du*.", footnotes: ["℘ Ps 55,20", "℘ Ps 90,2"] },
      { number: 3, text: "Ströme erhoben, HERR, Ströme erhoben ihr Tosen, Ströme erheben ihr Brausen*.", footnotes: ["℘ Ps 46,3"] },
      { number: 4, text: "Mächtiger als das Tosen gewaltiger Wasser, wuchtiger Brecher des Meeres*, mächtiger ist der HERR in der Höhe.", footnotes: ["℘ Ps 29,4; Mt 8,27"] },
      { number: 5, text: "Deine Zeugnisse sind sehr zuverlässig*. Deinem Haus geziemt Heiligkeit*, HERR, für alle Zeiten*.", footnotes: ["℘ Ps 19,8; Tit 1,9", "℘ 3Mo 10,3", "w. für die Länge der Tage"] },
    ]},
    { number: 94, verses: [
      { number: 1, text: "Gott der Rache*, HERR, Gott der Rache*, strahle hervor*!", heading: "Psalm 94", footnotes: ["w. der Rachetaten\n℘ 5Mo 32,35; Jer 51,6; Nah 1,2", "w. der Rachetaten\n℘ Kla 2,17", "℘ Ps 50,2"] },
      { number: 2, text: "Erhebe dich, Richter der Erde*, vergilt den Hochmütigen ihr Tun*!", footnotes: ["℘ Ps 82,8", "℘ Hi 40,11; Jes 2,12"] },
      { number: 3, text: "Bis wann werden die Gottlosen, HERR, bis wann werden die Gottlosen jubeln," },
      { number: 4, text: "übersprudeln, Freches reden*, werden sich rühmen alle Übeltäter*?", footnotes: ["℘ 1Sam 2,3", "℘ Ps 125,5; Hi 20,5"] },
      { number: 5, text: "Dein Volk, HERR, zertreten sie, dein Eigentum* bedrücken sie.", footnotes: ["o. Erbteil; o. Erbe"] },
      { number: 6, text: "Die Witwe und den Fremden bringen sie um, die Waisen ermorden sie*.", footnotes: ["℘ Jes 10,2; Hes 22,7"] },
      { number: 7, text: "Sie sagen: Jah sieht es nicht! Der Gott Jakobs merkt es nicht*!", footnotes: ["℘ Ps 10,11"] },
      { number: 8, text: "Habt Einsicht, ihr Unvernünftigen unter dem Volk! Ihr Toren, wann werdet ihr verständig werden*?", footnotes: ["℘ Spr 1,22"] },
      { number: 9, text: "Der das Ohr gestaltet* hat, sollte der nicht hören? Der das Auge gebildet hat, sollte der nicht sehen*?", footnotes: ["w. gepflanzt", "℘ Ps 34,16; Spr 20,12"] },
      { number: 10, text: "Der die Nationen unterweist*, sollte der nicht zurechtweisen? — er, der Erkenntnis lehrt den Menschen*?", footnotes: ["℘ Hes 39,21", "℘ Hi 28,28; Spr 2,6; 2Tim 2,7"] },
      { number: 11, text: "Der HERR kennt die Gedanken des Menschen*, dass sie ein Hauch* sind*.", footnotes: ["℘ Ps 44,22; Joh 2,24.25", "o. Nichtigkeit", "℘ 1Kor 3,20"] },
      { number: 12, text: "Glücklich der Mann, den du züchtigst*, Jah, den du belehrst aus deinem Gesetz*,", footnotes: ["℘ Hi 5,17", "℘ Ps 119,71"] },
      { number: 13, text: "um ihm Ruhe zu geben vor den bösen Tagen*, bis dem Gottlosen die Grube gegraben wird!", footnotes: ["℘ Jes 26,20"] },
      { number: 14, text: "Denn der HERR wird sein Volk nicht verstoßen, er wird sein Eigentum nicht verlassen*.", footnotes: ["℘ Ps 74,2; 1Sam 12,22; Röm 11,1.2"] },
      { number: 15, text: "Denn zur Gerechtigkeit wird zurückkehren das Recht* und hinter ihm her alle, die von Herzen aufrichtig sind*.", footnotes: ["o. Gericht", "℘ Ps 58,12"] },
      { number: 16, text: "Wer wird für mich aufstehen gegen die Übeltäter*? Wer wird für mich auftreten gegen die, die Böses tun?", footnotes: ["℘ Ps 118,6.7"] },
      { number: 17, text: "Wäre der HERR mir nicht eine Hilfe gewesen, so hätte wenig gefehlt, und meine Seele hätte im Schweigen* gelegen.", footnotes: ["»Schweigen« bezeichnet hier die Unterwelt, das Totenreich."] },
      { number: 18, text: "Wenn ich sagte: Mein Fuß wankt!, so unterstützte mich deine Gnade, HERR*.", footnotes: ["℘ Ps 37,24"] },
      { number: 19, text: "Als viele unruhige Gedanken in mir waren, beglückten* deine Tröstungen meine Seele*.", footnotes: ["eigentlich: liebkosten", "℘ Kla 3,20-24"] },
      { number: 20, text: "Sollte mit dir verbündet sein der Thron des Verderbens, der Unheil schafft gegen die Ordnung*?", footnotes: ["℘ Spr 28,9"] },
      { number: 21, text: "Sie rotten sich gegen die Seele des Gerechten zusammen, und unschuldiges Blut sprechen sie schuldig*.", footnotes: ["℘ 2Mo 23,7; Mt 27,24.26; Jak 5,6"] },
      { number: 22, text: "Doch der HERR wurde mir zur Burg, mein Gott zum Fels meiner Zuflucht*.", footnotes: ["℘ Ps 62,8"] },
      { number: 23, text: "Er lässt ihre Ungerechtigkeit auf sie zurückfallen*, und in ihrer Bosheit wird er sie zum Schweigen bringen*. Zum Schweigen bringen wird sie der HERR, unser Gott*.", footnotes: ["w. zurückkehren", "o. vernichten", "℘ Spr 5,23"] },
    ]},
    { number: 95, verses: [
      { number: 1, text: "Kommt, lasst uns dem HERRN zujubeln, lasst uns zujauchzen dem Fels unseres Heils*!", heading: "Psalm 95", footnotes: ["℘ Ps 18,47"] },
      { number: 2, text: "Lasst uns vor sein Angesicht treten mit Dank! Lasst uns mit Psalmen ihm zujauchzen*!", footnotes: ["℘ Ps 100,2.4"] },
      { number: 3, text: "Denn ein großer Gott ist der HERR*, ein großer König* über alle Götter*.", footnotes: ["℘ Ps 104,1; 5Mo 7,21; Neh 8,6", "℘ Ps 47,3", "℘ Ps 86,8; 96,4; 97,9"] },
      { number: 4, text: "In seiner Hand sind die Tiefen der Erde*, und die Höhen der Berge sind auch sein.", footnotes: ["℘ Ps 71,20"] },
      { number: 5, text: "Sein ist das Meer; er hat es ja gemacht, und das Trockene, seine Hände haben es gebildet*.", footnotes: ["℘ 1Mo 1,9.10; Jon 1,9; Apg 4,24; Offb 14,7"] },
      { number: 6, text: "Kommt, lasst uns anbeten und uns neigen, lasst uns niederknien vor dem HERRN*, der uns gemacht hat*!", footnotes: ["℘ Eph 3,14", "℘ Ps 100,3; 119,73; 139,13; Jes 44,2; 64,8"] },
      { number: 7, text: "Denn er ist unser Gott*, und wir sind das Volk seiner Weide und die Herde seiner Hand*. *Heute, wenn ihr seine Stimme hört,", footnotes: ["℘ Ps 48,15", "℘ Ps 74,1", "℘ V. 7-11: Hebr 3,7-11"] },
      { number: 8, text: "verhärtet euer Herz nicht, wie zu Meriba, wie am Tag von Massa in der Wüste," },
      { number: 9, text: "wo eure Väter mich versuchten*, mich auf die Probe stellten, obwohl sie mein Werk gesehen hatten.", footnotes: ["℘ 5Mo 6,16"] },
      { number: 10, text: "Vierzig Jahre empfand ich Ekel vor diesem Geschlecht*, und ich sprach: Ein Volk irrenden Herzens sind sie*, und sie haben meine Wege nicht erkannt*.", footnotes: ["o. dieser Generation\n℘ Lk 11,29", "℘ Mt 22,29", "℘ Hi 21,14"] },
      { number: 11, text: "Darum schwor ich in meinem Zorn: *Sie sollen nicht in meine Ruhe eingehen*.", footnotes: ["w. Wenn sie in meine Ruhe eingehen, dann . . .!; hebr. Schwurformel, deren zweite Hälfte nicht ausgesprochen wurde", "w. Wenn sie in meine Ruhe eingehen, dann . . .!; hebr. Schwurformel, deren zweite Hälfte nicht ausgesprochen wurde"] },
    ]},
    { number: 96, verses: [
      { number: 1, text: "Singt dem HERRN ein neues Lied*, singe dem HERRN, ganze Erde*!", heading: "Psalm 961", footnotes: ["℘ Ps 33,3", "℘ Ps 66,4"] },
      { number: 2, text: "Singt dem HERRN, preist seinen Namen*, verkündet von Tag zu Tag sein Heil!", footnotes: ["℘ Ps 145,1.2"] },
      { number: 3, text: "Erzählt unter den Nationen seine Herrlichkeit, unter allen Völkern seine Wundertaten*!", footnotes: ["℘ Ps 9,2.12; 105,1"] },
      { number: 4, text: "Denn groß ist der HERR und sehr zu loben*, furchtbar ist er über allen Göttern*.", footnotes: ["℘ Ps 145,3; 150,2", "℘ Ps 95,3; Dan 2,47"] },
      { number: 5, text: "Denn alle Götter der Völker sind Götzen*, der HERR aber hat den Himmel gemacht*.", footnotes: ["Das sehr verächtliche hebr. Wort bedeutet eigentlich »Nichtse«, so auch Ps 97,7.", "℘ Ps 8,4; Jes 42,5"] },
      { number: 6, text: "Majestät und Pracht sind vor seinem Angesicht, Stärke und Herrlichkeit in seinem Heiligtum*.", footnotes: ["℘ Ps 63,3"] },
      { number: 7, text: "Gebt dem HERRN, ihr Völkerstämme, gebt dem HERRN Ehre* und Macht*!", footnotes: ["o. Herrlichkeit", "℘ Ps 29,1"] },
      { number: 8, text: "Gebt dem HERRN die Ehre* seines Namens! Bringt Opfer* und kommt in seine Vorhöfe*!", footnotes: ["o. Herrlichkeit", "℘ Mal 1,11", "℘ Ps 100,4; 116,19"] },
      { number: 9, text: "Betet an den HERRN in heiliger Pracht*! Erzittere vor ihm, ganze Erde*!", footnotes: ["s. Anm. zu Ps 29,2\n℘ Ps 29,2", "℘ Ps 99,1"] },
      { number: 10, text: "Sagt unter den Nationen: Der HERR ist König*! Ja, fest steht die Welt, sie wird nicht wanken*. Er wird die Völker richten in Geradheit*.", footnotes: ["℘ Jes 52,7; Offb 19,6", "℘ Ps 93,1", "℘ Ps 7,9"] },
      { number: 11, text: "Es freue sich der Himmel, und es jauchze die Erde*! Es brause das Meer und seine Fülle*!", footnotes: ["℘ Ps 97,1", "℘ Ps 98,7; 1Chr 16,32"] },
      { number: 12, text: "Es frohlockt das Feld und alles, was darauf ist! Auch alle Bäume im Wald sollen jubeln*", footnotes: ["℘ Jes 49,13; 55,12"] },
      { number: 13, text: "vor dem HERRN! Denn er kommt, denn er kommt*, die Erde zu richten*. Er wird die Welt richten in Gerechtigkeit* und die Völker in seiner Wahrheit*.", footnotes: ["℘ Ps 50,3", "℘ Jes 2,4", "℘ Apg 17,31; Offb 19,11", "o. Treue\n℘ Ps 7,9"] },
    ]},
    { number: 97, verses: [
      { number: 1, text: "Der HERR ist König*! Es jauchze die Erde*! Es sollen sich freuen die vielen Inseln*!", heading: "Psalm 97", footnotes: ["℘ Ps 93,1", "℘ Ps 96,11", "℘ Jes 60,9"] },
      { number: 2, text: "Gewölk und Dunkel sind um ihn her*. Gerechtigkeit und Recht sind die Grundfeste seines Thrones*.", footnotes: ["℘ 1Kö 8,10-12", "℘ Ps 89,15"] },
      { number: 3, text: "Feuer geht vor ihm her* und verzehrt seine Bedränger ringsum.", footnotes: ["℘ Ps 18,9; 2Thes 1,8"] },
      { number: 4, text: "Seine Blitze erleuchten die Welt*. Die Erde sah es und bebte*.", footnotes: ["℘ Hi 37,3.4", "℘ Ps 77,19"] },
      { number: 5, text: "Die Berge zerschmolzen wie Wachs vor dem HERRN, vor dem Herrn der ganzen Erde*.", footnotes: ["℘ Ps 75,4; Ri 5,5; Mi 1,4; Hab 3,6"] },
      { number: 6, text: "Der Himmel verkündete seine Gerechtigkeit*, und alle Völker sahen seine Herrlichkeit*.", footnotes: ["℘ Ps 50,6", "℘ Jes 40,5"] },
      { number: 7, text: "Schämen müssen sich alle Verehrer eines Götterbildes*, die sich der Götzen* rühmen. Fallt vor ihm nieder, alle Götter*!", footnotes: ["℘ Jes 42,7; 44,9.11; 45,16", "Das sehr verächtliche hebr. Wort bedeutet eigentlich »Nichtse«, so auch Ps 97,7.", "℘ 1Sam 5,3; Hebr 1,6"] },
      { number: 8, text: "Zion hörte es und freute sich, und es jauchzten die Töchter Judas wegen deiner Gerichte, HERR*.", footnotes: ["℘ Ps 48,12"] },
      { number: 9, text: "Denn du, HERR, bist der Höchste über die ganze Erde*. Du bist sehr erhaben über alle Götter*.", footnotes: ["℘ Ps 83,19", "℘ Ps 92,9; 95,3; 136,2; 2Mo 18,11"] },
      { number: 10, text: "Die ihr den HERRN liebt, hasst das Böse*! Er bewahrt die Seelen seiner Frommen*. Aus der Hand der Gottlosen errettet er sie.", footnotes: ["℘ Spr 8,13; Am 5,14.15; 2Tim 2,19", "℘ Ps 121,7"] },
      { number: 11, text: "Licht ist dem Gerechten* gesät* und Freude den von Herzen Aufrichtigen*.", footnotes: ["℘ Ps 112,4; Spr 4,18; Jes 58,8", "Viele alte Üs. lesen: Licht strahlt dem Gerechten auf", "℘ Ps 68,4"] },
      { number: 12, text: "Freut euch, ihr Gerechten, im HERRN*, und preist* seinen heiligen Namen*!", footnotes: ["℘ Ps 32,11", "o. bekennt", "w. zu seiner heiligen Namensanrufung\n℘ Ps 30,5"] },
    ]},
    { number: 98, verses: [
      { number: 1, text: "Ein Psalm. Singt dem HERRN ein neues Lied*, denn er hat Wunder getan*! Ihm half seine Rechte* und sein heiliger Arm*.", heading: "Psalm 98", footnotes: ["℘ Ps 33,3", "℘ Ps 72,18", "℘ 2Mo 15,6", "℘ Ps 89,14"] },
      { number: 2, text: "Der HERR hat kundgetan sein Heil*, vor den Augen der Nationen offenbart seine Gerechtigkeit*.", footnotes: ["℘ Jes 52,7; Lk 3,6", "℘ Röm 3,21; Offb 15,4"] },
      { number: 3, text: "Er hat seiner Gnade und seiner Treue für das Haus Israel gedacht*. Alle Enden der Erde haben das Heil unseres Gottes gesehen*.", footnotes: ["℘ Lk 1,54; Röm 15,8", "℘ Jes 52,7; Lk 3,6"] },
      { number: 4, text: "Jauchzt dem HERRN, alle Welt*! Seid fröhlich und jauchzt und spielt*!", footnotes: ["℘ Ps 66,1", "℘ Ps 95,2"] },
      { number: 5, text: "Singt dem HERRN zur Zither*, mit der Zither und der Stimme des Gesangs*!", footnotes: ["℘ Ps 147,7", "℘ Ps 71,22"] },
      { number: 6, text: "Mit Trompeten und dem Schall des Horns jauchzt vor dem König, dem HERRN!" },
      { number: 7, text: "Es brause das Meer und seine Fülle*, die Welt und die darauf wohnen!", footnotes: ["℘ Ps 96,11"] },
      { number: 8, text: "Die Ströme sollen in die Hände klatschen, alle Berge zusammen sollen jubeln*", footnotes: ["℘ Ps 65,13; 89,13"] },
      { number: 9, text: "vor dem HERRN! Denn er kommt, die Erde zu richten*. Er wird die Welt richten in Gerechtigkeit und die Völker in Geradheit.", footnotes: ["℘ Ps 9,9; 96,13"] },
    ]},
    { number: 99, verses: [
      { number: 1, text: "Der HERR ist König*! Es zittern die Völker*. Er thront auf den Cherubim*. Es wankt die Erde*.", heading: "Psalm 99", footnotes: ["℘ Ps 93,1", "℘ Ps 96,9", "℘ Ps 80,2; 2Mo 25,22; 2Sam 6,2", "℘ Ps 82,5"] },
      { number: 2, text: "Groß ist der HERR in Zion*, und hoch ist er über alle Völker*.", footnotes: ["℘ Jes 12,6", "℘ Ps 47,3"] },
      { number: 3, text: "Preisen sollen sie deinen Namen*, den großen und furchtbaren — heilig ist er*! —", footnotes: ["℘ Neh 9,5", "℘ Ps 103,1; 111,9; Offb 15,4"] },
      { number: 4, text: "und die Stärke des Königs, der das Recht liebt*! Du hast die Rechtsordnung begründet und hast Recht und Gerechtigkeit in Jakob geschaffen.", footnotes: ["℘ Hi 37,23; Jer 23,5"] },
      { number: 5, text: "Erhebt den HERRN, unseren Gott, und fallt nieder vor dem Schemel seiner Füße*! Heilig ist er.", footnotes: ["℘ Ps 132,7; Mt 5,35"] },
      { number: 6, text: "Mose und Aaron unter seinen Priestern*, und Samuel unter denen, die seinen Namen anriefen, sie riefen zu dem HERRN, und er antwortete ihnen*.", footnotes: ["℘ 4Mo 16,22", "℘ 1Sam 7,9"] },
      { number: 7, text: "In der Wolkensäule redete er zu ihnen*. Sie bewahrten seine Zeugnisse und die Ordnung, die er ihnen gegeben hatte.", footnotes: ["℘ 2Mo 33,9"] },
      { number: 8, text: "HERR, unser Gott, du hast ihnen geantwortet! Ein vergebender Gott warst du ihnen*, doch auch ein Rächer ihrer Taten*.", footnotes: ["℘ Ps 78,38", "℘ 4Mo 20,12"] },
      { number: 9, text: "Erhebt den HERRN, unseren Gott, und fallt nieder* an seinem heiligen Berg*! Denn heilig ist der HERR, unser Gott*.", footnotes: ["℘ Ps 132,7; Mt 5,35", "℘ Ps 48,2", "℘ Jes 6,3; Offb 4,8"] },
    ]},
    { number: 100, verses: [
      { number: 1, text: "Ein Psalm. Zum Dankopfer. Jauchzt dem HERRN, alle Welt*!", heading: "Psalm 100", footnotes: ["℘ Ps 66,1"] },
      { number: 2, text: "Dient dem HERRN mit Freuden*! Kommt vor sein Angesicht mit Jubel!", footnotes: ["℘ 5Mo 28,47"] },
      { number: 3, text: "Erkennt, dass der HERR Gott ist*! Er hat uns gemacht* und nicht wir selbst — sein Volk und die Herde seiner Weide*.", footnotes: ["℘ 5Mo 4,39", "℘ Ps 95,6; Eph 2,10", "℘ Ps 74,1"] },
      { number: 4, text: "Zieht ein in seine Tore mit Dank, in seine Vorhöfe mit Lobgesang! Preist ihn, dankt seinem Namen*!", footnotes: ["℘ Ps 95,2; 96,8; 99,3; 122,4"] },
      { number: 5, text: "Denn gut ist der HERR*. Seine Gnade ist ewig* und seine Treue von Generation zu Generation*.", footnotes: ["℘ Mt 19,17", "℘ Ps 106,1; 107,1; 118,1; 136; 138,8; 2Chr 5,13; Esr 3,11; Jer 33,11", "℘ Ps 119,90"] },
    ]},
    { number: 101, verses: [
      { number: 1, text: "Von David. Ein Psalm. Von Gnade und Recht* will ich singen; dir, HERR, will ich spielen*.", heading: "Psalm 101", footnotes: ["℘ Mi 6,8", "℘ Ps 92,2; Eph 5,19"] },
      { number: 2, text: "*Ich will einsichtig handeln auf vollkommenem Weg.* Wann wirst du zu mir kommen*? *Ich will mit lauterem Herzen wandeln in meinem Hause.*", footnotes: ["o. Ich will Acht haben auf vollkommenen Weg.", "o. Ich will Acht haben auf vollkommenen Weg.", "℘ 2Mo 20,24", "w. Ich will wandeln in Lauterkeit meines Herzens in meinem Hause.", "w. Ich will wandeln in Lauterkeit meines Herzens in meinem Hause.\n℘ Ps 26,11"] },
      { number: 3, text: "Ich will keine heillosen Dinge* ins Auge fassen*; Übertretungen zu begehen, hasse ich*; das soll nicht an mir kleben.", footnotes: ["w. keine Belialssache", "℘ Ps 41,9; Spr 6,12-15", "℘ Spr 8,13"] },
      { number: 4, text: "Ein verkehrtes Herz soll von mir weichen, Böses* will ich nicht kennen*.", footnotes: ["o. einen Bösen", "℘ Ps 26,4.5; Mt 7,23"] },
      { number: 5, text: "Wer seinen Nächsten heimlich verleumdet, den will ich stumm machen*. Wer stolze Augen und ein hochmütiges Herz hat, den will ich nicht dulden*.", footnotes: ["o. vernichten\n℘ 3Mo 19,16; Spr 20,19", "℘ Spr 21,4"] },
      { number: 6, text: "Meine Augen sind auf die Treuen im Lande gerichtet, damit sie bei mir wohnen. Wer auf vollkommenem Weg wandelt, der darf mir dienen." },
      { number: 7, text: "In meinem Haus* soll nicht wohnen, wer Trug übt. Wer Lügen redet, soll nicht bestehen vor meinen Augen*.", footnotes: ["w. Im Innern meines Hauses", "℘ Ps 5,7"] },
      { number: 8, text: "Jeden Morgen will ich alle Gottlosen des Landes stumm machen*, um aus der Stadt des HERRN alle Übeltäter auszurotten*.", footnotes: ["o. vernichten\n℘ Spr 20,26", "℘ Ps 92,10"] },
    ]},
    { number: 102, verses: [
      { number: 1, text: "Gebet eines Elenden, wenn er verzagt ist und seine Klage vor dem HERRN ausschüttet*.", heading: "Psalm 102", footnotes: ["℘ Ps 142,3"] },
      { number: 2, text: "HERR, höre mein Gebet, lass zu dir kommen mein Schreien*!", footnotes: ["℘ Ps 17,1; 2Mo 2,23"] },
      { number: 3, text: "Verbirg dein Angesicht nicht vor mir* am Tag meiner Bedrängnis! Neige zu mir dein Ohr! An dem Tage, da ich rufe, erhöre mich eilends*!", footnotes: ["℘ Ps 27,9", "℘ Ps 31,3"] },
      { number: 4, text: "Denn wie* Rauch entschwinden meine Tage*, meine Gebeine glühen wie ein Brand*.", footnotes: ["so mit alten Üs. und Handschr.; Mas. T.: im", "℘ Jak 4,14", "℘ Hi 30,30"] },
      { number: 5, text: "Wie Gras ist abgemäht und verdorrt mein Herz*, denn ich habe vergessen, mein Brot zu essen*.", footnotes: ["℘ Ps 90,6; Hi 14,2", "℘ 1Sam 1,7"] },
      { number: 6, text: "Wegen der Stimme meines Seufzens klebt mein Gebein an meinem Fleisch*.", footnotes: ["℘ Hi 19,20"] },
      { number: 7, text: "Ich gleiche der Eule* der Wüste, ich bin wie das Käuzchen in den Ruinen.", footnotes: ["Andere üs.: dem Pelikan"] },
      { number: 8, text: "Ich wache* und bin wie ein einsamer Vogel auf dem Dach.", footnotes: ["℘ Ps 77,5"] },
      { number: 9, text: "Den ganzen Tag höhnen mich meine Feinde*; die mich verspotten, schwören bei mir*.", footnotes: ["℘ Ps 42,11", "d. h. schwören, dass es ihnen ergehen soll wie mir, falls sie wortbrüchig werden"] },
      { number: 10, text: "Denn Asche esse ich wie Brot, meinen Trank vermische ich mit Tränen*", footnotes: ["℘ Ps 42,4"] },
      { number: 11, text: "vor deiner Verwünschung und deinem Grimm*. Denn du hast mich emporgehoben und hast mich hingeworfen.", footnotes: ["℘ Kla 3,1"] },
      { number: 12, text: "Meine Tage sind wie ein gestreckter Schatten*, ich verdorre wie Gras*.", footnotes: ["℘ Ps 109,23", "℘ Ps 90,6; Hi 14,2"] },
      { number: 13, text: "Du aber, HERR, bleibst auf ewig*, dein Lob* von Generation zu Generation*.", footnotes: ["℘ Ps 90,2; 92,9", "w. deine Anrufung", "℘ Ps 135,13; 2Mo 3,15"] },
      { number: 14, text: "Du wirst aufstehen, wirst dich Zions erbarmen*. Denn es ist Zeit, ihn* zu begnadigen, denn gekommen ist die bestimmte Zeit*.", footnotes: ["℘ Jes 51,3", "nämlich den Berg und die Stadt Zion", "℘ Ps 119,126; Jes 40,2; Jer 29,10"] },
      { number: 15, text: "Denn deine Knechte haben Gefallen an seinen Steinen, sie haben Mitleid mit seinem Schutt*.", footnotes: ["℘ Neh 2,3.17"] },
      { number: 16, text: "Die Nationen werden den Namen des HERRN fürchten*, alle Könige der Erde deine Herrlichkeit*.", footnotes: ["℘ Ps 67,8; Jes 59,19", "℘ Jes 60,3"] },
      { number: 17, text: "Denn der HERR wird Zion aufbauen*, er wird erscheinen in seiner Herrlichkeit*.", footnotes: ["℘ Ps 147,2", "℘ Jes 40,5"] },
      { number: 18, text: "Er wird sich wenden zum Gebet der Verlassenen, ihr Gebet wird er nicht verachten*.", footnotes: ["℘ Ps 69,34"] },
      { number: 19, text: "Dies sei aufgeschrieben für die künftige Generation*, und ein neu geschaffenes Volk soll Jah loben*.", footnotes: ["℘ Röm 15,4", "℘ Ps 22,32; Jes 43,21"] },
      { number: 20, text: "Denn der HERR hat herniedergeblickt von der Höhe seines Heiligtums, er hat herabgeschaut vom Himmel auf die Erde*,", footnotes: ["℘ 5Mo 26,15"] },
      { number: 21, text: "um zu hören das Seufzen des Gefangenen, um zu lösen die Kinder des Todes*,", footnotes: ["℘ Ps 79,11; 2Mo 3,16.17"] },
      { number: 22, text: "damit man den Namen des HERRN verkündige in Zion und in Jerusalem sein Lob*,", footnotes: ["℘ Jes 52,8-10"] },
      { number: 23, text: "wenn die Völker sich alle versammeln und die Königreiche, um dem HERRN zu dienen*.", footnotes: ["℘ Jes 2,2.3; Jer 3,17"] },
      { number: 24, text: "Er hat meine Kraft gebrochen auf dem Weg, hat verkürzt meine Tage*.", footnotes: ["℘ Ps 89,46"] },
      { number: 25, text: "Ich sprach: Mein Gott, nimm mich nicht hinweg in der Hälfte meiner Tage*! Von Generation zu Generation sind deine Jahre*.", footnotes: ["℘ Jes 38,10", "℘ Ps 90,2; 92,9"] },
      { number: 26, text: "*Du hast einst die Erde gegründet, und der Himmel ist deiner Hände Werk*.", footnotes: ["℘ V. 26-28: Hebr 1,10-12", "℘ 2Kö 19,15"] },
      { number: 27, text: "Sie werden umkommen*, du aber bleibst. Sie alle werden zerfallen wie ein Kleid; wie ein Gewand wechselst du sie, und sie werden verwandelt*.", footnotes: ["℘ Mt 24,35", "℘ 2Petr 3,10"] },
      { number: 28, text: "Du aber bist derselbe*, und deine Jahre enden nicht.", footnotes: ["w. Du aber bist es; vgl. 5Mo 32,39; Neh 9,6\n℘ Mal 3,6; Hebr 13,8"] },
      { number: 29, text: "Die Söhne deiner Knechte werden wohnen bleiben*, ihre Nachkommen werden vor dir Bestand haben*.", footnotes: ["℘ Ps 69,37", "℘ Hes 37,25"] },
    ]},
    { number: 103, verses: [
      { number: 1, text: "Von David. Preise den HERRN, meine Seele*, und all mein Inneres seinen heiligen Namen*!", heading: "Psalm 103", footnotes: ["℘ Ps 104,1; 146,1", "℘ Ps 99,3; 145,1.2"] },
      { number: 2, text: "Preise den HERRN, meine Seele, und vergiss nicht alle seine Wohltaten*!", footnotes: ["℘ 5Mo 8,2"] },
      { number: 3, text: "Der da vergibt alle deine Sünde*, der da heilt alle deine Krankheiten*.", footnotes: ["℘ Ps 32,1; 130,8; Jes 43,25; Eph 1,7", "℘ 2Mo 15,26"] },
      { number: 4, text: "Der dein Leben erlöst aus der Grube*, der dich krönt mit Gnade und Erbarmen*.", footnotes: ["℘ Hi 33,28; Jes 38,17", "℘ Jes 54,8"] },
      { number: 5, text: "Der mit Gutem sättigt dein Leben*. Deine Jugend erneuert sich wie bei einem Adler*.", footnotes: ["so mit leichter Änderung des Mas. T.; w. deine Zierde", "℘ Jes 40,31"] },
      { number: 6, text: "Der HERR verschafft Gerechtigkeit* und Recht allen, die bedrückt werden*.", footnotes: ["w. Gerechtigkeiten (als Heilstaten, vgl. Ps 11,7)", "℘ Ps 35,10"] },
      { number: 7, text: "Er tat seine Wege kund dem Mose*, den Söhnen Israel seine Taten*.", footnotes: ["℘ 2Mo 33,13", "℘ Ps 111,6"] },
      { number: 8, text: "Barmherzig und gnädig ist der HERR, langsam zum Zorn und groß an Gnade*.", footnotes: ["℘ Ps 86,15; 2Mo 34,6"] },
      { number: 9, text: "Er wird nicht immer rechten, nicht ewig zürnen*.", footnotes: ["℘ Jes 57,16; Mi 7,18"] },
      { number: 10, text: "Er hat uns nicht getan nach unseren Vergehen*, nach unseren Sünden uns nicht vergolten*.", footnotes: ["o. Treuebrüchen; o. Auflehnungen", "℘ Esr 9,13; Hi 33,27"] },
      { number: 11, text: "Denn so hoch der Himmel über der Erde ist, so übermächtig ist seine Gnade* über denen, die ihn fürchten*.", footnotes: ["℘ Ps 117,2", "℘ Ps 31,20"] },
      { number: 12, text: "So fern der Osten ist vom Westen, hat er von uns entfernt unsere Vergehen*.", footnotes: ["o. Treuebrüchen; o. Auflehnungen\n℘ Jes 44,22; Jer 50,20; Mi 7,19; Hebr 10,17"] },
      { number: 13, text: "Wie sich ein Vater über Kinder erbarmt, so erbarmt sich der HERR über die, die ihn fürchten*.", footnotes: ["℘ Jer 31,20; Mal 3,17; Jak 5,11"] },
      { number: 14, text: "Denn er kennt unser Gebilde, gedenkt, dass wir Staub sind*.", footnotes: ["℘ Ps 78,39; 1Mo 2,7; 3,19; Hi 10,9"] },
      { number: 15, text: "Der Mensch — wie Gras sind seine Tage, wie die Blume des Feldes, so blüht er*.", footnotes: ["℘ Ps 90,5.6; 1Petr 1,24"] },
      { number: 16, text: "Denn fährt ein Wind darüber, so ist sie nicht mehr, und ihr Ort kennt sie nicht mehr*.", footnotes: ["℘ Hi 7,8-10; Jes 40,6.7"] },
      { number: 17, text: "Die Gnade des HERRN aber währt von Ewigkeit zu Ewigkeit* über denen, die ihn fürchten*, seine Gerechtigkeit bis zu den Kindeskindern*,", footnotes: ["℘ Ps 25,6", "℘ Lk 1,50", "℘ Ps 111,3"] },
      { number: 18, text: "für die, die seinen Bund halten, die seiner Vorschriften gedenken, um sie zu tun*.", footnotes: ["℘ 5Mo 7,9"] },
      { number: 19, text: "Der HERR hat im Himmel aufgerichtet seinen Thron*, und seine Herrschaft regiert über alles*.", footnotes: ["℘ Ps 11,4", "℘ 1Chr 29,11.12; Dan 7,14"] },
      { number: 20, text: "Preist den HERRN, ihr seine Engel*, ihr Gewaltigen an Kraft*, Täter seines Wortes, dass man höre auf die Stimme seines Wortes*!", footnotes: ["℘ Ps 148,2", "℘ 2Petr 2,11; Offb 5,2", "℘ Lk 1,19"] },
      { number: 21, text: "Preist den HERRN, alle seine Heerscharen*, ihr seine Diener, die ihr seinen Willen* tut*.", footnotes: ["℘ Lk 2,13; Offb 5,11.12", "w. sein Wohlgefallen", "℘ Dan 7,10; Hebr 1,14"] },
      { number: 22, text: "Preist den HERRN, alle seine Werke an allen Orten seiner Herrschaft*! Preise den HERRN, meine Seele*!", footnotes: ["℘ Ps 145,10.21; 148,1-5", "℘ V. 1"] },
    ]},
    { number: 104, verses: [
      { number: 1, text: "Preise den HERRN, meine Seele*! HERR, mein Gott, du bist sehr groß*, mit Majestät und Pracht bist du bekleidet*.", heading: "Psalm 104", footnotes: ["℘ V. 35; Ps 103,1", "℘ Ps 95,3", "℘ Ps 93,1"] },
      { number: 2, text: "Du, der in Licht sich hüllt wie in ein Gewand*, der den Himmel ausspannt gleich einer Zeltdecke*,", footnotes: ["℘ 1Jo 1,5", "℘ Jes 40,22"] },
      { number: 3, text: "der seine Obergemächer errichtet in den Wassern*, der Wolken macht zu seinem Wagen*, der einherzieht auf den Flügeln des Windes*,", footnotes: ["Gemeint sind (vgl. 1Mo 1,7) die Wasser, die über dem Himmelsgewölbe sind. Aus ihnen tropft der Regen (Ps 104,13).\n℘ Ps 148,4; Am 9,6", "℘ 5Mo 33,26; Jes 19,1", "℘ Ps 18,11"] },
      { number: 4, text: "der Winde zu seinen Boten macht, Feuer und Lohe zu seinen Dienern*:", footnotes: ["℘ Hebr 1,7"] },
      { number: 5, text: "Er hat die Erde gegründet auf ihre Grundfesten*. Sie wird nicht wanken immer und ewig*.", footnotes: ["℘ Ps 119,90; Spr 8,29", "℘ Pred 1,4"] },
      { number: 6, text: "Die Urflut bedeckte* sie wie ein Kleid, das Wasser stand über den Bergen.", footnotes: ["Mas. T.: Du hast ihn bedeckt. — Text mit griech., lat. und aram. Üs."] },
      { number: 7, text: "Vor deinem Schelten floh es, vor dem Schall deines Donners wurde es fortgetrieben." },
      { number: 8, text: "Die Berge erhoben sich, es senkten sich die Täler* an den Ort, den du ihnen bestimmt hattest.", footnotes: ["℘ Spr 8,25"] },
      { number: 9, text: "Du hast eine Grenze gesetzt, die überschreitet es nicht. Es wird nicht zurückkehren, die Erde zu bedecken." },
      { number: 10, text: "Du, der Quellen entsendet in die Täler: Zwischen den Bergen fließen sie dahin*.", footnotes: ["℘ 5Mo 8,7"] },
      { number: 11, text: "Sie tränken alle Tiere des Feldes, die Wildesel stillen ihren Durst." },
      { number: 12, text: "An ihnen* wohnen die Vögel des Himmels, aus dichtem Laub lassen sie ihre Stimme erschallen.", footnotes: ["Gemeint sind die Bäche."] },
      { number: 13, text: "Du, der die Berge tränkt aus seinen Obergemächern*: von der Frucht deiner Werke wird die Erde gesättigt*.", footnotes: ["℘ Jer 10,13", "℘ Ps 65,10.11"] },
      { number: 14, text: "Der Gras hervorsprossen lässt* für das Vieh und Pflanzen zum Dienst des Menschen*, damit er Brot hervorbringe aus der Erde*", footnotes: ["℘ Ps 147,8; 1Mo 1,12", "℘ 1Mo 1,29.30", "℘ Mk 4,28; Jak 5,18"] },
      { number: 15, text: "und Wein, der des Menschen Herz erfreut*; damit er das Angesicht glänzend mache vom Öl und Brot des Menschen Herz stärke*.", footnotes: ["℘ Ri 9,13; Pred 10,19; Sach 10,7", "℘ Jes 55,10"] },
      { number: 16, text: "Es werden gesättigt die Bäume des HERRN, die Zedern des Libanon, die er gepflanzt hat*,", footnotes: ["℘ 4Mo 24,6"] },
      { number: 17, text: "wo die Vögel nisten*; der Storch — Wacholderbäume sind sein Nest*.", footnotes: ["℘ Hes 31,6", "Andere übersetzen mit Textkorr.: in den Wipfeln ist sein Nest"] },
      { number: 18, text: "Die hohen Berge sind für die Steinböcke, die Felsen eine Zuflucht für die Klippdachse*.", footnotes: ["℘ Spr 30,26"] },
      { number: 19, text: "Er hat den Mond gemacht zur Zeitbestimmung*, die Sonne kennt ihren Untergang.", footnotes: ["w. zu bestimmten Terminen"] },
      { number: 20, text: "Du bestellst Finsternis, und es wird Nacht*. In ihr regen sich alle Tiere des Waldes.", footnotes: ["℘ Ps 74,16"] },
      { number: 21, text: "Die Junglöwen brüllen nach Raub, sie fordern von Gott ihre Speise*.", footnotes: ["℘ Hi 38,39.40"] },
      { number: 22, text: "Geht die Sonne auf, ziehen sie sich zurück und lagern sich in ihren Verstecken*.", footnotes: ["℘ Hi 37,8"] },
      { number: 23, text: "Der Mensch geht aus an sein Werk, an seine Arbeit bis zum Abend." },
      { number: 24, text: "Wie zahlreich sind deine Werke, HERR*! Du hast sie alle mit Weisheit gemacht*, die Erde ist voll deines Eigentums.", footnotes: ["℘ Ps 92,6", "℘ Spr 3,19; Jer 10,12"] },
      { number: 25, text: "Da ist das Meer, groß und ausgedehnt nach allen Seiten. Dort ist ein Gewimmel ohne Zahl: Tiere klein und groß*.", footnotes: ["℘ 1Mo 1,20"] },
      { number: 26, text: "Da ziehen Schiffe einher*, der Leviatan, den du gebildet hast, um mit ihm zu spielen*.", footnotes: ["℘ Ps 107,23", "o. dass er darin spiele"] },
      { number: 27, text: "Sie alle warten auf dich, dass du ihnen ihre Speise gibst zu seiner Zeit*.", footnotes: ["℘ Ps 136,25; 145,15; Lk 12,6"] },
      { number: 28, text: "Du gibst ihnen: Sie sammeln ein. Du tust deine Hand auf: Sie werden gesättigt mit Gutem*.", footnotes: ["℘ Ps 145,16; Mt 14,20"] },
      { number: 29, text: "Du verbirgst dein Angesicht: Sie erschrecken. Du nimmst ihren Lebensatem weg: Sie vergehen und werden wieder zu Staub*.", footnotes: ["℘ Ps 90,3"] },
      { number: 30, text: "Du sendest deinen Lebenshauch aus: Sie werden geschaffen*; du erneuerst die Flächen des Ackers.", footnotes: ["℘ Hi 33,4; Apg 17,25"] },
      { number: 31, text: "Die Herrlichkeit des HERRN sei ewig*! Der HERR freue sich seiner Werke!", footnotes: ["℘ Röm 11,36"] },
      { number: 32, text: "Der die Erde anschaut, und sie bebt*; er rührt die Berge an, und sie rauchen*.", footnotes: ["℘ Ps 77,19; Nah 1,5", "℘ Ps 144,5; 2Mo 19,18"] },
      { number: 33, text: "Singen will ich dem HERRN mein Leben lang, ich will meinem Gott spielen, solange ich bin*.", footnotes: ["℘ Ps 63,5; 146,2"] },
      { number: 34, text: "Möge ihm gefallen meine Rede*! Ich, ich freue mich in dem HERRN*!", footnotes: ["o. Betrachtung\n℘ Ps 19,15", "℘ Ps 35,9; 105,3; Hab 3,18"] },
      { number: 35, text: "Die Sünder sollen verschwinden von der Erde* und die Gottlosen nicht mehr sein*. Preise den HERRN, meine Seele*! Halleluja!", footnotes: ["℘ Jes 13,9", "℘ Ps 145,20; Spr 2,22", "℘ V. 1"] },
    ]},
    { number: 105, verses: [
      { number: 1, text: "*Preist den HERRN, ruft an seinen Namen, macht unter den Völkern kund seine Taten*!", heading: "Psalm 105", footnotes: ["℘ V. 1-15: 1Chr 16,8-22", "℘ Ps 9,12; 96,3; Jes 12,4"] },
      { number: 2, text: "Singt ihm, spielt ihm, redet von allen seinen Wundern*!", footnotes: ["℘ Ps 77,13"] },
      { number: 3, text: "Rühmt euch seines heiligen Namens! Es freue sich das Herz derer, die den HERRN suchen*!", footnotes: ["℘ Ps 104,34"] },
      { number: 4, text: "Fragt nach dem HERRN und seiner Stärke, sucht sein Angesicht beständig*!", footnotes: ["℘ Ps 27,8; Am 5,4"] },
      { number: 5, text: "Gedenkt seiner Wunder, die er getan hat*, seiner Zeichen und der Urteile seines Mundes!", footnotes: ["℘ Ps 77,12"] },
      { number: 6, text: "Ihr Nachkommen Abrahams, seines Knechtes*, ihr Söhne Jakobs, seine Auserwählten*:", footnotes: ["℘ V. 42", "℘ V. 43; Ps 135,4; 5Mo 7,7; Jes 45,4"] },
      { number: 7, text: "Er ist der HERR, unser Gott*! Seine Urteile ergehen auf der ganzen Erde.", footnotes: ["℘ Ps 48,15"] },
      { number: 8, text: "Er gedenkt ewig seines Bundes* — des Wortes, das er geboten hat auf tausend Generationen hin* —,", footnotes: ["℘ Ps 106,45; 111,5; Lk 1,72", "℘ 5Mo 7,9"] },
      { number: 9, text: "den er gemacht hat mit Abraham*, und seines Eides an Isaak*.", footnotes: ["℘ 2Mo 2,24; 2Kö 13,23", "℘ 1Mo 26,3; Jer 11,5"] },
      { number: 10, text: "Er richtete ihn auf für Jakob zur Ordnung, Israel zum ewigen Bund," },
      { number: 11, text: "indem er sprach: Dir will ich das Land Kanaan geben als euch zugemessenes Erbe*.", footnotes: ["w. als die Messschnur eures Erbes\n℘ 1Mo 12,7"] },
      { number: 12, text: "Als sie noch gering waren an Zahl, nur wenige und Fremdlinge darin*,", footnotes: ["℘ 2Mo 6,4"] },
      { number: 13, text: "als sie von Volk zu Volk wanderten, von einem Reich zu einem anderen Volk," },
      { number: 14, text: "da gestattete er keinem Menschen, sie zu bedrücken, und ihretwegen wies er Könige zurecht*:", footnotes: ["℘ 1Mo 12,17; 20,3.7"] },
      { number: 15, text: "»Tastet meine Gesalbten nicht an, tut meinen Propheten nichts Übles*!«", footnotes: ["℘ Sach 2,12"] },
      { number: 16, text: "Er rief eine Hungersnot über das Land herbei*; jeden Brotstab* zerbrach er*.", footnotes: ["℘ 1Mo 41,54", "Gemeint sind die Stöcke, an denen die ringförmigen Brote aufgehängt wurden (zum Schutz vor Mäusen).", "℘ 3Mo 26,26; Jes 3,1"] },
      { number: 17, text: "Er sandte einen Mann vor ihnen her*: Josef wurde als Knecht verkauft*.", footnotes: ["℘ 1Mo 45,5", "℘ 1Mo 37,28"] },
      { number: 18, text: "Sie zwängten seine Füße in Fesseln*, in Eisen kam sein Hals,", footnotes: ["℘ 1Mo 39,20"] },
      { number: 19, text: "bis zu der Zeit, da sein Wort eintraf*, das Wort des HERRN ihn bewährte.", footnotes: ["℘ 1Mo 41,9-13"] },
      { number: 20, text: "Der König sandte hin und ließ ihn los, der Herrscher über Völker, und befreite ihn*.", footnotes: ["℘ 1Mo 41,14"] },
      { number: 21, text: "Er setzte ihn zum Herrn über sein Haus, zum Herrscher über all seinen Besitz*,", footnotes: ["w. seine Seele\n℘ 1Mo 41,40"] },
      { number: 22, text: "*um seine Obersten zurechtzuweisen nach seinem Sinn*; und seine Ältesten sollte er Weisheit lehren.", footnotes: ["so mit LXX, lat. und syr. Üs.; Mas. T.: um seine Obersten zu binden in seiner Seele", "so mit LXX, lat. und syr. Üs.; Mas. T.: um seine Obersten zu binden in seiner Seele\n℘ 1Mo 41,44"] },
      { number: 23, text: "Dann kam Israel nach Ägypten, Jakob war ein Fremder im Lande Hams*.", footnotes: ["℘ 1Mo 46,6"] },
      { number: 24, text: "Und er machte sein Volk sehr fruchtbar, er machte es stärker als seine Bedränger*.", footnotes: ["℘ 2Mo 1,9; Apg 13,17"] },
      { number: 25, text: "Er wandelte ihr Herz, sein Volk zu hassen, Arglist zu üben an seinen Knechten*.", footnotes: ["℘ 2Mo 1,13.14.16; Apg 7,19"] },
      { number: 26, text: "Er sandte Mose, seinen Knecht*, Aaron, den er auserwählt hatte*.", footnotes: ["℘ 2Mo 3,10", "℘ 2Mo 4,27.29"] },
      { number: 27, text: "*Sie taten unter ihnen seine Zeichen und Wunder im Lande Hams*.", footnotes: ["℘ V. 27-36: Ps 78,43-53", "℘ Ps 106,22; 2Mo 7,3; Neh 9,10"] },
      { number: 28, text: "Er sandte Finsternis und machte es finster*. Aber *sie achteten nicht auf* seine Worte*.", footnotes: ["℘ 2Mo 10,22", "so nach Ergänzung des Mas. T. durch einen vermutlich ausgefallenen Buchstaben; Mas. T.: und sie waren nicht widerspenstig gegen", "so nach Ergänzung des Mas. T. durch einen vermutlich ausgefallenen Buchstaben; Mas. T.: und sie waren nicht widerspenstig gegen", "℘ 1Sam 12,14; Hes 2,8"] },
      { number: 29, text: "Er verwandelte ihr Wasser in Blut*, ließ sterben ihre Fische*.", footnotes: ["℘ 2Mo 7,20; Offb 16,3.4", "℘ 2Mo 7,21"] },
      { number: 30, text: "Es wimmelte ihr Land von Fröschen bis in die Gemächer ihrer Könige*.", footnotes: ["℘ 2Mo 8,1-11"] },
      { number: 31, text: "Er sprach, und es kamen Hundsfliegen*, Stechmücken in ihr ganzes Gebiet*.", footnotes: ["℘ 2Mo 8,12-15; Jes 7,18", "w. in all ihre Grenzen\n℘ 2Mo 8,16-20"] },
      { number: 32, text: "Er gab ihnen Hagel statt Regen, flammendes Feuer in ihr Land.*", footnotes: ["℘ 2Mo 9,24; Offb 8,7"] },
      { number: 33, text: "Und er schlug ihre Weinstöcke und Feigenbäume, zerbrach die Bäume ihres Gebiets." },
      { number: 34, text: "Er sprach, und es kamen Heuschrecken und ihre Larven ohne Zahl*.", footnotes: ["℘ 2Mo 10,14; Offb 9,3"] },
      { number: 35, text: "Sie fraßen alles Kraut in ihrem Land, sie fraßen die Frucht ihres Bodens*.", footnotes: ["℘ 2Mo 10,15"] },
      { number: 36, text: "Und er schlug alle Erstgeburt in ihrem Land, die Erstlinge all ihrer Kraft*.", footnotes: ["℘ 2Mo 12,29; Apg 7,36"] },
      { number: 37, text: "Dann führte er sie heraus* mit Silber und Gold*, und kein Strauchelnder war unter seinen Stämmen*.", footnotes: ["℘ Ps 136,11", "℘ 2Mo 12,35", "℘ 1Sam 2,9; Jes 63,13"] },
      { number: 38, text: "Froh war Ägypten bei ihrem Auszug, denn ihr Schrecken war auf sie gefallen*.", footnotes: ["℘ 2Mo 12,33"] },
      { number: 39, text: "Er breitete eine Wolke aus zur Decke, ein Feuer, die Nacht zu erleuchten*.", footnotes: ["℘ 2Mo 13,21; Neh 9,12"] },
      { number: 40, text: "Sie forderten*, und er ließ Wachteln kommen. Mit Himmelsbrot sättigte er sie*.", footnotes: ["so mit fast allen alten Üs.; Mas. T.: Er forderte", "℘ Ps 78,24.25; 2Mo 16,14"] },
      { number: 41, text: "Er öffnete den Felsen, und es floss Wasser heraus. Es lief in die Wüste wie ein Strom*.", footnotes: ["℘ Ps 78,15.16; 2Mo 17,6; Jes 48,21; Apg 7,36"] },
      { number: 42, text: "Denn er gedachte seines heiligen Wortes, Abrahams, seines Knechtes*,", footnotes: ["℘ 1Mo 15,13-16; Lk 1,54.55"] },
      { number: 43, text: "und führte sein Volk heraus in Freude, seine Auserwählten* in Jubel.", footnotes: ["℘ V. 6; Ps 106,5; 2Mo 14,8; 15,1"] },
      { number: 44, text: "Er gab ihnen die Länder der Nationen und die Mühe* der Völkerschaften nahmen sie in Besitz*,", footnotes: ["d. h. das mühsam Errungene", "℘ Neh 9,25"] },
      { number: 45, text: "damit sie seine Ordnungen beachteten und seine Gesetze bewahrten*. Halleluja!", footnotes: ["℘ Ps 78,7; Hes 36,27"] },
    ]},
    { number: 106, verses: [
      { number: 1, text: "Halleluja! Preist den HERRN, denn er ist gut! Denn seine Gnade währt ewig*.", heading: "Psalm 106", footnotes: ["℘ Ps 100,5; 135,3"] },
      { number: 2, text: "Wer wird alle die Machttaten des HERRN erzählen, hören lassen all seinen Ruhm?" },
      { number: 3, text: "Glücklich, die das Recht bewahren, die Gerechtigkeit üben* zu aller Zeit*!", footnotes: ["so durch andere Konsonantenaufteilung; Mas. T.: der Gerechtigkeit übt", "℘ Jes 56,1"] },
      { number: 4, text: "Gedenke meiner*, HERR*, in der Zuneigung zu deinem Volk*. Suche mich* heim mit deiner Hilfe,", footnotes: ["hebr. Handschr. und alte Üs.: unser bzw. uns. Entsprechend lautet dann V. 5.", "℘ Lk 23,42", "℘ Ps 25,7", "hebr. Handschr. und alte Üs.: unser bzw. uns. Entsprechend lautet dann V. 5."] },
      { number: 5, text: "dass ich anschaue das Glück deiner Auserwählten*, mich freue an der Freude deiner Nation, mich rühme mit deinem Erbteil*.", footnotes: ["℘ Ps 105,43", "℘ 5Mo 32,9"] },
      { number: 6, text: "Wir haben gesündigt samt unseren Vätern, haben Unrecht getan, haben gottlos gehandelt*.", footnotes: ["℘ 1Kö 8,47; Esr 9,10; Dan 9,5"] },
      { number: 7, text: "Unsere Väter in Ägypten begriffen nicht deine Wunder, sie gedachten nicht der Menge deiner Gnadenerweise, sie waren widerspenstig am Meer, am Schilfmeer*.", footnotes: ["℘ 2Mo 14,11.12"] },
      { number: 8, text: "Aber er rettete sie um seines Namens willen*, um seine Macht kundzutun.", footnotes: ["℘ Ps 23,3; Jes 48,9"] },
      { number: 9, text: "Und er bedrohte das Schilfmeer*, und es wurde trocken*. Er ließ sie durch die Fluten gehen wie durch eine Wüste*.", footnotes: ["o. er schrie das Schilfmeer an", "℘ 2Mo 14,29", "℘ Jes 63,11-13"] },
      { number: 10, text: "Er rettete sie aus der Hand dessen, der sie hasste, er erlöste sie aus der Hand des Feindes*.", footnotes: ["℘ Ps 107,2"] },
      { number: 11, text: "Und das Wasser bedeckte ihre Bedränger, nicht einer von ihnen blieb übrig*.", footnotes: ["℘ Ps 78,53; 2Mo 14,28"] },
      { number: 12, text: "Da glaubten sie seinen Worten, sie sangen sein Lob*.", footnotes: ["℘ 2Mo 14,31; 15,1"] },
      { number: 13, text: "Schnell vergaßen sie seine Taten*, warteten nicht auf seinen Rat.", footnotes: ["℘ Ps 78,11"] },
      { number: 14, text: "Sie gierten voller Begierde in der Wüste*, versuchten Gott* in der Einöde.", footnotes: ["℘ 4Mo 11,4", "℘ Ps 78,18"] },
      { number: 15, text: "Da erfüllte er ihnen ihre Bitte*, und er sandte Schwindsucht in ihre Seele.", footnotes: ["℘ Ps 78,29"] },
      { number: 16, text: "Sie wurden eifersüchtig auf Mose im Lager*, auf Aaron, den Heiligen des HERRN*.", footnotes: ["℘ 4Mo 16,3", "℘ 4Mo 16,7.11"] },
      { number: 17, text: "Die Erde tat sich auf und verschlang Datan und bedeckte die Rotte Abirams*.", footnotes: ["℘ 4Mo 16,31.32"] },
      { number: 18, text: "Ein Feuer brannte unter ihrer Rotte, eine Flamme verzehrte die Gottlosen*.", footnotes: ["℘ 4Mo 16,35"] },
      { number: 19, text: "Sie machten ein Kalb am Horeb und beugten sich vor einem gegossenen Bild*.", footnotes: ["℘ 2Mo 32,1-8; Apg 7,41"] },
      { number: 20, text: "Sie vertauschten ihre Herrlichkeit* mit dem Bild eines Stieres, der Gras frisst*.", footnotes: ["℘ Jer 2,11", "℘ 2Mo 32,4; Röm 1,23"] },
      { number: 21, text: "Sie vergaßen Gott, der sie rettete*, der große Dinge getan in Ägypten,", footnotes: ["℘ Ps 78,42; 5Mo 32,18; Jes 17,10"] },
      { number: 22, text: "Wunder im Lande Hams*, Furchtbares am Schilfmeer*.", footnotes: ["℘ Ps 105,27", "℘ 2Mo 14,28; Apg 7,36"] },
      { number: 23, text: "Da gedachte er, sie auszurotten, wäre nicht Mose gewesen, sein Erwählter. Der trat in die Bresche vor ihn, um seinen Grimm vom Verderben abzuwenden*.", footnotes: ["℘ 2Mo 32,11"] },
      { number: 24, text: "Und sie verschmähten das köstliche Land*, glaubten nicht seinem Wort*.", footnotes: ["℘ 4Mo 13,32; Jer 3,19", "℘ 5Mo 1,32"] },
      { number: 25, text: "Sie murrten in ihren Zelten, hörten nicht auf die Stimme des HERRN*.", footnotes: ["℘ 4Mo 14,1.2"] },
      { number: 26, text: "Da erhob er seine Hand gegen sie, um sie niederzuschlagen in der Wüste*,", footnotes: ["℘ 4Mo 14,28.29; Hes 20,15; 1Kor 10,5; Hebr 3,18"] },
      { number: 27, text: "um ihre Nachkommenschaft zu Fall zu bringen unter den Nationen, um sie zu zersprengen in die Länder*.", footnotes: ["℘ 3Mo 26,33; Hes 20,23"] },
      { number: 28, text: "Und sie hängten sich an Baal-Peor* und aßen Schlachtopfer der Toten*.", footnotes: ["℘ 4Mo 25,1-3; Hos 9,10", "℘ 1Kor 8,4"] },
      { number: 29, text: "So erbitterten sie ihn durch ihre Taten, eine Plage brach unter ihnen aus*.", footnotes: ["℘ 4Mo 25,3; 1Kor 10,8"] },
      { number: 30, text: "Da stand Pinhas auf und übte Gericht, und der Plage wurde gewehrt*.", footnotes: ["℘ 4Mo 25,7.8"] },
      { number: 31, text: "Das wurde ihm zur Gerechtigkeit gerechnet*, von Generation zu Generation bis in Ewigkeit*.", footnotes: ["℘ 1Mo 15,6", "℘ 4Mo 25,10-13"] },
      { number: 32, text: "Und sie erzürnten ihn am Wasser von Meriba, und es erging Mose übel ihretwegen*.", footnotes: ["℘ 4Mo 20,13; 5Mo 4,21"] },
      { number: 33, text: "Denn sie reizten seinen Geist, so dass er unbedacht redete mit seinen Lippen*.", footnotes: ["℘ 4Mo 20,10"] },
      { number: 34, text: "Sie vertilgten die Völker nicht*, die der HERR ihnen genannt hatte*.", footnotes: ["℘ Ri 1,21-33", "o. wie der HERR ihnen gesagt hatte\n℘ 5Mo 7,2.16"] },
      { number: 35, text: "Sie vermischten sich mit den Nationen und lernten ihre Werke*.", footnotes: ["℘ Ri 3,5.6"] },
      { number: 36, text: "Sie dienten ihren Götzen*, die wurden ihnen zum Fallstrick*. //", footnotes: ["℘ Ri 3,7", "℘ 2Mo 23,33"] },
      { number: 37, text: "Und sie opferten ihre Söhne und ihre Töchter den Dämonen*,", footnotes: ["℘ 3Mo 17,7; 5Mo 32,17; 1Kor 10,20"] },
      { number: 38, text: "vergossen unschuldiges Blut, das Blut ihrer Söhne und Töchter, die sie den Götzen Kanaans opferten*. So wurde das Land durch die Blutschuld entweiht*.", footnotes: ["℘ 3Mo 18,21; 2Kö 17,17; Jer 19,4.5; Hes 16,20", "℘ 4Mo 35,33"] },
      { number: 39, text: "Sie verunreinigten sich durch ihre Werke* und hurten durch ihre Taten*.", footnotes: ["℘ Mt 15,20", "℘ 2Mo 34,16; Jer 3,6-9; Hes 20,30"] },
      { number: 40, text: "Da entbrannte der Zorn des HERRN gegen sein Volk*, und er verabscheute sein Eigentum*.", footnotes: ["℘ Ri 2,14", "℘ 5Mo 9,29"] },
      { number: 41, text: "Er gab sie in die Hand der Nationen, und die sie hassten, herrschten über sie." },
      { number: 42, text: "Ihre Feinde bedrängten sie, und sie wurden gebeugt unter ihrer Hand*.", footnotes: ["℘ Ri 2,14.15"] },
      { number: 43, text: "Oft rettete er sie*. Sie aber waren widerspenstig in ihren Plänen, und sie verkamen wegen ihrer Ungerechtigkeit*.", footnotes: ["℘ Ri 2,16", "℘ Ps 107,11; Ri 6,6"] },
      { number: 44, text: "Doch er sah an ihr Elend, als er ihr Schreien hörte*.", footnotes: ["℘ Ps 107,6; Ri 6,7.8"] },
      { number: 45, text: "Und er gedachte um ihretwillen seines Bundes*, und es reute ihn in der Fülle* seiner Gnade*.", footnotes: ["℘ Ps 105,8; 3Mo 26,45", "w. gemäß der Fülle", "℘ Ps 136,23; Ri 2,18; Kla 3,32"] },
      { number: 46, text: "Er ließ sie Erbarmen finden bei allen, die sie gefangen weggeführt hatten*.", footnotes: ["℘ 1Kö 8,50; Esr 9,9; Jer 42,12"] },
      { number: 47, text: "Rette uns, HERR, unser Gott, und sammle uns aus den Nationen*, dass wir deinen heiligen Namen preisen, dass wir uns rühmen deines Lobes*!", footnotes: ["℘ 5Mo 30,3", "℘ 1Chr 16,35"] },
      { number: 48, text: "Gepriesen sei der HERR, der Gott Israels, von Ewigkeit zu Ewigkeit*! Und alles Volk sage: Amen! Halleluja*!", footnotes: ["℘ Ps 41,14", "℘ 1Chr 16,36"] },
    ]},
    { number: 107, verses: [
      { number: 1, text: "FÜNFTES BUCH Preist den HERRN, denn er ist gut, denn seine Gnade währt ewig*!", heading: "Psalm 107", footnotes: ["℘ Ps 100,5"] },
      { number: 2, text: "So sollen sagen die Erlösten des HERRN, die er aus der Hand des Bedrängers* erlöst hat*.", footnotes: ["o. der Not", "℘ Ps 106,10"] },
      { number: 3, text: "Die er gesammelt hat aus den Ländern, von Osten und von Westen, von Norden und von Süden*.", footnotes: ["Mas. T.: vom Meer. — Vermutlich ist ein Buchstabe ausgefallen, den man wieder einsetzen muss, um das ursprüngliche Wort »Süden« zu gewinnen.\n℘ Jes 43,5.6"] },
      { number: 4, text: "Sie irrten in der Wüste, auf ödem Weg, sie fanden keinen bewohnten Ort*.", footnotes: ["℘ 5Mo 32,10"] },
      { number: 5, text: "Hungrig waren sie* und durstig*, es verschmachtete in ihnen ihre Seele.", footnotes: ["℘ 2Mo 16,3", "℘ 2Mo 17,3; 2Sam 17,29"] },
      { number: 6, text: "Da schrien sie zum HERRN in ihrer Not*: aus ihren Bedrängnissen rettete er sie*.", footnotes: ["℘ Hos 5,15", "℘ Ps 106,44; Lk 8,24"] },
      { number: 7, text: "Er leitete sie auf rechtem Weg, so dass sie zu einem bewohnten Ort gelangten*.", footnotes: ["℘ Jes 32,18"] },
      { number: 8, text: "Sie sollen den HERRN preisen für seine Gnade und für seine Wunder an den Menschenkindern!" },
      { number: 9, text: "Denn er hat die durstende Seele gesättigt, die hungernde Seele mit Gutem erfüllt*.", footnotes: ["℘ Ps 34,11; 146,7; Lk 1,53"] },
      { number: 10, text: "Die Bewohner des Dunkels und der Finsternis* lagen gefesselt in Elend und Eisen*:", footnotes: ["℘ Lk 1,79", "℘ Hi 36,8"] },
      { number: 11, text: "denn sie waren widerspenstig gewesen gegen die Worte Gottes und hatten verachtet den Rat des Höchsten*;", footnotes: ["℘ Ps 106,43; Jes 63,10"] },
      { number: 12, text: "und er hatte ihr Herz gebeugt durch Unheil. Sie waren gestürzt, und kein Helfer war da*.", footnotes: ["℘ 2Kö 14,26; Jes 63,5; Joh 5,7"] },
      { number: 13, text: "Da schrien sie zum HERRN um Hilfe in ihrer Not*: aus ihren Bedrängnissen rettete er sie*.", footnotes: ["℘ Ps 106,44; Lk 8,24", "℘ Ps 106,44; Lk 8,24"] },
      { number: 14, text: "Er führte sie heraus aus Dunkel und Finsternis, er zerriss ihre Fesseln." },
      { number: 15, text: "Sie sollen den HERRN preisen für seine Gnade, für seine Wunder an den Menschenkindern!" },
      { number: 16, text: "Denn er hat eherne* Türen zerbrochen, und eiserne Riegel hat er zerschlagen*.", footnotes: ["w. bronzene", "℘ Jes 45,2"] },
      { number: 17, text: "Die Toren litten wegen ihres gottlosen* Weges und wegen ihrer Sünden*.", footnotes: ["w. wegen des Weges ihres Vergehens (o. Treuebruchs)", "℘ Ps 38,4.6"] },
      { number: 18, text: "Ihre Seele ekelte vor jeder Speise, sie rührten an die Pforten des Todes*.", footnotes: ["℘ Hi 33,20-22"] },
      { number: 19, text: "Dann aber schrien sie zum HERRN um Hilfe in ihrer Not*: aus ihren Bedrängnissen rettete er sie*.", footnotes: ["℘ Ps 106,44; Lk 8,24", "℘ Ps 106,44; Lk 8,24"] },
      { number: 20, text: "Er sandte sein Wort und heilte sie*, er rettete sie aus ihren Gruben*.", footnotes: ["℘ 2Kö 20,5; Mt 8,8", "Andere lesen: und rettete ihr Leben aus der Grube\n℘ Ps 30,3.4; Hi 33,24"] },
      { number: 21, text: "Sie sollen den HERRN preisen für seine Gnade, für seine Wunder an den Menschenkindern." },
      { number: 22, text: "Sie sollen Dankopfer darbringen* und mit Jubel seine Taten erzählen*!", footnotes: ["℘ Ps 27,6; 3Mo 7,12", "℘ Ps 9,15"] },
      { number: 23, text: "Die sich mit Schiffen aufs Meer hinausbegaben, auf großen Wassern Handel trieben*,", footnotes: ["℘ Ps 104,26"] },
      { number: 24, text: "das sind die, die die Taten des HERRN sahen und seine Wunder in der Tiefe*.", footnotes: ["℘ Ps 104,24.25"] },
      { number: 25, text: "Er redete und bestellte einen Sturmwind, und der trieb seine Wellen hoch*.", footnotes: ["℘ Jon 1,4; Mt 8,24; Joh 6,18"] },
      { number: 26, text: "Sie stiegen zum Himmel empor, sie sanken hinab in die Tiefen, es verzagte in der Not ihre Seele." },
      { number: 27, text: "Sie taumelten und schwankten wie ein Betrunkener, es versagte all ihre Weisheit." },
      { number: 28, text: "Dann aber schrien sie zum HERRN in ihrer Not*: und er führte sie heraus aus ihren Bedrängnissen*.", footnotes: ["℘ Ps 106,44; Lk 8,24", "℘ Ps 106,44; Lk 8,24"] },
      { number: 29, text: "Er verwandelte den Sturm in Stille, und es legten sich die Wellen*.", footnotes: ["w. ihre Wellen; wahrsch. mit syr. Üs.: die Wellen des Meeres\n℘ Ps 65,8; Jon 1,15"] },
      { number: 30, text: "Sie freuten sich, dass es still geworden war*, und er führte sie in den ersehnten Hafen*.", footnotes: ["w. dass sie zur Ruhe gekommen waren", "℘ Joh 6,21"] },
      { number: 31, text: "Sie sollen den HERRN preisen für seine Gnade, für seine Wunder an den Menschenkindern." },
      { number: 32, text: "Sie sollen ihn erheben in der Versammlung des Volkes*, in der Sitzung der Ältesten ihn loben!", footnotes: ["℘ Ps 26,12"] },
      { number: 33, text: "Er macht Ströme zur Wüste und Wasserquellen zu dürrem Land*.", footnotes: ["℘ Jes 42,15"] },
      { number: 34, text: "Fruchtbares Land macht er zur Salzsteppe wegen der Bosheit seiner Bewohner*.", footnotes: ["℘ Ps 68,7; 1Mo 13,10"] },
      { number: 35, text: "Er macht die Wüste zum Wasserteich und dürres Land zu Wasserquellen*.", footnotes: ["℘ Ps 78,16; Jes 35,7"] },
      { number: 36, text: "Und er ließ Hungrige dort wohnen, damit sie Siedlungen gründen konnten." },
      { number: 37, text: "Sie besäten Felder und pflanzten Weinberge, die Frucht brachten als Ertrag*.", footnotes: ["℘ Jer 31,5"] },
      { number: 38, text: "Und er segnete sie, und sie mehrten sich sehr*, ihr Vieh ließ er nicht wenig sein*.", footnotes: ["℘ 2Mo 1,7", "℘ 5Mo 7,13"] },
      { number: 39, text: "*Und sie wurden wieder wenig und beugten sich unter der Last von Unglück und Jammer*.", footnotes: ["Manche vermuten, dass V. 39 und V. 40 versehentlich vertauscht worden sind. In diesem Falle würde der Text lauten: Er schüttete Verachtung . . ., so dass sie wenig wurden und sich beugten . . .", "℘ Hi 12,23"] },
      { number: 40, text: "Er schüttete Verachtung auf Edle, er ließ sie umherirren in wegloser Einöde*.", footnotes: ["Manche vermuten, dass V. 39 und V. 40 versehentlich vertauscht worden sind. In diesem Falle würde der Text lauten: Er schüttete Verachtung . . ., so dass sie wenig wurden und sich beugten . . .\n℘ Hi 12,21.24"] },
      { number: 41, text: "Doch den Armen hob er empor aus dem Elend* und machte seine Sippen zahlreich wie Herden*.", footnotes: ["℘ Ps 113,7; 1Sam 2,8; Lk 1,52", "℘ Jer 31,27"] },
      { number: 42, text: "Die Aufrichtigen sehen es und freuen sich*, und alle Ungerechtigkeit muss ihren Mund schließen*.", footnotes: ["℘ Ps 58,11; Hi 22,19; Jes 66,14", "℘ Hi 5,16; Mt 22,12"] },
      { number: 43, text: "Wer ist weise? Der merke sich dies*! Und sie* sollen die Gnadentaten des HERRN sorgsam beachten.", footnotes: ["℘ Jer 9,11; Hos 14,9", "nämlich die in V. 43a Angeredeten"] },
    ]},
    { number: 108, verses: [
      { number: 1, text: "Ein Lied. Ein Psalm. Von David.", heading: "Psalm 108" },
      { number: 2, text: "*Gefestigt* ist mein Herz, Gott!* Ich will singen und spielen. *Wach auf, meine Ehre!*", footnotes: ["℘ V. 2-6: Ps 57,8-12", "w. Festgestellt; d. h. ohne Schwanken, gewiss, bereit", "5 Handschr., LXX u. syr. Üs. wiederholen hier: Gefestigt ist mein Herz!", "Mas. T.: auch meine Ehre. — Da Ps 108,2—6 gleich Ps 57,8—12 ist, ist Mas. T. nach Ps 57,9 verbessert.", "Mas. T.: auch meine Ehre. — Da Ps 108,2—6 gleich Ps 57,8—12 ist, ist Mas. T. nach Ps 57,9 verbessert."] },
      { number: 3, text: "Wach auf, Harfe und Zither! Ich will aufwecken die Morgenröte." },
      { number: 4, text: "Ich will dich preisen unter den Völkern, HERR, ich will dir spielen unter den Völkerschaften." },
      { number: 5, text: "Denn groß ist deine Gnade über den Himmel hinaus, und bis zu den Wolken deine Treue*.", footnotes: ["o. Wahrheit"] },
      { number: 6, text: "Erhebe dich über den Himmel, Gott! Über der ganzen Erde sei deine Herrlichkeit!" },
      { number: 7, text: "*Damit deine Geliebten befreit werden, rette durch deine Rechte und erhöre mich!", footnotes: ["℘ V. 7-14: Ps 60,7-14"] },
      { number: 8, text: "Gott hat geredet in seinem Heiligtum: Jubeln will ich, will Sichem verteilen und das Tal Sukkot ausmessen." },
      { number: 9, text: "Mein ist Gilead, mein Manasse, und Ephraim ist der Schutz meines Hauptes, Juda mein Herrscherstab." },
      { number: 10, text: "Moab ist mein Waschbecken. Auf Edom will ich meine Sandale werfen, über Philistäa will ich jauchzen." },
      { number: 11, text: "Wer wird mich führen in die befestigte Stadt? Wer wird mich leiten bis nach Edom?" },
      { number: 12, text: "Hast du, Gott, uns nicht verworfen? Du ziehst nicht aus, Gott, mit unseren Heeren!" },
      { number: 13, text: "Schaffe uns Hilfe vor dem Bedränger! Menschenhilfe ist ja wertlos*.", footnotes: ["o. ein Nichts"] },
      { number: 14, text: "Mit Gott werden wir mächtige Taten* tun; und er, er wird unsere Bedränger zertreten.", footnotes: ["w. Macht, o. Mächtiges"] },
    ]},
    { number: 109, verses: [
      { number: 1, text: "Dem Chorleiter. Von David. Ein Psalm. Gott meines Lobes*, schweige nicht*!", heading: "Psalm 109", footnotes: ["o. Gott, mein Ruhm", "℘ Ps 83,2"] },
      { number: 2, text: "Denn den Mund des Gottlosen und den Mund des Betruges* haben sie gegen mich geöffnet, mit Lügenzungen haben sie zu mir geredet.", footnotes: ["o. der Hinterlist"] },
      { number: 3, text: "Mit Worten des Hasses haben sie mich umgeben und ohne Grund gegen mich gestritten*.", footnotes: ["℘ Ps 35,19"] },
      { number: 4, text: "Für meine Liebe feindeten sie mich an. Ich aber bin stets im Gebet*.", footnotes: ["℘ Lk 6,12"] },
      { number: 5, text: "Sie haben mir Böses für Gutes erwiesen* und Hass für meine Liebe*:", footnotes: ["℘ Ps 35,12; Spr 17,13; Jer 18,20", "Möglicherweise zitiert der Psalmist in den Versen 6—19 die Flüche seiner Feinde."] },
      { number: 6, text: "Bestelle einen Gottlosen über ihn, ein Verkläger trete zu seiner Rechten*.", footnotes: ["℘ Sach 3,1"] },
      { number: 7, text: "Aus dem Gericht gehe er als Schuldiger hervor, sein Gebet werde zur Sünde*!", footnotes: ["℘ Spr 28,9"] },
      { number: 8, text: "Seiner Tage seien wenige*, sein Amt empfange ein anderer*!", footnotes: ["℘ Ps 55,24", "℘ Apg 1,20"] },
      { number: 9, text: "Seine Kinder seien Waisen und seine Frau eine Witwe!" },
      { number: 10, text: "Herumirren, ja, herumirren sollen seine Kinder und betteln, *Überreste suchen aus ihren Trümmern*.", footnotes: ["LXX liest mit Änderung eines Buchstabens: vertrieben aus ihren Trümmern", "LXX liest mit Änderung eines Buchstabens: vertrieben aus ihren Trümmern"] },
      { number: 11, text: "Der Wucherer umgarne alles, was er hat, Fremde mögen seinen Erwerb rauben!" },
      { number: 12, text: "Er soll niemanden haben, der ihm Gnade bewahrt, und keiner sei seinen Waisen gnädig." },
      { number: 13, text: "Seine Nachkommen sollen ausgerottet werden*, in der folgenden Generation soll ihr Name erlöschen*!", footnotes: ["℘ Hi 18,19", "℘ Ps 21,11; Hi 18,17; Spr 10,7"] },
      { number: 14, text: "Der Ungerechtigkeit seiner Väter werde gedacht vor dem HERRN, nicht werde ausgelöscht die Sünde seiner Mutter*!", footnotes: ["℘ 2Mo 20,5; 34,7"] },
      { number: 15, text: "Sie seien dem HERRN stets gegenwärtig*. Er rotte ihre Erwähnung aus von der Erde*!", footnotes: ["℘ Ps 90,8", "℘ Ps 34,17"] },
      { number: 16, text: "Weil er nicht daran dachte, Gnade walten zu lassen, sondern den elenden und armen Mann verfolgte, den, der verzagten Herzens war, um ihn zu töten*.", footnotes: ["℘ Ps 10,2"] },
      { number: 17, text: "Und er liebte den Fluch, so komme er auf ihn! Und er hatte kein Gefallen an Segen, so sei er fern von ihm*!", footnotes: ["℘ Ps 59,13"] },
      { number: 18, text: "Er zog den Fluch an wie sein Gewand*, so dringe er wie Wasser in sein Inneres* und wie Öl in seine Gebeine!", footnotes: ["℘ Ps 73,6", "℘ 4Mo 5,22.27"] },
      { number: 19, text: "Er sei ihm wie ein Gewand, in das er sich hüllt, wie ein Gürtel, womit er stets sich gürtet!" },
      { number: 20, text: "Das sei die Strafe meiner Widersacher vonseiten des HERRN; und derer, die Böses reden gegen meine Seele!" },
      { number: 21, text: "Du aber, HERR, Herr, handle an mir um deines Namens willen*, denn gut ist deine Gnade, rette mich!", footnotes: ["℘ Ps 23,3"] },
      { number: 22, text: "Denn ich bin elend und arm*, und mein Herz ist verwundet in meinem Innern.", footnotes: ["℘ Ps 25,16"] },
      { number: 23, text: "Wie ein Schatten, wenn er sich streckt, gehe ich dahin*, werde abgeschüttelt wie eine Heuschrecke.", footnotes: ["℘ Ps 102,12"] },
      { number: 24, text: "Meine Knie wanken vom Fasten, mein Fleisch ist abgemagert, ohne Fett." },
      { number: 25, text: "Und ich bin ihnen zum Hohn geworden*. Wenn sie mich sehen, schütteln sie ihren Kopf*.", footnotes: ["℘ Ps 69,10.11.21", "℘ Ps 22,7.8"] },
      { number: 26, text: "Hilf mir, HERR, mein Gott! Rette mich nach deiner Gnade!" },
      { number: 27, text: "Lass sie erkennen, dass dies deine Hand ist, dass du, HERR, es getan hast*.", footnotes: ["℘ 1Kö 18,37"] },
      { number: 28, text: "Sie mögen fluchen, du aber segne*! Stehen sie auf, so lass sie beschämt werden und deinen Knecht sich freuen*!", footnotes: ["℘ 2Sam 16,12", "℘ Jes 65,14"] },
      { number: 29, text: "Kleiden mögen sich meine Widersacher mit Schande und in ihre Schmach sich hüllen wie in einen Mantel." },
      { number: 30, text: "Ich will den HERRN sehr preisen mit meinem Mund, und inmitten vieler werde ich ihn loben*.", footnotes: ["℘ Ps 22,23"] },
      { number: 31, text: "Denn er steht zur Rechten des Armen, um ihn von denen zu retten, die seine Seele richteten." },
    ]},
    { number: 110, verses: [
      { number: 1, text: "Von David. Ein Psalm. Spruch des HERRN für meinen Herrn: Setze dich zu meiner Rechten, bis ich deine Feinde gemacht habe zum Schemel deiner Füße*!", heading: "Psalm 110", footnotes: ["℘ Mt 22,44; Eph 1,20"] },
      { number: 2, text: "Den Stab deiner Macht wird der HERR aus Zion ausstrecken. Herrsche inmitten deiner Feinde!" },
      { number: 3, text: "Dein Volk ist voller Willigkeit am Tage deiner Macht*. In heiliger Pracht*, aus dem Schoß der Morgenröte *habe ich dich wie Tau gezeugt*.", footnotes: ["℘ Ri 5,2", "℘ Ps 29,2", "Mas. T.: der Tau deiner Kindschaft ist dein! Die Übersetzung stützt sich auf zahlreiche hebr. Handschr. und wichtige alte Üs.", "Mas. T.: der Tau deiner Kindschaft ist dein! Die Übersetzung stützt sich auf zahlreiche hebr. Handschr. und wichtige alte Üs.\n℘ Mi 5,6"] },
      { number: 4, text: "Geschworen hat der HERR, und es wird ihn nicht gereuen: »Du bist Priester in Ewigkeit nach der Weise Melchisedeks*!«", footnotes: ["℘ Hebr 5,6"] },
      { number: 5, text: "Der Herr zu deiner Rechten zerschmettert Könige am Tag seines Zorns*.", footnotes: ["℘ Ps 2,9; Offb 6,17"] },
      { number: 6, text: "Er wird richten unter den Nationen*, er füllt Täler* mit Leichen. Das Haupt über ein großes Land zerschmettert er*.", footnotes: ["℘ Jes 2,4; Joe 4,2.12", "So ergänzt nach alten Üs. Mas. T. hat nur: er füllt Leichen. Das Wort für »Täler« bildet mit dem Wort für »Leichen« ein Wortspiel (gewijjot geajot), kann aber dieses Gleichklangs wegen ausgefallen sein.", "℘ Ps 68,22"] },
      { number: 7, text: "Auf dem Weg wird er trinken aus dem Bach, darum wird er das Haupt erheben." },
    ]},
    { number: 111, verses: [
      { number: 1, text: "Halleluja! Preisen will ich den HERRN von ganzem Herzen im Kreis der Aufrichtigen und der Gemeinde*.", heading: "Psalm 1111", footnotes: ["℘ Ps 22,23; 149,1"] },
      { number: 2, text: "Groß sind die Taten des HERRN*, zu erforschen von allen, die Lust an ihnen haben.", footnotes: ["℘ Ps 118,15"] },
      { number: 3, text: "Majestät und Pracht ist sein Tun*, seine Gerechtigkeit besteht ewig*.", footnotes: ["℘ Ps 145,5", "℘ Ps 103,17; 112,3.9; Jes 51,6; Offb 15,3"] },
      { number: 4, text: "Er hat seinen Wundern Erwähnung verschafft*, gnädig und barmherzig ist der HERR*.", footnotes: ["℘ 1Kor 11,24.25", "℘ Ps 86,15"] },
      { number: 5, text: "Er hat Speise gegeben denen, die ihn fürchten*. Er gedenkt in Ewigkeit seines Bundes*.", footnotes: ["℘ Ps 33,18.19", "℘ Ps 105,8"] },
      { number: 6, text: "Die Kraft seiner Taten* hat er seinem Volk kundgemacht, ihnen das Erbe der Nationen zu geben*.", footnotes: ["℘ Ps 103,7; 145,12", "℘ Ps 44,3.4"] },
      { number: 7, text: "Die Taten seiner Hände sind Wahrheit* und Recht*. Zuverlässig sind alle seine Gebote*,", footnotes: ["o. Treue", "℘ Dan 9,14", "℘ Ps 19,8"] },
      { number: 8, text: "fest gegründet auf immer und ewig*, ausgeführt in Wahrheit* und Geradheit.", footnotes: ["℘ Ps 119,89", "o. Treue"] },
      { number: 9, text: "Er hat Erlösung gesandt zu seinem Volk*, seinen Bund verordnet auf ewig*. Heilig und furchtbar ist sein Name*.", footnotes: ["℘ Lk 1,68", "℘ 2Sam 23,5", "℘ Ps 99,3; 5Mo 28,58; Lk 1,49"] },
      { number: 10, text: "Die Furcht des HERRN ist der Weisheit Anfang*: eine gute Einsicht für alle, die sie* ausüben*. Sein Ruhm besteht ewig*.", footnotes: ["℘ Spr 9,10", "d. h. mit den alten Üs.: die Furcht des HERRN; mit dem Mas. T.: die in V. 7f genannten Gebote", "℘ Spr 1,7", "℘ Offb 5,13"] },
    ]},
    { number: 112, verses: [
      { number: 1, text: "Halleluja! Glücklich der Mann, der den HERRN fürchtet, der große Freude an seinen Geboten hat*!", heading: "Psalm 1121", footnotes: ["℘ Ps 1,1.2"] },
      { number: 2, text: "Seine Nachkommenschaft wird mächtig sein im Land. Das Geschlecht der Aufrichtigen wird gesegnet werden*.", footnotes: ["℘ Spr 11,21"] },
      { number: 3, text: "Vermögen und Reichtum wird in seinem Haus sein*, und seine Gerechtigkeit besteht ewig*.", footnotes: ["℘ Ps 34,10.11", "℘ Ps 111,3; 2Kor 9,9"] },
      { number: 4, text: "Den Aufrichtigen strahlt Licht auf in der Finsternis*. Er ist gnädig und barmherzig und gerecht*.", footnotes: ["℘ Ps 97,11; Hi 22,28", "℘ Ps 116,5; 145,17; Spr 21,21; Jes 58,10"] },
      { number: 5, text: "Gut steht es um den Mann, der gütig ist und leiht*! Er wird seine Sachen durchführen nach dem Recht.", footnotes: ["℘ Ps 37,26"] },
      { number: 6, text: "Denn in Ewigkeit wird er nicht wanken*, zu einer ewigen Erinnerung wird der Gerechte sein*.", footnotes: ["℘ Ps 55,23; Spr 10,30", "℘ Spr 10,7"] },
      { number: 7, text: "Er wird sich nicht fürchten vor böser Nachricht*. Fest ist sein Herz, es vertraut auf den HERRN*.", footnotes: ["℘ Spr 3,25; 1Petr 3,6", "℘ Ps 27,3"] },
      { number: 8, text: "Beständig ist sein Herz, er* fürchtet sich nicht*, bis er heruntersieht auf seine Bedränger*.", footnotes: ["o. es", "℘ Ps 49,6; 118,6", "℘ Ps 37,34"] },
      { number: 9, text: "Er streut aus, gibt den Armen*. Seine Gerechtigkeit besteht ewig*. Sein Horn ragt auf in Ehre*.", footnotes: ["℘ 1Tim 6,18", "℘ Ps 111,3; 2Kor 9,9", "℘ Ps 92,11"] },
      { number: 10, text: "Der Gottlose wird es sehen und sich ärgern, mit seinen Zähnen wird er knirschen und vergehen*. Das Begehren der Gottlosen geht verloren*.", footnotes: ["℘ Hi 20,7", "℘ Hi 8,13"] },
    ]},
    { number: 113, verses: [
      { number: 1, text: "Halleluja! Lobt, ihr Knechte des HERRN! Lobt den Namen des HERRN*!", heading: "Psalm 113", footnotes: ["℘ Ps 134,1; 135,1"] },
      { number: 2, text: "Gepriesen sei der Name des HERRN von nun an bis in Ewigkeit*!", footnotes: ["℘ Ps 115,18; Dan 2,20"] },
      { number: 3, text: "Vom Aufgang der Sonne bis zu ihrem Niedergang sei gelobt der Name des HERRN*!", footnotes: ["℘ Mal 1,11"] },
      { number: 4, text: "Hoch über alle Nationen ist der HERR, über den Himmel seine Herrlichkeit*.", footnotes: ["℘ Ps 57,12"] },
      { number: 5, text: "*Wer ist wie der HERR, unser Gott*, der hoch oben thront*,", footnotes: ["Bei Umstellung der Verse in folgender Reihenfolge: 5a, 6b, 5b, 6a ergäbe sich ein besserer Sinn.", "℘ Ps 89,7.9; 2Mo 15,11", "℘ Ps 11,4; Jes 57,15"] },
      { number: 6, text: "der in die Tiefe schaut* — im Himmel und auf Erden*?", footnotes: ["℘ Ps 33,14; Hi 28,24", "Bei Umstellung der Verse in folgender Reihenfolge: 5a, 6b, 5b, 6a ergäbe sich ein besserer Sinn."] },
      { number: 7, text: "Der aus dem Staub emporhebt den Geringen, aus dem Schmutz den Armen erhöht*,", footnotes: ["℘ Ps 107,41"] },
      { number: 8, text: "um ihn sitzen zu lassen bei Edlen, bei den Edlen seines Volkes*.", footnotes: ["℘ 1Sam 2,8"] },
      { number: 9, text: "Der die Unfruchtbare des Hauses* wohnen lässt als eine fröhliche Mutter von Söhnen*! Halleluja!", footnotes: ["d. h. die unfruchtbare Ehefrau", "℘ Jes 54,1"] },
    ]},
    { number: 114, verses: [
      { number: 1, text: "Als Israel aus Ägypten zog*, das Haus Jakob aus dem Volk, das unverständlich redete*,", heading: "Psalm 114", footnotes: ["℘ 2Mo 12,41", "℘ Ps 81,6"] },
      { number: 2, text: "da wurde Juda sein Heiligtum, Israel sein Herrschaftsbereich*.", footnotes: ["℘ 2Mo 19,6; 5Mo 7,6"] },
      { number: 3, text: "Das Meer sah es und floh*, der Jordan wandte sich zurück*.", footnotes: ["℘ 2Mo 14,21", "℘ Ps 74,15; Jos 3,16"] },
      { number: 4, text: "Die Berge hüpften wie Widder, die Hügel wie Lämmer*.", footnotes: ["w. Söhne der Herde\n℘ Ps 29,6; 2Mo 19,18"] },
      { number: 5, text: "Was war mit dir, Meer, dass du flohst? Mit dir, Jordan, dass du dich zurückwandtest?" },
      { number: 6, text: "Mit euch, Berge, dass ihr hüpftet wie Widder? Mit euch, Hügel, dass ihr hüpftet wie Lämmer*?", footnotes: ["w. Söhne der Herde"] },
      { number: 7, text: "Erbebe vor dem Herrn, Erde*, vor dem Gott Jakobs,", footnotes: ["℘ Jes 64,1.2"] },
      { number: 8, text: "der den Felsen verwandelte in einen Wasserteich, den Kieselfelsen in einen Wasserquell*!", footnotes: ["℘ Ps 78,16; 2Mo 17,6; 4Mo 20,11"] },
    ]},
    { number: 115, verses: [
      { number: 1, text: "Nicht uns, HERR, nicht uns, sondern deinem Namen gib Ehre* wegen deiner Gnade*, wegen deiner Treue*!", heading: "Psalm 115", footnotes: ["℘ Jes 48,11; Hes 36,22", "℘ Ps 44,27", "o. Wahrheit\n℘ Ps 138,2"] },
      { number: 2, text: "Warum sollen die Völker sagen: Wo ist denn ihr Gott*?", footnotes: ["℘ Ps 42,4"] },
      { number: 3, text: "Unser Gott ist im Himmel; alles, was ihm wohlgefällt, tut er*.", footnotes: ["℘ Dan 4,32"] },
      { number: 4, text: "*Ihre Götzen sind Silber und Gold, ein Werk von Menschenhänden*.", footnotes: ["℘ V. 4-8: Ps 135,15-18", "℘ Jes 44,9-17; Jer 10,3-5.9; Hab 2,18.19"] },
      { number: 5, text: "Einen Mund haben sie, reden aber nicht. Augen haben sie, sehen aber nicht." },
      { number: 6, text: "Ohren haben sie, hören aber nicht. Eine Nase haben sie, riechen aber nicht*.", footnotes: ["℘ 5Mo 4,28"] },
      { number: 7, text: "Sie haben Hände, tasten aber nicht; Füße, gehen aber nicht*. Keinen Laut geben sie mit ihrer Kehle*.", footnotes: ["℘ Offb 9,20", "℘ Jes 46,6.7"] },
      { number: 8, text: "Ihnen gleich sollen die werden, die sie machten, ein jeder, der auf sie vertraut*.", footnotes: ["℘ Jer 10,14"] },
      { number: 9, text: "Israel, vertraue auf den HERRN*! Ihre Hilfe und ihr Schild ist er*.", footnotes: ["℘ Jer 10,15", "℘ Ps 33,20"] },
      { number: 10, text: "Haus Aaron, vertraut auf den HERRN! Ihre Hilfe und ihr Schild ist er*.", footnotes: ["℘ 1Mo 15,1"] },
      { number: 11, text: "Ihr, die ihr den HERRN fürchtet*, vertraut auf den HERRN! Ihre Hilfe und ihr Schild ist er.", footnotes: ["℘ Ps 118,2-4; 135,19.20"] },
      { number: 12, text: "Der HERR hat unser gedacht*, er wird segnen*. Er segne das Haus Israel*, er segne das Haus Aaron.", footnotes: ["℘ 1Mo 8,1", "℘ Ps 67,8", "℘ Ps 3,9; 4Mo 6,27"] },
      { number: 13, text: "Er segne, die den HERRN fürchten*, die Kleinen samt den Großen*.", footnotes: ["℘ Pred 8,12; Mal 3,16", "℘ Offb 11,18; 19,5"] },
      { number: 14, text: "Der HERR mehre euch, euch und eure Kinder*!", footnotes: ["℘ Apg 2,39"] },
      { number: 15, text: "Ihr seid gesegnet vom HERRN*, der Himmel und Erde gemacht hat*.", footnotes: ["℘ 1Mo 14,19", "℘ Ps 121,2; 124,8; 134,3; 146,6; 1Mo 1,1"] },
      { number: 16, text: "Der Himmel ist der Himmel des HERRN*, die Erde aber hat er den Menschenkindern gegeben*.", footnotes: ["℘ Ps 89,12; 5Mo 10,14", "℘ 1Mo 1,28"] },
      { number: 17, text: "Die Toten werden Jah nicht loben, noch alle, die zum Schweigen hinabgehen*.", footnotes: ["℘ Ps 6,6"] },
      { number: 18, text: "Wir aber, wir werden Jah preisen von nun an bis in Ewigkeit*. Halleluja!", footnotes: ["℘ Ps 113,2"] },
    ]},
    { number: 116, verses: [
      { number: 1, text: "Ich liebe den HERRN*, denn er hörte meine Stimme, mein Flehen*.", heading: "Psalm 116", footnotes: ["℘ Ps 18,2; Joh 21,15", "℘ 1Kö 9,3; Jon 2,3"] },
      { number: 2, text: "Ja, er hat zu mir geneigt sein Ohr*; und an allen meinen Tagen werde ich ihn anrufen.", footnotes: ["℘ Ps 28,6; 31,3"] },
      { number: 3, text: "Es umfingen mich die Fesseln des Todes, die Ängste des Scheols erreichten mich. Ich geriet in* Not und Kummer*.", footnotes: ["w. Ich fand", "℘ Ps 18,5.6"] },
      { number: 4, text: "Da rief ich den Namen des HERRN an: »Bitte, HERR, rette meine Seele*!«", footnotes: ["℘ Ps 6,5"] },
      { number: 5, text: "Gnädig ist der HERR und gerecht, und unser Gott ist barmherzig*.", footnotes: ["℘ Ps 112,4"] },
      { number: 6, text: "Der HERR behütet die Einfältigen. Ich war schwach, doch er hat mich gerettet." },
      { number: 7, text: "Kehre zurück, meine Seele, zu deiner Ruhe! Denn der HERR hat dir Gutes erwiesen." },
      { number: 8, text: "Denn du hast meine Seele vom Tod gerettet, meine Augen von Tränen*, meinen Fuß vom Sturz*.", footnotes: ["℘ Jes 25,8", "℘ Jud 24"] },
      { number: 9, text: "Ich werde wandeln vor dem HERRN in den Landen der Lebendigen*.", footnotes: ["℘ Ps 27,13; 56,14"] },
      { number: 10, text: "Ich habe geglaubt, darum kann ich sagen*: »Ich bin sehr gebeugt gewesen.«", footnotes: ["w. denn ich sage\n℘ 2Kor 4,13"] },
      { number: 11, text: "Ich sprach in meiner Bestürzung: »Alle Menschen sind Lügner*!«", footnotes: ["℘ Ps 12,2.3; Röm 3,4"] },
      { number: 12, text: "Wie soll ich dem HERRN vergelten alle seine Wohltaten an mir*?", footnotes: ["℘ Mi 6,6.7"] },
      { number: 13, text: "Den Heilsbecher will ich erheben und den Namen des HERRN anrufen." },
      { number: 14, text: "Ich will dem HERRN meine Gelübde erfüllen, ja, vor seinem ganzen Volk*!", footnotes: ["℘ Ps 22,26; 65,2"] },
      { number: 15, text: "Kostbar ist in den Augen des HERRN der Tod seiner Frommen*.", footnotes: ["℘ Ps 72,14"] },
      { number: 16, text: "Ach, HERR, ich bin ja dein Knecht*! Ich bin dein Knecht, der Sohn deiner Magd*! Gelöst hast du meine Fesseln!", footnotes: ["℘ Ps 119,125; 143,12", "℘ Ps 86,16"] },
      { number: 17, text: "Dir will ich ein Dankopfer bringen*, anrufen will ich den Namen des HERRN*!", footnotes: ["℘ Ps 107,22", "℘ Lk 13,13"] },
      { number: 18, text: "Ich will dem HERRN meine Gelübde erfüllen, ja, vor seinem ganzen Volk*,", footnotes: ["℘ Ps 22,26; 65,2"] },
      { number: 19, text: "in den Vorhöfen des Hauses des HERRN*, in deiner Mitte, Jerusalem! Halleluja!", footnotes: ["℘ Ps 96,8"] },
    ]},
    { number: 117, verses: [
      { number: 1, text: "Lobt den HERRN, alle Nationen! Rühmt ihn, alle Völker*!", heading: "Psalm 117", footnotes: ["℘ Ps 45,18; 66,8"] },
      { number: 2, text: "Denn mächtig über uns ist seine Gnade*! Die Treue* des HERRN währt ewig*! Halleluja!", footnotes: ["℘ Ps 103,11", "o. Wahrheit", "℘ Ps 146,6"] },
    ]},
    { number: 118, verses: [
      { number: 1, text: "Preist den HERRN, denn er ist gut, denn seine Gnade währt ewig!", heading: "Psalm 118" },
      { number: 2, text: "Es sage Israel*: Ja, seine Gnade währt ewig!", footnotes: ["LXX liest hier: Haus Israel"] },
      { number: 3, text: "Es sage das Haus Aaron: Ja, seine Gnade währt ewig!" },
      { number: 4, text: "Es sagen, die den HERRN fürchten*: Ja, seine Gnade währt ewig*!", footnotes: ["℘ Ps 115,9-11", "℘ V. 29; Ps 100,5"] },
      { number: 5, text: "Aus der Bedrängnis rief ich zu Jah. Jah antwortete mir in der Weite*.", footnotes: ["d. h. schuf mir Raum\n℘ Ps 18,20"] },
      { number: 6, text: "Der HERR ist für mich*, ich werde mich nicht fürchten. Was könnte ein Mensch mir tun*?", footnotes: ["℘ Ps 56,10", "℘ Ps 56,5; 94,16; 112,8; Jes 51,12; Hebr 13,6"] },
      { number: 7, text: "Der HERR ist für mich unter denen, die mir helfen*. Ich werde herabsehen auf meine Hasser*.", footnotes: ["℘ Ps 54,6", "℘ Ps 59,11"] },
      { number: 8, text: "Es ist besser, sich bei dem HERRN zu bergen, als sich auf Menschen zu verlassen*.", footnotes: ["℘ Jer 17,5.7"] },
      { number: 9, text: "Es ist besser, sich bei dem HERRN zu bergen, als sich auf Edle zu verlassen*.", footnotes: ["℘ Ps 146,3.5"] },
      { number: 10, text: "Alle Nationen hatten mich umringt*. Im Namen des HERRN — ja, ich wehrte sie ab*.", footnotes: ["℘ Ps 88,18", "℘ Ps 18,41"] },
      { number: 11, text: "Sie hatten mich umringt, ja, mich eingeschlossen*. Im Namen des HERRN — ja, ich wehrte sie ab*.", footnotes: ["℘ Ps 18,41", "℘ Ps 18,41"] },
      { number: 12, text: "Sie hatten mich umringt wie Bienen*. Sie sind erloschen wie Dornenfeuer*. Im Namen des HERRN — ja, ich wehrte sie ab.", footnotes: ["℘ 5Mo 1,44", "℘ Jes 33,12"] },
      { number: 13, text: "Hart hat man* mich gestoßen, um mich zu Fall zu bringen. Aber der HERR hat mir geholfen*.", footnotes: ["so mit LXX, lat. und syr. Üs.; Mas. T.: hast du", "℘ Ps 129,2"] },
      { number: 14, text: "Meine Stärke und mein Gesang ist Jah. Er ist mir zur Rettung geworden*.", footnotes: ["℘ 2Mo 15,2; Jes 12,2"] },
      { number: 15, text: "Klang von Jubel und Heil ist in den Zelten der Gerechten*. Die Rechte des HERRN tut Gewaltiges*.", footnotes: ["℘ Ps 5,12", "℘ Ps 111,2; 2Mo 15,6"] },
      { number: 16, text: "Die Rechte des HERRN ist erhoben, die Rechte des HERRN tut Gewaltiges." },
      { number: 17, text: "Ich werde nicht sterben, sondern leben* und die Taten Jahs erzählen*.", footnotes: ["℘ Hab 1,12", "℘ Jer 51,10"] },
      { number: 18, text: "Hart hat mich Jah gezüchtigt, aber dem Tod hat er mich nicht übergeben*.", footnotes: ["℘ Hi 5,17.20; 2Kor 6,9"] },
      { number: 19, text: "Öffnet mir die Tore der Gerechtigkeit!* Ich will durch sie eingehen, Jah will ich preisen*.", footnotes: ["℘ Jes 26,2", "℘ Ps 68,5"] },
      { number: 20, text: "Dies ist das Tor des HERRN. Gerechte ziehen hier ein." },
      { number: 21, text: "Ich will dich preisen, denn du hast mich erhört und bist mir zur Rettung geworden*.", footnotes: ["℘ 2Mo 15,2; Jes 12,2"] },
      { number: 22, text: "Der Stein, den die Bauleute verworfen haben, ist zum Eckstein geworden*.", footnotes: ["℘ Jes 28,16; Lk 20,17; Apg 4,11; 1Petr 2,7"] },
      { number: 23, text: "Vom HERRN ist dies geschehen, es ist ein Wunder vor unseren Augen*.", footnotes: ["℘ Jes 28,29; Mt 21,42; Mk 12,10.11"] },
      { number: 24, text: "Dies ist der Tag, den der HERR gemacht hat! Seien wir fröhlich und freuen wir uns in ihm*!", footnotes: ["℘ Offb 19,7"] },
      { number: 25, text: "Ach, HERR, hilf doch! Ach, HERR, gib doch Gelingen!" },
      { number: 26, text: "Gesegnet sei, der kommt im Namen des HERRN*. Vom Haus des HERRN aus haben wir euch gesegnet.", footnotes: ["℘ Mt 21,9; 23,39; Mk 11,9; Lk 13,35; Joh 12,13"] },
      { number: 27, text: "Der HERR ist Gott. Er hat uns Licht gegeben*. Bindet das Festopfer mit Stricken bis an die Hörner des Altars*!", footnotes: ["℘ Lk 1,79", "℘ 2Mo 27,2"] },
      { number: 28, text: "Du bist mein Gott*, ich will dich preisen! Mein Gott, ich will dich erheben*.", footnotes: ["℘ Ps 143,10", "℘ Ps 145,1; Jes 25,1"] },
      { number: 29, text: "Preist den HERRN, denn er ist gut! Ja, seine Gnade währt ewig*!", footnotes: ["℘ V. 1"] },
    ]},
    { number: 119, verses: [
      { number: 1, text: "Glücklich sind, die im Weg untadelig sind, die im Gesetz des HERRN wandeln*.", heading: "Psalm 1191", footnotes: ["℘ Ps 128,1; Lk 1,6"] },
      { number: 2, text: "Glücklich sind, die seine Zeugnisse bewahren*, die ihn von ganzem Herzen suchen*.", footnotes: ["℘ V. 17.33.34.57.69.88.101.115.146; 5Mo 6,17; 1Kö 2,3; Lk 11,28", "℘ 5Mo 4,29; 2Chr 31,21"] },
      { number: 3, text: "Die auch kein Unrecht tun*, die auf seinen Wegen wandeln*!", footnotes: ["℘ Hes 18,17", "℘ Jer 7,23"] },
      { number: 4, text: "Du hast deine Vorschriften geboten, dass man sie eifrig beobachte*.", footnotes: ["℘ 5Mo 6,3; Mt 5,19"] },
      { number: 5, text: "Oh, dass doch meine Wege beständig wären, deine Ordnungen zu halten!" },
      { number: 6, text: "Dann werde ich nicht beschämt werden, wenn ich beachte alle deine Gebote*.", footnotes: ["℘ V. 31.80.116"] },
      { number: 7, text: "Ich will dich preisen mit aufrichtigem Herzen, wenn ich gelernt habe die Bestimmungen deiner Gerechtigkeit*.", footnotes: ["℘ V. 171"] },
      { number: 8, text: "Deine Ordnungen will ich halten*. Verlass mich nicht ganz und gar!", footnotes: ["℘ V. 145"] },
      { number: 9, text: "Wodurch hält ein Jüngling seinen Pfad rein? Indem er sich bewahrt nach deinem Wort*.", footnotes: ["℘ Ps 17,4; Spr 1,4"] },
      { number: 10, text: "Mit meinem ganzen Herzen habe ich dich gesucht*. Lass mich nicht abirren von deinen Geboten!", footnotes: ["℘ 2Chr 15,15"] },
      { number: 11, text: "In meinem Herzen habe ich dein Wort verwahrt*, damit ich nicht gegen dich sündige.", footnotes: ["℘ Lk 8,15; Kol 3,16"] },
      { number: 12, text: "Gepriesen seist du, HERR! Lehre mich deine Ordnungen*!", footnotes: ["℘ V. 26.33.64.68.108.124.135"] },
      { number: 13, text: "Mit meinen Lippen habe ich erzählt alle Bestimmungen deines Mundes*.", footnotes: ["℘ 5Mo 6,6.7"] },
      { number: 14, text: "An dem Weg deiner Zeugnisse habe ich Freude*, mehr als an allem Reichtum*.", footnotes: ["℘ V. 111", "℘ V. 72.127.162"] },
      { number: 15, text: "Deine Vorschriften will ich bedenken* und beachten deine Pfade.", footnotes: ["℘ V. 23.48.78.97.99.148; Ps 1,2"] },
      { number: 16, text: "An deinen Satzungen habe ich meine Lust*. Dein Wort vergesse ich nicht*.", footnotes: ["℘ V. 24.47.70.77.92.143.174; Jer 15,16; Röm 7,22", "℘ V. 61.83.93.109.141.153.176"] },
      { number: 17, text: "Tue Gutes an deinem Knecht, so werde ich leben*. Ich will dein Wort halten*!", footnotes: ["℘ V. 77.116.144.175", "℘ V. 2"] },
      { number: 18, text: "Öffne meine Augen*, damit ich schaue die Wunder aus deinem Gesetz.", footnotes: ["℘ Eph 1,18"] },
      { number: 19, text: "Ein Gast bin ich im Land*. Verbirg nicht vor mir deine Gebote!", footnotes: ["℘ Ps 39,13"] },
      { number: 20, text: "Meine Seele zermürbt sich vor Verlangen nach deinen Bestimmungen zu aller Zeit*.", footnotes: ["℘ V. 40"] },
      { number: 21, text: "Gescholten* hast du die Übermütigen, die Verfluchten, die abirren von deinen Geboten*.", footnotes: ["o. Angeschrien", "℘ V. 118; 5Mo 27,26"] },
      { number: 22, text: "Wälze von mir Hohn und Verachtung*! Denn deine Zeugnisse habe ich bewahrt.", footnotes: ["℘ V. 39"] },
      { number: 23, text: "Sitzen auch Oberste und verhandeln gegen mich*, dein Knecht sinnt nach über deine Ordnungen*.", footnotes: ["℘ V. 161", "℘ V. 15"] },
      { number: 24, text: "Deine Zeugnisse sind auch meine Lust*, meine Ratgeber sind sie.", footnotes: ["℘ V. 16"] },
      { number: 25, text: "Am Staub klebt meine Seele*. Belebe mich nach deinem Wort*!", footnotes: ["℘ Ps 44,26", "℘ V. 93.107.149.156; Ps 143,11"] },
      { number: 26, text: "Meine Wege habe ich erzählt, und du hast mich erhört*. Lehre mich deine Ordnungen*!", footnotes: ["℘ 2Kö 20,3-5", "℘ V. 12"] },
      { number: 27, text: "Lass mich verstehen den Weg deiner Vorschriften. Sinnen will ich über deine Wunder*.", footnotes: ["℘ Ps 77,13"] },
      { number: 28, text: "*Keinen Schlaf findet* meine Seele vor Kummer. Richte mich auf nach deinem Wort*!", footnotes: ["o. Es zerfließt", "o. Es zerfließt", "℘ Mt 5,4"] },
      { number: 29, text: "Halte fern von mir den Weg der Lüge*, und gewähre mir dein Gesetz!", footnotes: ["℘ Spr 30,8"] },
      { number: 30, text: "Den Weg der Treue habe ich erwählt, ich habe vor mich gestellt deine Bestimmungen*.", footnotes: ["℘ Ps 18,23; 5Mo 6,6-9"] },
      { number: 31, text: "Ich halte an deinen Zeugnissen fest. HERR, lass mich nicht beschämt werden*!", footnotes: ["℘ V. 6"] },
      { number: 32, text: "Den Weg deiner Gebote werde ich laufen, denn du machst mir das Herz weit*.", footnotes: ["℘ V. 45; 1Mo 26,22"] },
      { number: 33, text: "Lehre mich, HERR, den Weg deiner Ordnungen*, und ich will ihn bewahren* bis ans Ende.", footnotes: ["℘ V. 12; Jes 54,13", "℘ V. 2; Ps 39,2"] },
      { number: 34, text: "Gib mir Einsicht*, und ich will dein Gesetz bewahren* und es halten von ganzem Herzen.", footnotes: ["℘ V. 66.73.100.104.125.130.144.169; Spr 2,6", "℘ V. 2; Ps 39,2"] },
      { number: 35, text: "Leite mich auf dem Pfad deiner Gebote! Denn ich habe Gefallen daran*.", footnotes: ["℘ Ps 1,2"] },
      { number: 36, text: "Neige mein Herz zu deinen Zeugnissen und nicht zum Gewinn*!", footnotes: ["℘ Ps 141,4"] },
      { number: 37, text: "Wende meine Augen davon ab, das Eitle zu betrachten. Belebe mich auf deinen Wegen!" },
      { number: 38, text: "Halte deinem Knecht deine Zusage* aufrecht, *die deiner Furcht entspricht*!", footnotes: ["℘ V. 50.76.116.154", "Gemeint ist: die denen gilt, die dich fürchten", "Gemeint ist: die denen gilt, die dich fürchten"] },
      { number: 39, text: "Wende ab meine Schande, die ich fürchte*! Denn deine Bestimmungen sind gut.", footnotes: ["℘ V. 22"] },
      { number: 40, text: "Siehe, ich sehne mich nach deinen Vorschriften*! Belebe mich durch deine Gerechtigkeit!", footnotes: ["℘ V. 20"] },
      { number: 41, text: "Lass über mich kommen deine Gnaden, HERR, dein Heil* nach deiner Zusage*,", footnotes: ["℘ V. 81.123.174", "℘ V. 50.76.116.154"] },
      { number: 42, text: "damit ich meinem Lästerer ein Wort antworten kann. Denn ich vertraue auf dein Wort." },
      { number: 43, text: "Entziehe meinem Mund das Wort der Wahrheit* nicht allzu sehr*! Denn ich hoffe auf deine Bestimmungen*.", footnotes: ["o. Treue", "℘ Jes 59,21", "℘ V. 74.81.114.147"] },
      { number: 44, text: "Halten will ich dein Gesetz beständig, immer und ewig*.", footnotes: ["℘ V. 55.112"] },
      { number: 45, text: "Und ich werde wandeln in weitem Raum*, denn nach deinen Vorschriften habe ich geforscht*.", footnotes: ["℘ V. 32", "℘ V. 94"] },
      { number: 46, text: "Vor Königen will ich reden von deinen Zeugnissen* und mich nicht schämen*.", footnotes: ["℘ Mt 10,18", "℘ Röm 1,16"] },
      { number: 47, text: "Ich habe meine Lust an deinen Geboten*, die ich liebe*,", footnotes: ["℘ V. 16", "℘ V. 97.113.119.127.140.159.163.167"] },
      { number: 48, text: "und werde meine Hände aufheben zu deinen Geboten, die ich lieb habe*. Und über deine Ordnungen will ich nachdenken*.", footnotes: ["℘ V. 97.113.119.127.140.159.163.167", "℘ V. 15"] },
      { number: 49, text: "Gedenke des Wortes an deinen Knecht, worauf du mich hast warten lassen!" },
      { number: 50, text: "Dies ist mein Trost in meinem Elend*, dass deine Zusage mich belebt hat*.", footnotes: ["℘ V. 92", "℘ V. 38; Ps 138,7"] },
      { number: 51, text: "Die Übermütigen haben mich über die Maßen verspottet, aber von deinem Gesetz bin ich nicht abgewichen*.", footnotes: ["℘ V. 157"] },
      { number: 52, text: "Ich gedachte, HERR, deiner Bestimmungen von alters her*, und ich tröstete mich.", footnotes: ["℘ Ps 77,12"] },
      { number: 53, text: "Zornglut hat mich ergriffen* wegen der Gottlosen, die dein Gesetz verlassen*.", footnotes: ["℘ Mk 3,5", "℘ Neh 5,6"] },
      { number: 54, text: "Lieder waren mir deine Ordnungen im Haus meiner Fremdlingschaft." },
      { number: 55, text: "In der Nacht habe ich deines Namens gedacht, HERR, und ich habe dein Gesetz gehalten*.", footnotes: ["℘ V. 44"] },
      { number: 56, text: "Dies ist mir zuteilgeworden: Dass ich deine Vorschriften bewahre." },
      { number: 57, text: "*Mein Teil ist der HERR! Ich habe versprochen, deine Worte zu bewahren*.*", footnotes: ["o. Mein Teil ist der HERR!, habe ich gesagt, um deine Worte zu bewahren.", "℘ V. 2", "o. Mein Teil ist der HERR!, habe ich gesagt, um deine Worte zu bewahren."] },
      { number: 58, text: "Ich suchte dich zu besänftigen von ganzem Herzen*. Sei mir gnädig nach deiner Zusage!", footnotes: ["℘ V. 145"] },
      { number: 59, text: "Ich habe meine Wege überdacht und meine Füße gekehrt zu deinen Zeugnissen*.", footnotes: ["℘ Kla 3,40"] },
      { number: 60, text: "Ich bin geeilt und habe nicht gezögert, deine Gebote zu halten*.", footnotes: ["℘ 1Mo 18,6"] },
      { number: 61, text: "Stricke der Gottlosen haben mich umgeben. Dein Gesetz habe ich nicht vergessen*.", footnotes: ["℘ V. 16"] },
      { number: 62, text: "Um Mitternacht stehe ich auf, um dich zu preisen wegen der Bestimmungen deiner Gerechtigkeit*.", footnotes: ["℘ V. 164; Apg 16,25"] },
      { number: 63, text: "Ich bin der Gefährte aller, die dich fürchten, derer, die deine Vorschriften einhalten*.", footnotes: ["℘ V. 79"] },
      { number: 64, text: "Von deiner Gnade, HERR, ist die Erde erfüllt*. Lehre mich deine Ordnungen*!", footnotes: ["℘ Ps 33,5", "℘ V. 12"] },
      { number: 65, text: "Du hast Gutes getan an deinem Knecht, HERR, nach deinem Wort!" },
      { number: 66, text: "Gute Einsicht und Erkenntnis lehre mich! Denn ich habe deinen Geboten geglaubt*.", footnotes: ["℘ V. 34"] },
      { number: 67, text: "Bevor ich gedemütigt wurde, irrte ich. Jetzt aber halte ich dein Wort." },
      { number: 68, text: "Du bist gut und tust Gutes. Lehre mich deine Ordnungen*!", footnotes: ["℘ V. 12"] },
      { number: 69, text: "Lügen haben die Übermütigen gegen mich erdichtet.* Ich bewahre deine Vorschriften von ganzem Herzen*.", footnotes: ["eigentlich: Mit Lügen haben die Übermütigen mich besudelt.", "℘ V. 2"] },
      { number: 70, text: "Ihr Herz ist unempfindlich geworden wie Fett*. Ich habe meine Lust an deinem Gesetz*.", footnotes: ["℘ Jes 6,10", "℘ V. 16"] },
      { number: 71, text: "Es war gut für mich, dass ich gedemütigt wurde, damit ich deine Ordnungen lernte*.", footnotes: ["℘ Ps 94,12"] },
      { number: 72, text: "Lieber ist mir das Gesetz deines Mundes als Tausende von Gold- und Silberstücken*.", footnotes: ["℘ V. 14; Ps 19,11; Spr 3,13-15"] },
      { number: 73, text: "Deine Hände haben mich gemacht und bereitet*. Gib mir Einsicht, ich will deine Gebote lernen*.", footnotes: ["℘ Ps 95,6; Hi 10,8", "℘ V. 34; Kol 1,9"] },
      { number: 74, text: "Die dich fürchten, werden mich sehen und sich freuen, denn ich harre auf dein Wort*.", footnotes: ["℘ V. 43"] },
      { number: 75, text: "Ich habe erkannt, HERR, dass deine Gerichte Gerechtigkeit sind und dass du mich in Treue gedemütigt hast." },
      { number: 76, text: "Lass doch deine Gnade mir zum Trost sein nach deiner Zusage an deinen Knecht*!", footnotes: ["℘ V. 38"] },
      { number: 77, text: "Lass deine Erbarmungen über mich kommen, dass ich lebe*. Denn dein Gesetz ist meine Lust*.", footnotes: ["℘ V. 17", "℘ V. 16"] },
      { number: 78, text: "Lass beschämt werden die Übermütigen, die mich lügnerisch bedrücken*. Ich denke über deine Vorschriften nach*.", footnotes: ["℘ V. 86", "℘ V. 15"] },
      { number: 79, text: "Lass sich zu mir wenden, die dich fürchten und die deine Zeugnisse erkennen*!", footnotes: ["℘ V. 63"] },
      { number: 80, text: "Lass mein Herz untadelig sein in deinen Ordnungen, damit ich nicht in Schande komme*.", footnotes: ["℘ V. 6"] },
      { number: 81, text: "Meine Seele verzehrt sich nach deinem Heil*. Ich warte auf dein Wort*.", footnotes: ["℘ V. 41", "℘ V. 43; Ps 130,5"] },
      { number: 82, text: "Meine Augen verzehren sich nach deiner Zusage: »Wann wirst du mich trösten?«" },
      { number: 83, text: "Denn wie ein Schlauch im Rauch bin ich*. Deine Ordnungen habe ich nicht vergessen*.", footnotes: ["℘ Hi 30,30", "℘ V. 16"] },
      { number: 84, text: "Wie viele werden der Tage deines Knechts sein*? Wann wirst du Gericht halten über meine Verfolger*?", footnotes: ["℘ Ps 89,48", "℘ 2Thes 1,6"] },
      { number: 85, text: "Die Übermütigen haben mir Gruben gegraben*, sie, die nicht nach deinem Gesetz sind.", footnotes: ["℘ Ps 35,7"] },
      { number: 86, text: "Alle deine Gebote sind Treue*. Sie haben mich verfolgt ohne Grund*. Hilf mir!", footnotes: ["o. Wahrheit", "℘ V. 78"] },
      { number: 87, text: "Wenig fehlte, so hätten sie mich vernichtet im Land. Ich aber, ich habe deine Vorschriften nicht verlassen." },
      { number: 88, text: "Belebe mich nach deiner Gnade*, und ich werde bewahren das Zeugnis deines Mundes*.", footnotes: ["℘ V. 124.149", "℘ V. 2"] },
      { number: 89, text: "In Ewigkeit, HERR, steht dein Wort fest im Himmel*.", footnotes: ["℘ Ps 111,7.8; Jes 40,8; Mt 5,18; 1Petr 1,25"] },
      { number: 90, text: "Von Generation zu Generation währt deine Treue*. Du hast die Erde gegründet, und sie steht*.", footnotes: ["℘ Ps 100,5", "℘ Ps 104,5"] },
      { number: 91, text: "Nach deinen Ordnungen bestehen sie bis heute*, denn alles ist dir dienstbar.", footnotes: ["℘ Jes 40,26"] },
      { number: 92, text: "Wäre nicht dein Gesetz meine Lust gewesen*, dann wäre ich verloren gegangen in meinem Elend*.", footnotes: ["℘ V. 16", "℘ V. 50"] },
      { number: 93, text: "Ewig werde ich deine Vorschriften nicht vergessen*, denn durch sie hast du mich belebt*.", footnotes: ["℘ V. 16", "℘ V. 25"] },
      { number: 94, text: "Ich bin dein*, rette mich*! Denn ich habe nach deinen Vorschriften gesucht*.", footnotes: ["℘ Hl 6,3; Apg 27,23", "℘ V. 146.170; Ps 3,8; Jer 17,14", "℘ V. 45"] },
      { number: 95, text: "Die Gottlosen haben mir aufgelauert, um mich umzubringen*. Ich achte auf deine Zeugnisse.", footnotes: ["w. verloren gehen zu lassen"] },
      { number: 96, text: "Von allen Vollkommenen habe ich ein Ende gesehen. Doch dein Gebot reicht sehr weit." },
      { number: 97, text: "Wie liebe ich dein Gesetz*! Es ist mein Nachdenken den ganzen Tag*.", footnotes: ["℘ V. 47", "℘ V. 15"] },
      { number: 98, text: "Dein Gebot macht mich weiser als meine Feinde*. Denn ewig ist es mein!", footnotes: ["℘ 5Mo 4,6"] },
      { number: 99, text: "Verständiger bin ich als alle meine Lehrer. Denn deine Zeugnisse sind mein Überlegen*.", footnotes: ["℘ V. 15"] },
      { number: 100, text: "Einsichtiger als Greise bin ich*. Denn deine Vorschriften habe ich gehalten.", footnotes: ["℘ V. 34; Hi 32,9"] },
      { number: 101, text: "Von jedem bösen Pfad habe ich meine Füße zurückgehalten, damit ich dein Wort bewahre*.", footnotes: ["℘ V. 2; Spr 1,15"] },
      { number: 102, text: "Von deinen Bestimmungen gewichen bin ich nicht, denn du, du hast mich unterwiesen*.", footnotes: ["℘ Hi 36,22; Tit 2,12"] },
      { number: 103, text: "Wie süß sind meinem Gaumen deine Worte, mehr als Honig meinem Mund*!", footnotes: ["℘ Ps 19,11; Hes 3,3"] },
      { number: 104, text: "Aus deinen Vorschriften empfange ich Einsicht*. Darum hasse ich jeden Lügenpfad*!", footnotes: ["℘ V. 34; Hi 32,9", "℘ V. 128.163"] },
      { number: 105, text: "Eine Leuchte für meinen Fuß ist dein Wort, ein Licht für meinen Pfad*.", footnotes: ["℘ Spr 6,23; 2Petr 1,19"] },
      { number: 106, text: "Ich habe geschworen und halte es aufrecht, die Bestimmungen deiner Gerechtigkeit zu bewahren*.", footnotes: ["℘ Neh 10,30"] },
      { number: 107, text: "Ich bin über die Maßen gebeugt. HERR, belebe mich nach deinem Wort*!", footnotes: ["℘ V. 25"] },
      { number: 108, text: "Die Gaben* meines Mundes lass dir doch wohlgefallen*, HERR! Lehre mich deine Bestimmungen*!", footnotes: ["d. h. freiwilligen Gaben; vgl. 3Mo 22,23", "℘ Ps 19,15; 27,6; Hebr 13,15", "℘ V. 12"] },
      { number: 109, text: "Mein Leben ist ständig in meiner Hand*, aber dein Gesetz habe ich nicht vergessen*.", footnotes: ["Das bedeutet: stets in Gefahr.", "℘ V. 16"] },
      { number: 110, text: "Die Gottlosen haben mir eine Schlinge gelegt*, aber von deinen Vorschriften bin ich nicht abgeirrt.", footnotes: ["℘ Ps 38,13; 57,7"] },
      { number: 111, text: "Deine Zeugnisse sind mein Erbe für ewig*, denn die Freude meines Herzens sind sie*.", footnotes: ["℘ 5Mo 33,4", "℘ V. 14; Ps 19,9"] },
      { number: 112, text: "Ich habe mein Herz geneigt*, deine Ordnungen zu tun. *Für ewig ist der Lohn!*", footnotes: ["℘ Spr 2,2", "o. Für ewig bis ans Ende!", "o. Für ewig bis ans Ende!\n℘ V. 44"] },
      { number: 113, text: "Die Gemeinen hasse ich, aber ich liebe dein Gesetz*.", footnotes: ["℘ V. 47"] },
      { number: 114, text: "Mein Schutz* und mein Schild bist du*. Auf dein Wort hoffe ich*.", footnotes: ["w. Versteck", "℘ Ps 3,4; 32,7", "℘ V. 43"] },
      { number: 115, text: "Weicht von mir, ihr Übeltäter*, ich will die Gebote meines Gottes halten*!", footnotes: ["℘ Ps 139,19; Mt 7,23; Lk 13,27", "℘ V. 2"] },
      { number: 116, text: "Stütze mich nach deiner Zusage, so werde ich leben*. Lass mich nicht beschämt werden* in meiner Hoffnung!", footnotes: ["℘ V. 17.38", "℘ V. 6"] },
      { number: 117, text: "Stütze mich, dass ich gerettet werde. Und ich will beständig auf deine Ordnungen schauen*.", footnotes: ["Die alten Üs. lesen: Und ich freue mich beständig an deinen Ordnungen"] },
      { number: 118, text: "Abgewiesen hast du alle, die von deinen Ordnungen abirren*. Denn Lüge ist ihr Sinnen*.", footnotes: ["℘ V. 21", "so mit alten Üs.; Mas. T.: Denn Lüge ist ihr Trug.\n℘ Spr 12,20"] },
      { number: 119, text: "Wie Schlacken hast du hinweggeräumt alle Gottlosen des Landes*, darum liebe ich deine Zeugnisse*.", footnotes: ["℘ Hes 22,18", "℘ V. 47"] },
      { number: 120, text: "Vor deinem Schrecken schaudert mein Fleisch*, ich fürchte mich vor deinen Urteilen*.", footnotes: ["℘ Ps 88,16", "℘ Hab 3,16"] },
      { number: 121, text: "Ich habe Recht und Gerechtigkeit geübt. Überlass mich nicht meinen Unterdrückern!" },
      { number: 122, text: "Sei Bürge für deinen Knecht zum Guten! Lass die Übermütigen mich nicht unterdrücken!" },
      { number: 123, text: "Meine Augen sehnen sich nach deinem Heil* und nach der Zusage deiner Gerechtigkeit.", footnotes: ["℘ V. 41"] },
      { number: 124, text: "Handle mit deinem Knecht nach deiner Gnade* und lehre mich deine Ordnungen*!", footnotes: ["℘ V. 88; Ps 31,20", "℘ V. 12"] },
      { number: 125, text: "Dein Knecht bin ich*; gib mir Einsicht, so werde ich deine Zeugnisse erkennen*.", footnotes: ["℘ Ps 116,16", "℘ V. 34"] },
      { number: 126, text: "Es ist Zeit für den HERRN, zu handeln*. Sie haben dein Gesetz gebrochen*.", footnotes: ["℘ Ps 102,14", "o. aufgehoben\n℘ 1Kö 19,10"] },
      { number: 127, text: "Darum liebe ich deine Gebote* mehr als Gold und Feingold*.", footnotes: ["℘ V. 47", "℘ V. 14"] },
      { number: 128, text: "Darum wandle ich aufrichtig *nach allen deinen Vorschriften*. Jeden Lügenpfad hasse ich*.", footnotes: ["so mit LXX, lat. und syr. Üs.; Mas. T.: alle Befehle alles", "so mit LXX, lat. und syr. Üs.; Mas. T.: alle Befehle alles\n℘ V. 172", "℘ V. 104"] },
      { number: 129, text: "Wunderbar sind deine Zeugnisse, darum bewahrt sie meine Seele." },
      { number: 130, text: "Die Eröffnung deiner Worte leuchtet*, sie gibt Einsicht den Einfältigen*.", footnotes: ["o. erleuchtet", "℘ V. 34; Ps 19,8.9"] },
      { number: 131, text: "Ich habe meinen Mund weit aufgetan und gelechzt, denn ich sehne mich nach deinen Geboten*.", footnotes: ["℘ 1Petr 2,2"] },
      { number: 132, text: "Wende dich zu mir und sei mir gnädig* nach dem Anrecht derer, die deinen Namen lieben*!", footnotes: ["℘ Ps 25,16", "℘ Ps 5,12"] },
      { number: 133, text: "Befestige meine Schritte durch dein Wort*, und gib keinem Unrecht Macht über mich!", footnotes: ["℘ Ps 40,3"] },
      { number: 134, text: "Erlöse mich von der Bedrückung durch Menschen, und ich will deine Vorschriften einhalten." },
      { number: 135, text: "Lass dein Angesicht leuchten über deinen Knecht, und lehre mich deine Ordnungen*!", footnotes: ["℘ V. 12"] },
      { number: 136, text: "Wasserbäche fließen herab aus meinen Augen*, weil man dein Gesetz nicht hält.", footnotes: ["℘ Phil 3,18"] },
      { number: 137, text: "Gerecht bist du, HERR, und richtig sind deine Urteile*.", footnotes: ["℘ Esr 9,15; Offb 19,2"] },
      { number: 138, text: "Du hast in Gerechtigkeit deine Zeugnisse geboten* und in großer Treue*.", footnotes: ["℘ 5Mo 4,8", "w. und Treue sehr"] },
      { number: 139, text: "Verzehrt* hat mich mein Eifer, denn meine Bedränger haben deine Worte vergessen*.", footnotes: ["o. Zum Schweigen gebracht", "℘ Ps 69,10; 1Kö 19,10"] },
      { number: 140, text: "Wohlgeläutert ist dein Wort,* dein Knecht hat es lieb*.", footnotes: ["℘ Ps 12,7; Spr 30,5", "℘ V. 47"] },
      { number: 141, text: "Gering bin ich und verachtet. Deine Vorschriften habe ich nicht vergessen*.", footnotes: ["℘ V. 16"] },
      { number: 142, text: "Deine Gerechtigkeit ist eine ewige Gerechtigkeit, und dein Gesetz ist Wahrheit*.", footnotes: ["o. Treue"] },
      { number: 143, text: "Angst und Bedrängnis haben mich erreicht. Deine Gebote sind meine Lust*.", footnotes: ["℘ V. 16"] },
      { number: 144, text: "Gerechtigkeit sind deine Zeugnisse für ewig*. Gib mir Einsicht*, damit ich lebe*!", footnotes: ["℘ V. 151.160", "℘ V. 34", "℘ V. 17; Spr 4,4"] },
      { number: 145, text: "Von ganzem Herzen habe ich gerufen*: Erhöre mich, HERR! Ich will deine Ordnungen halten*.", footnotes: ["℘ V. 58", "℘ V. 8"] },
      { number: 146, text: "Zu dir habe ich gerufen: Rette mich*! Ich will deine Zeugnisse bewahren*.", footnotes: ["℘ V. 94", "℘ V. 2"] },
      { number: 147, text: "Der Morgendämmerung bin ich zuvorgekommen und habe um Hilfe gerufen*. Auf deine Worte habe ich gehofft*.", footnotes: ["℘ Ps 88,2", "℘ V. 43"] },
      { number: 148, text: "Meine Augen sind den Nachtwachen zuvorgekommen, um nachzudenken über dein Wort*.", footnotes: ["℘ V. 15"] },
      { number: 149, text: "Höre meine Stimme nach deiner Gnade*! HERR, belebe mich nach deinen Bestimmungen*!", footnotes: ["℘ V. 88", "℘ V. 25"] },
      { number: 150, text: "Nahe sind gekommen, die mich arglistig verfolgen*. Fern sind sie von deinem Gesetz*.", footnotes: ["so mit einigen hebr. Handschr. und alten Üs.; Mas. T.: die Arglist verfolgen\n℘ Mt 26,46", "℘ Jes 59,11-14"] },
      { number: 151, text: "Du bist nahe, HERR, und alle deine Gebote sind Wahrheit*.", footnotes: ["o. Treue\n℘ V. 142"] },
      { number: 152, text: "Längst habe ich aus deinen Zeugnissen erkannt, dass du sie gegründet hast auf ewig." },
      { number: 153, text: "Sieh mein Elend an und rette mich! Denn dein Gesetz habe ich nicht vergessen*.", footnotes: ["℘ V. 16"] },
      { number: 154, text: "Führe meinen Rechtsstreit* und erlöse mich! Belebe mich nach deiner Zusage*!", footnotes: ["℘ Ps 35,23; Mi 7,9", "℘ V. 38"] },
      { number: 155, text: "Fern von den Gottlosen ist das Heil, denn nach deinen Ordnungen suchen sie nicht*.", footnotes: ["℘ Jes 59,11-14"] },
      { number: 156, text: "Deiner Erbarmungen sind viele, HERR*. Belebe mich nach deinen Bestimmungen*!", footnotes: ["℘ 1Chr 21,13", "℘ V. 25"] },
      { number: 157, text: "Zahlreich sind meine Verfolger und meine Bedränger. Doch von deinen Zeugnissen bin ich nicht abgewichen*.", footnotes: ["℘ V. 51"] },
      { number: 158, text: "Die Treulosen habe ich gesehen, und es ekelte mich an, weil sie dein Wort nicht bewahrten*.", footnotes: ["℘ Ps 139,21"] },
      { number: 159, text: "Sieh, dass ich deine Vorschriften lieb habe*. Nach deiner Gnade, HERR, belebe mich!", footnotes: ["℘ V. 47"] },
      { number: 160, text: "Die Summe deines Wortes ist Wahrheit*, und jedes Urteil deiner Gerechtigkeit währt ewig*.", footnotes: ["o. Treue\n℘ Joh 17,17", "℘ V. 142"] },
      { number: 161, text: "Oberste haben mich verfolgt ohne Ursache*. Aber vor deinem Wort hat mein Herz gebebt*.", footnotes: ["℘ V. 23", "℘ Jes 66,2"] },
      { number: 162, text: "Ich freue mich über dein Wort wie einer, der große Beute macht*.", footnotes: ["℘ V. 14"] },
      { number: 163, text: "Lüge hasse und verabscheue ich*. Dein Gesetz liebe ich.*", footnotes: ["℘ V. 104", "℘ V. 47"] },
      { number: 164, text: "Siebenmal am Tag lobe ich dich wegen der Bestimmungen deiner Gerechtigkeit*.", footnotes: ["℘ V. 62"] },
      { number: 165, text: "Großen Frieden haben die, die dein Gesetz lieben. Sie trifft kein Straucheln." },
      { number: 166, text: "Ich habe auf dein Heil gewartet, HERR*, und deine Gebote habe ich erfüllt.", footnotes: ["℘ 1Mo 49,18; Kla 3,26"] },
      { number: 167, text: "Meine Seele hat deine Zeugnisse befolgt, und ich liebe sie sehr.*", footnotes: ["℘ V. 47"] },
      { number: 168, text: "Deine Vorschriften und deine Zeugnisse habe ich befolgt, denn alle meine Wege sind vor dir*.", footnotes: ["℘ Ps 139,3; Spr 5,21"] },
      { number: 169, text: "Lass mein Schreien nahe vor dich kommen, HERR! Gib mir Einsicht nach deinem Wort*!", footnotes: ["℘ V. 34"] },
      { number: 170, text: "Lass vor dich kommen mein Flehen*! Rette mich nach deiner Zusage*!", footnotes: ["℘ Jer 37,20; 42,2", "℘ V. 94"] },
      { number: 171, text: "Meine Lippen sollen Lob hervorströmen lassen, denn du lehrst mich deine Ordnungen*.", footnotes: ["℘ V. 7"] },
      { number: 172, text: "Meine Zunge soll dein Wort besingen*. Denn alle deine Gebote sind Gerechtigkeit*.", footnotes: ["o. dein Wort anheben o. anstimmen", "℘ V. 128; Röm 7,12"] },
      { number: 173, text: "Lass deine Hand mir zur Hilfe kommen! Denn ich habe deine Vorschriften erwählt." },
      { number: 174, text: "Ich sehne mich nach deiner Hilfe, HERR*! Dein Gesetz ist meine Lust*.", footnotes: ["℘ V. 41", "℘ V. 16"] },
      { number: 175, text: "Meine Seele soll leben und dich loben*! Deine Bestimmungen sollen mir helfen!", footnotes: ["℘ V. 17; Jes 38,19"] },
      { number: 176, text: "Ich bin umhergeirrt wie ein verloren gegangenes Schaf*. Suche deinen Knecht! Denn ich habe deine Gebote nicht vergessen*.", footnotes: ["℘ Jes 53,6; Hes 34,6; 1Petr 2,25", "℘ V. 16"] },
    ]},
    { number: 120, verses: [
      { number: 1, text: "Ein Wallfahrtslied*. Zum HERRN rief ich in meiner Not, und er erhörte mich*.", heading: "Psalm 120", footnotes: ["w. Lied des Hinaufgangs; damit ist wahrscheinlich das Hinaufziehen nach Jerusalem gemeint. Es kann aber auch das Besteigen der Vorhallen- und Altarstufen im Tempel gemeint sein; dann: Ein Stufenlied\n℘ Ps 121-134", "℘ Ps 50,15; Jon 2,3"] },
      { number: 2, text: "HERR, rette meine Seele vor der Lügenlippe, vor falscher Zunge*.", footnotes: ["℘ Ps 52,6; Mi 6,12"] },
      { number: 3, text: "Was wird er dir geben? Was dir hinzufügen, du falsche Zunge?" },
      { number: 4, text: "Scharfe Pfeile eines Starken* samt glühenden Ginsterkohlen*.", footnotes: ["℘ Jer 9,7", "Eine lange glühende Holzkohlenart, die zum Schmieden von Pfeilspitzen verwendet wurde."] },
      { number: 5, text: "Weh mir, dass ich Gast war in Mesech, dass ich wohnte bei den Zelten Kedars!" },
      { number: 6, text: "Lange hat meine Seele bei denen gewohnt, die den Frieden hassen." },
      { number: 7, text: "Ich will nur Frieden*. Aber wenn ich rede, so sind sie für Krieg*.", footnotes: ["w. Ich bin Friede", "℘ Röm 3,17"] },
    ]},
    { number: 121, verses: [
      { number: 1, text: "Ein Wallfahrtslied. Ich hebe meine Augen auf* zu den Bergen. Woher wird meine Hilfe kommen?", heading: "Psalm 121", footnotes: ["℘ Ps 123,1"] },
      { number: 2, text: "Meine Hilfe kommt vom HERRN, der Himmel und Erde gemacht hat*.", footnotes: ["℘ Ps 115,15; 1Mo 1,1"] },
      { number: 3, text: "Er wird nicht zulassen, dass dein Fuß wanke*. Dein Hüter schlummert nicht.", footnotes: ["℘ Ps 55,23; 1Sam 2,9; Spr 3,26"] },
      { number: 4, text: "Siehe, nicht schlummert und nicht schläft der Hüter Israels." },
      { number: 5, text: "Der HERR ist dein Hüter, der HERR ist dein Schatten über deiner rechten Hand." },
      { number: 6, text: "Am Tag wird die Sonne dich nicht stechen, der Mond nicht bei Nacht*.", footnotes: ["℘ Jes 49,10"] },
      { number: 7, text: "Der HERR wird dich behüten vor allem Unheil*, er wird dein Leben* behüten*.", footnotes: ["℘ 1Mo 28,15; Spr 12,21; 2Tim 4,18", "o. deine Seele", "℘ Ps 97,10"] },
      { number: 8, text: "Der HERR wird deinen Ausgang und deinen Eingang behüten* von nun an bis in Ewigkeit*.", footnotes: ["℘ 5Mo 28,6", "℘ Ps 125,2; 131,3"] },
    ]},
    { number: 122, verses: [
      { number: 1, text: "Ein Wallfahrtslied. Von David. Ich freute mich, als sie zu mir sagten: »Wir gehen zum Haus des HERRN*!«", heading: "Psalm 122", footnotes: ["℘ Ps 26,8"] },
      { number: 2, text: "Unsere Füße standen dann in deinen Toren, Jerusalem." },
      { number: 3, text: "Jerusalem, die du aufgebaut bist als eine fest in sich geschlossene Stadt," },
      { number: 4, text: "wohin die Stämme hinaufziehen*, die Stämme Jahs, ein Mahnzeichen für Israel*, um den Namen des HERRN zu preisen*.", footnotes: ["℘ 5Mo 16,16", "℘ Ps 81,6", "℘ Ps 100,4; Joh 4,20"] },
      { number: 5, text: "Denn dort stehen Throne zum Gericht*, die Throne des Hauses David*.", footnotes: ["℘ 5Mo 17,8; 2Chr 19,8", "℘ 1Kö 7,7"] },
      { number: 6, text: "Erbittet Heil* für Jerusalem*! Ruhe sollen die haben, die dich lieben*!", footnotes: ["o. Frieden", "℘ Ps 51,20", "℘ Neh 11,2; Jes 66,10"] },
      { number: 7, text: "Heil* sei in deinen Festungswerken, sichere Ruhe in deinen Palästen.", footnotes: ["o. Frieden"] },
      { number: 8, text: "Wegen meiner Brüder und meiner Freunde will ich sagen: Heil* sei in dir!", footnotes: ["o. Frieden"] },
      { number: 9, text: "Wegen des Hauses des HERRN, unseres Gottes, will ich dein Bestes suchen." },
    ]},
    { number: 123, verses: [
      { number: 1, text: "Ein Wallfahrtslied. Zu dir hebe ich meine Augen auf*, der du im Himmel thronst*.", heading: "Psalm 123", footnotes: ["℘ Ps 121,1", "℘ Ps 2,4"] },
      { number: 2, text: "Siehe: Wie die Augen der Knechte auf die Hand ihres Herrn, wie die Augen der Magd auf die Hand ihrer Gebieterin, so sind unsere Augen gerichtet auf den HERRN, unseren Gott*, bis er uns gnädig ist.", footnotes: ["℘ Ps 25,15; 2Chr 20,12"] },
      { number: 3, text: "Sei uns gnädig, HERR, sei uns gnädig! Denn reichlich sind wir mit Verachtung gesättigt*.", footnotes: ["℘ Ps 44,14"] },
      { number: 4, text: "Reichlich ist unsere Seele gesättigt mit dem Spott der Sorglosen, mit der Verachtung der Hochmütigen*.", footnotes: ["℘ Hebr 11,36"] },
    ]},
    { number: 124, verses: [
      { number: 1, text: "Ein Wallfahrtslied. Von David. Wenn nicht der HERR für uns gewesen wäre*, so soll Israel sagen —", heading: "Psalm 124", footnotes: ["℘ Ps 56,10"] },
      { number: 2, text: "wenn nicht der HERR für uns gewesen wäre*, als Menschen gegen uns aufstanden*,", footnotes: ["℘ Ps 56,10", "℘ Ps 3,2"] },
      { number: 3, text: "dann hätten sie uns lebendig verschlungen*, als ihr Zorn gegen uns entbrannte*.", footnotes: ["℘ Spr 1,12", "℘ Ps 83,5"] },
      { number: 4, text: "Dann hätten uns die Wasser fortgeschwemmt, der Wildbach hätte uns* überströmt*.", footnotes: ["w. unsere Seelen", "℘ Ps 18,5; 42,8; 144,7"] },
      { number: 5, text: "Dann wären über uns* gegangen die tobenden Wasser.", footnotes: ["w. unsere Seelen"] },
      { number: 6, text: "Gepriesen sei der HERR, der uns ihren Zähnen nicht zum Raub gab!" },
      { number: 7, text: "Unsere Seele ist entronnen wie ein Vogel aus der Schlinge der Vogelsteller*. Die Schlinge ist zerrissen, und wir sind entronnen*.", footnotes: ["℘ Ps 91,3; Spr 6,5", "℘ Ps 129,4"] },
      { number: 8, text: "Unsere Hilfe steht im Namen des HERRN*, der Himmel und Erde gemacht hat*.", footnotes: ["℘ Ps 20,8", "℘ Ps 115,15"] },
    ]},
    { number: 125, verses: [
      { number: 1, text: "Ein Wallfahrtslied. Die auf den HERRN vertrauen, sind wie der Berg Zion, der nicht wankt*, der ewig bleibt*.", heading: "Psalm 125", footnotes: ["℘ Ps 46,6; 62,7", "℘ Spr 10,25.30; Jes 26,3.4"] },
      { number: 2, text: "Jerusalem — Berge sind rings um es her. So ist der HERR rings um sein Volk*, von nun an bis in Ewigkeit*.", footnotes: ["℘ 2Kö 6,17", "℘ Ps 121,8"] },
      { number: 3, text: "Denn das Zepter der Gottlosigkeit wird nicht mehr ruhen auf dem Erbe der Gerechten, damit nicht auch die Gerechten ihre Hände nach Unrecht ausstrecken." },
      { number: 4, text: "Tu Gutes, HERR, den Guten und denen, die aufrichtig sind in ihren Herzen*!", footnotes: ["℘ Ps 84,12"] },
      { number: 5, text: "Die aber auf ihre krummen Wege abbiegen*, die wird der HERR dahinfahren lassen samt den Übeltätern*. Friede über Israel*!", footnotes: ["℘ Spr 2,15; Jes 59,8", "℘ Ps 92,8.10; 94,4", "℘ Ps 128,6; Gal 6,16"] },
    ]},
    { number: 126, verses: [
      { number: 1, text: "Ein Wallfahrtslied. Als der HERR die Gefangenen* Zions zurückführte*, waren wir wie Träumende.", heading: "Psalm 126", footnotes: ["eigentlich: die Heimkehrenden", "℘ Ps 14,7; 85,2; Esr 1,11; Jer 33,26"] },
      { number: 2, text: "Da wurde unser Mund voll Lachen und unsere Zunge voll Jubel*. Da sagte man unter den Nationen: »Der HERR hat Großes an ihnen getan*!«", footnotes: ["℘ Hi 8,21; Jes 35,10; 51,11", "℘ Hes 36,36"] },
      { number: 3, text: "Der HERR hat Großes an uns getan*: Wir waren fröhlich*!", footnotes: ["℘ Lk 1,49; 8,39", "℘ Joe 2,21"] },
      { number: 4, text: "Bringe zurück, HERR, unsere Gefangenen*, gleich den Bächen im Südland*.", footnotes: ["o. Wende, HERR, unser Schicksal\n℘ Jer 29,14; 30,3", "℘ Jes 41,18"] },
      { number: 5, text: "Die mit Tränen säen, werden mit Jubel ernten*.", footnotes: ["℘ Jer 31,9-13; Mt 5,4"] },
      { number: 6, text: "Er geht weinend hin und trägt den Samen zum Säen*. Er kommt heim mit Jubel und trägt seine Garben*.", footnotes: ["w. tragend den Beutel (die Tasche mit Saatgut) zum Säen", "℘ Ps 30,6"] },
    ]},
    { number: 127, verses: [
      { number: 1, text: "Ein Wallfahrtslied. Von Salomo*. Wenn der HERR das Haus nicht baut, arbeiten seine Erbauer vergebens daran. Wenn der HERR die Stadt nicht bewacht, wacht der Wächter vergebens.", heading: "Psalm 127", footnotes: ["℘ Ps 72,1"] },
      { number: 2, text: "Vergebens ist es für euch, dass ihr früh aufsteht, euch spät niedersetzt*, das Brot der Mühsal esst. So viel gibt er seinem Geliebten im Schlaf*.", footnotes: ["℘ Joh 21,3", "℘ Spr 10,22"] },
      { number: 3, text: "Siehe, ein Erbe vom HERRN sind Söhne, eine Belohnung die Leibesfrucht*.", footnotes: ["℘ Ps 128,3.4; 5Mo 28,11"] },
      { number: 4, text: "Wie Pfeile in der Hand eines Helden, so sind die Söhne der Jugend." },
      { number: 5, text: "Glücklich der Mann, der seinen Köcher mit ihnen gefüllt hat! Sie werden nicht beschämt werden, wenn sie mit Feinden reden im Tor." },
    ]},
    { number: 128, verses: [
      { number: 1, text: "Ein Wallfahrtslied. Glücklich ein jeder, der den HERRN fürchtet, der wandelt auf seinen Wegen*!", heading: "Psalm 128", footnotes: ["℘ Ps 119,1"] },
      { number: 2, text: "Denn essen wirst du die Arbeit deiner Hände. Heil dir! Gut steht es um dich*.", footnotes: ["w. und Gutes dir\n℘ Ps 1,3; 5Mo 28,8; Jes 3,10"] },
      { number: 3, text: "Deine Frau gleicht einem fruchtbaren Weinstock im Innern deines Hauses, deine Söhne den Ölbaumsprossen, rings um deinen Tisch*.", footnotes: ["℘ Ps 127,3; 144,12"] },
      { number: 4, text: "Siehe, so wird gesegnet sein der Mann, der den HERRN fürchtet*.", footnotes: ["℘ 5Mo 28,2"] },
      { number: 5, text: "Es segne dich der HERR von Zion aus*. Schaue das Wohl Jerusalems alle Tage deines Lebens*,", footnotes: ["℘ Ps 20,3", "℘ Jes 33,20"] },
      { number: 6, text: "und sieh deiner Kinder Kinder*! — Friede über Israel*! //", footnotes: ["℘ 1Mo 50,23; Hi 42,16", "℘ Ps 125,5"] },
    ]},
    { number: 129, verses: [
      { number: 1, text: "Ein Wallfahrtslied. Oft haben sie mich bedrängt von meiner Jugend an* — so soll Israel sagen —,", heading: "Psalm 129", footnotes: ["℘ 2Mo 1,11-14"] },
      { number: 2, text: "oft haben sie mich bedrängt von meiner Jugend an*; dennoch haben sie mich nicht überwältigt*.", footnotes: ["℘ 2Mo 1,11-14", "℘ Ps 118,13; 2Kor 4,8"] },
      { number: 3, text: "Pflüger haben auf meinem Rücken gepflügt, haben lang gezogen ihre Furchen*.", footnotes: ["℘ Jes 50,6; 51,23"] },
      { number: 4, text: "Der HERR ist gerecht*! Er hat durchschnitten den Strick der Gottlosen*.", footnotes: ["℘ Ps 7,12", "℘ Ps 124,7"] },
      { number: 5, text: "Mögen beschämt werden und zurückweichen alle, die Zion hassen*!", footnotes: ["℘ Ps 40,15; Jes 29,8"] },
      { number: 6, text: "Mögen sie sein wie das Gras auf den Dächern, das verdorrt, ehe man es ausreißt*,", footnotes: ["℘ Ps 37,2; Jes 37,27"] },
      { number: 7, text: "womit der Schnitter seine Hand nicht füllt noch der Garbenbinder seinen Arm*;", footnotes: ["w. Gewandbausch; s. Anm. zu Ps 89,51"] },
      { number: 8, text: "und wo die Vorübergehenden nicht sagen: Des HERRN Segen über euch! — Wir segnen euch im Namen des HERRN*.", footnotes: ["℘ 2Sam 6,18"] },
    ]},
    { number: 130, verses: [
      { number: 1, text: "Ein Wallfahrtslied. Aus den Tiefen rufe ich zu dir, HERR*.", heading: "Psalm 130", footnotes: ["℘ Kla 3,55"] },
      { number: 2, text: "Herr, höre auf meine Stimme! Lass deine Ohren aufmerksam sein auf die Stimme meines Flehens*!", footnotes: ["℘ Ps 5,3; 28,2"] },
      { number: 3, text: "Wenn du, Jah, die Sünden anrechnest*, Herr, wer wird bestehen*?", footnotes: ["w. beachtest, o. bewahrst", "℘ Ps 143,2; Hi 9,2.3"] },
      { number: 4, text: "Doch bei dir ist die Vergebung*, damit man dich fürchte*.", footnotes: ["℘ Ps 103,3; 2Mo 34,7; Jes 55,7; Dan 9,9; Mi 7,18; Eph 1,7", "℘ 1Kö 8,39.40"] },
      { number: 5, text: "Ich hoffe auf den HERRN, meine Seele hofft*, und auf sein Wort harre ich*.", footnotes: ["℘ Ps 33,20", "℘ Ps 119,81"] },
      { number: 6, text: "Meine Seele harrt auf den Herrn*, mehr als die Wächter auf den Morgen, die Wächter auf den Morgen.", footnotes: ["℘ Ps 39,8"] },
      { number: 7, text: "Harre, Israel, auf den HERRN*! Denn bei dem HERRN ist die Gnade*, und viel Erlösung bei ihm.", footnotes: ["℘ Ps 131,3", "℘ Ps 86,5"] },
      { number: 8, text: "Ja, er wird Israel erlösen von allen seinen Sünden*.", footnotes: ["℘ Ps 103,3; Jes 44,22; Mt 1,21; Lk 1,68"] },
    ]},
    { number: 131, verses: [
      { number: 1, text: "Ein Wallfahrtslied. Von David. HERR! Mein Herz will nicht hoch hinaus, meine Augen sind nicht hochmütig*. Ich gehe nicht mit Dingen um, die zu groß und zu wunderbar für mich sind.", heading: "Psalm 131", footnotes: ["℘ 2Sam 6,22; Spr 21,4"] },
      { number: 2, text: "Habe ich meine Seele nicht beschwichtigt und beruhigt? Wie ein entwöhntes Kind bei seiner Mutter, wie ein entwöhntes Kind ist meine Seele in mir." },
      { number: 3, text: "Harre, Israel, auf den HERRN*, von nun an bis in Ewigkeit*!", footnotes: ["℘ Ps 130,7", "℘ Ps 121,8"] },
    ]},
    { number: 132, verses: [
      { number: 1, text: "Ein Wallfahrtslied. Gedenke, HERR, dem David alle seine Mühsal*!", heading: "Psalm 132", footnotes: ["℘ Ps 25,18"] },
      { number: 2, text: "Der dem HERRN schwor, ein Gelübde tat dem Mächtigen Jakobs*:", footnotes: ["℘ 1Mo 49,24"] },
      { number: 3, text: "»Ich will* das Zelt meines Hauses nicht betreten, ich will das Lager meines Bettes nicht besteigen,", footnotes: ["w. Wenn ich betrete . . ., dann . . .!; hebr. Schwurformel; so auch entsprechend in V. 3b und V. 4"] },
      { number: 4, text: "ich will meinen Augen keinen Schlaf gestatten, keinen Schlummer meinen Augenlidern," },
      { number: 5, text: "bis ich eine Stätte finde für den HERRN, Wohnungen für den Starken Jakobs*!«", footnotes: ["℘ 2Sam 7,1; 1Kö 8,17; 1Chr 28,2; Apg 7,46"] },
      { number: 6, text: "Siehe, wir hören von ihr* in Efrata, wir fanden sie in dem Gebiete Jaars*.", footnotes: ["d. h. von der Bundeslade", "Wahrscheinlich eine dichterische Bezeichnung für Kirjat-Jearim, das im Gebiet von Efrata lag.\n℘ 1Sam 7,1; 2Sam 6,3"] },
      { number: 7, text: "Lasst uns einziehen in seine Wohnungen, niederfallen vor dem Schemel seiner Füße*!", footnotes: ["℘ Ps 99,5; Kla 2,1"] },
      { number: 8, text: "Erhebe dich, HERR, zu deiner Ruhe, du und die Lade deiner Stärke!" },
      { number: 9, text: "Deine Priester sollen sich bekleiden mit Gerechtigkeit*, und deine Frommen sollen jubeln*!", footnotes: ["℘ Hi 29,14; Offb 19,8", "℘ 2Chr 6,41"] },
      { number: 10, text: "Wegen Davids, deines Knechtes*, weise nicht ab das Angesicht deines Gesalbten*!", footnotes: ["℘ Ps 144,10", "℘ Ps 84,10; 2Chr 6,42"] },
      { number: 11, text: "Der HERR hat David einen Treueid* geschworen*, er wird nicht davon abweichen*: »Von der Frucht deines Leibes will ich auf deinen Thron setzen*.", footnotes: ["w. eine Treue o. Wahrheit", "℘ Ps 89,4; Apg 13,23", "℘ 4Mo 23,19", "℘ Ps 89,5; 2Sam 7,12; Lk 1,32; Joh 7,42; Apg 2,30"] },
      { number: 12, text: "Wenn deine Söhne meinen Bund und meine Zeugnisse bewahren*, die ich sie lehren werde, so sollen auch ihre Söhne für immer auf deinem Thron sitzen*.«", footnotes: ["℘ 1Kö 8,25", "℘ 2Chr 7,18; Jer 33,17"] },
      { number: 13, text: "Denn der HERR hat Zion erwählt, hat ihn begehrt zu seiner Wohnstätte*:", footnotes: ["℘ Ps 9,12"] },
      { number: 14, text: "»Dies ist meine Ruhestatt für immer, hier will ich wohnen, denn ich habe ihn* begehrt.", footnotes: ["d. h. den Berg u. die Stadt Zion"] },
      { number: 15, text: "Seine Speise will ich reichlich segnen, seine Armen mit Brot sättigen." },
      { number: 16, text: "Seine Priester will ich bekleiden mit Heil*, seine Frommen sollen laut jubeln*.", footnotes: ["℘ Jes 61,10", "℘ 2Chr 6,41"] },
      { number: 17, text: "Dort will ich das Horn Davids wachsen lassen*, habe ich ein Licht zugerichtet meinem Gesalbten*.", footnotes: ["w. David ein Horn sprossen lassen\n℘ Ps 89,25; 1Sam 2,10; Lk 1,69", "℘ 1Kö 15,4; 2Chr 21,7"] },
      { number: 18, text: "Seine Feinde will ich bekleiden mit Schande*, aber auf ihm wird seine Krone glänzen*.«", footnotes: ["℘ Ps 35,26", "w. blühen"] },
    ]},
    { number: 133, verses: [
      { number: 1, text: "Ein Wallfahrtslied. Von David. Siehe, wie gut und wie lieblich ist es, wenn Brüder einträchtig beieinander wohnen.", heading: "Psalm 133" },
      { number: 2, text: "Wie das köstliche Öl auf dem Haupt, das herabfließt auf den Bart, auf den Bart Aarons*, der* herabfließt auf den Halssaum seiner Kleider.", footnotes: ["℘ 2Mo 29,7", "o. das"] },
      { number: 3, text: "Wie der Tau des Hermon, der herabfließt auf die Berge Zions. Denn dorthin hat der HERR den Segen befohlen, Leben bis in Ewigkeit*.", footnotes: ["℘ Ps 21,5"] },
    ]},
    { number: 134, verses: [
      { number: 1, text: "Ein Wallfahrtslied. Auf*! preist den HERRN*, all ihr Knechte des HERRN*, die ihr steht im Haus des HERRN in den Nächten*!", heading: "Psalm 134", footnotes: ["w. Siehe", "℘ Ps 113,1", "℘ Ps 135,1.2", "℘ 1Chr 9,33"] },
      { number: 2, text: "Erhebt eure Hände* im* Heiligtum* und preist den HERRN!", footnotes: ["℘ Ps 63,5; Kla 3,41; 1Tim 2,8", "o. zum", "℘ Ps 28,2; 141,2"] },
      { number: 3, text: "Der HERR segne dich von Zion aus*, er, der Himmel und Erde gemacht hat*!", footnotes: ["℘ Ps 128,5", "℘ Ps 115,15; 136,5.6; Sach 12,1"] },
    ]},
    { number: 135, verses: [
      { number: 1, text: "Halleluja! Lobt den Namen des HERRN! Lobt, ihr Knechte des HERRN*,", heading: "Psalm 135", footnotes: ["℘ Ps 113,1; Offb 19,5"] },
      { number: 2, text: "die ihr steht im Hause des HERRN*, in den Vorhöfen des Hauses unseres Gottes!", footnotes: ["℘ Ps 134,1"] },
      { number: 3, text: "Halleluja! Denn gut ist der HERR*; spielt seinem Namen, denn er ist lieblich*.", footnotes: ["℘ Ps 106,1", "℘ Ps 54,8"] },
      { number: 4, text: "Denn Jah hat sich Jakob erwählt*, Israel zu seinem Eigentum*.", footnotes: ["℘ Ps 105,6; Joh 15,16; Apg 13,17", "℘ Ps 33,12; 2Mo 19,5; 5Mo 7,6; 26,18; Tit 2,14"] },
      { number: 5, text: "Ja, ich habe erkannt, dass der HERR groß ist, unser Herr ist größer als alle Götter*.", footnotes: ["℘ Ps 86,8; 147,5"] },
      { number: 6, text: "Alles, was dem HERRN wohlgefällt, tut er in den Himmeln und auf der Erde, in den Meeren und in allen Tiefen." },
      { number: 7, text: "Der Nebelschwaden aufsteigen lässt vom Ende der Erde*, der Blitze zum* Regen macht*, der den Wind herausführt aus seinen Vorratskammern*;", footnotes: ["℘ 1Mo 2,6; Jer 10,13; 51,16", "o. für den", "℘ Hi 28,26; 38,25; Sach 10,1", "℘ Ps 78,26"] },
      { number: 8, text: "der die Erstgeborenen Ägyptens schlug vom Menschen bis zum Vieh*.", footnotes: ["℘ Ps 78,51"] },
      { number: 9, text: "Zeichen und Wunder sandte er in deine Mitte, Ägypten, gegen den Pharao und gegen alle seine Knechte*.", footnotes: ["℘ Ps 78,12.43-51"] },
      { number: 10, text: "*Der viele Nationen schlug und starke Könige tötete:", footnotes: ["℘ V. 10-12: Ps 136,17-22"] },
      { number: 11, text: "Sihon, den König der Amoriter*, und Og, den König von Baschan*, und alle Königreiche Kanaans*.", footnotes: ["℘ 4Mo 21,24", "℘ 4Mo 21,35", "℘ Jos 12,7-24"] },
      { number: 12, text: "Und er gab ihr Land als Erbe, als Erbe seinem Volk Israel." },
      { number: 13, text: "HERR, dein Name währt ewig, HERR, dein Lob* von Geschlecht zu Geschlecht*.", footnotes: ["w. deine Anrufung", "℘ Ps 102,13"] },
      { number: 14, text: "Ja, der HERR wird seinem Volk Recht schaffen, über seine Knechte wird er sich erbarmen*.", footnotes: ["w. wird er sich's gereuen lassen\n℘ 5Mo 32,36"] },
      { number: 15, text: "*Die Götzen der Nationen sind aus Silber und Gold, ein Werk von Menschenhänden.", footnotes: ["℘ V. 15-18: Ps 115,4-8"] },
      { number: 16, text: "Einen Mund haben sie, reden aber nicht. Augen haben sie, sehen aber nicht." },
      { number: 17, text: "Ohren haben sie, hören aber nicht. Auch ist kein Atem in ihrem Mund." },
      { number: 18, text: "Ihnen gleich sind die, die sie machen, ein jeder, der auf sie vertraut*.", footnotes: ["℘ Jes 42,17"] },
      { number: 19, text: "Haus Israel*, preist den HERRN! Haus Aaron, preist den HERRN!", footnotes: ["℘ Ps 115,12"] },
      { number: 20, text: "Haus Levi, preist den HERRN! Die ihr den HERRN fürchtet*, preist den HERRN!", footnotes: ["℘ Ps 115,9-11"] },
      { number: 21, text: "Gepriesen sei der HERR von Zion aus, der in Jerusalem wohnt*! Halleluja!", footnotes: ["℘ Ps 48,2.3; 1Chr 23,25; Jes 12,6"] },
    ]},
    { number: 136, verses: [
      { number: 1, text: "Preist den HERRN, denn er ist gut. Denn seine Gnade währt ewig*!", heading: "Psalm 136", footnotes: ["℘ Ps 100,5; 1Chr 16,34; Esr 3,11"] },
      { number: 2, text: "Preist den Gott der Götter*, denn seine Gnade währt ewig!", footnotes: ["℘ Ps 97,9"] },
      { number: 3, text: "Preist den Herrn der Herren*! Denn seine Gnade währt ewig!", footnotes: ["℘ 5Mo 10,17; 1Tim 6,15"] },
      { number: 4, text: "Den, der große Wunder tut, er allein*. Denn seine Gnade währt ewig!", footnotes: ["℘ Ps 72,18"] },
      { number: 5, text: "Den, der den Himmel gemacht hat mit Einsicht*. Denn seine Gnade währt ewig!", footnotes: ["℘ 1Mo 1,7.8; Spr 3,19; Jer 10,12; Offb 14,7"] },
      { number: 6, text: "Den, der die Erde ausgebreitet hat über dem Wasser*. Denn seine Gnade währt ewig!", footnotes: ["℘ Ps 24,2"] },
      { number: 7, text: "Den, der große Lichter gemacht hat*. Denn seine Gnade währt ewig!", footnotes: ["℘ 1Mo 1,14"] },
      { number: 8, text: "Die Sonne zur Herrschaft am Tage — denn seine Gnade währt ewig!" },
      { number: 9, text: "Den Mond und die Sterne* zur Herrschaft in der Nacht*. Denn seine Gnade währt ewig!", footnotes: ["℘ Ps 8,4; 74,16; 1Mo 1,16", "℘ Jer 31,35"] },
      { number: 10, text: "Den, der Ägypten schlug an seinen Erstgeborenen*. Denn seine Gnade währt ewig!", footnotes: ["℘ Ps 78,51"] },
      { number: 11, text: "Der Israel herausführte aus ihrer Mitte* — denn seine Gnade währt ewig!", footnotes: ["℘ Ps 105,37; 2Mo 12,41"] },
      { number: 12, text: "Mit starker Hand und mit ausgestrecktem Arm*. Denn seine Gnade währt ewig!", footnotes: ["℘ 2Mo 13,3; 5Mo 4,34.37"] },
      { number: 13, text: "Den, der das Schilfmeer in zwei Teile zerteilte*. Denn seine Gnade währt ewig!", footnotes: ["℘ Ps 78,13"] },
      { number: 14, text: "Und Israel mitten hindurchführte*. Denn seine Gnade währt ewig!", footnotes: ["℘ 2Mo 14,22"] },
      { number: 15, text: "Und den Pharao und sein Heer ins Schilfmeer abschüttelte*. Denn seine Gnade währt ewig!", footnotes: ["℘ Ps 78,53; 2Mo 14,27"] },
      { number: 16, text: "Den, der sein Volk durch die Wüste führte*. Denn seine Gnade währt ewig!", footnotes: ["℘ 5Mo 8,2.15; Neh 9,19"] },
      { number: 17, text: "*Den, der große Könige schlug. Denn seine Gnade währt ewig!", footnotes: ["℘ V. 17-22: Ps 135,10-12"] },
      { number: 18, text: "Und mächtige Könige tötete. Denn seine Gnade währt ewig!" },
      { number: 19, text: "Sihon, den König der Amoriter*, denn seine Gnade währt ewig!", footnotes: ["℘ 5Mo 2,33"] },
      { number: 20, text: "Und Og, den König von Baschan*, denn seine Gnade währt ewig!", footnotes: ["℘ 5Mo 3,3"] },
      { number: 21, text: "Und ihr Land zum Erbe gab*, denn seine Gnade währt ewig!", footnotes: ["℘ 5Mo 3,18"] },
      { number: 22, text: "Zum Erbe Israel*, seinem Knecht. Denn seine Gnade währt ewig!", footnotes: ["℘ Jes 41,8"] },
      { number: 23, text: "Der unser gedachte in unserer Niedrigkeit*, denn seine Gnade währt ewig!", footnotes: ["℘ Ps 106,44-46"] },
      { number: 24, text: "Und uns unseren Bedrängern entriss*. Denn seine Gnade währt ewig!", footnotes: ["℘ Neh 9,27"] },
      { number: 25, text: "Der Nahrung gibt allem Fleisch*. Denn seine Gnade währt ewig!", footnotes: ["℘ Ps 104,27"] },
      { number: 26, text: "Preist den Gott des Himmels*! Denn seine Gnade währt ewig!", footnotes: ["℘ Neh 2,4; Dan 2,18"] },
    ]},
    { number: 137, verses: [
      { number: 1, text: "An den Strömen Babels*, da saßen wir und weinten, wenn wir an Zion dachten*.", heading: "Psalm 137", footnotes: ["℘ Esr 8,21; Hes 1,1", "℘ Kla 3,48"] },
      { number: 2, text: "An die Pappeln dort hängten wir unsere Zithern*.", footnotes: ["℘ Jes 24,8"] },
      { number: 3, text: "Denn die uns gefangen hielten, forderten dort von uns die Worte eines Liedes, und die uns wehklagen machten, forderten Freude: »Singt uns eins der Zionslieder*!«", footnotes: ["℘ Spr 25,20"] },
      { number: 4, text: "Wie sollten wir des HERRN Lied singen auf fremder Erde?" },
      { number: 5, text: "Wenn ich dich vergesse, Jerusalem, so werde vergessen* meine Rechte*!", footnotes: ["so mit LXX und anderen griech. Üs.; Mas. T.: so vergesse; bei geringfügiger Änderung des Mas. T.: so verdorre", "℘ Jer 51,50"] },
      { number: 6, text: "Es klebe meine Zunge an meinem Gaumen, wenn ich deiner nicht gedenke, wenn ich Jerusalem nicht zu meiner höchsten Freude erhebe*!", footnotes: ["w. erhebe zum Haupt (zur Spitze) meiner Freude"] },
      { number: 7, text: "Gedenke, HERR*, den Söhnen Edom den Tag Jerusalems, die da sprachen: Legt bloß, legt bloß — bis auf ihren Grund*!", footnotes: ["℘ Neh 6,14", "℘ Jer 49,7-22; Kla 4,21.22; Hes 25,12; 35,15; Ob 10"] },
      { number: 8, text: "Tochter Babel, du Verwüsterin*! Glücklich, der dir vergilt dein Tun, das du uns angetan hast*.", footnotes: ["so mit alten Üs.; Mas. T.: du Verwüstete", "℘ Jer 50,29; Offb 18,6"] },
      { number: 9, text: "Glücklich, der deine Kinder ergreift und sie am Felsen zerschmettert*!", footnotes: ["℘ Jes 13,16"] },
    ]},
    { number: 138, verses: [
      { number: 1, text: "Von David. Preisen will ich dich mit meinem ganzen Herzen*, ich will dir spielen vor den Göttern.", heading: "Psalm 138", footnotes: ["℘ Ps 9,2"] },
      { number: 2, text: "Ich falle nieder vor deinem heiligen Tempel*, und deinen Namen preise ich wegen deiner Gnade und Treue*. Denn du hast dein Wort* groß gemacht über deinen ganzen Namen*.", footnotes: ["℘ Ps 5,8", "o. Wahrheit\n℘ Ps 115,1", "o. deine Zusage", "LXX: Denn du hast dein Wort größer gemacht als jeden Namen."] },
      { number: 3, text: "An dem Tag, da ich rief, antwortetest du mir*. Du vermehrtest mir in meiner Seele die Kraft*.", footnotes: ["℘ Ps 34,5.7; Kla 3,57", "so mit LXX und Vulg. — Mas. T.: Du triebst mich an, in meiner Seele war Kraft.\n℘ 1Sam 30,6; 2Kor 12,9"] },
      { number: 4, text: "Alle Könige der Erde werden dich preisen, HERR, wenn sie die Worte deines Mundes gehört haben." },
      { number: 5, text: "Sie werden die Wege des HERRN besingen, denn groß ist die Herrlichkeit des HERRN*.", footnotes: ["℘ Mal 1,11"] },
      { number: 6, text: "Ja, der HERR ist erhaben*, doch er sieht den Niedrigen*, und den Hochmütigen erkennt er von fern.", footnotes: ["℘ Ps 83,19", "℘ Jes 57,15"] },
      { number: 7, text: "Wenn ich auch mitten in Bedrängnis wandeln muss — du belebst mich*. Gegen den Zorn meiner Feinde wirst du deine Hand ausstrecken, und deine Rechte wird mich retten*.", footnotes: ["℘ Ps 119,50", "℘ Ps 18,17.18"] },
      { number: 8, text: "Der HERR wird es für mich vollenden*. HERR, deine Gnade währt ewig*. Gib die Werke deiner Hände nicht auf*!", footnotes: ["℘ Ps 57,3; Phil 1,6", "℘ Ps 100,5", "℘ Hi 10,3"] },
    ]},
    { number: 139, verses: [
      { number: 1, text: "Dem Chorleiter. Von David. Ein Psalm. HERR, du hast mich erforscht und erkannt*.", heading: "Psalm 139", footnotes: ["℘ V. 23; Ps 17,3; 2Sam 7,20; Jer 12,3; 17,10; Joh 21,17"] },
      { number: 2, text: "Du kennst mein Sitzen und mein Aufstehen*, du verstehst mein Trachten* von fern*.", footnotes: ["℘ 2Kö 19,27", "o. Wollen; o. Absicht; o. Gedanke", "℘ Ps 44,22; Mt 6,4; Lk 5,22; Joh 1,48; 2,24"] },
      { number: 3, text: "Mein Wandeln und mein Liegen — du prüfst es*. Mit allen meinen Wegen bist du vertraut*.", footnotes: ["eigentlich: bestimmst es, misst es ab", "℘ Ps 119,168; Hi 31,4; Spr 5,21"] },
      { number: 4, text: "Denn das Wort ist noch nicht auf meiner Zunge — siehe, HERR, du weißt es genau." },
      { number: 5, text: "Von hinten und von vorn hast du mich umschlossen*, du hast deine Hand auf mich gelegt.", footnotes: ["o. eingeschlossen; o. eingeengt"] },
      { number: 6, text: "Zu wunderbar ist die Erkenntnis für mich, zu hoch: Ich vermag sie nicht zu erfassen*.", footnotes: ["w. Ich werde ihrer nicht mächtig\n℘ Hi 11,7-9; 42,3"] },
      { number: 7, text: "Wohin sollte ich gehen vor deinem Geist, wohin fliehen vor deinem Angesicht*?", footnotes: ["℘ Jer 23,24"] },
      { number: 8, text: "Stiege ich zum Himmel hinauf, so bist du da*. Bettete ich mich in dem Scheol, siehe, du bist da.", footnotes: ["℘ Spr 15,11; Am 9,2"] },
      { number: 9, text: "Erhöbe ich die Flügel der Morgenröte, ließe ich mich nieder am äußersten Ende des Meeres," },
      { number: 10, text: "auch dort würde deine Hand mich leiten und deine Rechte mich fassen*.", footnotes: ["℘ Am 9,3"] },
      { number: 11, text: "Und spräche ich: Nur Finsternis möge mich verbergen* und Nacht sei das Licht um mich her*:", footnotes: ["so mit alten Üs. wegen offensichtlicher Verschreibung von Mas. T.: Nur Finsternis möge mich zermalmen o. nach mir schnappen", "℘ Hi 12,22"] },
      { number: 12, text: "Auch Finsternis würde vor dir nicht verfinstern, und die Nacht würde leuchten wie der Tag, die Finsternis wäre wie das Licht*.", footnotes: ["℘ Hi 34,22; Dan 2,22"] },
      { number: 13, text: "Denn du bildetest meine Nieren. Du wobst* mich in meiner Mutter Leib*.", footnotes: ["o. verbargst; o. bargst; vgl. V. 11a", "℘ Ps 95,6"] },
      { number: 14, text: "Ich preise dich darüber, dass ich auf eine erstaunliche, ausgezeichnete Weise gemacht bin. Wunderbar sind deine Werke, und meine Seele erkennt es sehr wohl*.", footnotes: ["℘ Ps 92,6"] },
      { number: 15, text: "Nicht verborgen war mein Gebein vor dir, als ich gemacht wurde* im Verborgenen, gewoben* in den Tiefen der Erde.", footnotes: ["℘ Hi 10,8.9", "Dieses hebr. Wort bezeichnet speziell das Weben kostbarer Stoffe (Buntweberei, auch unter Benutzung von Gold- und Silberfäden)."] },
      { number: 16, text: "Meine Urform* sahen deine Augen. Und in dein Buch waren sie alle eingeschrieben, die Tage, die gebildet wurden, als noch keiner von ihnen da war.", footnotes: ["w. Mein Ungeformtes. — Gemeint ist der Embryo."] },
      { number: 17, text: "Für mich aber — wie schwer* sind deine Gedanken, Gott! Wie gewaltig sind ihre Summen!", footnotes: ["o. gewichtig; o. kostbar"] },
      { number: 18, text: "Wollte ich sie zählen, so sind sie zahlreicher als der Sand*. Ich erwache* und bin noch bei dir.", footnotes: ["℘ Ps 40,6", "Bei geringfügiger Veränderung der Vokalisierung ergibt sich: Wäre ich zu Ende gekommen — ich wäre noch immer bei dir. So auch einige hebr. Handschr."] },
      { number: 19, text: "Mögest du, Gott, den Gottlosen töten*! Ihr Blutmenschen, weicht von mir*!", footnotes: ["℘ Ps 9,18", "℘ Ps 119,115"] },
      { number: 20, text: "Sie, die mit Hinterlist von dir reden*, vergeblich die Hand gegen dich erheben*!", footnotes: ["℘ Jud 15", "So mit geringfügiger Änderung des Konsonantentextes. Manche vermuten in dem hier zu »gegen dich« veränderten Wort des Mas. T. ein aram. Lehnwort und übersetzen: sich vergeblich erheben, deine Feinde"] },
      { number: 21, text: "Sollte ich nicht hassen, HERR, die dich hassen, und sollte mir nicht ekeln vor denen, die gegen dich aufstehen*?", footnotes: ["℘ Ps 119,158; Offb 2,2"] },
      { number: 22, text: "Mit äußerstem Hass hasse ich sie. Sie sind Feinde für mich." },
      { number: 23, text: "Erforsche mich, Gott, und erkenne mein Herz. Prüfe mich und erkenne meine Gedanken*!", footnotes: ["℘ V. 1; Ps 11,4.5; Hi 31,6"] },
      { number: 24, text: "Und sieh, ob ein Weg der Mühsal* bei mir ist, und leite mich auf dem ewigen Weg*!", footnotes: ["o. des Abgotts; d. h. ein abgöttischer Weg", "℘ Ps 27,11"] },
    ]},
    { number: 140, verses: [
      { number: 1, text: "Dem Chorleiter. Ein Psalm. Von David.", heading: "Psalm 140" },
      { number: 2, text: "Rette mich, HERR, von bösen Menschen*. Vor gewalttätigen Männern* behüte mich*,", footnotes: ["In beiden Fällen steht im Mas. T. ein Gattungsbegriff in der Einzahl.\n℘ 2Thes 3,2", "In beiden Fällen steht im Mas. T. ein Gattungsbegriff in der Einzahl.", "℘ Ps 59,3"] },
      { number: 3, text: "die Bosheiten ersinnen im Herzen*, die täglich Kriege erregen.", footnotes: ["℘ Spr 6,14"] },
      { number: 4, text: "Sie haben geschärfte Zungen* wie eine Schlange*. Viperngift ist unter ihren Lippen*. //", footnotes: ["w. Sie haben ihre Zungen geschärft", "℘ Ps 52,4", "℘ Ps 58,5; Röm 3,13"] },
      { number: 5, text: "Bewahre mich, HERR, vor den Händen des Gottlosen, vor dem Mann der Gewalttaten behüte mich*, die beschlossen haben, meine Tritte umzustoßen!", footnotes: ["℘ Ps 43,1"] },
      { number: 6, text: "Hochmütige haben mir heimlich eine Schlinge und Fallstricke gelegt, ein Netz ausgespannt zur Seite des Weges, sie haben mir Fallen gestellt*. //", footnotes: ["℘ Ps 57,7; 142,4; Jer 18,22"] },
      { number: 7, text: "Ich sprach zu dem HERRN: Du bist mein Gott*! Höre, HERR, auf die Stimme meines Flehens!", footnotes: ["℘ Ps 31,15"] },
      { number: 8, text: "HERR, mein Herr, du Hort meiner Rettung! Du hast mein Haupt beschirmt am Tag der Waffen*.", footnotes: ["℘ Ps 144,10"] },
      { number: 9, text: "Gewähre die Gelüste des Gottlosen nicht, HERR! Lass sein Vorhaben nicht *gelingen: Sie würden sich überheben*. //", footnotes: ["Andere lesen: gelingen. Erheben sie ihre Häupter, die mich umringen — das Unheil ihrer Lippen bedecke sie! Die Abgrenzung der Verse ist nicht eindeutig.", "℘ 5Mo 32,27"] },
      { number: 10, text: "Die Häupter derer die mich umringen — das Unheil ihrer Lippen bedecke sie*!*", footnotes: ["℘ Ps 7,17; 64,9", "Andere lesen: gelingen. Erheben sie ihre Häupter, die mich umringen — das Unheil ihrer Lippen bedecke sie! Die Abgrenzung der Verse ist nicht eindeutig."] },
      { number: 11, text: "Mögen glühende Kohlen auf sie herabfallen, ins Feuer stürze er sie, in Wasserlöcher, dass sie sich nicht mehr erheben!" },
      { number: 12, text: "Ein Mensch mit böser Zunge — er bestehe nicht im Land*; der Mann der Gewalttat — das Böse möge ihn jagen Stoß um Stoß!", footnotes: ["℘ Ps 12,3.4"] },
      { number: 13, text: "Ich weiß, dass der HERR die Rechtssache des Elenden wahrnimmt, das Recht der Armen*.", footnotes: ["℘ Ps 35,10; Spr 22,23"] },
      { number: 14, text: "Ja, die Gerechten werden deinen Namen preisen, die Aufrichtigen werden vor deinem Angesicht wohnen*.", footnotes: ["℘ Ps 15,1.2"] },
    ]},
    { number: 141, verses: [
      { number: 1, text: "Ein Psalm. Von David. HERR, zu dir habe ich gerufen, eile zu mir*! Höre auf meine Stimme, wenn ich zu dir rufe*!", heading: "Psalm 141", footnotes: ["℘ Ps 70,2.6", "℘ Ps 28,2"] },
      { number: 2, text: "Lass als Rauchopfer vor dir stehen mein Gebet*, das Erheben meiner Hände als Speisopfer am Abend*.", footnotes: ["℘ 2Mo 30,7; Spr 15,8; Offb 5,8", "℘ Ps 134,2; 2Mo 29,39.40"] },
      { number: 3, text: "Bestelle, HERR, eine Wache für meinen Mund! Wache über die Tür meiner Lippen*!", footnotes: ["℘ Ps 39,2"] },
      { number: 4, text: "Lass mein Herz sich nicht neigen zur bösen Sache*, gottlos Taten zu begehen mit Männern, die Übeltäter sind*. Ich mag nicht kosten von ihren Leckerbissen!", footnotes: ["o. zum bösen Wort", "℘ Ps 28,3"] },
      { number: 5, text: "Der Gerechte schlage mich — es ist Gnade. Er strafe mich — es ist Öl für das Haupt*. Mein Haupt wird sich nicht weigern*. Denn noch immer bete ich trotz des Unheils, das sie tun*.", footnotes: ["℘ Spr 9,8; 12,1; 25,12", "Manche schlagen vor: sich schmücken", "w. Denn noch immer ist mein Gebet bei ihrem Unheiltun.\n℘ 3Mo 19,17"] },
      { number: 6, text: "*Sind sie gefallen in die Hände ihrer Richter*, so werden sie meine Worte hören, dass sie lieblich sind.", footnotes: ["Mas. T.: Sind herabgestürzt in die Hände des Felsens ihre Richter. — Durch die sachlich gebotene Umstellung des Wortes »Felsen« von V. 6a nach V. 7a ergibt sich der obige Text.", "Mas. T.: Sind herabgestürzt in die Hände des Felsens ihre Richter. — Durch die sachlich gebotene Umstellung des Wortes »Felsen« von V. 6a nach V. 7a ergibt sich der obige Text."] },
      { number: 7, text: "Wie wenn ein Fels* sich spaltet und die Erde aufreißt, so sind ihre* Gebeine hingestreut für den Schlund des Scheols.", footnotes: ["s. vorige Anm.", "so mit alten Üs.; Mas. T.: unsere"] },
      { number: 8, text: "Doch auf dich, HERR, mein Herr, sind meine Augen gerichtet*, bei dir suche ich Zuflucht. Gib meine Seele nicht preis.*", footnotes: ["℘ Ps 25,15", "w. Schütte meine Seele nicht aus."] },
      { number: 9, text: "Bewahre mich vor dem Netz*, das sie mir gelegt haben*, und vor den Fallen der Übeltäter*.", footnotes: ["w. vor den Händen des Netzes", "℘ Ps 57,7; 142,4", "℘ Ps 64,3.6; 140,5.6"] },
      { number: 10, text: "Lass die Gottlosen in ihre eigenen Gruben* fallen*, alle miteinander, während ich immer vorbeigehe!", footnotes: ["so mit LXX; Mas. T.: seine eigenen Gruben", "℘ Ps 7,16"] },
    ]},
    { number: 142, verses: [
      { number: 1, text: "Ein Maskil*. Von David. Als er in der Höhle war*. Ein Gebet.", heading: "Psalm 142", footnotes: ["s. Anm. zu Ps 32,1", "℘ Ps 57,1; 1Sam 22,1; 24,4"] },
      { number: 2, text: "Mit meiner Stimme schreie ich um Hilfe zum HERRN*, mit meiner Stimme flehe ich zum HERRN.", footnotes: ["℘ Ps 28,1.2"] },
      { number: 3, text: "Ich schütte mein Anliegen vor ihm aus*, meine Not erzähle ich vor ihm.", footnotes: ["℘ Ps 62,9; 102,1"] },
      { number: 4, text: "Als mein Geist in mir ermattete*, da kanntest du meinen Pfad*. Auf dem Weg, den ich wandle, haben sie mir heimlich eine Schlinge gelegt*.", footnotes: ["℘ Ps 143,4", "℘ Ps 1,6", "℘ Ps 140,6; 141,9; Jer 18,22"] },
      { number: 5, text: "Schau zur Rechten und sieh: ich habe ja niemanden, der etwas von mir wissen will. Verloren gegangen ist mir jede Zuflucht, niemand fragt nach meiner Seele*.", footnotes: ["℘ Ps 35,12; Joh 5,7"] },
      { number: 6, text: "Zu dir habe ich um Hilfe geschrien, HERR! Ich habe gesagt: Du bist meine Zuflucht*, mein Teil im Land der Lebendigen*.", footnotes: ["℘ Ps 46,2", "℘ Ps 27,13"] },
      { number: 7, text: "Horche auf mein Schreien, denn ich bin sehr schwach*. Rette mich vor meinen Verfolgern*, denn sie sind mir zu mächtig*!", footnotes: ["℘ Ps 40,18", "℘ Ps 143,9", "℘ Ps 38,20"] },
      { number: 8, text: "Führe aus dem Gefängnis heraus meine Seele*, damit ich deinen Namen preise*! Die Gerechten werden mich umringen, wenn du mir wohlgetan hast.", footnotes: ["℘ Ps 143,11", "o. um deinen Namen zu preisen\n℘ Ps 9,14.15"] },
    ]},
    { number: 143, verses: [
      { number: 1, text: "Ein Psalm. Von David. HERR, höre mein Gebet, merke auf mein Flehen! Erhöre mich in deiner Treue, in deiner Gerechtigkeit*!", heading: "Psalm 143", footnotes: ["℘ Ps 17,1"] },
      { number: 2, text: "Gehe nicht ins Gericht mit deinem Knecht! Denn vor dir ist kein Lebendiger gerecht*.", footnotes: ["℘ Ps 130,3; Hi 15,14; 25,4; Pred 7,20; Röm 3,10"] },
      { number: 3, text: "Denn der Feind verfolgt meine Seele, tritt zu Boden mein Leben*, lässt mich wohnen in Finsternissen* gleich den Toten der Urzeit*.", footnotes: ["℘ Ps 7,6", "℘ Mi 7,8", "℘ Kla 3,6"] },
      { number: 4, text: "Mein Geist ermattet in mir, mein Herz ist erstarrt in meinem Innern*.", footnotes: ["℘ Ps 142,4"] },
      { number: 5, text: "Ich gedenke der Tage der Vorzeit, überlege all dein Tun. Ich sinne nach über das Werk deiner Hände*.", footnotes: ["℘ Ps 77,6.7"] },
      { number: 6, text: "Zu dir breite ich meine Hände aus*. Gleich einem lechzenden Land schmachtet meine Seele nach dir*! //", footnotes: ["℘ Ps 88,10", "℘ Ps 42,3"] },
      { number: 7, text: "Schnell, erhöre mich, HERR! Es verschmachtet mein Geist. Verbirg dein Angesicht nicht vor mir*! Sonst bin ich denen gleich, die zur Grube hinabfahren*.", footnotes: ["℘ Ps 69,18", "℘ Ps 28,1"] },
      { number: 8, text: "Lass mich am Morgen hören deine Gnade*, denn ich vertraue auf dich*! Tu mir kund den Weg, den ich gehen soll*, denn zu dir erhebe ich meine Seele*!", footnotes: ["℘ Ps 90,14", "℘ Ps 25,20", "℘ Ps 32,8", "℘ Ps 86,4"] },
      { number: 9, text: "Rette mich, HERR, von meinen Feinden*! Zu dir nehme ich meine Zuflucht*.", footnotes: ["℘ Ps 142,7", "so mit einer hebr. Handschr. und LXX; Mas. T.: Zu dir habe ich bedeckt\n℘ Ps 57,2"] },
      { number: 10, text: "Lehre mich tun nach deinem Wohlgefallen, denn du bist mein Gott*! Dein guter Geist leite mich in ebenes Land*!", footnotes: ["℘ Ps 118,28", "mit einigen hebr. Handschr.: auf ebenem Weg\n℘ Ps 27,11"] },
      { number: 11, text: "Um deines Namens willen, HERR, belebe mich*! In deiner Gerechtigkeit führe meine Seele aus der Not*!", footnotes: ["o. erhalte mich am Leben\n℘ Ps 119,25", "℘ Ps 142,8"] },
      { number: 12, text: "In deiner Gnade vernichte meine Feinde*, und alle Bedränger meiner Seele lass umkommen*, denn ich bin dein Knecht*!", footnotes: ["o. bringe meine Feinde zum Schweigen", "℘ Ps 54,7", "℘ Ps 116,16"] },
    ]},
    { number: 144, verses: [
      { number: 1, text: "Von David. Gepriesen sei der HERR, mein Fels*, der meine Hände unterweist zum Kampf, meine Finger zum Krieg*:", heading: "Psalm 144", footnotes: ["℘ Ps 18,3.32", "℘ Ps 18,35"] },
      { number: 2, text: "Meine Gnade*, meine Burg und meine Zuflucht*, mein Retter, mein Schild und der, bei dem ich mich berge*, der mir Völker* unterwirft!", footnotes: ["Durch Veränderung eines Konsonanten ergibt sich: Meine Stärke", "℘ Ps 59,18", "o. bei dem ich Zuflucht suche", "so mit vielen hebr. Handschr. und vielen alten Üs.; Mas. T.: mein Volk"] },
      { number: 3, text: "HERR, was ist der Mensch, dass du Kenntnis von ihm nimmst, der Sohn des Menschen, dass du ihn beachtest*?", footnotes: ["℘ Ps 8,5; Hebr 2,6"] },
      { number: 4, text: "Der Mensch gleicht dem Hauch. Seine Tage sind wie ein vorübergehender Schatten*.", footnotes: ["℘ Ps 39,6; Hi 8,9; 14,2"] },
      { number: 5, text: "HERR, neige deinen Himmel und steige herab*! Rühre die Berge an, dass sie rauchen*!", footnotes: ["℘ Ps 18,10; Jes 64,1", "℘ Ps 104,32"] },
      { number: 6, text: "Blitze mit Blitzen und zerstreue sie! Schieße deine Pfeile ab und verwirre sie*!", footnotes: ["℘ Ps 18,15; 64,8"] },
      { number: 7, text: "Strecke deine Hand aus von der Höhe! Reiße mich heraus und rette mich aus großen Wassern*, aus der Hand der Söhne der Fremde,", footnotes: ["℘ Ps 18,17; 124,4"] },
      { number: 8, text: "deren Mund Falsches* redet, deren Rechte eine Rechte der Lüge ist!", footnotes: ["o. Nichtiges, Falschheit"] },
      { number: 9, text: "Gott, ein neues Lied will ich dir singen, auf der Harfe von zehn Saiten will ich dir spielen*!", footnotes: ["℘ Ps 33,2.3"] },
      { number: 10, text: "Dir, der Rettung gibt den Königen, der seinen Knecht David* entreißt dem verderblichen Schwert*.", footnotes: ["℘ Ps 132,10", "℘ Ps 18,51; 140,8"] },
      { number: 11, text: "Reiße mich heraus und rette mich aus der Hand der Söhne der Fremde, deren Mund Falschheit redet und deren Rechte eine Rechte der Lüge ist." },
      { number: 12, text: "Dass unsere Söhne seien gleich Pflanzen*, die großgezogen wurden in ihrer Jugend, unsere Töchter gleich Ecksäulen, geschnitzt nach der Bauart eines Palastes.", footnotes: ["℘ Ps 128,3"] },
      { number: 13, text: "Unsere Speicher seien gefüllt, sie mögen Nahrung spenden von jeglicher Art! Unser Kleinvieh mehre sich tausendfach, zehntausendfach auf unseren Fluren*!", footnotes: ["℘ Ps 65,14; 3Mo 26,5; 5Mo 7,13"] },
      { number: 14, text: "Unsere Rinder seien trächtig, ohne Riss* und Fehlgeburt! Kein Klagegeschrei sei auf unseren Plätzen*!", footnotes: ["eigentlich: Dammriss bei der Geburt", "℘ 3Mo 26,6; Jes 65,19"] },
      { number: 15, text: "Glücklich das Volk, dem es so ergeht! Glücklich das Volk, dessen Gott der HERR ist*!", footnotes: ["℘ Ps 33,12"] },
    ]},
    { number: 145, verses: [
      { number: 1, text: "Ein Lobgesang. Von David. Ich will dich erheben*, mein Gott, du König*, und deinen Namen preisen* immer und ewig.", heading: "Psalm 1451", footnotes: ["℘ Ps 30,2", "℘ Ps 5,3", "℘ Ps 118,28"] },
      { number: 2, text: "Täglich will ich dich preisen, deinen Namen will ich loben immer und ewig*.", footnotes: ["℘ Ps 30,13; 96,2; 146,2"] },
      { number: 3, text: "Groß ist der HERR und sehr zu loben*. Seine Größe ist unerforschlich*.", footnotes: ["℘ Ps 96,4", "℘ Hi 5,9; 36,26"] },
      { number: 4, text: "Eine Generation wird der andern rühmen deine Werke, deine Machttaten werden sie verkünden*.", footnotes: ["℘ Ps 78,3.4; 5Mo 4,10; Jes 38,19"] },
      { number: 5, text: "Reden sollen sie von der herrlichen Pracht deiner Majestät*, und deine Wunder will ich bedenken.", footnotes: ["so mit LXX und syr. Üs.; Mas. T.: Die Pracht der Herrlichkeit deiner Majestät und Worte\n℘ Ps 111,3; 5Mo 32,3"] },
      { number: 6, text: "Sie sollen sprechen von der Kraft deiner furchtbaren Taten, und deine Großtaten will ich erzählen*.", footnotes: ["℘ 1Chr 29,11"] },
      { number: 7, text: "Das Lob* deiner großen Güte werden sie hervorströmen lassen*, deine Gerechtigkeit werden sie jubelnd preisen*.", footnotes: ["w. Das Anrufen", "℘ Jes 63,7", "℘ Ps 71,15"] },
      { number: 8, text: "Gnädig und barmherzig ist der HERR, langsam zum Zorn und groß an Gnade*.", footnotes: ["℘ Ps 86,15"] },
      { number: 9, text: "Der HERR ist gut gegen alle*, sein Erbarmen ist über alle seine Werke*.", footnotes: ["℘ Ps 86,5; Mt 5,45", "℘ Jon 4,11"] },
      { number: 10, text: "Es werden dich loben, HERR, alle deine Werke* und deine Frommen dich preisen*.", footnotes: ["℘ Ps 69,35; 103,22", "℘ Ps 30,5; 149,5"] },
      { number: 11, text: "Sie werden sprechen von der Herrlichkeit deines Reiches*, sie werden reden von deiner Kraft,", footnotes: ["℘ Jes 11,1-10"] },
      { number: 12, text: "um den Menschenkindern kundzutun deine* Machttaten* und die prachtvolle Herrlichkeit deines* Reiches.", footnotes: ["so mit LXX u. syr. Üs.; Mas. T.: seine bzw. seines", "℘ Ps 111,6", "so mit LXX u. syr. Üs.; Mas. T.: seine bzw. seines"] },
      { number: 13, text: "Dein Reich ist ein Reich aller Zeiten*, deine Herrschaft dauert durch alle Generationen hindurch*.", footnotes: ["℘ 1Tim 1,17", "An dieser Stelle fehlt im Mas. T. die mit n beginnende Verszeile des alphabetischen Psalms. Eine hebr. Handschr., LXX und die syr. Üs. enthalten sie: Treu ist der HERR in allen seinen Worten und gnädig in allen seinen Taten.\n℘ Ps 146,10; Dan 4,31; 6,27; 7,14.27; Offb 11,15"] },
      { number: 14, text: "Der HERR stützt alle Fallenden*, er richtet auf alle Niedergebeugten*.", footnotes: ["℘ Ps 37,24", "℘ Ps 146,8"] },
      { number: 15, text: "Aller Augen warten auf dich, und du gibst ihnen ihre Speise zu seiner Zeit*.", footnotes: ["℘ Ps 104,27; Mt 6,26"] },
      { number: 16, text: "Du tust deine Hand auf und sättigst alles Lebendige nach Wohlgefallen*.", footnotes: ["℘ Ps 104,28; 147,9"] },
      { number: 17, text: "Der HERR ist gerecht in allen seinen Wegen* und treu in allen seinen Werken.", footnotes: ["℘ 5Mo 32,4; Zef 3,5; Mt 20,13; Offb 15,3"] },
      { number: 18, text: "Nahe ist der HERR allen, die ihn anrufen, allen, die ihn in Wahrheit* anrufen*.", footnotes: ["o. Treue", "℘ 5Mo 4,7; Jes 58,9; Jer 29,13; Röm 10,12; Jak 4,8"] },
      { number: 19, text: "Er erfüllt das Verlangen derer, die ihn fürchten. Ihr Schreien hört er*, und er hilft ihnen*.", footnotes: ["℘ Joh 9,31", "℘ Ps 34,18"] },
      { number: 20, text: "Der HERR bewahrt alle, die ihn lieben, aber alle Gottlosen vertilgt er*.", footnotes: ["℘ Ps 104,35; 1Sam 2,9"] },
      { number: 21, text: "Mein Mund soll das Lob des HERRN aussprechen, und alles Fleisch preise seinen heiligen Namen immer und ewig*!", footnotes: ["℘ Ps 69,35; 103,22"] },
    ]},
    { number: 146, verses: [
      { number: 1, text: "Halleluja! Lobe den HERRN, meine Seele*!", heading: "Psalm 146", footnotes: ["℘ Ps 103,1"] },
      { number: 2, text: "Loben will ich den HERRN mein Leben lang, will spielen meinem Gott, solange ich bin*.", footnotes: ["℘ Ps 104,33; 145,1.2"] },
      { number: 3, text: "Vertraut nicht auf Edle, auf einen Menschensohn, bei dem keine Hilfe ist*!", footnotes: ["℘ Ps 118,8.9; Jer 17,5"] },
      { number: 4, text: "Sein Geist geht aus, er kehrt wieder zu seiner Erde*: am selben Tag gehen seine Pläne verloren*.", footnotes: ["℘ Ps 90,3", "℘ Pred 9,6"] },
      { number: 5, text: "Glücklich der, dessen Hilfe der Gott Jakobs ist*, dessen Hoffnung auf dem HERRN, seinem Gott, steht*,", footnotes: ["℘ Ps 46,8", "℘ Jer 17,7; 1Tim 6,17"] },
      { number: 6, text: "der Himmel und Erde gemacht hat*, das Meer und alles, was in ihnen ist*; der Treue hält auf ewig*.", footnotes: ["℘ Ps 115,15; Jer 32,17", "℘ Apg 4,24", "℘ Ps 117,2"] },
      { number: 7, text: "Er schafft Recht den Bedrückten*, er gibt den Hungrigen Brot*. Der HERR macht die Gefangenen frei*.", footnotes: ["℘ Ps 35,10", "℘ Ps 107,9", "℘ Ps 68,7"] },
      { number: 8, text: "Der HERR öffnet die Augen der Blinden*. Der HERR richtet die Gebeugten auf*. Der HERR liebt die Gerechten.", footnotes: ["℘ Mt 9,30; Joh 9,32; Apg 26,18", "℘ Ps 145,14; Lk 13,13"] },
      { number: 9, text: "Der HERR behütet die Fremdlinge, Waisen und Witwen hilft er auf*; aber er krümmt den Weg der Gottlosen.", footnotes: ["℘ Ps 10,14; 2Mo 22,21; 5Mo 10,18"] },
      { number: 10, text: "Der HERR wird regieren in Ewigkeit*, dein Gott, Zion, von Generation zu Generation*. Halleluja!", footnotes: ["℘ 2Mo 15,18", "℘ Ps 145,13"] },
    ]},
    { number: 147, verses: [
      { number: 1, text: "Halleluja! Ja, es ist gut, unserem Gott zu spielen*! Ja, ein Lobgesang ist schön, ist lieblich*.", heading: "Psalm 147", footnotes: ["℘ Ps 92,2", "Andere übersetzen: Ja, es ist lieblich, einen Lobgesang anzustimmen."] },
      { number: 2, text: "Der HERR baut Jerusalem auf*, die Zerstreuten Israels sammelt er*.", footnotes: ["℘ Ps 102,17; Neh 6,15.16", "℘ 5Mo 30,3.4; Jer 31,10"] },
      { number: 3, text: "Er heilt, die zerbrochenen Herzens sind, er verbindet ihre Wunden*.", footnotes: ["℘ Ps 34,19; Hi 5,18; Jes 61,1; Jer 33,6; Lk 10,34"] },
      { number: 4, text: "Er zählt die Zahl der Sterne, er ruft sie alle mit Namen*.", footnotes: ["℘ Jes 40,26"] },
      { number: 5, text: "Groß ist unser Herr und reich an Macht*. Seine Einsicht ist ohne Maß*.", footnotes: ["℘ Ps 135,5", "w. ohne Zahl\n℘ Hi 36,5; Jes 40,28"] },
      { number: 6, text: "Der HERR hilft den Elenden auf*. Er erniedrigt die Gottlosen bis zur Erde*.", footnotes: ["℘ Ps 41,13", "℘ Mal 4,3"] },
      { number: 7, text: "Stimmt dem HERRN ein Danklied an, spielt unserem Gott auf der Zither*!", footnotes: ["℘ Ps 98,5"] },
      { number: 8, text: "Ihm, der den Himmel mit Wolken bedeckt und Regen bereitet der Erde*; der Gras sprossen lässt auf den Bergen*;", footnotes: ["℘ Jer 14,22; Joe 2,23", "℘ Ps 104,14; Apg 14,17"] },
      { number: 9, text: "der dem Vieh sein Futter gibt*, den jungen Raben, *wonach sie schreien*.", footnotes: ["℘ Ps 145,16", "o. die zu ihm schreien", "o. die zu ihm schreien\n℘ Hi 38,41; Mt 6,26"] },
      { number: 10, text: "Er hat kein Gefallen an der Stärke des Rosses, noch Freude an den Schenkeln des Mannes." },
      { number: 11, text: "Der HERR hat Gefallen an denen, die ihn fürchten, an denen, die auf seine Gnade harren*.", footnotes: ["℘ Ps 33,18; Apg 10,35"] },
      { number: 12, text: "Rühme, Jerusalem, den HERRN! Lobe, Zion, deinen Gott!" },
      { number: 13, text: "Denn er hat die Riegel deiner Tore befestigt, hat deine Kinder gesegnet in deiner Mitte*.", footnotes: ["℘ Jer 33,10.11"] },
      { number: 14, text: "Er schafft Frieden in deinen Grenzen*, er sättigt dich mit dem besten Weizen*.", footnotes: ["℘ 3Mo 26,6", "w. mit dem Fett (d. h. dem Besten) des Weizens\n℘ Ps 81,17"] },
      { number: 15, text: "Er sendet seinen Spruch auf die Erde, sehr schnell läuft sein Wort." },
      { number: 16, text: "Er gibt Schnee wie Wolle*, Reif streut er wie Staub aus.", footnotes: ["℘ Ps 148,8; Hi 37,6"] },
      { number: 17, text: "Er wirft sein Eis wie Brocken*. *Wer kann bestehen vor seinem Frost?*", footnotes: ["℘ Hi 38,22", "Wegen V. 18 ist möglicherweise mit geringfügiger Textkorrektur zu lesen: Vor seinem Frost erstarrt das Wasser.", "Wegen V. 18 ist möglicherweise mit geringfügiger Textkorrektur zu lesen: Vor seinem Frost erstarrt das Wasser."] },
      { number: 18, text: "Er sendet sein Wort und schmelzt sie. Er lässt seinen Wind wehen* — es rieselt das Wasser.", footnotes: ["℘ Ps 78,26"] },
      { number: 19, text: "Er verkündete Jakob sein Wort, Israel seine Ordnungen und seine Rechtsbestimmungen*.", footnotes: ["℘ Mal 4,22; Röm 3,2"] },
      { number: 20, text: "So handelte er an keiner Nation, und die* Rechtsbestimmungen, die haben sie nicht gekannt*. Halleluja!", footnotes: ["Die alten Üs. haben hier: seine", "bei anderer möglicher Vokalisierung: und die Rechte lehrte er sie nicht; so in Qumrantexten und alten Üs.\n℘ 5Mo 4,8; Apg 14,16"] },
    ]},
    { number: 148, verses: [
      { number: 1, text: "Halleluja! Lobt den HERRN vom Himmel her! Lobt ihn in den Höhen*!", heading: "Psalm 148", footnotes: ["℘ Lk 19,38"] },
      { number: 2, text: "Lobt ihn, alle seine Engel! Lobt ihn, alle seine Heerscharen!" },
      { number: 3, text: "Lobt ihn, Sonne und Mond! Lobt ihn, alle leuchtenden Sterne!" },
      { number: 4, text: "Lobt ihn, ihr Himmel der Himmel* und ihr Wasser, die ihr oberhalb des Himmels seid*!", footnotes: ["℘ Ps 69,35; 1Kö 8,27", "℘ Ps 104,3; 1Mo 1,6.7"] },
      { number: 5, text: "Loben sollen sie den Namen des HERRN*! Denn er gebot, und sie waren geschaffen*.", footnotes: ["℘ Ps 103,20-22", "℘ Ps 33,6.9"] },
      { number: 6, text: "Er stellte sie hin für immer und ewig. Er gab eine Ordnung, die wird man nicht überschreiten*.", footnotes: ["℘ Jer 31,35-36"] },
      { number: 7, text: "Lobt den HERRN von der Erde her, ihr Wasserungeheuer und alle Urfluten*!", footnotes: ["℘ Ps 104,24.25"] },
      { number: 8, text: "Feuer und Hagel, Schnee und Nebel, Sturmwind, der sein Wort vollzieht*!", footnotes: ["℘ Jon 1,4"] },
      { number: 9, text: "Ihr Berge und alle Hügel, Fruchtbäume und alle Zedern*!", footnotes: ["℘ Jes 44,23"] },
      { number: 10, text: "Das Wild und alles Vieh, Gewürm und gefiederte Vögel*!", footnotes: ["℘ Jes 43,20"] },
      { number: 11, text: "Könige der Erde und alle Völker, Oberste und alle Richter der Erde*!", footnotes: ["℘ Offb 21,24"] },
      { number: 12, text: "Junge Männer und auch Jungfrauen, Alte samt den Jungen*:", footnotes: ["℘ Jer 31,13"] },
      { number: 13, text: "Sie sollen loben den Namen des HERRN*! Denn allein sein Name ist hoch erhaben, seine Hoheit ist über Erde und Himmel*!", footnotes: ["℘ Ps 150,6", "℘ Ps 8,2; Jes 12,4"] },
      { number: 14, text: "Er hat erhöht ein Horn seinem Volk*. Ein Loblied für alle seine Frommen*, für die Söhne Israel, für das Volk, das ihm nahe ist*. Halleluja!", footnotes: ["℘ Ps 89,18", "℘ Ps 149,9", "w. das Volk seines Nahens\n℘ 5Mo 4,7"] },
    ]},
    { number: 149, verses: [
      { number: 1, text: "Halleluja! Singt dem HERRN ein neues Lied*, sein Lob in der Gemeinde der Frommen*!", heading: "Psalm 149", footnotes: ["℘ Ps 33,3", "℘ Ps 111,1"] },
      { number: 2, text: "Israel freue sich seines Schöpfers*! Die Kinder Zions sollen jauchzen über ihren König*!", footnotes: ["℘ Jes 43,15", "℘ Zef 3,14.15; Sach 9,9"] },
      { number: 3, text: "Loben sollen sie seinen Namen beim Reigen*, mit Tamburin und Zither sollen sie ihm spielen*!", footnotes: ["℘ Ps 87,7; 150,4", "℘ Ps 81,3"] },
      { number: 4, text: "Denn der HERR hat Wohlgefallen an seinem Volk*. Er schmückt die Demütigen mit Heil!", footnotes: ["℘ Jes 62,4.5"] },
      { number: 5, text: "Die Frommen* sollen jubeln in Herrlichkeit, jauchzen sollen sie auf ihren Lagern*!", footnotes: ["℘ Ps 145,10", "℘ Hi 35,10"] },
      { number: 6, text: "Lobpreis* Gottes sei in ihrer Kehle und ein zweischneidiges Schwert in ihrer Hand,", footnotes: ["eigentlich: Lobeserhebungen, Lobpreisungen"] },
      { number: 7, text: "um Rache zu vollziehen an den Nationen, Strafgerichte an den Völkerschaften*,", footnotes: ["℘ Mi 5,14"] },
      { number: 8, text: "um ihre Könige zu binden mit Ketten, ihre Edlen mit eisernen Fesseln," },
      { number: 9, text: "um das schon aufgeschriebene Gericht an ihnen zu vollziehen*! Das ist Ehre für alle seine Frommen*. Halleluja!", footnotes: ["℘ 5Mo 32,41", "℘ Ps 148,14"] },
    ]},
    { number: 150, verses: [
      { number: 1, text: "Halleluja! Lobt Gott in seinem Heiligtum*! Lobt ihn in der Feste* seiner Macht*!", heading: "Psalm 150", footnotes: ["℘ Ps 116,19", "im Hebräischen das gleiche Wort wie in 1Mo 1,6—8; w. Wölbung, d. h. Himmelsgewölbe", "℘ Ps 19,2"] },
      { number: 2, text: "Lobt ihn wegen seiner Machttaten! Lobt ihn in seiner gewaltigen Größe*!", footnotes: ["w. wegen der Menge seiner Größe\n℘ Ps 96,3.4"] },
      { number: 3, text: "Lobt ihn mit Hörnerschall*! Lobt ihn mit Harfe und Zither*!", footnotes: ["w. durch Stoßen ins Horn", "℘ 1Chr 25,1; 2Chr 5,13"] },
      { number: 4, text: "Lobt ihn mit Tamburin und Reigen*! Lobt ihn mit Saitenspiel* und Flöte*!", footnotes: ["℘ Ps 149,3", "℘ Jes 38,20", "℘ Hi 21,12"] },
      { number: 5, text: "Lobt ihn mit klingenden Becken! Lobt ihn mit schallenden Becken*!", footnotes: ["℘ 1Chr 25,1; 2Chr 5,13"] },
      { number: 6, text: "Alles, was Atem hat, lobe Jah*! Halleluja!", footnotes: ["℘ Ps 68,5; 148,13"] },
    ]},
  ]
};
